INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-espresso', 'coffee', 'COFFEE', '意式浓缩', 'Espresso', 'yishinongsuo', 'ysns', '以意式配方咖啡豆在九个大气压下、约三十秒内萃取约二十五毫升的高浓度咖啡液，油脂绵密，是意式咖啡系列的经典基底。', 'V6 标准采用意式配方豆 18 克出双份、单品浓缩按 8 克粉萃 25 毫升。本条目以单份浓缩为基准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso.jpg', 98, 1, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 9.0}, {"key": "ROAST", "label": "烘焙感", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["浓缩基底", "热饮", "苦味明显", "浓缩", "醇厚/酒体饱满", "含咖啡因", "无乳配方"]', '["日常", "下午茶", "经典"]', '{"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜偏苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶", "经典"]}', '[{"nameZh": "咖啡豆（意式配方）", "nameEn": "Coffee beans for espresso", "amount": 8, "unit": "g", "role": "意式配方细磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 40, "unit": "ml", "role": "92-94°C 萃取用水"}]', '["用电子秤称取 8 克意式配方咖啡豆并研磨成细粉。", "将咖啡粉布平并用压粉器压实至表面平整。", "用 92-94°C 的热水在 9 个大气压下萃取约 25 毫升浓缩液。", "萃取时间控制在 25-30 秒，观察油脂呈琥珀色即可停止。", "立即注入预热的小杯并饮用，以保留油脂与香气。"]', '["浓缩咖啡", "Espresso", "Single espresso"]', 'A', '2026-08-04', 1, '{"id": "coffee-espresso", "mode": "coffee", "category": "COFFEE", "nameZh": "意式浓缩", "nameEn": "Espresso", "intro": "以意式配方咖啡豆在九个大气压下、约三十秒内萃取约二十五毫升的高浓度咖啡液，油脂绵密，是意式咖啡系列的经典基底。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso.jpg", "tags": ["浓缩基底", "热饮", "苦味明显", "浓缩", "醇厚/酒体饱满", "含咖啡因", "无乳配方"], "scene": ["日常", "下午茶", "经典"], "recommendationScore": 98, "attributes": {"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜偏苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-double-espresso', 'coffee', 'COFFEE', '双份浓缩', 'Double Espresso', 'shuangfennongsuo', 'sfns', '以约十八克咖啡粉在九个大气压下萃取约三十六毫升的高浓度咖啡液，油脂厚重、苦甜集中，是奶咖与美式咖啡的标准双份基底。', 'V6 标准为 18 克粉萃 36-60 毫升，本条目采用 18 克粉萃 36 毫升的 Ristretto 范围外常规比例。', 'https://images.unsplash.com/photo-1634234498465-a3a63b112256?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1634234498465-a3a63b112256?w=1200&q=80&auto=format&fit=crop', 98, 2, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 9.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 10.0}, {"key": "ROAST", "label": "烘焙感", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["浓缩基底", "热饮", "苦味明显", "浓缩", "醇厚/酒体饱满", "高咖啡因", "无乳配方"]', '["日常", "下午茶", "经典"]', '{"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜偏苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常", "下午茶", "经典"]}', '[{"nameZh": "咖啡豆（意式配方）", "nameEn": "Coffee beans for espresso", "amount": 18, "unit": "g", "role": "意式配方细磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 90, "unit": "ml", "role": "92-94°C 萃取用水"}]', '["用电子秤称取 18 克意式配方咖啡豆并研磨成细粉。", "将咖啡粉布平压实，确保表面平整无通道。", "用 92-94°C 热水在 9 个大气压下萃取约 36 毫升浓缩液。", "萃取时间控制在 25-30 秒，观察油脂颜色转琥珀色即停止。", "立即注入预热小杯，趁油脂完整时饮用。"]', '["Doppio", "双倍浓缩", "Double shot"]', 'A', '2026-08-04', 1, '{"id": "coffee-double-espresso", "mode": "coffee", "category": "COFFEE", "nameZh": "双份浓缩", "nameEn": "Double Espresso", "intro": "以约十八克咖啡粉在九个大气压下萃取约三十六毫升的高浓度咖啡液，油脂厚重、苦甜集中，是奶咖与美式咖啡的标准双份基底。", "imageUrl": "https://images.unsplash.com/photo-1634234498465-a3a63b112256?w=1200&q=80&auto=format&fit=crop", "tags": ["浓缩基底", "热饮", "苦味明显", "浓缩", "醇厚/酒体饱满", "高咖啡因", "无乳配方"], "scene": ["日常", "下午茶", "经典"], "recommendationScore": 98, "attributes": {"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜偏苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-americano', 'coffee', 'COFFEE', '美式咖啡', 'Caffè Americano', 'meishikafei', 'mskf', '以双份意式浓缩加入热水稀释而成的黑咖啡，保留浓缩的烘焙香与油脂，同时降低浓度并增大杯量，口感比浓缩更轻盈。', 'V6 标准为双份浓缩 36 克加 120 毫升热水。先加热水再加入浓缩可更完整保留表面油脂。', '/assets/images/posters/coffee-americano-hero.webp', '/assets/images/posters/coffee-americano-hero.webp', 96, 3, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 3.0}, {"key": "BODY", "label": "醇厚度", "score": 4.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "黑咖啡", "浓缩基底", "无乳配方", "中等酒体", "日常"]', '["日常"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 120, "unit": "ml", "role": "88-94°C"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}]', '["预热容量不低于 180 毫升的杯子。", "向杯中加入 120 毫升、88-94°C 的热水。", "按意式浓缩标准萃取 36 克双份浓缩咖啡液。", "将浓缩缓慢倒入热水中，避免剧烈搅动。", "轻搅一次后立即饮用。"]', '["美式", "Americano", "热美式"]', 'A', '2026-08-04', 1, '{"id": "coffee-americano", "mode": "coffee", "category": "COFFEE", "nameZh": "美式咖啡", "nameEn": "Caffè Americano", "intro": "以双份意式浓缩加入热水稀释而成的黑咖啡，保留浓缩的烘焙香与油脂，同时降低浓度并增大杯量，口感比浓缩更轻盈。", "imageUrl": "/assets/images/posters/coffee-americano-hero.webp", "tags": ["热饮", "黑咖啡", "浓缩基底", "无乳配方", "中等酒体", "日常"], "scene": ["日常"], "recommendationScore": 96, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-long-black', 'coffee', 'COFFEE', '长美式', 'Long Black', 'zhangmeishi', 'zms', '先注入双份浓缩再加入热水的黑咖啡，与美式相比油脂层保留更完整、浓度略高，呈现浓郁烘焙香与干净的余味。', 'V6 标准为双份浓缩 36 毫升先入杯，再加热水至约 160 毫升，油脂层更明显。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Long%20Black%20Coffee.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Long%20Black%20Coffee.jpg', 96, 4, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 3.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "黑咖啡", "浓缩基底", "无乳配方", "中等酒体", "日常"]', '["日常"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 124, "unit": "ml", "role": "88-94°C"}]', '["预热容量不低于 200 毫升的玻璃杯。", "先向杯中注入 36 克双份浓缩咖啡液，保留表面油脂。", "沿杯壁缓缓加入 124 毫升、88-94°C 的热水。", "避免搅动以维持油脂完整，如需饮用再轻搅。", "趁热饮用，感受油脂与咖啡液的层次。"]', '["Long Black", "长黑", "澳洲长黑"]', 'B', '2026-08-04', 1, '{"id": "coffee-long-black", "mode": "coffee", "category": "COFFEE", "nameZh": "长美式", "nameEn": "Long Black", "intro": "先注入双份浓缩再加入热水的黑咖啡，与美式相比油脂层保留更完整、浓度略高，呈现浓郁烘焙香与干净的余味。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Long%20Black%20Coffee.jpg", "tags": ["热饮", "黑咖啡", "浓缩基底", "无乳配方", "中等酒体", "日常"], "scene": ["日常"], "recommendationScore": 96, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-latte', 'coffee', 'COFFEE', '拿铁', 'Latte', 'natie', 'nt', '以双份浓缩为基底，加入大量蒸热牛奶与薄层奶泡的奶咖，奶香柔和、口感顺滑，是奶味最突出的经典意式饮品。', 'V6 标准为双份浓缩 36 克加热牛奶 180 毫升与约 1 厘米奶泡，奶咖比约 1 比 5。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 96, 5, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["奶咖", "热饮", "奶油感", "顺滑", "日常", "早午餐"]', '["日常", "早午餐"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "早午餐"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "蒸热至 60-65°C"}]', '["萃取 36 克双份浓缩咖啡液注入预热的大杯。", "将 180 毫升全脂牛奶蒸热至 60-65°C，打出细密奶泡。", "先倒入 120 g 牛奶，轻晃杯子使奶咖混合。", "将剩余 60 g 牛奶与奶泡沿杯缘注入，形成约 1 厘米奶泡层。", "按喜好做简单拉花后立即饮用。"]', '["Caffè latte", "咖啡拿铁", "牛奶咖啡"]', 'A', '2026-08-04', 1, '{"id": "coffee-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "拿铁", "nameEn": "Latte", "intro": "以双份浓缩为基底，加入大量蒸热牛奶与薄层奶泡的奶咖，奶香柔和、口感顺滑，是奶味最突出的经典意式饮品。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["奶咖", "热饮", "奶油感", "顺滑", "日常", "早午餐"], "scene": ["日常", "早午餐"], "recommendationScore": 96, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cappuccino', 'coffee', 'COFFEE', '卡布奇诺', 'Cappuccino', 'kabuqinuo', 'kbqn', '由浓缩、蒸奶与绵密奶泡各占约三分之一组成的奶咖，奶泡厚而干爽，咖啡香与奶香层次分明，口感绵密。', 'V6 标准为双份浓缩 36 克、牛奶 60 毫升与厚奶泡，泡体丰盈可直接呈勺。', '/assets/images/posters/coffee-cappuccino-hero.webp', '/assets/images/posters/coffee-cappuccino-hero.webp', 96, 6, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["奶咖", "热饮", "泡沫质地", "奶油感", "经典", "早午餐"]', '["经典", "早午餐"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "早午餐"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 120, "unit": "ml", "role": "其中 60 毫升蒸热，余下打成奶泡"}]', '["萃取 36 克双份浓缩咖啡液注入预热的中杯。", "将 120 毫升全脂牛奶蒸热，打出绵密厚实的奶泡。", "先用勺挡住奶泡，把牛奶倒入浓缩中至半满。", "再舀入厚奶泡至杯满，使奶泡堆起高于杯口。", "可撒 1 g 可可粉或肉桂粉后立即饮用。"]', '["Cappuccino", "卡布", "干卡布奇诺"]', 'A', '2026-08-04', 1, '{"id": "coffee-cappuccino", "mode": "coffee", "category": "COFFEE", "nameZh": "卡布奇诺", "nameEn": "Cappuccino", "intro": "由浓缩、蒸奶与绵密奶泡各占约三分之一组成的奶咖，奶泡厚而干爽，咖啡香与奶香层次分明，口感绵密。", "imageUrl": "/assets/images/posters/coffee-cappuccino-hero.webp", "tags": ["奶咖", "热饮", "泡沫质地", "奶油感", "经典", "早午餐"], "scene": ["经典", "早午餐"], "recommendationScore": 96, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-flat-white', 'coffee', 'COFFEE', '馥芮白', 'Flat White', 'furuibai', 'frb', '以双份浓缩与细滑微泡牛奶组成的小杯奶咖，奶泡极薄、奶量少于拿铁，突出咖啡本身风味，口感柔和顺滑。', 'V6 标准为双份浓缩 36 克加热牛奶 150 毫升，薄奶泡约 3-5 毫米，拉花细腻。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Flat%20white.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Flat%20white.jpg', 96, 7, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["奶咖", "热饮", "顺滑", "奶油感", "早午餐", "下午茶"]', '["早午餐", "下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐", "下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 150, "unit": "ml", "role": "蒸热至 55-60°C 打出微泡"}]', '["萃取 36 克双份浓缩咖啡液注入预热的小杯。", "将 150 毫升全脂牛奶蒸热至 55-60°C，仅打出细小微泡。", "把牛奶与微泡一起匀速倒入浓缩中。", "以收尾点出细密奶泡，形成薄而光滑的表面。", "趁奶温合适立即饮用，无需额外装饰。"]', '["Flat White", "平白", "澳白"]', 'A', '2026-08-04', 1, '{"id": "coffee-flat-white", "mode": "coffee", "category": "COFFEE", "nameZh": "馥芮白", "nameEn": "Flat White", "intro": "以双份浓缩与细滑微泡牛奶组成的小杯奶咖，奶泡极薄、奶量少于拿铁，突出咖啡本身风味，口感柔和顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Flat%20white.jpg", "tags": ["奶咖", "热饮", "顺滑", "奶油感", "早午餐", "下午茶"], "scene": ["早午餐", "下午茶"], "recommendationScore": 96, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-mocha', 'coffee', 'COFFEE', '摩卡咖啡', 'Caffè Mocha', 'mokakafei', 'mkkf', '在拿铁基础上加入巧克力酱的甜味奶咖，咖啡、牛奶与可可风味相互融合，甜感明显、口感醇厚顺滑。', 'V6 标准为双份浓缩 36 克、巧克力酱 20 克与蒸奶 180 毫升，甜度来自巧克力。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mocha%20coffee.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mocha%20coffee.jpg', 96, 8, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["奶咖", "热饮", "甜感明显", "巧克力", "奶油感", "浓郁甜"]', '["日常", "下午茶", "节日"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶", "节日"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "巧克力糖浆", "nameEn": "Chocolate syrup", "amount": 20, "unit": "g", "role": "摩卡巧克力酱"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "蒸热至 60-65°C"}]', '["萃取 36 克双份浓缩咖啡液注入预热的大杯。", "向杯中加入 20 克巧克力酱并搅匀至完全融合。", "将 180 毫升全脂牛奶蒸热至 60-65°C，打出细密奶泡。", "把蒸奶倒入杯中，最后铺一层薄奶泡。", "可按喜好挤 10 g 打发奶油或撒 1 g 可可粉后饮用。"]', '["摩卡", "Mocha", "巧克力咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-mocha", "mode": "coffee", "category": "COFFEE", "nameZh": "摩卡咖啡", "nameEn": "Caffè Mocha", "intro": "在拿铁基础上加入巧克力酱的甜味奶咖，咖啡、牛奶与可可风味相互融合，甜感明显、口感醇厚顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mocha%20coffee.jpg", "tags": ["奶咖", "热饮", "甜感明显", "巧克力", "奶油感", "浓郁甜"], "scene": ["日常", "下午茶", "节日"], "recommendationScore": 96, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-caramel-macchiato', 'coffee', 'COFFEE', '焦糖玛奇朵', 'Caramel Macchiato', 'jiaotangmaqiduo', 'jtmqd', '以蒸热牛奶打底、淋入双份浓缩再以焦糖酱装饰的甜味奶咖，层次分明、焦糖香甜突出，口感顺滑且甜感明显。', 'V6 标准为蒸奶 180 毫升、双份浓缩 36 克与焦糖酱 20 克，与意大利传统玛奇朵配方不同。', 'https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?w=1200&q=80&auto=format&fit=crop', 96, 9, '[{"key": "ACIDITY", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 9.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["奶咖", "热饮", "甜感明显", "焦糖", "奶油感", "下午茶"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "蒸热至 60-65°C"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "焦糖糖浆", "nameEn": "Caramel syrup", "amount": 20, "unit": "g", "role": "焦糖酱"}]', '["将 180 毫升全脂牛奶蒸热至 60-65°C，打出绵密奶泡。", "把蒸奶与奶泡倒入预热的大杯至约八分满。", "沿杯壁缓缓淋入 36 克双份浓缩咖啡液，形成分层。", "在表面淋上 20 克焦糖酱，按喜好交叉装饰。", "略等分层稳定后直接饮用，饮用前可轻搅。"]', '["焦糖玛琪朵", "Caramel latte macchiato", "焦糖拿铁玛奇朵"]', 'B', '2026-08-04', 1, '{"id": "coffee-caramel-macchiato", "mode": "coffee", "category": "COFFEE", "nameZh": "焦糖玛奇朵", "nameEn": "Caramel Macchiato", "intro": "以蒸热牛奶打底、淋入双份浓缩再以焦糖酱装饰的甜味奶咖，层次分明、焦糖香甜突出，口感顺滑且甜感明显。", "imageUrl": "https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?w=1200&q=80&auto=format&fit=crop", "tags": ["奶咖", "热饮", "甜感明显", "焦糖", "奶油感", "下午茶"], "scene": ["下午茶"], "recommendationScore": 96, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-vanilla-latte', 'coffee', 'COFFEE', '香草拿铁', 'Vanilla Latte', 'xiangcaonatie', 'xcnt', '在拿铁中加入香草糖浆的甜味奶咖，奶香顺滑、带有柔和香草香气与适中甜感，是接受度很高的经典口味。', 'V6 标准为双份浓缩 36 克、香草糖浆 15 克与蒸奶 180 毫升，糖浆甜度约四分之一。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Vanilla%20Latte%20%285339583568%29.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Vanilla%20Latte%20%285339583568%29.jpg', 96, 10, '[{"key": "ACIDITY", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["奶咖", "热饮", "甜感明显", "香草", "奶油感", "下午茶"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 15, "unit": "g", "role": "香草糖浆"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "蒸热至 60-65°C"}]', '["向预热的大杯中挤入 15 克香草糖浆。", "萃取 36 克双份浓缩咖啡液，与糖浆搅匀。", "将 180 毫升全脂牛奶蒸热至 60-65°C，打出薄奶泡。", "把蒸奶倒入杯中，收尾铺出薄奶泡层。", "可按喜好做简单拉花后立即饮用。"]', '["香草咖啡拿铁", "Vanilla latte", "香草奶咖"]', 'B', '2026-08-04', 1, '{"id": "coffee-vanilla-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "香草拿铁", "nameEn": "Vanilla Latte", "intro": "在拿铁中加入香草糖浆的甜味奶咖，奶香顺滑、带有柔和香草香气与适中甜感，是接受度很高的经典口味。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Vanilla%20Latte%20%285339583568%29.jpg", "tags": ["奶咖", "热饮", "甜感明显", "香草", "奶油感", "下午茶"], "scene": ["下午茶"], "recommendationScore": 96, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-hazelnut-latte', 'coffee', 'COFFEE', '榛果拿铁', 'Hazelnut Latte', 'zhenguonatie', 'zgnt', '在拿铁中加入榛果糖浆的甜味奶咖，榛果坚果香气与蒸奶奶香充分融合，甜感适中、口感圆润顺滑。', 'V6 标准为双份浓缩 36 克、榛果糖浆 15 克与蒸奶 180 毫升，坚果风味来自糖浆。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gigi%20Coffee%20Hazelnut%20Praline%20Latte.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gigi%20Coffee%20Hazelnut%20Praline%20Latte.jpg', 93, 11, '[{"key": "ACIDITY", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["奶咖", "热饮", "甜感明显", "坚果", "奶油感", "下午茶"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "榛果糖浆", "nameEn": "Hazelnut syrup", "amount": 15, "unit": "g", "role": "榛果糖浆"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "蒸热至 60-65°C"}]', '["向预热的大杯中挤入 15 克榛果糖浆。", "萃取 36 克双份浓缩咖啡液，与糖浆搅匀。", "将 180 毫升全脂牛奶蒸热至 60-65°C，打出薄奶泡。", "把蒸奶缓慢倒入杯中，收尾铺出薄奶泡层。", "趁热饮用，保持坚果香与奶香的融合。"]', '["榛果奶咖", "Hazelnut latte", "榛子拿铁"]', 'B', '2026-08-04', 1, '{"id": "coffee-hazelnut-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "榛果拿铁", "nameEn": "Hazelnut Latte", "intro": "在拿铁中加入榛果糖浆的甜味奶咖，榛果坚果香气与蒸奶奶香充分融合，甜感适中、口感圆润顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Gigi%20Coffee%20Hazelnut%20Praline%20Latte.jpg", "tags": ["奶咖", "热饮", "甜感明显", "坚果", "奶油感", "下午茶"], "scene": ["下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-oat-latte', 'coffee', 'COFFEE', '燕麦拿铁', 'Oat Milk Latte', 'yanmainatie', 'ymnt', '以燕麦奶替代牛奶的奶咖，口感顺滑略带谷物甜香，适合乳糖不耐受与纯素人群，咖啡风味依然清晰。', 'V6 标准为双份浓缩 36 克加燕麦奶 180 毫升，燕麦奶选可打发型以形成奶泡。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Oat%20Milk%20Latte.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Oat%20Milk%20Latte.jpg', 93, 12, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["奶咖", "热饮", "纯素", "奶油感", "顺滑", "无乳配方"]', '["日常", "下午茶"]', '{"coffeeType": "奶咖", "milk": "燕麦奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 克咖啡粉萃取"}, {"nameZh": "燕麦奶", "nameEn": "Oat milk", "amount": 180, "unit": "ml", "role": "蒸热至 60-65°C"}]', '["萃取 36 克双份浓缩咖啡液注入预热的大杯。", "将 180 毫升燕麦奶蒸热至 60-65°C，打出细密奶泡。", "把燕麦奶缓缓倒入浓缩中，与咖啡融合。", "收尾铺出薄奶泡层，按喜好做简单拉花。", "趁热饮用，燕麦奶冷却较快需尽快享用。"]', '["燕麦奶拿铁", "Oat latte", "植物奶拿铁"]', 'B', '2026-08-04', 1, '{"id": "coffee-oat-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "燕麦拿铁", "nameEn": "Oat Milk Latte", "intro": "以燕麦奶替代牛奶的奶咖，口感顺滑略带谷物甜香，适合乳糖不耐受与纯素人群，咖啡风味依然清晰。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Oat%20Milk%20Latte.jpg", "tags": ["奶咖", "热饮", "纯素", "奶油感", "顺滑", "无乳配方"], "scene": ["日常", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "奶咖", "milk": "燕麦奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-soy-latte', 'coffee', 'COFFEE', '豆奶拿铁', 'Soy Latte', 'dounainatie', 'dnnt', '以意式浓缩与豆奶调和的植物基奶咖，豆香与咖啡烘焙香并重，口感顺滑，不含牛奶成分。', 'V6 标准使用 36 g 双份浓缩和 180 g 豆奶。豆奶的蛋白质和脂肪含量低于全脂牛奶，起泡较弱，表面泡沫更薄，过敏原按 SOY 记录。', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Soy_Vanilla_Chai_Latte_at_G.S.T._Bean.jpg', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Soy_Vanilla_Chai_Latte_at_G.S.T._Bean.jpg', 97, 13, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["奶咖", "热饮", "浓缩基底", "奶油感", "纯素", "无乳配方", "日常", "甜感明显"]', '["日常"]', '{"coffeeType": "奶咖", "milk": "豆奶", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "豆奶", "nameEn": "Soy milk", "amount": 180, "unit": "g", "role": "冷藏豆奶"}]', '["预热容量约 240 ml 的杯子。", "萃取 36 g 双份意式浓缩至杯中。", "将 180 g 冷藏豆奶加热至 55–65°C，并轻打入细薄泡沫。", "轻敲并旋转奶缸，使豆奶与泡沫均匀融合。", "将豆奶缓慢注入浓缩，表面保留薄层泡沫。", "立即饮用。"]', '["豆奶咖啡拿铁", "豆浆拿铁", "Soy Latte"]', 'A', '2026-08-04', 1, '{"id": "coffee-soy-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "豆奶拿铁", "nameEn": "Soy Latte", "intro": "以意式浓缩与豆奶调和的植物基奶咖，豆香与咖啡烘焙香并重，口感顺滑，不含牛奶成分。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/89/Soy_Vanilla_Chai_Latte_at_G.S.T._Bean.jpg", "tags": ["奶咖", "热饮", "浓缩基底", "奶油感", "纯素", "无乳配方", "日常", "甜感明显"], "scene": ["日常"], "recommendationScore": 97, "attributes": {"coffeeType": "奶咖", "milk": "豆奶", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-almond-latte', 'coffee', 'COFFEE', '杏仁拿铁', 'Almond Milk Latte', 'xingrennatie', 'xrnt', '以意式浓缩与杏仁奶调和的植物基奶咖，坚果甜香突出、苦感柔和，口感轻盈顺滑，不含牛奶成分。', 'V6 标准使用 36 g 双份浓缩和 180 g 杏仁奶。杏仁奶脂肪与蛋白质含量低，几乎不起泡，表面无奶泡层，过敏原按 TREE_NUTS 记录。', 'https://images.unsplash.com/photo-1601436423474-51738541c1b1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1601436423474-51738541c1b1?w=1200&q=80&auto=format&fit=crop', 95, 14, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["奶咖", "热饮", "浓缩基底", "坚果", "奶油感", "纯素", "无乳配方"]', '["日常", "下午茶", "节日"]', '{"coffeeType": "奶咖", "milk": "杏仁奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶", "节日"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "杏仁奶", "nameEn": "Almond milk", "amount": 180, "unit": "g", "role": "冷藏杏仁奶"}]', '["预热容量约 240 ml 的杯子。", "萃取 36 g 双份意式浓缩至杯中。", "将 180 g 冷藏杏仁奶加热至 55–65°C，杏仁奶几乎不起泡，仅轻微打发。", "轻敲奶缸消除大气泡。", "将杏仁奶注入浓缩并轻搅均匀。", "立即饮用。"]', '["杏仁奶拿铁", "巴旦木拿铁", "Almond Latte"]', 'A', '2026-08-04', 1, '{"id": "coffee-almond-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "杏仁拿铁", "nameEn": "Almond Milk Latte", "intro": "以意式浓缩与杏仁奶调和的植物基奶咖，坚果甜香突出、苦感柔和，口感轻盈顺滑，不含牛奶成分。", "imageUrl": "https://images.unsplash.com/photo-1601436423474-51738541c1b1?w=1200&q=80&auto=format&fit=crop", "tags": ["奶咖", "热饮", "浓缩基底", "坚果", "奶油感", "纯素", "无乳配方"], "scene": ["日常", "下午茶", "节日"], "recommendationScore": 95, "attributes": {"coffeeType": "奶咖", "milk": "杏仁奶", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-coconut-latte', 'coffee', 'COFFEE', '椰奶拿铁', 'Coconut Milk Latte', 'yenainatie', 'ynnt', '以意式浓缩与椰奶调和的植物基奶咖，椰香与热带甜感明显、咖啡苦感被乳化柔化，不含牛奶成分。', 'V6 标准使用 36 g 双份浓缩和 180 g 椰奶。椰奶脂肪较高、口感偏润，起泡能力弱于牛奶，过敏原按 COCONUT 记录。', 'https://upload.wikimedia.org/wikipedia/commons/6/64/Alfajor_de_maicena_and_a_latte.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/64/Alfajor_de_maicena_and_a_latte.jpg', 97, 15, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 9.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["奶咖", "热饮", "浓缩基底", "椰子", "奶油感", "纯素", "无乳配方", "甜感明显"]', '["日常", "下午茶", "节日"]', '{"coffeeType": "奶咖", "milk": "椰奶", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶", "节日"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "椰奶", "nameEn": "Coconut milk", "amount": 180, "unit": "g", "role": "冷藏椰奶"}]', '["预热容量约 240 ml 的杯子。", "萃取 36 g 双份意式浓缩至杯中。", "将 180 g 冷藏椰奶加热至 55–65°C，椰奶起泡较弱，轻微打发即可。", "轻敲奶缸使椰奶质地均匀。", "将椰奶缓慢注入浓缩并轻搅。", "立即饮用。"]', '["椰奶拿铁咖啡", "椰浆拿铁", "Coconut Latte"]', 'A', '2026-08-04', 1, '{"id": "coffee-coconut-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "椰奶拿铁", "nameEn": "Coconut Milk Latte", "intro": "以意式浓缩与椰奶调和的植物基奶咖，椰香与热带甜感明显、咖啡苦感被乳化柔化，不含牛奶成分。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/64/Alfajor_de_maicena_and_a_latte.jpg", "tags": ["奶咖", "热饮", "浓缩基底", "椰子", "奶油感", "纯素", "无乳配方", "甜感明显"], "scene": ["日常", "下午茶", "节日"], "recommendationScore": 97, "attributes": {"coffeeType": "奶咖", "milk": "椰奶", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-pour-over', 'coffee', 'COFFEE', '手冲咖啡', 'Pour Over Coffee', 'shouchongkafei', 'sckf', '用细嘴壶在滤杯上分次注水萃取的黑咖啡，风味干净、层次清晰，突出产地与烘焙特征，常搭配浅度烘焙。', 'V6 标准为 15 g 咖啡粉配 240 ml 热水，总冲煮时间约 2 分半至 3 分钟。注水节奏和研磨度会显著改变萃取率，属 V6 编辑标准化配方，用于统一检索与比较。', 'https://upload.wikimedia.org/wikipedia/commons/4/4d/Caf%C3%A9_coado.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4d/Caf%C3%A9_coado.jpg', 95, 16, '[{"key": "ACIDITY", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["手冲过滤", "手冲", "黑咖啡", "热饮", "无乳配方", "轻盈", "经典"]', '["经典"]', '{"coffeeType": "手冲过滤", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}', '[{"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "92–96°C"}]', '["将滤纸放入滤杯并用热水冲洗预热。", "称取 15 g 咖啡豆，中细研磨后倒入滤杯并轻摇平整。", "注入约 40 ml、92–96°C 热水闷蒸约 30 秒。", "分两至三段缓慢注水至总水量 240 ml，保持液面平稳。", "待滤液滴尽后移走滤杯，立即饮用。"]', '["手冲", "手冲黑咖啡", "滴滤咖啡", "Pour Over"]', 'A', '2026-08-04', 1, '{"id": "coffee-pour-over", "mode": "coffee", "category": "COFFEE", "nameZh": "手冲咖啡", "nameEn": "Pour Over Coffee", "intro": "用细嘴壶在滤杯上分次注水萃取的黑咖啡，风味干净、层次清晰，突出产地与烘焙特征，常搭配浅度烘焙。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/4d/Caf%C3%A9_coado.jpg", "tags": ["手冲过滤", "手冲", "黑咖啡", "热饮", "无乳配方", "轻盈", "经典"], "scene": ["经典"], "recommendationScore": 95, "attributes": {"coffeeType": "手冲过滤", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-siphon', 'coffee', 'COFFEE', '虹吸咖啡', 'Siphon Coffee', 'hongxikafei', 'hxkf', '利用真空虹吸原理在水温稳定的环境中浸泡萃取的咖啡，口感干净顺滑，香气细腻，适合展现花果调性。', 'V6 标准为 18 g 咖啡粉配 240 ml 水，浸泡约 60 秒后经真空回流过滤。虹吸的全程浸泡与水温恒定使其萃取偏均衡，属 V6 编辑标准化配方。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg', 97, 17, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["浸泡", "黑咖啡", "热饮", "无乳配方", "中等酒体", "顺滑", "花香", "经典"]', '["经典"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 18, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "90–94°C"}]', '["将 240 ml 过滤水倒入下壶并安装好滤芯。", "点燃热源加热下壶，待水柱被推入上壶后转小火。", "倒入 18 g 中细研磨咖啡粉并搅拌使其完全浸湿。", "保持浸泡约 60 秒后熄火。", "咖啡液经真空回流滤入下壶，立即倒出饮用。"]', '["虹吸壶咖啡", "真空咖啡", "Syphon Coffee"]', 'A', '2026-08-04', 1, '{"id": "coffee-siphon", "mode": "coffee", "category": "COFFEE", "nameZh": "虹吸咖啡", "nameEn": "Siphon Coffee", "intro": "利用真空虹吸原理在水温稳定的环境中浸泡萃取的咖啡，口感干净顺滑，香气细腻，适合展现花果调性。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg", "tags": ["浸泡", "黑咖啡", "热饮", "无乳配方", "中等酒体", "顺滑", "花香", "经典"], "scene": ["经典"], "recommendationScore": 97, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-french-press', 'coffee', 'COFFEE', '法压咖啡', 'French Press Coffee', 'fayakafei', 'fykf', '以粗研磨咖啡粉在热水中浸泡数分钟后压滤成杯的咖啡，醇厚度高、油脂感明显，做法简单无需滤纸。', 'V6 标准为 18 g 咖啡粉配 240 ml 热水，浸泡 4 分钟后压滤。金属滤网会保留细粉和咖啡油脂，口感比纸滤更厚重，属 V6 编辑标准化配方。', 'https://upload.wikimedia.org/wikipedia/commons/4/41/French_Press_coffee_making_03.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/41/French_Press_coffee_making_03.jpg', 97, 18, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 9.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["法压", "浸泡", "黑咖啡", "热饮", "无乳配方", "醇厚/酒体饱满", "泥土", "经典"]', '["经典"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 18, "unit": "g", "role": "中粗研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 240, "unit": "ml", "role": "92–96°C"}]', '["将 18 g 中粗研磨咖啡粉倒入法压壶。", "注入 240 ml、92–96°C 热水并搅拌使咖啡粉完全湿润。", "加盖静置浸泡约 4 分钟。", "缓慢下压压杆至底部，避免滤网翘起。", "立即倒出饮用，避免过度萃取。"]', '["法压壶咖啡", "法式压滤咖啡", "French Press"]', 'A', '2026-08-04', 1, '{"id": "coffee-french-press", "mode": "coffee", "category": "COFFEE", "nameZh": "法压咖啡", "nameEn": "French Press Coffee", "intro": "以粗研磨咖啡粉在热水中浸泡数分钟后压滤成杯的咖啡，醇厚度高、油脂感明显，做法简单无需滤纸。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/4/41/French_Press_coffee_making_03.jpg", "tags": ["法压", "浸泡", "黑咖啡", "热饮", "无乳配方", "醇厚/酒体饱满", "泥土", "经典"], "scene": ["经典"], "recommendationScore": 97, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-aeropress', 'coffee', 'COFFEE', '爱乐压咖啡', 'AeroPress Coffee', 'aileyakafei', 'alykf', '用气压将浸泡后的咖啡液压过滤纸的一次性冲煮咖啡，兼具浸泡与过滤特点，出品快、易清洗、口感干净。', 'V6 标准以倒置法使用 15 g 咖啡粉配 180 ml 水，浸泡 60 秒后压滤 20–30 秒。爱乐压可通过研磨度、水温与浸泡时间大幅调整风格，属 V6 编辑标准化配方。', 'https://images.unsplash.com/photo-1666950030199-d68343ea5a9a?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1666950030199-d68343ea5a9a?w=1200&q=80&auto=format&fit=crop', 97, 19, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["爱乐压", "黑咖啡", "热饮", "无乳配方", "顺滑", "中等酒体", "快速制作", "新手友好"]', '["新手友好"]', '{"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["新手友好"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 15, "unit": "g", "role": "中细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 180, "unit": "ml", "role": "88–92°C"}]', '["将滤纸放入滤盖并冲洗预热。", "以倒置法组装爱乐压，加入 15 g 中细研磨咖啡粉。", "注入 180 ml、88–92°C 热水并搅拌约 10 秒。", "浸泡约 60 秒后翻转，缓慢下压约 20–30 秒。", "取下压筒，倒入杯中立即饮用。"]', '["爱乐压", "AeroPress", "爱乐压咖啡"]', 'A', '2026-08-04', 1, '{"id": "coffee-aeropress", "mode": "coffee", "category": "COFFEE", "nameZh": "爱乐压咖啡", "nameEn": "AeroPress Coffee", "intro": "用气压将浸泡后的咖啡液压过滤纸的一次性冲煮咖啡，兼具浸泡与过滤特点，出品快、易清洗、口感干净。", "imageUrl": "https://images.unsplash.com/photo-1666950030199-d68343ea5a9a?w=1200&q=80&auto=format&fit=crop", "tags": ["爱乐压", "黑咖啡", "热饮", "无乳配方", "顺滑", "中等酒体", "快速制作", "新手友好"], "scene": ["新手友好"], "recommendationScore": 97, "attributes": {"coffeeType": "黑咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cold-brew', 'coffee', 'COFFEE', '冷萃咖啡', 'Cold Brew Coffee', 'lengcuikafei', 'lckf', '使用室温或冷水长时间浸泡粗研磨咖啡制成的冷咖啡，通常更圆润、苦感较低，可直接饮用或加冰。', 'V6 样例以 60 g 咖啡和 300 g 水制得浓缩液，浸泡约 12 小时，再以 120 ml 浓缩液、80 ml 水和 80 g 冰组成一杯。咖啡水比与接触时间会影响浓度与咖啡因。', '/assets/images/posters/coffee-cold-brew-hero.webp', '/assets/images/posters/coffee-cold-brew-hero.webp', 97, 20, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["冷萃", "冷饮", "黑咖啡", "无乳配方", "顺滑", "低苦", "长时间制作", "清爽"]', '["新手友好", "下午茶", "日常"]', '{"coffeeType": "冷萃", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": ["新手友好", "下午茶", "日常"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 60, "unit": "g", "role": "粗研磨"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 300, "unit": "g", "role": "浸泡用"}, {"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 120, "unit": "ml", "role": "由前两项过滤所得"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 80, "unit": "ml", "role": "稀释用"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "饮用冰"}]', '["将 60 g 咖啡豆粗研磨并放入洁净带盖容器。", "分次加入 300 g 室温过滤水，轻搅确保咖啡粉完全湿润。", "密封后在室温或冷藏环境浸泡约 12 小时。", "先用细筛过滤，再用纸滤二次过滤，得到冷萃浓缩液。", "杯中加入 80 g 冰和 80 ml 冷水。", "加入 120 ml 冷萃浓缩液并轻搅。", "未使用浓缩液应冷藏，并按食品安全规则设置保质期。"]', '["冷泡咖啡", "Cold Brew", "冷萃"]', 'A', '2026-08-04', 1, '{"id": "coffee-cold-brew", "mode": "coffee", "category": "COFFEE", "nameZh": "冷萃咖啡", "nameEn": "Cold Brew Coffee", "intro": "使用室温或冷水长时间浸泡粗研磨咖啡制成的冷咖啡，通常更圆润、苦感较低，可直接饮用或加冰。", "imageUrl": "/assets/images/posters/coffee-cold-brew-hero.webp", "tags": ["冷萃", "冷饮", "黑咖啡", "无乳配方", "顺滑", "低苦", "长时间制作", "清爽"], "scene": ["新手友好", "下午茶", "日常"], "recommendationScore": 97, "attributes": {"coffeeType": "冷萃", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-nitro-cold-brew', 'coffee', 'COFFEE', '氮气冷萃', 'Nitro Cold Brew Coffee', 'danqilengcui', 'dqlc', '以冷萃浓缩液充入氮气后从龙头打出的冷咖啡，产生绵密细腻的泡沫层，口感如奶咖般顺滑而不含奶。', 'V6 标准将 150 ml 冷萃浓缩液与 90 ml 冷过滤水混合并冷藏，再经氮气发泡装置打出。氮气产生细密泡沫与奶油般质地，不含乳成分，属 V6 编辑标准化配方。', 'https://upload.wikimedia.org/wikipedia/commons/8/8c/Hardtank_-_Logo_Black.png', 'https://upload.wikimedia.org/wikipedia/commons/8/8c/Hardtank_-_Logo_Black.png', 97, 21, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 9.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷萃", "冷饮", "黑咖啡", "无乳配方", "奶油感", "气泡感", "高咖啡因", "清爽"]', '["新手友好", "下午茶", "日常"]', '{"coffeeType": "冷萃", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": ["新手友好", "下午茶", "日常"]}', '[{"nameZh": "冷萃浓缩液", "nameEn": "Cold brew concentrate", "amount": 150, "unit": "ml", "role": "冷萃浓缩液"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 90, "unit": "ml", "role": "稀释用"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "杯中冰"}]', '["将 150 ml 冷萃浓缩液与 90 ml 冷过滤水混合，并充分冷藏至 4°C 以下。", "将稀释后的咖啡液装入已预冷的气压壶或冷萃桶。", "连接氮气气瓶并加压，使咖啡液通过发泡装置流出。", "从高位龙头接入杯中，静置至形成绵密泡沫层。", "待泡沫稳定后立即饮用，口感顺滑。"]', '["氮气咖啡", "Nitro Cold Brew", "氮气冷萃咖啡"]', 'A', '2026-08-04', 1, '{"id": "coffee-nitro-cold-brew", "mode": "coffee", "category": "COFFEE", "nameZh": "氮气冷萃", "nameEn": "Nitro Cold Brew Coffee", "intro": "以冷萃浓缩液充入氮气后从龙头打出的冷咖啡，产生绵密细腻的泡沫层，口感如奶咖般顺滑而不含奶。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/8/8c/Hardtank_-_Logo_Black.png", "tags": ["冷萃", "冷饮", "黑咖啡", "无乳配方", "奶油感", "气泡感", "高咖啡因", "清爽"], "scene": ["新手友好", "下午茶", "日常"], "recommendationScore": 97, "attributes": {"coffeeType": "冷萃", "milk": "无奶", "sweetBitter": "微甜低苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-iced-americano', 'coffee', 'COFFEE', '冰美式', 'Iced Americano', 'bingmeishi', 'bms', '以双份意式浓缩、冰水和冰块组成的冷黑咖啡，烘焙香清晰、浓度较低，比热美式更冰爽解腻。', 'V6 标准为 36 g 双份浓缩加 120 ml 冷水和 80 g 冰。先加冰水再倒入浓缩可更好保留表面油脂；冰块融化会进一步稀释，需在产品中说明冰块规格。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20americano.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20americano.jpg', 97, 22, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 3.0}, {"key": "BODY", "label": "醇厚度", "score": 4.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "浓缩基底", "黑咖啡", "无乳配方", "低糖", "清爽", "快速制作", "夏季"]', '["夏季"]', '{"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "冷过滤水", "nameEn": "Cold filtered water", "amount": 120, "unit": "ml", "role": "冷水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 80, "unit": "g", "role": "杯中冰"}]', '["在杯中放入 80 g 冰块。", "加入 120 ml 冷过滤水。", "萃取 36 g 双份意式浓缩。", "将浓缩缓慢倒入冰水中，保持表面油脂完整。", "轻搅一次后立即饮用。"]', '["冰美式咖啡", "冷美式", "Iced Americano"]', 'A', '2026-08-04', 1, '{"id": "coffee-iced-americano", "mode": "coffee", "category": "COFFEE", "nameZh": "冰美式", "nameEn": "Iced Americano", "intro": "以双份意式浓缩、冰水和冰块组成的冷黑咖啡，烘焙香清晰、浓度较低，比热美式更冰爽解腻。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Iced%20americano.jpg", "tags": ["冷饮", "浓缩基底", "黑咖啡", "无乳配方", "低糖", "清爽", "快速制作", "夏季"], "scene": ["夏季"], "recommendationScore": 97, "attributes": {"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-iced-latte', 'coffee', 'COFFEE', '冰拿铁', 'Iced Latte', 'bingnatie', 'bnt', '以意式浓缩、冷藏牛奶和冰块组成的冷奶咖，乳甜明显、苦感低、口感顺滑，适合夏季饮用。', 'V6 标准为 36 g 双份浓缩、150 ml 冷藏全脂牛奶和 60 g 冰。牛奶不经蒸汽加热，保持冷藏温度，口感更清爽，过敏原按 MILK 记录。', 'https://upload.wikimedia.org/wikipedia/commons/e/ee/KFC_iced_orange_creamy_sparkling_latte.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/ee/KFC_iced_orange_creamy_sparkling_latte.jpg', 95, 23, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["冷饮", "奶咖", "浓缩基底", "奶油感", "甜感明显", "含咖啡因", "早午餐"]', '["早午餐"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 150, "unit": "ml", "role": "冷藏全脂牛奶"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "杯中冰"}]', '["在杯中放入约 60 g 冰块。", "加入 150 ml 冷藏全脂牛奶。", "萃取 36 g 双份意式浓缩。", "将浓缩缓慢倒在牛奶与冰块之上。", "轻搅一次使混合均匀后饮用。"]', '["冰拿铁咖啡", "冷拿铁", "Iced Caffè Latte"]', 'A', '2026-08-04', 1, '{"id": "coffee-iced-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "冰拿铁", "nameEn": "Iced Latte", "intro": "以意式浓缩、冷藏牛奶和冰块组成的冷奶咖，乳甜明显、苦感低、口感顺滑，适合夏季饮用。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/ee/KFC_iced_orange_creamy_sparkling_latte.jpg", "tags": ["冷饮", "奶咖", "浓缩基底", "奶油感", "甜感明显", "含咖啡因", "早午餐"], "scene": ["早午餐"], "recommendationScore": 95, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-iced-cappuccino', 'coffee', 'COFFEE', '冰卡布奇诺', 'Iced Cappuccino', 'bingkabuqinuo', 'bkbqn', '以意式浓缩、冷藏牛奶和冰组成的冷奶咖，奶泡与咖啡比例接近经典卡布奇诺，口感绵密偏浓郁。', 'V6 标准为 36 g 双份浓缩、130 ml 冷藏全脂牛奶和 60 g 冰，顶部铺冷奶泡。与热卡布奇诺相比奶泡冷制、更轻盈，过敏原按 MILK 记录。', 'https://upload.wikimedia.org/wikipedia/commons/2/22/Cappuccino_Freddo_-_Milos_2025-08-11.jpg', 'https://upload.wikimedia.org/wikipedia/commons/2/22/Cappuccino_Freddo_-_Milos_2025-08-11.jpg', 95, 24, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["冷饮", "奶咖", "浓缩基底", "奶油感", "泡沫质地", "含咖啡因", "夏季"]', '["夏季"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 130, "unit": "ml", "role": "冷藏全脂牛奶"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "杯中冰"}]', '["在杯中放入约 60 g 冰块。", "加入 130 ml 冷藏全脂牛奶。", "萃取 36 g 双份意式浓缩。", "取部分冷藏牛奶打发成冷奶泡，铺在液面。", "轻搅杯体后饮用，保留顶部奶泡。"]', '["冰卡布", "冷卡布奇诺", "Iced Cappuccino"]', 'A', '2026-08-04', 1, '{"id": "coffee-iced-cappuccino", "mode": "coffee", "category": "COFFEE", "nameZh": "冰卡布奇诺", "nameEn": "Iced Cappuccino", "intro": "以意式浓缩、冷藏牛奶和冰组成的冷奶咖，奶泡与咖啡比例接近经典卡布奇诺，口感绵密偏浓郁。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/2/22/Cappuccino_Freddo_-_Milos_2025-08-11.jpg", "tags": ["冷饮", "奶咖", "浓缩基底", "奶油感", "泡沫质地", "含咖啡因", "夏季"], "scene": ["夏季"], "recommendationScore": 95, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-iced-mocha', 'coffee', 'COFFEE', '冰摩卡', 'Iced Mocha', 'bingmoka', 'bmk', '以双份浓缩、牛奶与巧克力糖浆加冰块组合成的冷奶咖，兼具咖啡苦香与可可甜感，口感顺滑。', 'V6 标准为双份浓缩 36 g、巧克力糖浆 20 ml 与全脂奶 180 ml，加冰冷却。不同品牌糖浆甜度与浓稠度有差异，用量可在此基础上微调，该配比为统一比较用的编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mocha%20coffee.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mocha%20coffee.jpg', 93, 25, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 5.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["冷饮", "奶咖", "巧克力", "甜感明显", "奶油感", "含咖啡因"]', '["日常", "夏季", "下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["日常", "夏季", "下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩，现萃"}, {"nameZh": "巧克力糖浆", "nameEn": "Chocolate syrup", "amount": 20, "unit": "ml", "role": "可可基底甜味"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "可换燕麦奶等植物奶"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 6, "unit": "g", "role": "约 180 g，装入杯中"}]', '["按意式浓缩标准萃取 36 g 双份浓缩。", "在杯底加入 20 ml 巧克力糖浆并倒入浓缩搅匀。", "向杯中装满冰块。", "缓缓倒入 180 ml 冷牛奶，使其与浓缩分层。", "轻搅一次后立即饮用。"]', '["冰巧克力摩卡", "Iced Mocha Latte"]', 'A', '2026-08-04', 1, '{"id": "coffee-iced-mocha", "mode": "coffee", "category": "COFFEE", "nameZh": "冰摩卡", "nameEn": "Iced Mocha", "intro": "以双份浓缩、牛奶与巧克力糖浆加冰块组合成的冷奶咖，兼具咖啡苦香与可可甜感，口感顺滑。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Mocha%20coffee.jpg", "tags": ["冷饮", "奶咖", "巧克力", "甜感明显", "奶油感", "含咖啡因"], "scene": ["日常", "夏季", "下午茶"], "recommendationScore": 93, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-affogato', 'coffee', 'COFFEE', '阿芙佳朵', 'Affogato', 'afujiaduo', 'afjd', '将热浓缩直接淋在乳脂甜味基底上制成的咖啡甜品，浓缩苦香与乳脂甜感交融，冷热并存的甜点式咖啡。', 'V6 标准以 40 g 稀奶油与香草糖浆构成顺滑乳脂基底，再淋上 36 g 热浓缩。传统做法配香草冰淇淋，本条目以乳脂基底标准化以便统一比较，属于编辑调整。', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Affogato.JPG', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Affogato.JPG', 97, 26, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "甜感明显", "香草", "奶油感", "餐后", "含咖啡因", "风味咖啡", "奶咖"]', '["餐后"]', '{"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩，现萃"}, {"nameZh": "稀奶油", "nameEn": "Heavy cream", "amount": 40, "unit": "g", "role": "乳脂基底"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 10, "unit": "ml", "role": "香草风味"}]', '["在杯中放入 40 g 稀奶油与 10 ml 香草糖浆拌匀。", "按意式浓缩标准萃取 36 g 双份浓缩。", "将热浓缩沿杯壁缓缓淋在乳脂基底上。", "静置片刻让油脂与乳脂融合，趁温热用勺舀食。"]', '["浓缩咖啡冰淇淋", "Affogato al caffè"]', 'A', '2026-08-04', 1, '{"id": "coffee-affogato", "mode": "coffee", "category": "COFFEE", "nameZh": "阿芙佳朵", "nameEn": "Affogato", "intro": "将热浓缩直接淋在乳脂甜味基底上制成的咖啡甜品，浓缩苦香与乳脂甜感交融，冷热并存的甜点式咖啡。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/1/19/Affogato.JPG", "tags": ["热饮", "甜感明显", "香草", "奶油感", "餐后", "含咖啡因", "风味咖啡", "奶咖"], "scene": ["餐后"], "recommendationScore": 97, "attributes": {"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-espresso-tonic', 'coffee', 'COFFEE', '浓缩汤力水', 'Espresso Tonic', 'nongsuotanglishui', 'nstls', '以汤力水的气泡与微甜中和浓缩苦感形成的冷咖啡饮，口感明亮清爽，是近年流行的汽泡咖啡变体。', 'V6 标准为 36 g 双份浓缩加 150 ml 冰镇汤力水。先加汤力水后淋浓缩可保留表面油脂泡沫；汤力水含糖量与气泡度因品牌而异，该配比是统一比较用的编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20tonic.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20tonic.jpg', 97, 27, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 4.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["冷饮", "气泡感", "清爽", "轻盈", "夏季", "含咖啡因", "无乳配方", "浓缩基底"]', '["夏季"]', '{"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩，现萃"}, {"nameZh": "汤力水", "nameEn": "Tonic water", "amount": 150, "unit": "ml", "role": "冰镇汤力水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 200, "unit": "g", "role": "约 150 g，装满杯"}]', '["将冰块装满高杯并倒入 150 ml 冰镇汤力水。", "按意式浓缩标准萃取 36 g 双份浓缩。", "沿杯壁将热浓缩缓缓淋在汤力水上。", "让油脂泡沫留在表面，不搅动，立即饮用。"]', '["浓缩汤力", "Espresso and Tonic"]', 'A', '2026-08-04', 1, '{"id": "coffee-espresso-tonic", "mode": "coffee", "category": "COFFEE", "nameZh": "浓缩汤力水", "nameEn": "Espresso Tonic", "intro": "以汤力水的气泡与微甜中和浓缩苦感形成的冷咖啡饮，口感明亮清爽，是近年流行的汽泡咖啡变体。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20tonic.jpg", "tags": ["冷饮", "气泡感", "清爽", "轻盈", "夏季", "含咖啡因", "无乳配方", "浓缩基底"], "scene": ["夏季"], "recommendationScore": 97, "attributes": {"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-sparkling-americano', 'coffee', 'COFFEE', '气泡美式', 'Sparkling Americano', 'qipaomeishi', 'qpms', '以气泡水稀释双份浓缩形成的汽泡黑咖啡，保留浓缩的烘焙香与油脂，同时以气泡带来清爽口感。', 'V6 标准为 36 g 双份浓缩加 160 ml 冰镇气泡水。使用无糖气泡水可完整呈现咖啡风味；如用汤力水则风味偏甜，属于另一种变体。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg', 95, 28, '[{"key": "ACIDITY", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 3.0}, {"key": "BODY", "label": "醇厚度", "score": 3.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["冷饮", "气泡感", "清爽", "轻盈", "无乳配方", "夏季", "浓缩基底"]', '["夏季"]', '{"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩，现萃"}, {"nameZh": "气泡水", "nameEn": "Sparkling water", "amount": 160, "unit": "ml", "role": "冰镇无糖气泡水"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 200, "unit": "g", "role": "约 150 g，装满杯"}]', '["将冰块装满玻璃杯并倒入 160 ml 冰镇气泡水。", "按意式浓缩标准萃取 36 g 双份浓缩。", "沿杯壁缓慢倒入浓缩，保持油脂泡沫浮于表面。", "不搅动，直接饮用以体验气泡与油脂层次。"]', '["苏打美式", "Sparkling Coffee"]', 'A', '2026-08-04', 1, '{"id": "coffee-sparkling-americano", "mode": "coffee", "category": "COFFEE", "nameZh": "气泡美式", "nameEn": "Sparkling Americano", "intro": "以气泡水稀释双份浓缩形成的汽泡黑咖啡，保留浓缩的烘焙香与油脂，同时以气泡带来清爽口感。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg", "tags": ["冷饮", "气泡感", "清爽", "轻盈", "无乳配方", "夏季", "浓缩基底"], "scene": ["夏季"], "recommendationScore": 95, "attributes": {"coffeeType": "浓缩基底", "milk": "无奶", "sweetBitter": "不甜微苦", "temperature": "冰饮", "caffeine": "中等咖啡因", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cold-drip', 'coffee', 'COFFEE', '冰滴咖啡', 'Cold Drip Coffee', 'bingdikafei', 'bdkf', '以室温水在数小时内缓慢滴过咖啡粉得到的冷萃浓缩液，酸苦柔和、甜感突出，常加水或冰稀释饮用。', 'V6 标准以 60 g 中细研磨咖啡粉配 500 ml 室温水，滴滤约 6 至 8 小时，得约 400 ml 浓缩液。所得浓缩液咖啡因与浓度较高，通常按 1 比 1 加水或加冰稀释。', 'https://images.unsplash.com/photo-1549652127-2e5e59e86a7a?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1549652127-2e5e59e86a7a?w=1200&q=80&auto=format&fit=crop', 95, 29, '[{"key": "ACIDITY", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["冷饮", "冷萃", "顺滑", "低苦", "长时间制作", "含咖啡因", "无乳配方"]', '["新手友好", "下午茶", "日常"]', '{"coffeeType": "冷萃", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "冰饮", "caffeine": "高咖啡因", "scene": ["新手友好", "下午茶", "日常"]}', '[{"nameZh": "中度烘焙咖啡豆", "nameEn": "Medium roast coffee beans", "amount": 60, "unit": "g", "role": "中细研磨"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 500, "unit": "ml", "role": "滴滤用水，注入上壶"}]', '["将 60 g 中细研磨咖啡粉均匀铺入滴滤筒。", "在上壶注入 500 ml 室温过滤水，调节滴速至每秒 1 至 2 滴。", "持续滴滤 6 至 8 小时至收集壶约得 400 ml。", "取下收集壶，将浓缩液冷藏保存。", "饮用时按 1 比 1 加入冷水或冰块稀释。"]', '["水滴咖啡", "Dutch Coffee", "Cold Water Drip"]', 'A', '2026-08-04', 1, '{"id": "coffee-cold-drip", "mode": "coffee", "category": "COFFEE", "nameZh": "冰滴咖啡", "nameEn": "Cold Drip Coffee", "intro": "以室温水在数小时内缓慢滴过咖啡粉得到的冷萃浓缩液，酸苦柔和、甜感突出，常加水或冰稀释饮用。", "imageUrl": "https://images.unsplash.com/photo-1549652127-2e5e59e86a7a?w=1200&q=80&auto=format&fit=crop", "tags": ["冷饮", "冷萃", "顺滑", "低苦", "长时间制作", "含咖啡因", "无乳配方"], "scene": ["新手友好", "下午茶", "日常"], "recommendationScore": 95, "attributes": {"coffeeType": "冷萃", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "冰饮", "caffeine": "高咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-vietnamese-drip', 'coffee', 'COFFEE', '越南滴滤咖啡', 'Vietnamese Drip Coffee', 'yuenandilvkafei', 'yndlkf', '以越南滴滤壶（phin）慢滴深焙咖啡并配炼乳的越式热咖啡，苦甜交织、口感浓郁，是越南日常饮品。', 'V6 标准以 18 g 深焙咖啡粉配 100 ml 热水经 phin 壶滴滤，杯底放 20 ml 炼乳。传统常用罗布斯塔豆，苦味较明显；本配比是统一比较用的编辑标准。', 'https://images.unsplash.com/photo-1662105489808-f3dd79b7f13c?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1662105489808-f3dd79b7f13c?w=1200&q=80&auto=format&fit=crop', 97, 30, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "浓郁甜", "苦味明显", "奶油感", "经典", "含咖啡因", "地域特色咖啡", "奶咖"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 18, "unit": "g", "role": "细研磨"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 100, "unit": "ml", "role": "90 至 95°C 热水"}, {"nameZh": "炼乳", "nameEn": "Condensed milk", "amount": 20, "unit": "ml", "role": "杯底炼乳"}]', '["在杯底放入 20 ml 炼乳。", "将 18 g 细研磨咖啡粉装入 phin 壶并轻压滤片。", "先注入 30 g 热水浸润咖啡粉约 30 秒。", "再注入剩余 100 ml 热水，盖上壶盖等待滴滤完成。", "取下 phin 壶，将咖啡与炼乳充分搅匀后饮用。"]', '["越式滴滴壶咖啡", "Cà phê phin"]', 'B', '2026-08-04', 1, '{"id": "coffee-vietnamese-drip", "mode": "coffee", "category": "COFFEE", "nameZh": "越南滴滤咖啡", "nameEn": "Vietnamese Drip Coffee", "intro": "以越南滴滤壶（phin）慢滴深焙咖啡并配炼乳的越式热咖啡，苦甜交织、口感浓郁，是越南日常饮品。", "imageUrl": "https://images.unsplash.com/photo-1662105489808-f3dd79b7f13c?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "浓郁甜", "苦味明显", "奶油感", "经典", "含咖啡因", "地域特色咖啡", "奶咖"], "scene": ["经典"], "recommendationScore": 97, "attributes": {"coffeeType": "地域特色咖啡", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-turkish', 'coffee', 'COFFEE', '土耳其咖啡', 'Turkish Coffee', 'tuerqikafei', 'teqkf', '用细磨咖啡粉与水一起在铜壶中煮沸、不过滤直接饮用的传统咖啡，浓稠带细渣，是中东与巴尔干地区常见做法。', 'V6 标准以 9 g 极细咖啡粉、75 ml 水与 6 g 细砂糖在 ibrik 中两次煮沸。甜度分无糖、半糖、多糖，本配比取中等甜度，是统一比较用的编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg', 93, 31, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 9.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "苦感主导", "醇厚/酒体饱满", "泥土", "经典", "含咖啡因", "地域特色咖啡", "无乳配方"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "不甜偏苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 9, "unit": "g", "role": "极细研磨"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 75, "unit": "ml", "role": "室温水"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 6, "unit": "g", "role": "中等甜度"}]', '["在铜壶中加入 75 ml 水、9 g 极细咖啡粉与 6 g 细砂糖。", "小火加热并持续搅拌至糖与咖啡粉完全溶解。", "液面将沸时离火，静置数秒后再放回火上。", "第二次冒泡前离火，将泡沫与咖啡液倒入杯中。", "静置片刻让细渣沉底后饮用。"]', '["土式咖啡", "Türk kahvesi"]', 'B', '2026-08-04', 1, '{"id": "coffee-turkish", "mode": "coffee", "category": "COFFEE", "nameZh": "土耳其咖啡", "nameEn": "Turkish Coffee", "intro": "用细磨咖啡粉与水一起在铜壶中煮沸、不过滤直接饮用的传统咖啡，浓稠带细渣，是中东与巴尔干地区常见做法。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Espresso%20cup.jpg", "tags": ["热饮", "苦感主导", "醇厚/酒体饱满", "泥土", "经典", "含咖啡因", "地域特色咖啡", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "不甜偏苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-greek', 'coffee', 'COFFEE', '希腊咖啡', 'Greek Coffee', 'xilakafei', 'xlkf', '与土耳其咖啡同源的传统煮沸式咖啡，以细磨咖啡粉在 briki 中煮制并保留厚实泡沫，通常配一杯冷水。', 'V6 标准以 9 g 极细咖啡粉、75 ml 水与 5 g 细砂糖在 briki 中煮至起泡。糖量分无糖、中糖、多糖三档，本配比取中等，是统一比较用的编辑标准。', 'https://images.unsplash.com/photo-1495862433577-132cf20d7902?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1495862433577-132cf20d7902?w=1200&q=80&auto=format&fit=crop', 93, 32, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 9.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "苦感主导", "醇厚/酒体饱满", "顺滑", "经典", "含咖啡因", "地域特色咖啡", "无乳配方"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "微甜偏苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 9, "unit": "g", "role": "极细研磨"}, {"nameZh": "室温过滤水", "nameEn": "Room-temperature filtered water", "amount": 75, "unit": "ml", "role": "室温水"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 5, "unit": "g", "role": "中等甜度"}]', '["将 75 ml 水、9 g 极细咖啡粉与 5 g 细砂糖放入 briki。", "小火加热并搅拌至粉末完全化开。", "液面开始冒泡时立即离火，让泡沫成形。", "将泡沫与咖啡液缓缓倒入小杯。", "静置让细渣沉淀后配冷水一起饮用。"]', '["希式咖啡", "Ellinikos kafes"]', 'B', '2026-08-04', 1, '{"id": "coffee-greek", "mode": "coffee", "category": "COFFEE", "nameZh": "希腊咖啡", "nameEn": "Greek Coffee", "intro": "与土耳其咖啡同源的传统煮沸式咖啡，以细磨咖啡粉在 briki 中煮制并保留厚实泡沫，通常配一杯冷水。", "imageUrl": "https://images.unsplash.com/photo-1495862433577-132cf20d7902?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "苦感主导", "醇厚/酒体饱满", "顺滑", "经典", "含咖啡因", "地域特色咖啡", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "微甜偏苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-spanish-latte', 'coffee', 'COFFEE', '西班牙拿铁', 'Spanish Latte', 'xibanyanatie', 'xbynt', '以双份浓缩、热牛奶与炼乳组合成的甜感奶咖，较普通拿铁更甜更浓稠，是近年流行的咖啡风味。', 'V6 标准为 36 g 双份浓缩、180 ml 热牛奶与 15 ml 炼乳。炼乳同时提供甜味与浓稠质地，与普通拿铁的主要差异正在于此；配比为统一比较用的编辑标准。', 'https://upload.wikimedia.org/wikipedia/commons/e/e0/2_coffee_drinks.jpg', 'https://upload.wikimedia.org/wikipedia/commons/e/e0/2_coffee_drinks.jpg', 89, 33, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "奶咖", "甜感明显", "奶油感", "顺滑", "含咖啡因"]', '["日常", "下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["日常", "下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩，现萃"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "加热至 60 至 65°C"}, {"nameZh": "炼乳", "nameEn": "Condensed milk", "amount": 15, "unit": "ml", "role": "甜味与稠度"}]', '["按意式浓缩标准萃取 36 g 双份浓缩倒入杯中。", "将 180 ml 牛奶加热至 60 至 65°C。", "加入 15 ml 炼乳并与浓缩搅匀。", "倒入热牛奶，轻搅一次后饮用。"]', '["西班牙咖啡拿铁", "Café con Leche"]', 'A', '2026-08-04', 1, '{"id": "coffee-spanish-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "西班牙拿铁", "nameEn": "Spanish Latte", "intro": "以双份浓缩、热牛奶与炼乳组合成的甜感奶咖，较普通拿铁更甜更浓稠，是近年流行的咖啡风味。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/e/e0/2_coffee_drinks.jpg", "tags": ["热饮", "奶咖", "甜感明显", "奶油感", "顺滑", "含咖啡因"], "scene": ["日常", "下午茶"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-matcha-latte', 'coffee', 'COFFEE', '抹茶拿铁', 'Matcha Latte', 'mochanatie', 'mcnt', '以抹茶粉打发的浓浆与热牛奶结合的茶咖饮品，抹茶鲜绿带微苦，奶感顺滑，甜度适中，口感温和。', 'V6 标准以 3 g 抹茶粉加 60 ml 热水搅打成浆，再兑入 180 ml 加热牛奶。抹茶等级与牛奶类型影响苦度与口感，该配比是统一比较用的编辑标准。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Matcha%20latte.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Matcha%20latte.jpg', 93, 34, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 1.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["热饮", "草本", "奶油感", "顺滑", "日常", "含咖啡因", "茶咖", "奶咖"]', '["日常"]', '{"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "低咖啡因", "scene": ["日常"]}', '[{"nameZh": "抹茶粉", "nameEn": "Matcha powder", "amount": 3, "unit": "g", "role": "茶道级抹茶粉"}, {"nameZh": "热过滤水", "nameEn": "Hot filtered water", "amount": 60, "unit": "ml", "role": "约 80°C，不过沸"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 180, "unit": "ml", "role": "加热至 60 至 65°C"}]', '["将 3 g 抹茶粉过筛后放入碗中。", "加入 60 ml 约 80°C 热水，用茶筅快速搅打至起泡。", "将 180 ml 牛奶加热至 60 至 65°C。", "把抹茶浆倒入杯中，再注入热牛奶。", "轻搅使其融合后饮用。"]', '["抹茶牛奶", "Green Tea Latte"]', 'B', '2026-08-04', 1, '{"id": "coffee-matcha-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "抹茶拿铁", "nameEn": "Matcha Latte", "intro": "以抹茶粉打发的浓浆与热牛奶结合的茶咖饮品，抹茶鲜绿带微苦，奶感顺滑，甜度适中，口感温和。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Matcha%20latte.jpg", "tags": ["热饮", "草本", "奶油感", "顺滑", "日常", "含咖啡因", "茶咖", "奶咖"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"coffeeType": "茶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "低咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-chai-latte', 'coffee', 'COFFEE', '印度奶茶拿铁', 'Chai Latte', 'yindunaichanatie', 'ydncnt', '以浓缩咖啡、香料红茶浓缩液与蒸汽牛奶制成的茶咖饮品，茶香、咖啡烘焙香与肉桂豆蔻等香料风味并存。', 'V6 标准采用 36 g 双份浓缩、120 g 全脂牛奶与 80 ml 印度奶茶浓缩液，成品约 240 ml。红茶浓缩液以红茶液为基底并含肉桂、豆蔻等香料；实际香料配比属编辑标准化。', 'https://upload.wikimedia.org/wikipedia/commons/6/62/Almond_croissant_%2B_chai_latte_-_Heene_Road_Coffee_2026-01-20.jpg', 'https://upload.wikimedia.org/wikipedia/commons/6/62/Almond_croissant_%2B_chai_latte_-_Heene_Road_Coffee_2026-01-20.jpg', 91, 36, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "奶咖", "香料", "奶油感", "下午茶", "甜感明显", "茶咖"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 36, "unit": "g", "role": "双份浓缩"}, {"nameZh": "印度奶茶浓缩液", "nameEn": "Chai tea concentrate", "amount": 80, "unit": "ml", "role": "含肉桂与豆蔻等香料"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 120, "unit": "g", "role": "冷藏全脂牛奶"}, {"nameZh": "肉桂棒", "nameEn": "Cinnamon stick", "amount": 4, "unit": "g", "role": "约 8 cm，装饰"}]', '["预热 300 ml 高杯。", "将 80 ml 奶茶浓缩液与 120 g 全脂牛奶一同加热并打发至 55–65°C，形成均匀微泡。", "萃取 36 g 意式浓缩至杯中。", "将奶与茶液混合物注入杯中。", "以约 4 g 的肉桂棒作装饰，趁热饮用。"]', '["柴拿铁", "Chai Latte", "香料奶茶咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-chai-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "印度奶茶拿铁", "nameEn": "Chai Latte", "intro": "以浓缩咖啡、香料红茶浓缩液与蒸汽牛奶制成的茶咖饮品，茶香、咖啡烘焙香与肉桂豆蔻等香料风味并存。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/6/62/Almond_croissant_%2B_chai_latte_-_Heene_Road_Coffee_2026-01-20.jpg", "tags": ["热饮", "奶咖", "香料", "奶油感", "下午茶", "甜感明显", "茶咖"], "scene": ["下午茶"], "recommendationScore": 91, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-moka-pot', 'coffee', 'COFFEE', '摩卡壶咖啡', 'Moka Pot Coffee', 'mokahukafei', 'mkhkf', '利用蒸汽压力使热水穿过咖啡粉层在炉具上萃取的小壶咖啡，浓度介于浓缩与手冲之间，口感厚实。', 'V6 标准使用 20 g 中细研磨咖啡与 110 ml 室温水在 3 杯份摩卡壶中萃取，成品约 80 ml。摩卡壶出品介于浓缩与滴滤之间，各型号容量差异较大，需按壶型记录。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Moka%20pot.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Moka%20pot.jpg', 93, 37, '[{"key": "ACIDITY", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 5.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 8.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "摩卡壶", "醇厚/酒体饱满", "苦味明显", "经典", "日常", "浸泡式", "无乳配方"]', '["经典", "日常"]', '{"coffeeType": "浸泡式", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}', '[{"nameZh": "咖啡豆（意式配方）", "nameEn": "Coffee beans for espresso", "amount": 20, "unit": "g", "role": "中细研磨"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 110, "unit": "ml", "role": "室温水，装入下壶至安全阀下方"}]', '["将 20 g 咖啡豆中细研磨并轻装入粉碗，不压粉。", "下壶注入 110 ml 室温水，不超过安全阀。", "旋紧上下壶后置于中火加热。", "咖啡液缓慢溢出时调至小火，接近喷溅前关火。", "轻搅后倒入预热杯中饮用。"]', '["摩卡壶", "Moka Pot", "炉上意式咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-moka-pot", "mode": "coffee", "category": "COFFEE", "nameZh": "摩卡壶咖啡", "nameEn": "Moka Pot Coffee", "intro": "利用蒸汽压力使热水穿过咖啡粉层在炉具上萃取的小壶咖啡，浓度介于浓缩与手冲之间，口感厚实。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Moka%20pot.jpg", "tags": ["热饮", "摩卡壶", "醇厚/酒体饱满", "苦味明显", "经典", "日常", "浸泡式", "无乳配方"], "scene": ["经典", "日常"], "recommendationScore": 93, "attributes": {"coffeeType": "浸泡式", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-piccolo', 'coffee', 'COFFEE', '短笛咖啡', 'Piccolo Latte', 'duandikafei', 'ddkf', '以单份浓缩与少量蒸汽牛奶组成的小杯奶咖，咖啡烘焙感比拿铁更突出，容量也更小，适合喜欢浓郁咖啡感的小份量饮用。', 'V6 标准使用 18 g 单份浓缩与约 60 g 全脂牛奶，成品约 90 ml。短笛与小杯拿铁的区别主要在浓缩份数比，V6 以此配比作为检索与比较的编辑标准。', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Cream_pitcher_MET_DP208410.jpg', 'https://upload.wikimedia.org/wikipedia/commons/d/d1/Cream_pitcher_MET_DP208410.jpg', 89, 38, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "奶咖", "浓缩基底", "顺滑", "泡沫质地", "新手友好"]', '["新手友好"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "低咖啡因", "scene": ["新手友好"]}', '[{"nameZh": "浓缩咖啡液", "nameEn": "Espresso liquid", "amount": 18, "unit": "g", "role": "单份浓缩"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 60, "unit": "g", "role": "冷藏全脂牛奶"}]', '["预热 120 ml 小杯。", "萃取 18 g 单份意式浓缩至杯中。", "将 60 g 冷藏牛奶打发至 55–65°C，形成细腻微泡。", "将牛奶注入浓缩，保留约 0.5 cm 薄奶泡层。", "立即饮用。"]', '["小拿铁", "Piccolo", "短笛拿铁"]', 'A', '2026-08-04', 1, '{"id": "coffee-piccolo", "mode": "coffee", "category": "COFFEE", "nameZh": "短笛咖啡", "nameEn": "Piccolo Latte", "intro": "以单份浓缩与少量蒸汽牛奶组成的小杯奶咖，咖啡烘焙感比拿铁更突出，容量也更小，适合喜欢浓郁咖啡感的小份量饮用。", "imageUrl": "https://upload.wikimedia.org/wikipedia/commons/d/d1/Cream_pitcher_MET_DP208410.jpg", "tags": ["热饮", "奶咖", "浓缩基底", "顺滑", "泡沫质地", "新手友好"], "scene": ["新手友好"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "低咖啡因", "scene": ["新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-mexico', 'coffee', 'COFFEE', '墨西哥咖啡', 'Café de Olla', 'moxigekafei', 'mxgkf', '墨西哥传统陶罐咖啡，以瓦罐慢煮咖啡粉并加入肉桂与棕榈糖，带有明显的香料与焦糖甜味。', 'V6 采用墨西哥常见做法：浅度烘焙咖啡粉 15 g 加 240 ml 水与棕榈糖慢煮，并用肉桂棒增香。源自墨西哥民间家庭配方，非单一法定标准。', 'https://images.unsplash.com/photo-1576685880864-50b3b35f1c55?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1576685880864-50b3b35f1c55?w=1200&q=80&auto=format&fit=crop', 91, 59, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "香料", "甜感明显", "醇厚/酒体饱满", "经典", "无乳配方", "地域特色咖啡"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "浅度烘焙咖啡豆", "nameEn": "Light roast coffee beans", "amount": 15, "unit": "g", "role": "磨至粗中研磨度"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 240, "unit": "ml", "role": "常温水"}, {"nameZh": "棕榈糖", "nameEn": "Palm sugar", "amount": 20, "unit": "g", "role": "可依喜好调整"}, {"nameZh": "肉桂棒", "nameEn": "Cinnamon stick", "amount": 1, "unit": "g", "role": "约 5 cm 一段"}]', '["将粗研磨咖啡粉、棕榈糖与肉桂棒放入陶罐。", "加入常温水并置于中火加热至沸腾前。", "转小火保持微沸煮 5 分钟，期间轻搅两次。", "离火静置 2 分钟让粉渣沉淀。", "滤去粉渣后趁热倒入杯中饮用。"]', '["Café de olla", "墨西哥陶罐咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-mexico", "mode": "coffee", "category": "COFFEE", "nameZh": "墨西哥咖啡", "nameEn": "Café de Olla", "intro": "墨西哥传统陶罐咖啡，以瓦罐慢煮咖啡粉并加入肉桂与棕榈糖，带有明显的香料与焦糖甜味。", "imageUrl": "https://images.unsplash.com/photo-1576685880864-50b3b35f1c55?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "香料", "甜感明显", "醇厚/酒体饱满", "经典", "无乳配方", "地域特色咖啡"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "偏甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cuba', 'coffee', 'COFFEE', '古巴咖啡', 'Café Cubano', 'gubakafei', 'gbkf', '古巴浓缩咖啡，以深度烘焙细研磨咖啡粉萃取并趁热拌入糖粉，形成明显甜感与细密泡沫。', 'V6 标准化为 25 g 深度烘焙粉萃取 50 ml 浓缩，趁热加入 10 g 糖粉搅拌至绵密泡沫。源自古巴咖啡馆传统做法，不同家庭配糖比例略有差异。', 'https://images.unsplash.com/photo-1626885128484-7968f9b8b0e9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1626885128484-7968f9b8b0e9?w=1200&q=80&auto=format&fit=crop', 93, 60, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 9.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "苦味明显", "浓郁甜", "浓缩", "泡沫质地", "经典", "地域特色咖啡", "无乳配方"]', '["经典"]', '{"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}', '[{"nameZh": "深度烘焙咖啡豆", "nameEn": "Dark roast coffee beans", "amount": 25, "unit": "g", "role": "意式细研磨"}, {"nameZh": "过滤水", "nameEn": "Filtered water", "amount": 50, "unit": "ml", "role": "萃取用 92°C"}, {"nameZh": "细砂糖", "nameEn": "Superfine sugar", "amount": 10, "unit": "g", "role": "细砂糖"}]', '["将细研磨深度烘焙咖啡粉压入粉碗。", "萃取出约 50 ml 浓缩咖啡液。", "趁热将糖粉倒入浓缩液中快速搅拌。", "持续搅打至液体呈现细密浅色泡沫。", "倒入预热小杯后立即饮用。"]', '["Café cubano", "Cuban espresso"]', 'A', '2026-08-04', 1, '{"id": "coffee-cuba", "mode": "coffee", "category": "COFFEE", "nameZh": "古巴咖啡", "nameEn": "Café Cubano", "intro": "古巴浓缩咖啡，以深度烘焙细研磨咖啡粉萃取并趁热拌入糖粉，形成明显甜感与细密泡沫。", "imageUrl": "https://images.unsplash.com/photo-1626885128484-7968f9b8b0e9?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "苦味明显", "浓郁甜", "浓缩", "泡沫质地", "经典", "地域特色咖啡", "无乳配方"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"coffeeType": "地域特色咖啡", "milk": "无奶", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-butter', 'coffee', 'COFFEE', '黄油咖啡', 'Butter Coffee', 'huangyoukafei', 'hykf', '以热咖啡为基础，加入黄油搅拌乳化而成的浓郁热饮，口感厚实顺滑，苦味柔和，常作为能量密度较高的早餐咖啡。', 'V6 编辑标准化配方为 240 ml 法压热咖啡配 15 g 无盐黄油与 1 g 海盐，高速搅打乳化。配方不使用牛奶，但黄油仍属乳制品，乳糖或乳蛋白敏感者需留意。', 'https://images.unsplash.com/photo-1745892477174-61d2145109ed?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1745892477174-61d2145109ed?w=1200&q=80&auto=format&fit=crop', 93, 120, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 4.0}, {"key": "BODY", "label": "醇厚度", "score": 9.0}, {"key": "ROAST", "label": "烘焙感", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["热饮", "醇厚/酒体饱满", "奶油感", "低糖", "含咖啡因", "日常", "风味咖啡", "奶咖"]', '["日常"]', '{"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常"]}', '[{"nameZh": "法压咖啡液", "nameEn": "French press coffee", "amount": 240, "unit": "ml", "role": "深度烘焙豆按 1:12 粉水比法压萃取"}, {"nameZh": "黄油", "nameEn": "Butter", "amount": 15, "unit": "g", "role": "无盐黄油，室温软化"}, {"nameZh": "细海盐", "nameEn": "Fine sea salt", "amount": 1, "unit": "g", "role": "平衡风味"}]', '["用 1:12 粉水比法压萃取 240 ml 热咖啡。", "将咖啡、15 g 无盐黄油与 1 g 海盐放入搅拌杯。", "高速搅拌 20–30 秒至油脂完全乳化。", "倒入杯中，确认表面无油花分层。", "趁热饮用，避免久置后再次分层。"]', '["防弹咖啡", "Bulletproof Coffee"]', 'B', '2026-08-04', 1, '{"id": "coffee-butter", "mode": "coffee", "category": "COFFEE", "nameZh": "黄油咖啡", "nameEn": "Butter Coffee", "intro": "以热咖啡为基础，加入黄油搅拌乳化而成的浓郁热饮，口感厚实顺滑，苦味柔和，常作为能量密度较高的早餐咖啡。", "imageUrl": "https://images.unsplash.com/photo-1745892477174-61d2145109ed?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "醇厚/酒体饱满", "奶油感", "低糖", "含咖啡因", "日常", "风味咖啡", "奶咖"], "scene": ["日常"], "recommendationScore": 93, "attributes": {"coffeeType": "风味咖啡", "milk": "含乳", "sweetBitter": "不甜微苦", "temperature": "热饮", "caffeine": "较高咖啡因", "scene": ["日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-vietnamese', 'coffee', 'COFFEE', '越南咖啡', 'Vietnamese Iced Coffee', 'yuenankafei', 'ynkf', '以深度烘焙咖啡经滴滤萃取后，与炼乳混合并加冰而成的经典越南冰饮，甜与苦并存，口感浓郁醇厚。', 'V6 编辑标准化按 phin 滤杯滴滤：20 g 中细研磨深烘焙咖啡粉用 88–92°C 热水萃取约 100 ml，兑 25 g 全脂炼乳后加冰至满杯。炼乳提供奶香与甜感，属于含乳饮品。', 'https://images.unsplash.com/photo-1578314675249-a6910f80cc4e?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1578314675249-a6910f80cc4e?w=1200&q=80&auto=format&fit=crop', 89, 121, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 8.0}, {"key": "ROAST", "label": "烘焙感", "score": 9.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["冷饮", "奶咖", "甜感明显", "醇厚/酒体饱满", "浓郁甜", "夏季"]', '["夏季"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": ["夏季"]}', '[{"nameZh": "手冲咖啡液", "nameEn": "Drip coffee liquid", "amount": 100, "unit": "ml", "role": "深度烘焙豆 phin 滴滤萃取"}, {"nameZh": "炼乳", "nameEn": "Condensed milk", "amount": 25, "unit": "g", "role": "全脂炼乳"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "满杯冰块"}]', '["将 20 g 中细研磨的深烘焙咖啡粉放入 phin 滤杯。", "注入 30 g 88–92°C 热水预浸润 30 秒。", "注入剩余热水，静置滴滤约 4–6 分钟得到约 100 ml 咖啡液。", "杯底先放 25 g 炼乳，倒入咖啡液并搅匀。", "加入 120 g 冰块，搅匀后饮用。"]', '["越式冰咖啡", "炼乳咖啡", "cà phê sữa đá"]', 'B', '2026-08-04', 1, '{"id": "coffee-vietnamese", "mode": "coffee", "category": "COFFEE", "nameZh": "越南咖啡", "nameEn": "Vietnamese Iced Coffee", "intro": "以深度烘焙咖啡经滴滤萃取后，与炼乳混合并加冰而成的经典越南冰饮，甜与苦并存，口感浓郁醇厚。", "imageUrl": "https://images.unsplash.com/photo-1578314675249-a6910f80cc4e?w=1200&q=80&auto=format&fit=crop", "tags": ["冷饮", "奶咖", "甜感明显", "醇厚/酒体饱满", "浓郁甜", "夏季"], "scene": ["夏季"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜微苦", "temperature": "冰饮", "caffeine": "较高咖啡因", "scene": ["夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-cafe-au-lait', 'coffee', 'COFFEE', '法式牛奶咖啡', 'Café au Lait', 'fashiniunaikafei', 'fsnnkf', '以等比例的法压或滴滤咖啡与热牛奶调和而成的法式经典热饮，奶香与咖啡味均衡，口感温和顺滑。', 'V6 编辑标准化为 1:1 配比：150 ml 法压咖啡兑 150 ml 60–65°C 全脂牛奶。不使用浓缩，咖啡与奶的浓度比浓缩基奶咖更低更温和。', 'https://images.unsplash.com/photo-1511920170033-f8396924c348?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1511920170033-f8396924c348?w=1200&q=80&auto=format&fit=crop', 89, 122, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 6.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["热饮", "奶咖", "均衡", "顺滑", "经典", "日常"]', '["经典", "日常"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}', '[{"nameZh": "法压咖啡液", "nameEn": "French press coffee", "amount": 150, "unit": "ml", "role": "中度烘焙豆按 1:12 粉水比法压萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 150, "unit": "ml", "role": "加热至 60–65°C，不追求厚奶泡"}]', '["用 1:12 粉水比法压萃取 150 ml 咖啡。", "将 150 ml 全脂牛奶加热至 60–65°C。", "将咖啡与牛奶同时倒入杯中，保持约 1:1 比例。", "轻搅一次使奶咖融合。", "趁热饮用。"]', '["牛奶咖啡", "欧蕾咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-cafe-au-lait", "mode": "coffee", "category": "COFFEE", "nameZh": "法式牛奶咖啡", "nameEn": "Café au Lait", "intro": "以等比例的法压或滴滤咖啡与热牛奶调和而成的法式经典热饮，奶香与咖啡味均衡，口感温和顺滑。", "imageUrl": "https://images.unsplash.com/photo-1511920170033-f8396924c348?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "奶咖", "均衡", "顺滑", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-latte-macchiato', 'coffee', 'COFFEE', '拿铁玛奇朵', 'Latte Macchiato', 'natiemaqiduo', 'ntmqd', '以大量热牛奶和厚奶泡为基底、浓缩咖啡最后注入形成的分层奶咖，奶香突出，浓缩风味作为收尾。', 'V6 编辑标准化为 220 ml 蒸煮全脂牛奶加厚奶泡，再注入双份浓缩 36 g。与浓缩基的拿铁相比，奶的比例更高、分层更明显，浓缩以点缀方式叠加。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20macchiato.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20macchiato.jpg', 89, 123, '[{"key": "ACIDITY", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["热饮", "奶咖", "奶油感", "泡沫质地", "甜感明显", "早午餐"]', '["早午餐"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}', '[{"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C，上层留约 1 cm 厚奶泡"}, {"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}]', '["将 220 ml 全脂牛奶蒸煮至 60–65°C 并打出约 1 cm 厚奶泡。", "将牛奶与奶泡倒入透明杯中。", "缓慢注入双份浓缩 36 g，让浓缩浮于奶泡上形成分层。", "保持分层状态上桌，饮用前轻搅。"]', '["拉提玛琪朵", "牛奶玛奇朵"]', 'A', '2026-08-04', 1, '{"id": "coffee-latte-macchiato", "mode": "coffee", "category": "COFFEE", "nameZh": "拿铁玛奇朵", "nameEn": "Latte Macchiato", "intro": "以大量热牛奶和厚奶泡为基底、浓缩咖啡最后注入形成的分层奶咖，奶香突出，浓缩风味作为收尾。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20macchiato.jpg", "tags": ["热饮", "奶咖", "奶油感", "泡沫质地", "甜感明显", "早午餐"], "scene": ["早午餐"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜微苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-salted-caramel-latte', 'coffee', 'COFFEE', '海盐焦糖拿铁', 'Salted Caramel Latte', 'haiyanjiaotangnatie', 'hyjtnt', '拿铁中加入焦糖糖浆并以海盐提味的奶咖，咸甜交织，焦糖的浓甜被盐粒平衡，苦味轻柔，口感层次丰富。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶与 18 g 焦糖糖浆，表层撒 0.5 g 海盐。盐的作用是平衡甜度而非咸味主导，整体甜感仍明显。', 'https://images.unsplash.com/photo-1637178035222-a08f2d4dd1a3?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1637178035222-a08f2d4dd1a3?w=1200&q=80&auto=format&fit=crop', 89, 125, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 8.0}, {"key": "BODY", "label": "醇厚度", "score": 6.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "焦糖", "甜感明显", "奶油感", "餐后"]', '["餐后"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "蒸煮至 60–65°C 并打出薄奶泡"}, {"nameZh": "焦糖糖浆", "nameEn": "Caramel syrup", "amount": 18, "unit": "g", "role": "焦糖糖浆"}, {"nameZh": "细海盐", "nameEn": "Fine sea salt", "amount": 0.5, "unit": "g", "role": "表面撒盐约一小撮"}]', '["萃取双份浓缩 36 g，加入 18 g 焦糖糖浆搅匀。", "将 220 ml 牛奶蒸煮至 60–65°C 并打出薄奶泡。", "牛奶倒入杯中，奶泡铺面。", "表面均匀撒 0.5 g 海盐。", "轻搅后趁热饮用。"]', '["盐焦糖拿铁", "海盐焦糖牛奶咖啡"]', 'B', '2026-08-04', 1, '{"id": "coffee-salted-caramel-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "海盐焦糖拿铁", "nameEn": "Salted Caramel Latte", "intro": "拿铁中加入焦糖糖浆并以海盐提味的奶咖，咸甜交织，焦糖的浓甜被盐粒平衡，苦味轻柔，口感层次丰富。", "imageUrl": "https://images.unsplash.com/photo-1637178035222-a08f2d4dd1a3?w=1200&q=80&auto=format&fit=crop", "tags": ["热饮", "奶咖", "焦糖", "甜感明显", "奶油感", "餐后"], "scene": ["餐后"], "recommendationScore": 89, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "偏甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('coffee-pistachio-latte', 'coffee', 'COFFEE', '开心果拿铁', 'Pistachio Latte', 'kaixinguonatie', 'kxgnt', '拿铁中加入开心果酱调制的奶咖，开心果细腻清雅的坚果香与奶咖结合，甜感适度，尾韵干净，口感丝滑醇厚。', 'V6 编辑标准化为双份浓缩 36 g、220 ml 蒸煮牛奶与 15 g 无糖开心果酱，开心果酱需研磨细腻以保持口感顺滑。属含乳与坚果类饮品。', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg', 91, 129, '[{"key": "ACIDITY", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜感", "score": 7.0}, {"key": "BODY", "label": "醇厚度", "score": 7.0}, {"key": "ROAST", "label": "烘焙感", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["热饮", "奶咖", "坚果", "香草", "奶油感", "甜感明显", "下午茶"]', '["下午茶"]', '{"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}', '[{"nameZh": "双份浓缩咖啡液", "nameEn": "Double espresso liquid", "amount": 36, "unit": "g", "role": "由 18 g 咖啡粉萃取"}, {"nameZh": "全脂牛奶", "nameEn": "Whole milk", "amount": 220, "unit": "ml", "role": "与 15 g 开心果酱混合后蒸煮"}, {"nameZh": "香草糖浆", "nameEn": "Vanilla syrup", "amount": 5, "unit": "g", "role": "提升甜香层次"}]', '["将 15 g 无糖开心果酱与 220 ml 牛奶混合搅匀。", "混合液蒸煮至 60–65°C 并打出薄奶泡。", "萃取双份浓缩 36 g 倒入杯中。", "倒入开心果牛奶，加入 5 g 香草糖浆。", "轻搅后趁热饮用。"]', '["开心果牛奶咖啡", "开心果奶咖"]', 'B', '2026-08-04', 1, '{"id": "coffee-pistachio-latte", "mode": "coffee", "category": "COFFEE", "nameZh": "开心果拿铁", "nameEn": "Pistachio Latte", "intro": "拿铁中加入开心果酱调制的奶咖，开心果细腻清雅的坚果香与奶咖结合，甜感适度，尾韵干净，口感丝滑醇厚。", "imageUrl": "https://commons.wikimedia.org/wiki/Special:Redirect/file/Latte%20art.jpg", "tags": ["热饮", "奶咖", "坚果", "香草", "奶油感", "甜感明显", "下午茶"], "scene": ["下午茶"], "recommendationScore": 91, "attributes": {"coffeeType": "奶咖", "milk": "含乳", "sweetBitter": "微甜低苦", "temperature": "热饮", "caffeine": "中等咖啡因", "scene": ["下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-dry-martini', 'cocktail', 'COCKTAIL', '干马天尼', 'Dry Martini', 'ganmatianni', 'gmtn', '以金酒为主、干味美思仅极少量辅助的极干型鸡尾酒，几乎纯烈的金酒风味与低甜度构成其标志性口感。', '本条目按 IBA 干马天尼配比标准化：60 ml 金酒兑 10 ml 干味美思，搅拌后滤杯。家庭版常以极少量味美思润杯即弃，风味更干。 背景：马天尼家族最经典版本，起源有马丁内斯演变说与纽约调酒师创制说等多种说法，金酒与极少量干味美思的组合，成为“鸡尾酒之王”。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-dry-martini-6694910fb500c.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-dry-martini-6694910fb500c.webp', 98, 2, '[{"key":"SWEETNESS","label":"甜度","score":1.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":4.0},{"key":"ALCOHOL","label":"酒精感","score":9.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":3.0}]', '["烈酒主导","金酒基底","偏干","草本","搅拌","高强度","经典"]', '["经典"]', '{"baseSpirit":"金酒基底","cocktailType":"烈酒主导","flavor":"偏干、草本","abv":"高度＞30%","extra":"无明显非酒精成分","scene":["经典"]}', '[{"nameZh":"伦敦干金酒","nameEn":"Gin","amount":60,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"干味美思","nameEn":"Dry Vermouth","amount":10,"unit":"ml","role":"官方比例，仅少量"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":80,"unit":"g","role":"搅拌用"},{"nameZh":"柠檬皮","nameEn":"Lemon peel","amount":1,"unit":"piece","role":"装饰用，挤油提香"}]', '["将马天尼杯提前冰镇。","搅拌杯加冰，倒入金酒与干味美思。","搅拌约 20 秒至充分降温。","滤入冰镇马天尼杯。","挤入柠檬皮油提香，或按需求以青橄榄装饰。"]', '["Dry Martini", "干马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-dry-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "干马天尼", "nameEn": "Dry Martini", "intro": "以金酒为主、干味美思仅极少量辅助的极干型鸡尾酒，几乎纯烈的金酒风味与低甜度构成其标志性口感。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-dry-martini-6694910fb500c.webp", "tags": ["烈酒主导", "金酒基底", "偏干", "草本", "搅拌", "高强度", "经典"], "scene": ["经典"], "recommendationScore": 98, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "偏干、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-espresso-martini', 'cocktail', 'COCKTAIL', '浓缩咖啡马天尼', 'Espresso Martini', 'nongsuokafeimatianni', 'nskfmtn', '以伏特加、咖啡利口酒与浓缩咖啡摇制的咖啡风味鸡尾酒，杯面浮着绵密泡沫，兼具咖啡香与酒感。', '本条目按 IBA 官方配比标准化：50 ml 伏特加、30 ml 咖啡利口酒、10 ml 单糖浆与一杯浓缩咖啡，加冰用力摇和起泡后滤入马天尼杯，以咖啡豆装饰。使用新鲜浓缩咖啡可稳定获得泡沫层。 背景：1980年代伦敦调酒师迪克·布拉德塞尔（Dick Bradsell）为一位点“唤醒我”的模特创制，伏特加+咖啡利口酒+浓缩咖啡，原名伏特加浓缩咖啡。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-espresso-martini-6695d3a172fd3.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-espresso-martini-6695d3a172fd3.webp', 100, 6, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":3.0},{"key":"ALCOHOL","label":"酒精感","score":7.0},{"key":"BODY","label":"酒体","score":6.0},{"key":"REFRESHING","label":"清爽度","score":2.0}]', '["咖啡鸡尾酒", "伏特加基底", "咖啡风味", "泡沫质地", "摇和", "甜感明显", "餐后", "含咖啡因"]', '["餐后"]', '{"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["餐后"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"咖啡利口酒（甘露）","nameEn":"Coffee Liqueur (Kahlúa)","amount":30,"unit":"ml","role":"咖啡利口酒"},{"nameZh":"单糖浆","nameEn":"Sugar Syrup","amount":10,"unit":"ml","role":"平衡苦度"},{"nameZh":"浓缩咖啡液","nameEn":"Strong Espresso","amount":30,"unit":"ml","role":"一杯浓缩咖啡"},{"nameZh":"咖啡豆","nameEn":"Coffee beans","amount":3,"unit":"piece","role":"装饰用"}]', '["将马天尼杯提前冰镇。","摇酒壶加冰，倒入伏特加、咖啡利口酒、单糖浆与浓缩咖啡。","用力摇和约 15 秒至充分降温并起泡。","滤入冰镇马天尼杯。","以三颗咖啡豆装饰。"]', '["Espresso Martini", "意式浓缩马天尼", "咖啡马提尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-espresso-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "浓缩咖啡马天尼", "nameEn": "Espresso Martini", "intro": "以伏特加、咖啡利口酒与浓缩咖啡摇制的咖啡风味鸡尾酒，杯面浮着绵密泡沫，兼具咖啡香与酒感。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-espresso-martini-6695d3a172fd3.webp", "tags": ["咖啡鸡尾酒", "伏特加基底", "咖啡风味", "泡沫质地", "摇和", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后"], "recommendationScore": 100, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "较高＞20%～30%", "extra": ["浓缩咖啡液"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-french-martini', 'cocktail', 'COCKTAIL', '法国马天尼', 'French Martini', 'faguomatianni', 'fgmtn', '以伏特加、树莓利口酒与菠萝汁摇制的果味鸡尾酒，酸甜果香与顺滑质地结合，外观呈粉红。', '本条目按 IBA 配比标准化：45 ml 伏特加、15 ml 树莓利口酒加 15 ml 菠萝汁，摇和滤入马天尼杯。水果比例与利口酒甜度决定整体酸甜平衡。 背景：1980年代伦敦调酒师迪克·布拉德塞尔（Dick Bradsell）创制，伏特加+黑莓利口酒+菠萝汁。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-french-martini-6695d3a4acf5f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-french-martini-6695d3a4acf5f.webp', 96, 7, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":2.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":4.0}]', '["伏特加基底", "莓果", "菠萝", "粉红色外观", "摇和", "酸甜"]', '["节日", "经典", "开胃"]', '{"baseSpirit":"伏特加基底","cocktailType":"果味鸡尾酒","flavor":"莓果、菠萝","abv":"较高＞20%～30%","extra":["新鲜菠萝汁"],"scene":["节日","经典","开胃"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"树莓利口酒","nameEn":"Raspberry Liqueur","amount":15,"unit":"ml","role":"莓果甜香"},{"nameZh":"新鲜菠萝汁","nameEn":"Fresh Pineapple Juice","amount":15,"unit":"ml","role":"果香与酸度"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":90,"unit":"g","role":"摇和用"},{"nameZh":"柠檬皮","nameEn":"Lemon peel","amount":1,"unit":"piece","role":"装饰用，挤油提香"}]', '["将马天尼杯提前冰镇。","摇酒壶加冰，倒入伏特加、树莓利口酒与菠萝汁。","摇和约 12 秒至充分降温。","滤入冰镇马天尼杯。","挤入柠檬皮油提香。"]', '["French Martini", "法式马天尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-french-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "法国马天尼", "nameEn": "French Martini", "intro": "以伏特加、树莓利口酒与菠萝汁摇制的果味鸡尾酒，酸甜果香与顺滑质地结合，外观呈粉红。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-french-martini-6695d3a4acf5f.webp", "tags": ["伏特加基底", "莓果", "菠萝", "粉红色外观", "摇和", "酸甜"], "scene": ["节日", "经典", "开胃"], "recommendationScore": 96, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "果味鸡尾酒", "flavor": "莓果、菠萝", "abv": "较高＞20%～30%", "extra": ["新鲜菠萝汁"], "scene": ["节日", "经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sazerac', 'cocktail', 'COCKTAIL', '萨泽拉克', 'Sazerac', 'sazelake', 'szlk', '以干邑为基底，方糖与佩肖苦精调味、苦艾酒涮杯的新奥尔良经典，茴香与苦味交织，被视为最早的鸡尾酒之一。', '本条目按 IBA 官方配比标准化：50 ml 干邑白兰地、方糖 1 颗与佩肖苦精 2 滴，搅拌后滤入以苦艾酒涮洗的古典杯。美国内战后黑麦威士忌曾替代干邑，IBA 官方现行配方以干邑为准。 背景：1838年前后新奥尔良诞生，最初为干邑+佩肖苦精（苦艾酒前身），1850年代后改用黑麦威士忌，被列为新奥尔良官方鸡尾酒。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-sazerac-66949129b50d1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-sazerac-66949129b50d1.webp', 93, 16, '[{"key":"SWEETNESS","label":"甜度","score":3.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":5.0},{"key":"ALCOHOL","label":"酒精感","score":8.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":2.0}]', '["烈酒主导","干邑基底","苦味明显","茴香","搅拌","经典"]', '["经典"]', '{"baseSpirit":"干邑基底","cocktailType":"古典家族","flavor":"苦感主导、茴香","abv":"高度＞30%","extra":"无明显非酒精成分","scene":["经典"]}', '[{"nameZh":"干邑白兰地","nameEn":"Cognac","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"佩肖苦精","nameEn":"Peychaud\'s Bitters","amount":2,"unit":"dash","role":"官方苦精"},{"nameZh":"方糖","nameEn":"Sugar cube","amount":1,"unit":"piece","role":"溶解于苦精"},{"nameZh":"苦艾酒","nameEn":"Absinthe","amount":10,"unit":"ml","role":"涮洗杯壁用"},{"nameZh":"柠檬皮","nameEn":"Lemon zest","amount":1,"unit":"piece","role":"装饰用"}]', '["将古典杯以苦艾酒涮洗杯壁后倒出多余酒液，放入碎冰预冷。","调酒杯中放入方糖，滴入佩肖苦精，加少许水搅拌至溶解。","加入干邑白兰地，加冰搅拌约 20 秒。","倒出预冷杯中的碎冰与多余苦艾酒。","滤入杯中，以柠檬皮装饰。"]', '["萨泽拉克鸡尾酒", "Sazerac"]', 'A', '2026-08-04', 1, '{"id": "cocktail-sazerac", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "萨泽拉克", "nameEn": "Sazerac", "intro": "以干邑为基底，方糖与佩肖苦精调味、苦艾酒涮杯的新奥尔良经典，茴香与苦味交织，被视为最早的鸡尾酒之一。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-sazerac-66949129b50d1.webp", "tags": ["烈酒主导", "干邑基底", "苦味明显", "茴香", "搅拌", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "古典家族", "flavor": "苦感主导、茴香", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-manhattan', 'cocktail', 'COCKTAIL', '曼哈顿', 'Manhattan', 'manhadun', 'mhd', '以威士忌为基底，加入甜红味美思与苦精搅拌而成的经典鸡尾酒，甜苦平衡，酒体圆润，以樱桃装饰。', '曼哈顿是经典的威士忌马天尼家族鸡尾酒。本条目按 IBA 官方配比标准化：黑麦威士忌 50 ml、甜红味美思 20 ml 与安格斯图拉苦精 1 滴，冰面搅拌后滤入马天尼杯，以鸡尾酒樱桃装饰。 背景：1870年代纽约曼哈顿俱乐部为温斯顿·丘吉尔之母珍妮·杰罗姆的宴会调制（传说），黑麦威士忌+甜味美思+苦精，是最早的“现代鸡尾酒”之一。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-manhattan-6694911627de7.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-manhattan-6694911627de7.webp', 93, 17, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":3.0},{"key":"ALCOHOL","label":"酒精感","score":8.0},{"key":"BODY","label":"酒体","score":6.0},{"key":"REFRESHING","label":"清爽度","score":2.0}]', '["烈酒主导","黑麦基底","草本","甜苦平衡","搅拌","经典","餐后"]', '["经典", "餐后"]', '{"baseSpirit":"黑麦基底","cocktailType":"烈酒主导","flavor":"草本、甜苦平衡","abv":"高度＞30%","extra":"无明显非酒精成分","scene":["经典","餐后"]}', '[{"nameZh":"黑麦威士忌","nameEn":"Rye Whiskey","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"甜红味美思","nameEn":"Sweet Red Vermouth","amount":20,"unit":"ml","role":"甜味美思"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":1,"unit":"dash","role":"官方用量"},{"nameZh":"鸡尾酒樱桃","nameEn":"Cocktail cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["将马天尼杯提前冰镇。","搅拌杯加冰，倒入黑麦威士忌、甜红味美思与安格斯图拉苦精。","搅拌约 20 秒至充分降温。","滤入冰镇马天尼杯。","以鸡尾酒樱桃装饰。"]', '["曼哈顿鸡尾酒", "Manhattan"]', 'A', '2026-08-04', 1, '{"id": "cocktail-manhattan", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "曼哈顿", "nameEn": "Manhattan", "intro": "以威士忌为基底，加入甜红味美思与苦精搅拌而成的经典鸡尾酒，甜苦平衡，酒体圆润，以樱桃装饰。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-manhattan-6694911627de7.webp", "tags": ["烈酒主导", "黑麦基底", "草本", "甜苦平衡", "搅拌", "经典", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "烈酒主导", "flavor": "草本、甜苦平衡", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-old-fashioned', 'cocktail', 'COCKTAIL', '老式鸡尾酒', 'Old Fashioned', 'laoshijiweijiu', 'lsjwj', '以波本威士忌加方糖与苦精直调而成的经典鸡尾酒，苦甜平衡、酒体扎实，用橙皮提香，被视为威士忌风格鸡尾酒的基石。', '本条目按 IBA 官方配比标准化：波本或黑麦威士忌 45 ml、方糖 1 颗与安格斯图拉苦精数滴，捣压溶解方糖后加冰直调，以橙片与樱桃装饰。使用方糖而非糖浆是古典做法的经典标志。 背景：1880年代肯塔基州路易斯维尔潘德尼斯俱乐部，为纪念“威士忌老式调法”倡导者詹姆斯·E·佩珀上校而流行，被认为是最接近“鸡尾酒”一词原义的饮品。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-old-fashioned-6694911fce360.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-old-fashioned-6694911fce360.webp', 93, 22, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":4.0},{"key":"ALCOHOL","label":"酒精感","score":9.0},{"key":"BODY","label":"酒体","score":6.0},{"key":"REFRESHING","label":"清爽度","score":2.0}]', '["烈酒主导","威士忌基底","苦甜","直调","经典"]', '["经典"]', '{"baseSpirit":"威士忌基底","cocktailType":"古典家族","flavor":"苦甜、橡木","abv":"高度＞30%","extra":"无明显非酒精成分","scene":["经典"]}', '[{"nameZh":"波本或黑麦威士忌","nameEn":"Bourbon or Rye Whiskey","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"方糖","nameEn":"Sugar cube","amount":1,"unit":"piece","role":"捣压溶解"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":3,"unit":"dash","role":"浸透方糖"},{"nameZh":"过滤水","nameEn":"Plain water","amount":5,"unit":"ml","role":"助溶方糖"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":90,"unit":"g","role":"搅拌用"},{"nameZh":"橙片","nameEn":"Orange slice","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"鸡尾酒樱桃","nameEn":"Cocktail cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["古典杯底放入方糖，滴入安格斯图拉苦精与少量过滤水。","用捣棒将方糖捣压至溶解。","加满冰块，倒入威士忌。","轻轻搅拌约 20 秒。","以橙片与鸡尾酒樱桃装饰。"]', '["古典", "Old Fashioned", "老式"]', 'A', '2026-08-04', 1, '{"id": "cocktail-old-fashioned", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "老式鸡尾酒", "nameEn": "Old Fashioned", "intro": "以波本威士忌加方糖与苦精直调而成的经典鸡尾酒，苦甜平衡、酒体扎实，用橙皮提香，被视为威士忌风格鸡尾酒的基石。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-old-fashioned-6694911fce360.webp", "tags": ["烈酒主导", "威士忌基底", "苦甜", "直调", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦甜、橡木", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-whiskey-sour', 'cocktail', 'COCKTAIL', '威士忌酸酒', 'Whiskey Sour', 'weishijisuanjiu', 'wsjsj', '以波本威士忌、柠檬汁与糖浆摇和而成的酸型鸡尾酒，酸甜平衡、泡沫绵密，是威士忌家族中最具代表性的酸酒。', 'V6 标准按 IBA 配比以波本威士忌 45 毫升、柠檬汁 25 毫升与糖浆 20 毫升，另加蛋清摇和出绵密泡沫。 背景：19世纪中期美国流行的“酸酒”（sour）家族代表，1870年代已有记载，威士忌+柠檬+糖。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-whiskey-sour-66949132e6ae9.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-whiskey-sour-66949132e6ae9.webp', 93, 27, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":7.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":4.0}]', '["酸型鸡尾酒","威士忌基底","蛋清泡沫","摇和","经典"]', '["经典", "开胃"]', '{"baseSpirit":"威士忌基底","cocktailType":"酸型鸡尾酒","flavor":"酸甜、柑橘","abv":"较高＞20%～30%","extra":["新鲜柠檬汁","蛋清（可选）"],"scene":["经典","开胃"]}', '[{"nameZh":"波本威士忌","nameEn":"Bourbon Whiskey","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜柠檬汁","nameEn":"Fresh Lemon Juice","amount":25,"unit":"ml","role":"酸度核心"},{"nameZh":"单糖浆","nameEn":"Sugar Syrup","amount":20,"unit":"ml","role":"平衡酸度"},{"nameZh":"蛋清","nameEn":"Egg white","amount":1,"unit":"piece","role":"可选，起泡用"},{"nameZh":"橙片","nameEn":"Orange slice","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"马拉斯奇诺樱桃","nameEn":"Maraschino cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["摇酒壶中加入波本威士忌、柠檬汁、单糖浆与蛋清。","不加冰干摇约 15 秒使蛋清起泡。","加冰再摇和约 10 秒至充分冰镇。","滤入冰镇鸡尾酒杯。","以半片橙片与马拉斯奇诺樱桃装饰。"]', '["威士忌酸酒", "Whiskey Sour", "酸威士忌"]', 'A', '2026-08-04', 1, '{"id": "cocktail-whiskey-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "威士忌酸酒", "nameEn": "Whiskey Sour", "intro": "以波本威士忌、柠檬汁与糖浆摇和而成的酸型鸡尾酒，酸甜平衡、泡沫绵密，是威士忌家族中最具代表性的酸酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-whiskey-sour-66949132e6ae9.webp", "tags": ["酸型鸡尾酒", "威士忌基底", "蛋清泡沫", "摇和", "经典"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清（可选）"], "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pisco-sour', 'cocktail', 'COCKTAIL', '皮斯科酸酒', 'Pisco Sour', 'pisikesuanjiu', 'psksj', '以秘鲁皮斯科为基底、加入柠檬汁与蛋清的秘鲁国饮级酸型鸡尾酒，顶部苦精点睛，泡沫绵密、酸爽而富有果香。', '配方采用 IBA 官方比例：60 ml 皮斯科、30 ml 新鲜柠檬汁、20 ml 单糖浆与整颗蛋清摇和，滤入冰镇高脚杯后在泡沫表面滴安格斯图拉苦精作芳香装饰。 背景：1920年代秘鲁利马莫里斯酒吧调酒师维克托·莫里斯（Victor Morris）创制，皮斯科+青柠+糖+蛋清+苦精。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-pisco-sour-6695cdcaf1122.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-pisco-sour-6695cdcaf1122.webp', 93, 36, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":7.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":6.0},{"key":"REFRESHING","label":"清爽度","score":4.0}]', '["酸型鸡尾酒","皮斯科基底","蛋清泡沫","摇和","经典"]', '["经典"]', '{"baseSpirit":"皮斯科基底","cocktailType":"酸型鸡尾酒","flavor":"柑橘、绵密泡沫","abv":"较高＞20%～30%","extra":["新鲜柠檬汁","蛋清"],"scene":["经典"]}', '[{"nameZh":"皮斯科","nameEn":"Pisco","amount":60,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜柠檬汁","nameEn":"Fresh Lemon Juice","amount":30,"unit":"ml","role":"酸度核心"},{"nameZh":"单糖浆","nameEn":"Simple Syrup","amount":20,"unit":"ml","role":"平衡酸度"},{"nameZh":"蛋清","nameEn":"Raw whole Egg White","amount":1,"unit":"piece","role":"整颗蛋清，起泡用"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":2,"unit":"dash","role":"泡沫表面芳香装饰"}]', '["摇酒壶中加入皮斯科、柠檬汁、单糖浆与蛋清。","不加冰干摇约 10 秒使蛋清起泡。","加冰摇和约 10 秒至充分冰镇。","滤入冰镇高脚杯。","在泡沫表面滴数滴安格斯图拉苦精作芳香装饰。"]', '["Pisco Sour", "皮斯科酸酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-pisco-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皮斯科酸酒", "nameEn": "Pisco Sour", "intro": "以秘鲁皮斯科为基底、加入柠檬汁与蛋清的秘鲁国饮级酸型鸡尾酒，顶部苦精点睛，泡沫绵密、酸爽而富有果香。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-pisco-sour-6695cdcaf1122.webp", "tags": ["酸型鸡尾酒", "皮斯科基底", "蛋清泡沫", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "皮斯科基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、绵密泡沫", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-singapore-sling', 'cocktail', 'COCKTAIL', '新加坡司令', 'Singapore Sling', 'xinjiaposiling', 'xjpsl', '源自新加坡莱佛士酒店的经典长饮，以金酒为基底叠加樱桃白兰地、君度与菠萝汁，果香奔放、清凉多汁。', '配方采用 IBA 官方配比：金酒 30 ml、樱桃白兰地利口酒 15 ml、君度 7.5 ml、班尼狄克汀 7.5 ml、菠萝汁 120 ml、青柠汁 15 ml、石榴糖浆 10 ml 与安格斯图拉苦精 1 滴，摇和滤入装满冰块的海波杯，以菠萝角与樱桃装饰。 背景：1915年前后新加坡莱佛士酒店长吧调酒师严崇文（Ngiam Tong Boon）创制，金酒+樱桃白兰地+菠萝汁+柠檬等，颜色绯红。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-singapore-sling-6695cdd136426.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-singapore-sling-6695cdd136426.webp', 93, 37, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":4.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":5.0},{"key":"BODY","label":"酒体","score":4.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["长饮","金酒基底","热带水果","果香","摇和","经典"]', '["经典","夏季"]', '{"baseSpirit":"金酒基底","cocktailType":"长饮","flavor":"热带水果、果香","abv":"中度＞10%～20%","extra":["新鲜菠萝汁","新鲜青柠汁"],"scene":["经典","夏季"]}', '[{"nameZh":"金酒","nameEn":"Gin","amount":30,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"樱桃白兰地利口酒","nameEn":"Cherry Brandy Liqueur","amount":15,"unit":"ml","role":"果香与绯红色"},{"nameZh":"君度橙酒","nameEn":"Cointreau","amount":7.5,"unit":"ml","role":"橙香"},{"nameZh":"班尼狄克汀","nameEn":"DOM Bénédictine","amount":7.5,"unit":"ml","role":"草本甜香"},{"nameZh":"新鲜菠萝汁","nameEn":"Fresh Pineapple Juice","amount":120,"unit":"ml","role":"果香主体"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":15,"unit":"ml","role":"平衡甜度"},{"nameZh":"石榴糖浆","nameEn":"Grenadine Syrup","amount":10,"unit":"ml","role":"增色增甜"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":1,"unit":"dash","role":"提升层次"},{"nameZh":"菠萝角","nameEn":"Pineapple wedge","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"马拉斯奇诺樱桃","nameEn":"Maraschino cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["海波杯加满冰块。","摇酒壶加冰，倒入金酒、樱桃白兰地、君度、班尼狄克汀、菠萝汁、青柠汁、石榴糖浆与苦精。","摇和约 12 秒至充分降温。","滤入海波杯。","以菠萝角与马拉斯奇诺樱桃装饰。"]', '["Singapore Sling", "新加坡司令酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-singapore-sling", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "新加坡司令", "nameEn": "Singapore Sling", "intro": "源自新加坡莱佛士酒店的经典长饮，以金酒为基底叠加樱桃白兰地、君度与菠萝汁，果香奔放、清凉多汁。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-singapore-sling-6695cdd136426.webp", "tags": ["长饮", "金酒基底", "热带水果", "果香", "摇和", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "长饮", "flavor": "热带水果、果香", "abv": "中度＞10%～20%", "extra": ["新鲜菠萝汁", "新鲜青柠汁"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-daiquiri', 'cocktail', 'COCKTAIL', '大吉利', 'Daiquiri', 'dajili', 'djl', '以白朗姆酒、青柠汁与糖浆构成的三元素经典酸型鸡尾酒，酸爽清爽、朗姆果香纯粹，是极简平衡的代表。', '配方采用 IBA 官方比例：60 ml 白朗姆、20 ml 新鲜青柠汁与 2 吧匙细砂糖，先搅拌至糖溶解再加冰摇和，滤入冰镇鸡尾酒杯，不加装饰。 背景：1898年美西战争期间，美国工程师詹宁斯·考克斯（Jennings Cox）在古巴圣地亚哥附近的大吉利村调制，以村名命名，朗姆+青柠+糖的经典组合。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-daiquiri-6694910c5866e.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-daiquiri-6694910c5866e.webp', 93, 38, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":6.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["酸型鸡尾酒","朗姆基底","柑橘","摇和","经典"]', '["经典","夏季"]', '{"baseSpirit":"朗姆基底","cocktailType":"酸型鸡尾酒","flavor":"柑橘、酸甜","abv":"较高＞20%～30%","extra":["新鲜青柠汁"],"scene":["经典","夏季"]}', '[{"nameZh":"白朗姆酒","nameEn":"White Cuban Rum","amount":60,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":20,"unit":"ml","role":"酸度核心"},{"nameZh":"细砂糖","nameEn":"Superfine Sugar","amount":10,"unit":"g","role":"2 吧匙，先溶解"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":90,"unit":"g","role":"摇和用"}]', '["摇酒壶中加入白朗姆、青柠汁与细砂糖。","搅拌至糖完全溶解。","加冰摇和约 12 秒至充分降温。","滤入冰镇鸡尾酒杯。"]', '["Daiquiri", "代基里", "得其利"]', 'A', '2026-08-04', 1, '{"id": "cocktail-daiquiri", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "大吉利", "nameEn": "Daiquiri", "intro": "以白朗姆酒、青柠汁与糖浆构成的三元素经典酸型鸡尾酒，酸爽清爽、朗姆果香纯粹，是极简平衡的代表。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-daiquiri-6694910c5866e.webp", "tags": ["酸型鸡尾酒", "朗姆基底", "柑橘", "摇和", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cuba-libre', 'cocktail', 'COCKTAIL', '自由古巴', 'Cuba Libre', 'ziyouguba', 'zygb', '以白朗姆酒与可乐为基干、以新鲜青柠汁提香的经典高球鸡尾酒，甜气与气泡明快，是上手度极高的日常长饮。', '配方遵循 IBA 官方框架：白朗姆、可乐配青柠汁现挤提香；酒精度与甜度随可乐品牌浮动，编辑取常见估算区间。 背景：1900年前后古巴，美西战争后美军士兵用可乐加朗姆庆祝古巴独立，高呼“自由古巴”口号而得名。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cuba-libre-6695cdb0a6f80.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cuba-libre-6695cdb0a6f80.webp', 93, 39, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":2.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["长饮","朗姆基底","可乐","直调","新手友好"]', '["日常","派对"]', '{"baseSpirit":"朗姆基底","cocktailType":"高球","flavor":"焦糖、可乐","abv":"中度＞10%～20%","extra":["可乐","新鲜青柠汁"],"scene":["日常","派对"]}', '[{"nameZh":"白朗姆酒","nameEn":"White Rum","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"可乐","nameEn":"Cola","amount":120,"unit":"ml","role":"甜味与气泡"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":10,"unit":"ml","role":"现挤提香"},{"nameZh":"青柠角","nameEn":"Lime wedge","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加满冰块。","倒入白朗姆酒。","挤入新鲜青柠汁。","补入冰镇可乐至满。","轻轻搅拌，以青柠角装饰。"]', '["Cuba Libre", "古巴自由", "朗姆可乐"]', 'A', '2026-08-04', 1, '{"id": "cocktail-cuba-libre", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "自由古巴", "nameEn": "Cuba Libre", "intro": "以白朗姆酒与可乐为基干、以新鲜青柠汁提香的经典高球鸡尾酒，甜气与气泡明快，是上手度极高的日常长饮。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cuba-libre-6695cdb0a6f80.webp", "tags": ["长饮", "朗姆基底", "可乐", "直调", "新手友好"], "scene": ["日常", "派对"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "焦糖、可乐", "abv": "中度＞10%～20%", "extra": ["可乐", "新鲜青柠汁"], "scene": ["日常", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mojito', 'cocktail', 'COCKTAIL', '莫吉托', 'Mojito', 'mojituo', 'mjt', '以白朗姆酒、青柠、薄荷与苏打水构成的古巴经典清凉长饮，薄荷辛香与青柠酸爽在气泡中格外清爽。', '配方采用 IBA 官方配比：白朗姆 45 ml、青柠汁 20 ml、薄荷叶 6 支与 2 茶匙细砂糖，捣压薄荷后加碎冰倒入朗姆，再以苏打水补足。薄荷用量与甜度可依杯型微调。 背景：古巴传统鸡尾酒，可追溯至16世纪的“德拉凯”（甘蔗酒+薄荷+青柠），因海明威长驻哈瓦那拉博德吉塔酒吧而闻名。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mojito-6695cdc755626.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mojito-6695cdc755626.webp', 93, 40, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":5.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":2.0},{"key":"REFRESHING","label":"清爽度","score":9.0}]', '["长饮","朗姆基底","薄荷","捣压","夏季","新手友好"]', '["夏季", "新手友好"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季", "新手友好"]}', '[{"nameZh":"白朗姆酒","nameEn":"White Cuban Rum","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":20,"unit":"ml","role":"酸度核心"},{"nameZh":"薄荷叶","nameEn":"Mint sprigs","amount":6,"unit":"piece","role":"轻压释放香气"},{"nameZh":"细砂糖","nameEn":"White Cane Sugar","amount":10,"unit":"g","role":"2 茶匙"},{"nameZh":"苏打水","nameEn":"Soda Water","amount":60,"unit":"ml","role":"加满顶部"},{"nameZh":"薄荷枝","nameEn":"Mint sprig","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"青柠角","nameEn":"Lime wedge","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯中加入薄荷叶、细砂糖与青柠汁。","用捣棒轻压薄荷叶释放香气。","加入少许苏打水搅拌至糖溶解。","加满碎冰，倒入白朗姆酒。","补入苏打水，轻轻搅拌，以薄荷枝与青柠角装饰。"]', '["Mojito", "莫希托"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mojito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "莫吉托", "nameEn": "Mojito", "intro": "以白朗姆酒、青柠、薄荷与苏打水构成的古巴经典清凉长饮，薄荷辛香与青柠酸爽在气泡中格外清爽。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mojito-6695cdc755626.webp", "tags": ["长饮", "朗姆基底", "薄荷", "捣压", "夏季", "新手友好"], "scene": ["夏季", "新手友好"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "苏打水"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-caipirinha', 'cocktail', 'COCKTAIL', '凯匹林纳', 'Caipirinha', 'kaipilinna', 'kpln', '以卡莎萨、新鲜青柠与细砂糖捣压而成的巴西经典鸡尾酒，酸爽清甜，甘蔗香气清晰，是巴西代表性国民饮品。', '本条目按 IBA 官方配比标准化：60 ml 卡莎萨、1 个青柠切角与 4 茶匙细砂糖，捣压青柠后加碎冰直调。青柠的用量与捣压强度决定酸度，砂糖量可按青柠成熟度微调。 背景：巴西国民鸡尾酒，1918年巴西圣保罗州乡村为流感患者调制（卡莎萨+青柠+糖，最初还加蒜），后演变为经典版本。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-caipirinha-6695cda74b13a.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-caipirinha-6695cda74b13a.webp', 93, 41, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":7.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["酸型鸡尾酒","卡莎萨基底","柑橘","捣压","经典","夏季"]', '["经典", "夏季"]', '{"baseSpirit":"卡莎萨基底","cocktailType":"酸型鸡尾酒","flavor":"柑橘、甘蔗","abv":"较高＞20%～30%","extra":"无明显非酒精成分","scene":["经典","夏季"]}', '[{"nameZh":"卡莎萨","nameEn":"Cachaça","amount":60,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"青柠","nameEn":"Lime","amount":1,"unit":"piece","role":"切成小块，捣压用"},{"nameZh":"细砂糖","nameEn":"White Cane Sugar","amount":16,"unit":"g","role":"4 茶匙"},{"nameZh":"碎冰","nameEn":"Cracked ice","amount":150,"unit":"ml","role":"加满杯"}]', '["厚底杯中加入青柠角与细砂糖。","用捣棒轻捣青柠释放汁液。","加满碎冰。","倒入卡莎萨，搅拌至糖完全溶解。"]', '["凯匹林纳", "卡皮利尼亚", "Caipirinha Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-caipirinha", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "凯匹林纳", "nameEn": "Caipirinha", "intro": "以卡莎萨、新鲜青柠与细砂糖捣压而成的巴西经典鸡尾酒，酸爽清甜，甘蔗香气清晰，是巴西代表性国民饮品。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-caipirinha-6695cda74b13a.webp", "tags": ["酸型鸡尾酒", "卡莎萨基底", "柑橘", "捣压", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "卡莎萨基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、甘蔗", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-margarita', 'cocktail', 'COCKTAIL', '玛格丽特', 'Margarita', 'magelite', 'mglt', '以龙舌兰、橙味利口酒与新鲜青柠汁组成的经典酸型鸡尾酒，酸度明亮，可选半圈盐边，是墨西哥风味的代表。', '本条目按 IBA 官方配比标准化：50 ml 银龙舌兰、20 ml 橙味利口酒与 15 ml 新鲜青柠汁摇和滤冰。盐边是可选装饰，不进入液体配比；橙味利口酒用君度或库拉索会带来不同甜度与酒精度。 背景：1930至40年代美墨边境地区流行，起源有多种传说（纪念名为玛格丽特的恋人等），龙舌兰+君度+青柠+盐边。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-margarita-6695cdd7505e0.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-margarita-6695cdd7505e0.webp', 93, 42, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":7.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["酸型鸡尾酒","龙舌兰基底","柑橘","盐边","摇和","经典"]', '["经典", "夏季"]', '{"baseSpirit":"龙舌兰基底","cocktailType":"酸型鸡尾酒","flavor":"柑橘","abv":"较高＞20%～30%","extra":["新鲜青柠汁","细海盐（可选）"],"scene":["经典","夏季"]}', '[{"nameZh":"100% 龙舌兰酒","nameEn":"Tequila 100% Agave","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"橙味利口酒","nameEn":"Triple Sec","amount":20,"unit":"ml","role":"橙香与甜度"},{"nameZh":"新鲜青柠汁","nameEn":"Freshly Squeezed Lime Juice","amount":15,"unit":"ml","role":"酸度核心"},{"nameZh":"细海盐","nameEn":"Salt","amount":1,"unit":"dash","role":"可选，半圈盐边"},{"nameZh":"青柠片","nameEn":"Lime slice","amount":1,"unit":"piece","role":"装饰用"}]', '["可选：以青柠润湿杯口，蘸取细盐作半圈盐边。","摇酒壶加冰，倒入龙舌兰、橙味利口酒与青柠汁。","摇和约 12 秒至充分降温。","滤入冰镇鸡尾酒杯。","以青柠片装饰。"]', '["玛格丽塔", "Margarita Cocktail", "经典玛格丽特"]', 'A', '2026-08-04', 1, '{"id": "cocktail-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "玛格丽特", "nameEn": "Margarita", "intro": "以龙舌兰、橙味利口酒与新鲜青柠汁组成的经典酸型鸡尾酒，酸度明亮，可选半圈盐边，是墨西哥风味的代表。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-margarita-6695cdd7505e0.webp", "tags": ["酸型鸡尾酒", "龙舌兰基底", "柑橘", "盐边", "摇和", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "细海盐（可选）"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-sunrise', 'cocktail', 'COCKTAIL', '龙舌兰日出', 'Tequila Sunrise', 'longshelanrichu', 'lslrc', '以银龙舌兰、新鲜橙汁与石榴糖浆直调的长饮，石榴糖浆沉底形成落日般的红橙渐变，色彩与果味都很鲜明。', '本条目按 IBA 官方配比标准化：45 ml 银龙舌兰、90 ml 橙汁，石榴糖浆沉底后用吸管缓缓倒入形成渐变。石榴糖浆密度较高会自然下沉，倒入过快会破坏分层效果。 背景：1970年代旧金山流行（雏形为1930年代亚利桑那的同名饮品），龙舌兰+橙汁+石榴糖浆，橙红渐变的“日出”效果是其标志，滚石乐队1972年巡演带火。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-tequila-sunrise-6695cdd3da10a.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-tequila-sunrise-6695cdd3da10a.webp', 91, 43, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":3.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["长饮","龙舌兰基底","果味","渐变","直调","夏季"]', '["夏季","派对"]', '{"baseSpirit":"龙舌兰基底","cocktailType":"高球","flavor":"柑橘、果香","abv":"中度＞10%～20%","extra":["新鲜橙汁","石榴糖浆"],"scene":["夏季","派对"]}', '[{"nameZh":"龙舌兰酒","nameEn":"Tequila","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜橙汁","nameEn":"Fresh Orange Juice","amount":90,"unit":"ml","role":"果香主体"},{"nameZh":"石榴糖浆","nameEn":"Grenadine Syrup","amount":15,"unit":"ml","role":"沉底形成日出渐变"},{"nameZh":"橙片","nameEn":"Orange slice","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加满冰块。","倒入龙舌兰与橙汁，轻搅混合。","沿杯壁缓缓倒入石榴糖浆，使其沉底形成日出渐变。","切勿搅拌，以橙片装饰。"]', '["龙舌兰日出鸡尾酒", "Tequila Sunrise Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-tequila-sunrise", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "龙舌兰日出", "nameEn": "Tequila Sunrise", "intro": "以银龙舌兰、新鲜橙汁与石榴糖浆直调的长饮，石榴糖浆沉底形成落日般的红橙渐变，色彩与果味都很鲜明。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-tequila-sunrise-6695cdd3da10a.webp", "tags": ["长饮", "龙舌兰基底", "果味", "渐变", "直调", "夏季"], "scene": ["夏季", "派对"], "recommendationScore": 91, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "柑橘、果香", "abv": "中度＞10%～20%", "extra": ["新鲜橙汁", "石榴糖浆"], "scene": ["夏季", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bloody-mary', 'cocktail', 'COCKTAIL', '血腥玛丽', 'Bloody Mary', 'xuexingmali', 'xxml', '以伏特加与番茄汁为主、加入柠檬汁与辣酱调味的咸鲜长饮，酸辣鲜香与浓稠质地结合，是经典佐餐鸡尾酒。', '本条目按 IBA 官方配比标准化：45 ml 伏特加、90 ml 番茄汁、15 ml 柠檬汁与适量辣酱、伍斯特酱、盐和胡椒。番茄汁的稠度与调味料的用量决定整体咸鲜与辣度，可按口味调整。 背景：1934年前后巴黎哈里酒吧（一说纽约圣瑞吉酒店由费迪南·佩蒂奥完善），以英国女王玛丽一世绰号“血腥玛丽”命名，伏特加+番茄汁+香料。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-bloody-mary-6695cda72fe0f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-bloody-mary-6695cda72fe0f.webp', 91, 46, '[{"key":"SWEETNESS","label":"甜度","score":1.0},{"key":"SOURNESS","label":"酸度","score":2.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":3.0}]', '["咸鲜","伏特加基底","番茄","辛辣","直调","早午餐"]', '["早午餐", "经典"]', '{"baseSpirit":"伏特加基底","cocktailType":"血腥玛丽类","flavor":"咸鲜、辛辣","abv":"中度＞10%～20%","extra":["番茄汁","伍斯特酱","新鲜柠檬汁"],"scene":["早午餐","经典"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"番茄汁","nameEn":"Tomato Juice","amount":90,"unit":"ml","role":"主体"},{"nameZh":"新鲜柠檬汁","nameEn":"Fresh Lemon Juice","amount":15,"unit":"ml","role":"提亮酸度"},{"nameZh":"伍斯特酱","nameEn":"Worcestershire Sauce","amount":2,"unit":"dash","role":"咸鲜风味"},{"nameZh":"塔巴斯科辣酱","nameEn":"Tabasco","amount":1,"unit":"dash","role":"可选，辣度"},{"nameZh":"芹菜盐","nameEn":"Celery Salt","amount":1,"unit":"dash","role":"可选，盐味"},{"nameZh":"芹菜杆","nameEn":"Celery stick","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"柠檬角","nameEn":"Lemon wedge","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加冰。","倒入伏特加、番茄汁、柠檬汁、伍斯特酱与辣酱。","撒入芹菜盐与黑胡椒。","以吧勺轻轻提拉混合。","以芹菜杆与柠檬角装饰。"]', '["Bloody Mary", "血腥玛丽鸡尾酒", "经典血腥玛丽"]', 'A', '2026-08-04', 1, '{"id": "cocktail-bloody-mary", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "血腥玛丽", "nameEn": "Bloody Mary", "intro": "以伏特加与番茄汁为主、加入柠檬汁与辣酱调味的咸鲜长饮，酸辣鲜香与浓稠质地结合，是经典佐餐鸡尾酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-bloody-mary-6695cda72fe0f.webp", "tags": ["咸鲜", "伏特加基底", "番茄", "辛辣", "直调", "早午餐"], "scene": ["早午餐", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、辛辣", "abv": "中度＞10%～20%", "extra": ["番茄汁", "伍斯特酱", "新鲜柠檬汁"], "scene": ["早午餐", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-john-collins', 'cocktail', 'COCKTAIL', '约翰·柯林斯', 'John Collins', 'yuehan·kelinsi', 'yh·kls', '以金酒配柠檬与糖浆、兑苏打水的经典柯林斯长饮，草本与柑橘酸度平衡，是柯林斯家族的鼻祖。', '本条目按 IBA 官方配比标准化：金酒 45 ml、新鲜柠檬汁 30 ml、单糖浆 15 ml，摇和后滤入加冰柯林斯杯，补 60 ml 苏打水，以柠檬片与樱桃装饰。IBA 现行配方以金酒为基（汤姆柯林斯则用老汤姆金酒）。 背景：原型以19世纪伦敦利默酒店侍者约翰·柯林斯命名；1876年“汤姆·柯林斯骗局”恶作剧使其名声大噪，用老汤姆金酒即汤姆柯林斯（本书收录的是汤姆柯林斯）。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-john-collins-669491130ef87.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-john-collins-669491130ef87.webp', 91, 53, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":5.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["长饮","金酒基底","柑橘","直调","经典"]', '["经典","夏季"]', '{"baseSpirit":"金酒基底","cocktailType":"科林斯","flavor":"柑橘、酸甜","abv":"中度＞10%～20%","extra":["新鲜柠檬汁","苏打水"],"scene":["经典","夏季"]}', '[{"nameZh":"金酒","nameEn":"Gin","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜柠檬汁","nameEn":"Fresh Lemon Juice","amount":30,"unit":"ml","role":"酸度核心"},{"nameZh":"单糖浆","nameEn":"Simple Syrup","amount":15,"unit":"ml","role":"平衡酸度"},{"nameZh":"苏打水","nameEn":"Soda Water","amount":60,"unit":"ml","role":"气泡补足"},{"nameZh":"柠檬片","nameEn":"Lemon slice","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"马拉斯奇诺樱桃","nameEn":"Maraschino cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["柯林斯杯加满冰块。","摇酒壶加冰，倒入金酒、柠檬汁与单糖浆，摇和约 10 秒。","滤入柯林斯杯。","补入苏打水，轻轻搅拌。","以柠檬片与马拉斯奇诺樱桃装饰。"]', '["约翰柯林斯鸡尾酒", "John Collins Cocktail"]', 'B', '2026-08-04', 1, '{"id": "cocktail-john-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "约翰·柯林斯", "nameEn": "John Collins", "intro": "以金酒配柠檬与糖浆、兑苏打水的经典柯林斯长饮，草本与柑橘酸度平衡，是柯林斯家族的鼻祖。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-john-collins-669491130ef87.webp", "tags": ["长饮", "金酒基底", "柑橘", "直调", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "科林斯", "flavor": "柑橘、酸甜", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-negroni', 'cocktail', 'COCKTAIL', '内格罗尼', 'Negroni', 'neigeluoni', 'ngln', '金酒、金巴利与甜红味美思等量构成的开胃鸡尾酒，苦甜草本并重、酒体较强，是苦味鸡尾酒的代表。', '本条目按 IBA 官方等量结构标准化：各 30 ml 金酒、金巴利与甜红味美思，搅拌后滤入加冰古典杯，以橙皮装饰。三者等量是内格罗尼不变的骨架，基酒风格决定苦甜走向。 背景：1919年前后佛罗伦萨，内格罗尼伯爵要求调酒师把美国佬的苏打水换成金酒以增强酒劲，遂以伯爵姓氏命名。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-negroni-6694911cc3b65.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-negroni-6694911cc3b65.webp', 93, 58, '[{"key":"SWEETNESS","label":"甜度","score":3.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":9.0},{"key":"ALCOHOL","label":"酒精感","score":8.0},{"key":"BODY","label":"酒体","score":6.0},{"key":"REFRESHING","label":"清爽度","score":3.0}]', '["烈酒主导", "金酒基底", "苦感主导", "草本", "搅拌", "高强度", "经典", "开胃"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}', '[{"nameZh":"金酒","nameEn":"Gin","amount":30,"unit":"ml","role":"IBA 等量配比"},{"nameZh":"金巴利","nameEn":"Bitter Campari","amount":30,"unit":"ml","role":"苦味核心"},{"nameZh":"甜红味美思","nameEn":"Sweet Red Vermouth","amount":30,"unit":"ml","role":"甜味平衡"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":80,"unit":"g","role":"搅拌用"},{"nameZh":"橙皮","nameEn":"Orange peel","amount":1,"unit":"piece","role":"装饰用，挤油提香"}]', '["古典杯加大块冰预冷。","搅拌杯加冰，倒入金酒、金巴利与甜红味美思。","搅拌约 20 秒至充分降温。","滤入加冰古典杯。","挤入橙皮油后投入橙皮装饰。"]', '["内格罗尼鸡尾酒", "Negroni Cocktail", "尼格罗尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-negroni", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "内格罗尼", "nameEn": "Negroni", "intro": "金酒、金巴利与甜红味美思等量构成的开胃鸡尾酒，苦甜草本并重、酒体较强，是苦味鸡尾酒的代表。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-negroni-6694911cc3b65.webp", "tags": ["烈酒主导", "金酒基底", "苦感主导", "草本", "搅拌", "高强度", "经典", "开胃"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-americano', 'cocktail', 'COCKTAIL', '美国佬', 'Americano', 'meiguolao', 'mgl', '以金巴利与甜红味美思等量调配、再以苏打水冲调而成的开胃长饮，苦甜交织并带柑橘与草本气息，口感清爽，适合餐前饮用。', 'IBA 标准为金巴利与甜红味美思各 30 ml 加苏打水冲调，V6 采用此配比；相比内格罗尼去掉金酒、以苏打水拉长，苦度与酒精感均更低。 背景：1860年代诞生于意大利米兰金巴利咖啡馆，原名“米兰-都灵”（Milano-Torino，金巴利+甜味美思+苏打水），因20世纪初美国游客偏爱而得名美国佬。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-americano-669490fe3cb42.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-americano-669490fe3cb42.webp', 89, 61, '[{"key":"SWEETNESS","label":"甜度","score":3.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":7.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":4.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["开胃","金巴利","苦甜","草本","直调","低酒精度"]', '["开胃", "经典"]', '{"baseSpirit":"金巴利基底","cocktailType":"高球","flavor":"苦感主导、草本","abv":"中度＞10%～20%","extra":["苏打水"],"scene":["开胃","经典"]}', '[{"nameZh":"金巴利","nameEn":"Bitter Campari","amount":30,"unit":"ml","role":"IBA 等量配比"},{"nameZh":"甜红味美思","nameEn":"Sweet Red Vermouth","amount":30,"unit":"ml","role":"甜味平衡"},{"nameZh":"苏打水","nameEn":"Soda Water","amount":60,"unit":"ml","role":"冲调补足"},{"nameZh":"橙片","nameEn":"Orange slice","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"柠檬皮","nameEn":"Lemon zest","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加满冰块。","倒入金巴利与甜红味美思。","补入苏打水。","轻轻搅拌。","以半片橙片与柠檬皮装饰。"]', '["Americano", "美式开胃酒", "金巴利味美思苏打"]', 'A', '2026-08-04', 1, '{"id": "cocktail-americano", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "美国佬", "nameEn": "Americano", "intro": "以金巴利与甜红味美思等量调配、再以苏打水冲调而成的开胃长饮，苦甜交织并带柑橘与草本气息，口感清爽，适合餐前饮用。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-americano-669490fe3cb42.webp", "tags": ["开胃", "金巴利", "苦甜", "草本", "直调", "低酒精度"], "scene": ["开胃", "经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "金巴利基底", "cocktailType": "高球", "flavor": "苦感主导、草本", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-moscow-mule', 'cocktail', 'COCKTAIL', '莫斯科骡子', 'Moscow Mule', 'mosikeluozi', 'msklz', '以伏特加、姜汁啤酒与新鲜青柠汁调制而成的经典骡子鸡尾酒，姜味辛辣与青柠酸香平衡，气泡充足，传统以铜杯盛装。', 'IBA 标准以伏特加、姜汁啤酒与青柠汁调配，V6 采用此配比；相比姜汁威士忌，基底换成伏特加，姜味更干净、无威士忌木质调。 背景：1941年洛杉矶Cock \'n\' Bull酒吧，伏特加厂商约翰·马丁与姜汁啤酒商联手推广伏特加而创，标志性铜杯盛装。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-moscow-mule-6695cdc7d8cb2.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-moscow-mule-6695cdc7d8cb2.webp', 91, 70, '[{"key":"SWEETNESS","label":"甜度","score":3.0},{"key":"SOURNESS","label":"酸度","score":5.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":8.0}]', '["长饮","伏特加基底","姜味","直调","铜杯","经典"]', '["经典","夏季"]', '{"baseSpirit":"伏特加基底","cocktailType":"雄鹿","flavor":"姜味、柑橘","abv":"中度＞10%～20%","extra":["姜汁啤酒","新鲜青柠汁"],"scene":["经典","夏季"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"姜汁啤酒","nameEn":"Ginger Beer","amount":120,"unit":"ml","role":"姜味与气泡"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":10,"unit":"ml","role":"酸香平衡"},{"nameZh":"青柠片","nameEn":"Lime slice","amount":1,"unit":"piece","role":"装饰用"}]', '["铜杯加满冰块。","倒入伏特加与新鲜青柠汁。","补入冷藏姜汁啤酒。","轻轻搅拌混合。","以青柠片装饰。"]', '["Moscow Mule", "莫斯科骡", "铜杯骡子"]', 'A', '2026-08-04', 1, '{"id": "cocktail-moscow-mule", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "莫斯科骡子", "nameEn": "Moscow Mule", "intro": "以伏特加、姜汁啤酒与新鲜青柠汁调制而成的经典骡子鸡尾酒，姜味辛辣与青柠酸香平衡，气泡充足，传统以铜杯盛装。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-moscow-mule-6695cdc7d8cb2.webp", "tags": ["长饮", "伏特加基底", "姜味", "直调", "铜杯", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sea-breeze', 'cocktail', 'COCKTAIL', '海风', 'Sea Breeze', 'haifeng', 'hf', '以伏特加为基底、混合蔓越莓汁与葡萄柚汁的粉红长饮，酸甜多汁、带葡萄柚的微苦回甘，清爽度很高。', '配方采用 IBA 官方配比：伏特加 40 ml、蔓越莓汁 120 ml 与葡萄柚汁 30 ml，在高球杯中直调。果汁品牌与含糖量会影响酸甜平衡，酒精度为编辑估算值。 背景：1920年代已有伏特加版记录，1980年代以蔓越莓汁+西柚汁版本流行，伏特加+蔓越莓汁+西柚汁，清透如海风。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-sea-breeze-6695cdce015a8.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-sea-breeze-6695cdce015a8.webp', 93, 76, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":4.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["长饮","伏特加基底","蔓越莓","葡萄柚","直调","夏季"]', '["夏季","经典"]', '{"baseSpirit":"伏特加基底","cocktailType":"高球","flavor":"蔓越莓、柑橘","abv":"低度≤10%","extra":["蔓越莓汁","葡萄柚汁"],"scene":["夏季","经典"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":40,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"蔓越莓汁","nameEn":"Cranberry Juice","amount":120,"unit":"ml","role":"果味主体"},{"nameZh":"葡萄柚汁","nameEn":"Grapefruit Juice","amount":30,"unit":"ml","role":"微苦回甘"},{"nameZh":"橙皮","nameEn":"Orange zest","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"马拉斯奇诺樱桃","nameEn":"Cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加满冰块。","倒入伏特加、蔓越莓汁与葡萄柚汁。","轻轻搅拌混合。","以橙皮与樱桃装饰。"]', '["Sea Breeze", "海风鸡尾酒", "海洋微风"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sea-breeze", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "海风", "nameEn": "Sea Breeze", "intro": "以伏特加为基底、混合蔓越莓汁与葡萄柚汁的粉红长饮，酸甜多汁、带葡萄柚的微苦回甘，清爽度很高。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-sea-breeze-6695cdce015a8.webp", "tags": ["长饮", "伏特加基底", "蔓越莓", "葡萄柚", "直调", "夏季"], "scene": ["夏季", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蔓越莓、柑橘", "abv": "低度≤10%", "extra": ["蔓越莓汁", "葡萄柚汁"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sex-on-the-beach', 'cocktail', 'COCKTAIL', '性感沙滩', 'Sex on the Beach', 'xingganshatan', 'xgst', '以伏特加与蜜桃利口酒为基底、混合橙汁与蔓越莓汁的果味长饮，蜜桃香甜与莓果酸爽平衡，适合夏季畅饮。', '配方采用 IBA 官方配比：伏特加 40 ml、蜜桃利口酒 20 ml、橙汁 40 ml 与蔓越莓汁 40 ml，在高球杯中直调。蜜桃利口酒与果汁的含糖量影响甜度，酒精度为编辑估算值。 背景：1980年代佛罗里达（一说Confetti\'s酒吧泰德·皮齐奥创制），伏特加+桃子利口酒+橙汁+蔓越莓汁，因大胆的名字风靡。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-sex-on-the-beach-6695cdd0aecf3.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-sex-on-the-beach-6695cdd0aecf3.webp', 93, 78, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":3.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["长饮","伏特加基底","蜜桃","果味","直调","夏季"]', '["夏季","派对"]', '{"baseSpirit":"伏特加基底","cocktailType":"高球","flavor":"蜜桃、蔓越莓","abv":"中度＞10%～20%","extra":["新鲜橙汁","蔓越莓汁"],"scene":["夏季","派对"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":40,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"蜜桃利口酒","nameEn":"Peach Schnapps","amount":20,"unit":"ml","role":"蜜桃甜香"},{"nameZh":"新鲜橙汁","nameEn":"Fresh Orange Juice","amount":40,"unit":"ml","role":"柑橘果味"},{"nameZh":"蔓越莓汁","nameEn":"Cranberry Juice","amount":40,"unit":"ml","role":"莓果酸度"},{"nameZh":"橙片","nameEn":"Orange slice","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加满冰块。","倒入伏特加、蜜桃利口酒、橙汁与蔓越莓汁。","轻轻搅拌混合。","以半片橙片装饰。"]', '["Sex on the Beach", "沙滩风情", "蜜桃蔓越莓长饮"]', 'B', '2026-08-04', 1, '{"id": "cocktail-sex-on-the-beach", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "性感沙滩", "nameEn": "Sex on the Beach", "intro": "以伏特加与蜜桃利口酒为基底、混合橙汁与蔓越莓汁的果味长饮，蜜桃香甜与莓果酸爽平衡，适合夏季畅饮。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-sex-on-the-beach-6695cdd0aecf3.webp", "tags": ["长饮", "伏特加基底", "蜜桃", "果味", "直调", "夏季"], "scene": ["夏季", "派对"], "recommendationScore": 93, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "高球", "flavor": "蜜桃、蔓越莓", "abv": "中度＞10%～20%", "extra": ["新鲜橙汁", "蔓越莓汁"], "scene": ["夏季", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tequila-paloma', 'cocktail', 'COCKTAIL', '帕洛玛', 'Paloma', 'paluoma', 'plm', '以龙舌兰为基底、配粉红葡萄柚苏打与青柠的清爽长饮，葡萄柚的酸甜微苦与龙舌兰植物香相得益彰，是墨西哥国民调酒。', '配方采用 IBA 官方配比：100% 龙舌兰 50 ml、青柠汁 5 ml、少许盐，加冰后以粉红葡萄柚苏打补满。盐可增强果味，甜酸随苏打品牌浮动，酒精度为编辑估算值。 背景：1950年代墨西哥流行的国民调酒，龙舌兰+西柚苏打（Squirt）+青柠，“帕洛玛”意为鸽子。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-paloma-6695d3b19cda4.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-paloma-6695d3b19cda4.webp', 93, 79, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":4.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":4.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":8.0}]', '["长饮","龙舌兰基底","葡萄柚","气泡","直调","夏季"]', '["夏季","经典"]', '{"baseSpirit":"龙舌兰基底","cocktailType":"高球","flavor":"葡萄柚、柑橘","abv":"中度＞10%～20%","extra":["葡萄柚苏打","新鲜青柠汁"],"scene":["夏季","经典"]}', '[{"nameZh":"100% 龙舌兰酒","nameEn":"Tequila 100% Agave","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":5,"unit":"ml","role":"现挤提香"},{"nameZh":"细盐","nameEn":"Salt","amount":1,"unit":"dash","role":"提升果味"},{"nameZh":"粉红葡萄柚苏打","nameEn":"Pink Grapefruit Soda","amount":100,"unit":"ml","role":"补满杯"},{"nameZh":"青柠片","nameEn":"Lime slice","amount":1,"unit":"piece","role":"装饰用"}]', '["高球杯加满冰块。","倒入龙舌兰，挤入青柠汁。","撒入少许盐。","补入粉红葡萄柚苏打。","轻轻搅拌，以青柠片装饰。"]', '["Paloma", "帕洛玛", "龙舌兰葡萄柚苏打"]', 'B', '2026-08-04', 1, '{"id": "cocktail-tequila-paloma", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "帕洛玛", "nameEn": "Paloma", "intro": "以龙舌兰为基底、配粉红葡萄柚苏打与青柠的清爽长饮，葡萄柚的酸甜微苦与龙舌兰植物香相得益彰，是墨西哥国民调酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-paloma-6695d3b19cda4.webp", "tags": ["长饮", "龙舌兰基底", "葡萄柚", "气泡", "直调", "夏季"], "scene": ["夏季", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "高球", "flavor": "葡萄柚、柑橘", "abv": "中度＞10%～20%", "extra": ["葡萄柚苏打", "新鲜青柠汁"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mai-tai', 'cocktail', 'COCKTAIL', '迈泰', 'Mai Tai', 'maitai', 'mt', '以牙买加琥珀朗姆与马提尼克朗姆为基底、配橙味库拉索与杏仁糖浆的提基经典，青柠酸爽与坚果甜香平衡，热带气息浓郁。', '配方遵循 IBA 官方配比：牙买加琥珀朗姆 30 ml、马提尼克朗姆 30 ml、橙味库拉索 15 ml、杏仁糖浆 15 ml、青柠汁 30 ml 与单糖浆 7.5 ml，加冰摇和后连同碎冰倒入双老式杯。朗姆陈年与库拉索品牌影响风味。 背景：1944年加州奥克兰Trader Vic酒吧老板维克多·伯杰龙（Victor Bergeron）创制，朋友尝后惊叹“迈泰！”（塔希提语“最好的”），朗姆+橙皮利口酒+青柠+杏仁糖浆。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mai-tai-6695cdc169ea3.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mai-tai-6695cdc169ea3.webp', 93, 80, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":6.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":7.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":5.0}]', '["提基","朗姆基底","坚果","热带水果","摇和","经典"]', '["经典","热带"]', '{"baseSpirit":"朗姆基底","cocktailType":"提基","flavor":"坚果、柑橘","abv":"较高＞20%～30%","extra":["新鲜青柠汁","杏仁糖浆"],"scene":["经典","热带"]}', '[{"nameZh":"牙买加琥珀朗姆","nameEn":"Amber Jamaican Rum","amount":30,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"马提尼克朗姆","nameEn":"Martinique Rhum","amount":30,"unit":"ml","role":"甘蔗风味"},{"nameZh":"橙味库拉索","nameEn":"Orange Curaçao","amount":15,"unit":"ml","role":"橙香"},{"nameZh":"杏仁糖浆","nameEn":"Orgeat Syrup","amount":15,"unit":"ml","role":"坚果甜香"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":30,"unit":"ml","role":"酸度核心"},{"nameZh":"单糖浆","nameEn":"Simple Syrup","amount":7.5,"unit":"ml","role":"微调甜度"},{"nameZh":"菠萝角","nameEn":"Pineapple spear","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"薄荷叶","nameEn":"Mint leaves","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"青柠皮","nameEn":"Lime peel","amount":1,"unit":"piece","role":"装饰用"}]', '["摇酒壶加冰，倒入两种朗姆、橙味库拉索、杏仁糖浆、青柠汁与单糖浆。","摇和约 12 秒至充分降温。","连同碎冰倒入双老式杯或高球杯。","以菠萝角、薄荷叶与青柠皮装饰。"]', '["Mai Tai", "麦泰", "迈泰鸡尾酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mai-tai", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "迈泰", "nameEn": "Mai Tai", "intro": "以牙买加琥珀朗姆与马提尼克朗姆为基底、配橙味库拉索与杏仁糖浆的提基经典，青柠酸爽与坚果甜香平衡，热带气息浓郁。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mai-tai-6695cdc169ea3.webp", "tags": ["提基", "朗姆基底", "坚果", "热带水果", "摇和", "经典"], "scene": ["经典", "热带"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "坚果、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜青柠汁", "杏仁糖浆"], "scene": ["经典", "热带"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-zombie', 'cocktail', 'COCKTAIL', '僵尸', 'Zombie', 'jiangshi', 'js', '以牙买加黑朗姆、波多黎各金朗姆与德梅拉拉朗姆三种朗姆叠配的高酒精度提基鸡尾酒，青柠与热带风味浓烈，源自 1934 年好莱坞提基酒吧。', '配方遵循 IBA 官方配比：牙买加黑朗姆 45 ml、波多黎各金朗姆 45 ml、德梅拉拉朗姆 30 ml、青柠汁 20 ml、法勒纳姆 15 ml、唐氏混合汁 15 ml、石榴糖浆 1 茶匙、安格斯图拉苦精 1 滴与佩诺 6 滴，加碎冰搅打后倒入高脚杯。 背景：1934年洛杉矶Don the Beachcomber酒吧老板唐恩·比奇创制，多种朗姆+多种果汁+苦精，酒劲极强，名字暗示“喝完如僵尸”。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-zombie-6695cdd6cef05.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-zombie-6695cdd6cef05.webp', 91, 81, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":5.0},{"key":"BITTERNESS","label":"苦度","score":3.0},{"key":"ALCOHOL","label":"酒精感","score":9.0},{"key":"BODY","label":"酒体","score":6.0},{"key":"REFRESHING","label":"清爽度","score":4.0}]', '["提基","朗姆基底","热带水果","高度数","摇和","派对"]', '["经典","派对"]', '{"baseSpirit":"朗姆基底","cocktailType":"提基","flavor":"热带水果、香料","abv":"高度＞30%","extra":["新鲜青柠汁","唐氏混合汁"],"scene":["经典","派对"]}', '[{"nameZh":"牙买加黑朗姆","nameEn":"Jamaican Dark Rum","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"波多黎各金朗姆","nameEn":"Gold Puerto Rican Rum","amount":45,"unit":"ml","role":"甜润"},{"nameZh":"德梅拉拉朗姆","nameEn":"Demerara Rum","amount":30,"unit":"ml","role":"焦糖香料"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":20,"unit":"ml","role":"酸度核心"},{"nameZh":"法勒纳姆利口酒","nameEn":"Falernum","amount":15,"unit":"ml","role":"香料甜香"},{"nameZh":"唐氏混合汁","nameEn":"Donn\'s Mix","amount":15,"unit":"ml","role":"葡萄柚+肉桂糖浆"},{"nameZh":"石榴糖浆","nameEn":"Grenadine Syrup","amount":5,"unit":"ml","role":"1 茶匙"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":1,"unit":"dash","role":"提升层次"},{"nameZh":"佩诺茴香酒","nameEn":"Pernod","amount":1,"unit":"dash","role":"约 6 滴"},{"nameZh":"薄荷叶","nameEn":"Mint leaves","amount":1,"unit":"piece","role":"装饰用"}]', '["搅拌机中加入三种朗姆、青柠汁、法勒纳姆、唐氏混合汁、石榴糖浆、苦精与佩诺。","加入约 170 克碎冰，点动搅打数秒。","倒入高脚直身杯。","以薄荷叶装饰。"]', '["Zombie", "僵尸鸡尾酒", "僵尸提基"]', 'B', '2026-08-04', 1, '{"id": "cocktail-zombie", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "僵尸", "nameEn": "Zombie", "intro": "以牙买加黑朗姆、波多黎各金朗姆与德梅拉拉朗姆三种朗姆叠配的高酒精度提基鸡尾酒，青柠与热带风味浓烈，源自 1934 年好莱坞提基酒吧。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-zombie-6695cdd6cef05.webp", "tags": ["提基", "朗姆基底", "热带水果", "高度数", "摇和", "派对"], "scene": ["经典", "派对"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "热带水果、香料", "abv": "高度＞30%", "extra": ["新鲜青柠汁", "唐氏混合汁"], "scene": ["经典", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pina-colada', 'cocktail', 'COCKTAIL', '椰林飘香', 'Piña Colada', 'yelinpiaoxiang', 'ylpx', '以白朗姆、椰浆与菠萝汁搅打而成的热带鸡尾酒，奶油质感绵密、菠萝椰香浓郁，波多黎各的国民饮品，也是 IBA 官方经典。', '配方遵循 IBA 官方配比：白朗姆 50 ml、椰浆 30 ml 与菠萝汁 50 ml，加碎冰搅打至顺滑，以菠萝片与樱桃装饰。椰浆品牌与熟度影响甜度，ABV 为编辑估算值。 背景：1954年前后波多黎各圣胡安加勒比希尔顿酒店调酒师拉蒙·马雷罗（Ramón Marrero）创制，朗姆+椰浆+菠萝汁，波多黎各国饮。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-pina-colada-6695cdcabbf00.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-pina-colada-6695cdcabbf00.webp', 91, 82, '[{"key":"SWEETNESS","label":"甜度","score":8.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":5.0},{"key":"BODY","label":"酒体","score":7.0},{"key":"REFRESHING","label":"清爽度","score":5.0}]', '["提基","朗姆基底","椰子","菠萝","搅打","夏季"]', '["夏季","热带"]', '{"baseSpirit":"朗姆基底","cocktailType":"提基","flavor":"椰子、菠萝","abv":"中度＞10%～20%","extra":["椰浆","新鲜菠萝汁"],"scene":["夏季","热带"]}', '[{"nameZh":"白朗姆酒","nameEn":"White Rum","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"椰浆","nameEn":"Coconut Cream","amount":30,"unit":"ml","role":"奶油质感"},{"nameZh":"新鲜菠萝汁","nameEn":"Fresh Pineapple Juice","amount":50,"unit":"ml","role":"果香主体"},{"nameZh":"碎冰","nameEn":"Crushed ice","amount":150,"unit":"ml","role":"搅打用"},{"nameZh":"菠萝片","nameEn":"Pineapple slice","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"鸡尾酒樱桃","nameEn":"Cocktail cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["搅拌机中加入白朗姆、椰浆、菠萝汁与碎冰。","搅打约 20 秒至质地顺滑。","倒入大杯。","以菠萝片与鸡尾酒樱桃装饰，配吸管饮用。"]', '["Piña Colada", "椰林飘香", "皮娜可乐达"]', 'A', '2026-08-04', 1, '{"id": "cocktail-pina-colada", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "椰林飘香", "nameEn": "Piña Colada", "intro": "以白朗姆、椰浆与菠萝汁搅打而成的热带鸡尾酒，奶油质感绵密、菠萝椰香浓郁，波多黎各的国民饮品，也是 IBA 官方经典。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-pina-colada-6695cdcabbf00.webp", "tags": ["提基", "朗姆基底", "椰子", "菠萝", "搅打", "夏季"], "scene": ["夏季", "热带"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "椰子、菠萝", "abv": "中度＞10%～20%", "extra": ["椰浆", "新鲜菠萝汁"], "scene": ["夏季", "热带"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-suffering-bastard', 'cocktail', 'COCKTAIL', '受难杂种', 'Suffering Bastard', 'shounanzazhong', 'snzz', '以金酒与白兰地双烈酒为基底、配姜汁啤酒与青柠的高球式提基饮品，辛香果味交织，苦甜平衡，源于二战时期的开罗酒吧。', '配方遵循 IBA 官方配比：白兰地 30 ml、金酒 30 ml、青柠汁 15 ml 与安格斯图拉苦精 2 滴摇和，连冰倒入柯林斯杯后以姜汁啤酒补足。姜汁啤酒品牌决定辣度强度，ABV 为编辑估算值。 背景：1942年埃及开罗谢泼德酒店（二战时期）创制，金酒/朗姆+姜汁啤酒+青柠，名字源于酒保对宿醉客人的调侃。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-suffering-bastard-6695d3c1081c4.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-suffering-bastard-6695d3c1081c4.webp', 91, 89, '[{"key":"SWEETNESS","label":"甜度","score":3.0},{"key":"SOURNESS","label":"酸度","score":4.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":5.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["长饮","金酒基底","姜味","直调","夏季","经典"]', '["夏季", "经典"]', '{"baseSpirit":"金酒基底","cocktailType":"长饮","flavor":"姜味、柑橘","abv":"中度＞10%～20%","extra":["姜汁啤酒","新鲜青柠汁"],"scene":["夏季","经典"]}', '[{"nameZh":"白兰地","nameEn":"Cognac or Brandy","amount":30,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"金酒","nameEn":"Gin","amount":30,"unit":"ml","role":"双基酒之一"},{"nameZh":"新鲜青柠汁","nameEn":"Fresh Lime Juice","amount":15,"unit":"ml","role":"酸度平衡"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":2,"unit":"dash","role":"提升层次"},{"nameZh":"姜汁啤酒","nameEn":"Ginger Beer","amount":100,"unit":"ml","role":"加满顶部"},{"nameZh":"薄荷枝","nameEn":"Mint sprig","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"橙片","nameEn":"Orange slice","amount":1,"unit":"piece","role":"装饰用，可选"}]', '["摇酒壶加冰，倒入白兰地、金酒、青柠汁与苦精。","摇和约 10 秒。","连冰倒入柯林斯杯。","补入姜汁啤酒。","以薄荷枝与橙片装饰。"]', '["Suffering Bastard", "受苦混蛋", "受难者"]', 'B', '2026-08-04', 1, '{"id": "cocktail-suffering-bastard", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "受难杂种", "nameEn": "Suffering Bastard", "intro": "以金酒与白兰地双烈酒为基底、配姜汁啤酒与青柠的高球式提基饮品，辛香果味交织，苦甜平衡，源于二战时期的开罗酒吧。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-suffering-bastard-6695d3c1081c4.webp", "tags": ["长饮", "金酒基底", "姜味", "直调", "夏季", "经典"], "scene": ["夏季", "经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "长饮", "flavor": "姜味、柑橘", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bellini', 'cocktail', 'COCKTAIL', '贝利尼', 'Bellini', 'beilini', 'bln', '以普罗塞克与白桃泥调和而成的意大利开胃起泡鸡尾酒，蜜桃果香细腻清甜，气泡轻盈，是经典早午餐与开胃场合饮品。', 'IBA 官方配比为 100 ml 普罗塞克兑 50 ml 白桃泥，直调于预冷笛型杯。白桃泥的新鲜度与甜度决定整体口感，属编辑估算值。 背景：1948年威尼斯哈里酒吧老板朱塞佩·奇普里亚尼创制，因色泽如威尼斯画家乔瓦尼·贝利尼画中的晚霞而命名，桃泥+普罗塞克气泡酒。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-bellini-6695cda4217da.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-bellini-6695cda4217da.webp', 91, 96, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":3.0},{"key":"BODY","label":"酒体","score":2.0},{"key":"REFRESHING","label":"清爽度","score":8.0}]', '["起泡","蜜桃","果味","直调","早午餐","开胃"]', '["早午餐", "开胃"]', '{"baseSpirit":"起泡酒基底","cocktailType":"菲兹","flavor":"蜜桃、果香","abv":"低度≤10%","extra":"无明显非酒精成分","scene":["早午餐","开胃"]}', '[{"nameZh":"普罗塞克","nameEn":"Prosecco","amount":100,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"白桃泥","nameEn":"White Peach Puree","amount":50,"unit":"ml","role":"蜜桃果香"}]', '["将香槟笛型杯预冷。","杯底倒入白桃泥。","缓缓注入冰镇普罗塞克，轻搅混合即可。"]', '["贝里尼", "Bellini", "桃子贝利尼"]', 'A', '2026-08-04', 1, '{"id": "cocktail-bellini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "贝利尼", "nameEn": "Bellini", "intro": "以普罗塞克与白桃泥调和而成的意大利开胃起泡鸡尾酒，蜜桃果香细腻清甜，气泡轻盈，是经典早午餐与开胃场合饮品。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-bellini-6695cda4217da.webp", "tags": ["起泡", "蜜桃", "果味", "直调", "早午餐", "开胃"], "scene": ["早午餐", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "蜜桃、果香", "abv": "低度≤10%", "extra": "无明显非酒精成分", "scene": ["早午餐", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mimosa', 'cocktail', 'COCKTAIL', '含羞草', 'Mimosa', 'hanxiucao', 'hxc', '以普罗塞克与鲜榨橙汁等比例调和而成的开胃气泡鸡尾酒，柑橘香气明亮、气泡轻盈干爽，是经典早午餐与庆祝场合饮品。', 'IBA 官方配比为鲜榨橙汁与普罗塞克各 75 ml，直调于笛型杯。起泡酒与橙汁比例可按杯型调整，别名 Buck\'s Fizz。 背景：1925年巴黎丽兹酒店调酒师弗兰克·迈耶（Frank Meier）创制，以含羞草花命名，橙汁+香槟，成为早午餐经典。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mimosa-6695cdc4463c9.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mimosa-6695cdc4463c9.webp', 91, 97, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":2.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":3.0},{"key":"BODY","label":"酒体","score":2.0},{"key":"REFRESHING","label":"清爽度","score":8.0}]', '["起泡","柑橘","果味","直调","早午餐","开胃"]', '["早午餐", "开胃"]', '{"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜橙汁"], "scene": ["早午餐", "开胃"]}', '[{"nameZh":"新鲜橙汁","nameEn":"Freshly Squeezed Orange Juice","amount":75,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"普罗塞克","nameEn":"Prosecco","amount":75,"unit":"ml","role":"气泡补足"},{"nameZh":"橙皮","nameEn":"Orange twist","amount":1,"unit":"piece","role":"装饰用，可选"}]', '["将笛型杯预冷。","先倒入鲜榨橙汁。","缓缓注入冰镇普罗塞克。","轻搅混合，可加橙皮装饰。"]', '["美美酒", "Mimosa", "香槟橙汁"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mimosa", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "含羞草", "nameEn": "Mimosa", "intro": "以普罗塞克与鲜榨橙汁等比例调和而成的开胃气泡鸡尾酒，柑橘香气明亮、气泡轻盈干爽，是经典早午餐与庆祝场合饮品。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mimosa-6695cdc4463c9.webp", "tags": ["起泡", "柑橘", "果味", "直调", "早午餐", "开胃"], "scene": ["早午餐", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "柑橘、果香", "abv": "低度≤10%", "extra": ["新鲜橙汁"], "scene": ["早午餐", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-french-75', 'cocktail', 'COCKTAIL', '法兰西75', 'French 75', 'falanxi75', 'flx7', '以金酒、柠檬汁、糖浆与香槟调制而成的经典气泡鸡尾酒，金酒草本与柠檬酸香为底，香槟气泡轻盈，是优雅的餐前或庆祝饮品。', 'IBA 官方配比为金酒 30 ml、柠檬汁 15 ml、糖浆 15 ml 摇和后滤入笛型杯，再以 60 ml 香槟补足。香槟用量决定气泡与酒体。 背景：以一战法国75毫米野战炮命名，1920年代巴黎流行，金酒+柠檬+糖+香槟。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-french-75-6695cdb175e06.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-french-75-6695cdb175e06.webp', 91, 100, '[{"key":"SWEETNESS","label":"甜度","score":4.0},{"key":"SOURNESS","label":"酸度","score":6.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":5.0},{"key":"BODY","label":"酒体","score":3.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["起泡","金酒基底","柑橘","摇和","庆祝","经典"]', '["开胃","庆祝"]', '{"baseSpirit":"金酒基底","cocktailType":"菲兹","flavor":"柑橘、草本","abv":"中度＞10%～20%","extra":["新鲜柠檬汁"],"scene":["开胃","庆祝"]}', '[{"nameZh":"金酒","nameEn":"Gin","amount":30,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜柠檬汁","nameEn":"Fresh Lemon Juice","amount":15,"unit":"ml","role":"酸度核心"},{"nameZh":"单糖浆","nameEn":"Sugar Syrup","amount":15,"unit":"ml","role":"平衡酸度"},{"nameZh":"香槟","nameEn":"Champagne","amount":60,"unit":"ml","role":"气泡补足"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":80,"unit":"g","role":"摇和用"}]', '["将笛型杯预冷。","摇酒壶加冰，倒入金酒、柠檬汁与单糖浆，摇和约 10 秒。","滤入笛型杯。","补入冰镇香槟，轻搅混合。"]', '["法国75号", "French 75", "French Seventy-Five"]', 'A', '2026-08-04', 1, '{"id": "cocktail-french-75", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "法兰西75", "nameEn": "French 75", "intro": "以金酒、柠檬汁、糖浆与香槟调制而成的经典气泡鸡尾酒，金酒草本与柠檬酸香为底，香槟气泡轻盈，是优雅的餐前或庆祝饮品。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-french-75-6695cdb175e06.webp", "tags": ["起泡", "金酒基底", "柑橘", "摇和", "庆祝", "经典"], "scene": ["开胃", "庆祝"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、草本", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁"], "scene": ["开胃", "庆祝"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-champagne-cocktail', 'cocktail', 'COCKTAIL', '香槟鸡尾酒', 'Champagne Cocktail', 'xiangbinjiweijiu', 'xbjwj', '在方糖上滴苦精、注入香槟再补以白兰地的经典起泡鸡尾酒，气泡细腻，兼具干冽口感与微苦层次，是香槟调酒的代表做法。', '本条目按 IBA 配比标准化：方糖加 2 滴安格斯图拉苦精，倒入 10 ml 干邑，再注入 90 ml 冰镇香槟，以橙皮与樱桃装饰。直接在笛型杯中直调完成。 背景：19世纪末的经典香槟开场酒，香槟+方糖+苦精，1862年杰里·托马斯著作已收录。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-champagne-cocktail-6695cdaa71bb2.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-champagne-cocktail-6695cdaa71bb2.webp', 93, 104, '[{"key":"SWEETNESS","label":"甜度","score":3.0},{"key":"SOURNESS","label":"酸度","score":2.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":5.0},{"key":"BODY","label":"酒体","score":2.0},{"key":"REFRESHING","label":"清爽度","score":7.0}]', '["开胃","起泡","香槟","苦甜","直调","经典"]', '["开胃", "经典"]', '{"baseSpirit":"起泡酒基底","cocktailType":"菲兹","flavor":"苦甜、果香","abv":"中度＞10%～20%","extra":"无明显非酒精成分","scene":["开胃","经典"]}', '[{"nameZh":"香槟","nameEn":"Chilled Champagne","amount":90,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"干邑白兰地","nameEn":"Cognac","amount":10,"unit":"ml","role":"补足酒感"},{"nameZh":"方糖","nameEn":"Sugar cube","amount":1,"unit":"piece","role":"承托苦精"},{"nameZh":"安格斯图拉苦精","nameEn":"Angostura Bitters","amount":2,"unit":"dash","role":"官方用量"},{"nameZh":"橙皮","nameEn":"Orange zest","amount":1,"unit":"piece","role":"装饰用"},{"nameZh":"马拉斯奇诺樱桃","nameEn":"Maraschino cherry","amount":1,"unit":"piece","role":"装饰用"}]', '["将方糖放入香槟杯底。","在方糖上滴安格斯图拉苦精。","倒入干邑白兰地。","缓缓注入冰镇香槟，避免冲击气泡。","以橙皮与马拉斯奇诺樱桃装饰。"]', '["Champagne Cocktail", "香槟古典", "Classic Champagne Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-champagne-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "香槟鸡尾酒", "nameEn": "Champagne Cocktail", "intro": "在方糖上滴苦精、注入香槟再补以白兰地的经典起泡鸡尾酒，气泡细腻，兼具干冽口感与微苦层次，是香槟调酒的代表做法。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-champagne-cocktail-6695cdaa71bb2.webp", "tags": ["开胃", "起泡", "香槟", "苦甜", "直调", "经典"], "scene": ["开胃", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "菲兹", "flavor": "苦甜、果香", "abv": "中度＞10%～20%", "extra": "无明显非酒精成分", "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-irish-coffee', 'cocktail', 'COCKTAIL', '爱尔兰咖啡', 'Irish Coffee', 'aierlankafei', 'aelkf', '以爱尔兰威士忌、热咖啡与砂糖调制，覆以打发奶油的热饮鸡尾酒，兼具咖啡香、威士忌酒感与奶油顺滑。', '本条目按 IBA 官方配比标准化：50 ml 爱尔兰威士忌、120 ml 热咖啡与一茶匙砂糖搅拌至溶解，再沿勺背缓缓倒入 50 ml 冷藏淡奶油使其漂浮。使用玻璃杯并先热杯可保持温度。 背景：1943年爱尔兰福因斯机场厨师乔·谢里登（Joe Sheridan）为美国航班乘客调制，威士忌+热咖啡+奶油，1952年传入旧金山布埃纳维斯塔咖啡馆后风靡。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-irish-coffee-copy-6695cdbb430cd.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-irish-coffee-copy-6695cdbb430cd.webp', 93, 107, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":5.0},{"key":"BODY","label":"酒体","score":7.0},{"key":"REFRESHING","label":"清爽度","score":1.0}]', '["热饮", "咖啡鸡尾酒", "威士忌基底", "咖啡风味", "奶油感", "甜感明显", "餐后", "含咖啡因"]', '["餐后","冬季"]', '{"baseSpirit":"威士忌基底","cocktailType":"咖啡鸡尾酒","flavor":"咖啡风味、甜感明显","abv":"中度＞10%～20%","extra":["热咖啡","淡奶油"],"scene":["餐后","冬季"]}', '[{"nameZh":"爱尔兰威士忌","nameEn":"Irish Whiskey","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"热咖啡","nameEn":"Hot Coffee","amount":120,"unit":"ml","role":"热饮主体"},{"nameZh":"冷藏淡奶油","nameEn":"Fresh Cream (Chilled)","amount":50,"unit":"ml","role":"漂浮于表面"},{"nameZh":"砂糖","nameEn":"Sugar","amount":4,"unit":"g","role":"1 茶匙，搅拌溶解"}]', '["预热爱尔兰咖啡杯。","倒入热咖啡。","加入威士忌与砂糖，搅拌至溶解。","沿勺背缓缓倒入冷藏淡奶油，使其浮于表面。"]', '["Irish Coffee", "爱尔兰咖啡鸡尾酒", "热爱尔兰咖啡"]', 'A', '2026-08-04', 1, '{"id": "cocktail-irish-coffee", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "爱尔兰咖啡", "nameEn": "Irish Coffee", "intro": "以爱尔兰威士忌、热咖啡与砂糖调制，覆以打发奶油的热饮鸡尾酒，兼具咖啡香、威士忌酒感与奶油顺滑。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-irish-coffee-copy-6695cdbb430cd.webp", "tags": ["热饮", "咖啡鸡尾酒", "威士忌基底", "咖啡风味", "奶油感", "甜感明显", "餐后", "含咖啡因"], "scene": ["餐后", "冬季"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡风味、甜感明显", "abv": "中度＞10%～20%", "extra": ["热咖啡", "淡奶油"], "scene": ["餐后", "冬季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-black-russian', 'cocktail', 'COCKTAIL', '黑俄罗斯', 'Black Russian', 'heieluosi', 'hels', '伏特加与咖啡利口酒在冰上直调的经典鸡尾酒，口感甜润并带咖啡与焦糖风味，酒体中等偏烈，几乎无酸感。', 'V6 采用 IBA 官方配比：伏特加 50 ml 与咖啡利口酒 20 ml 于加冰古典杯中直调；相较白俄罗斯不含奶油，更纯粹地呈现咖啡利口酒的甜香与酒精感。 背景：1949年布鲁塞尔大都会酒店调酒师古斯塔夫·托普斯（Gustave Tops）为美国驻卢森堡大使创制，伏特加+咖啡利口酒。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-black-russian-6695cda4183dc.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-black-russian-6695cda4183dc.webp', 91, 114, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":2.0},{"key":"ALCOHOL","label":"酒精感","score":7.0},{"key":"BODY","label":"酒体","score":4.0},{"key":"REFRESHING","label":"清爽度","score":2.0}]', '["咖啡风味","伏特加基底","甜感","直调","餐后","经典"]', '["经典", "餐后"]', '{"baseSpirit":"伏特加基底","cocktailType":"咖啡鸡尾酒","flavor":"咖啡、焦糖","abv":"高度＞30%","extra":"无明显非酒精成分","scene":["经典","餐后"]}', '[{"nameZh":"伏特加","nameEn":"Vodka","amount":50,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"咖啡利口酒","nameEn":"Coffee Liqueur","amount":20,"unit":"ml","role":"咖啡甜香"},{"nameZh":"冰块","nameEn":"Ice cubes","amount":60,"unit":"g","role":"直调用"}]', '["古典杯加满冰块。","倒入伏特加。","倒入咖啡利口酒。","轻轻搅拌混合。"]', '["黑色俄罗斯", "Black Russian Cocktail"]', 'A', '2026-08-04', 1, '{"id": "cocktail-black-russian", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑俄罗斯", "nameEn": "Black Russian", "intro": "伏特加与咖啡利口酒在冰上直调的经典鸡尾酒，口感甜润并带咖啡与焦糖风味，酒体中等偏烈，几乎无酸感。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-black-russian-6695cda4183dc.webp", "tags": ["咖啡风味", "伏特加基底", "甜感", "直调", "餐后", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "咖啡鸡尾酒", "flavor": "咖啡、焦糖", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mint-julep', 'cocktail', 'COCKTAIL', '薄荷茱莉普', 'Mint Julep', 'bohezhulipu', 'bhzlp', '以波本威士忌、新鲜薄荷与糖浆加碎冰调制的经典长饮，薄荷清凉衬托波本的焦糖与橡木香，冰爽饱满，是美国南部的代表鸡尾酒。', 'IBA 官方配比为波本威士忌 60 ml、薄荷叶 4 支、糖粉 1 茶匙与水 2 茶匙，捣压薄荷后加满碎冰，搅拌至杯壁结霜，以薄荷枝装饰。本款是朱利普家族的标准波本版本。 背景：19世纪美国南部传统饮品，杰里·托马斯著作已收录，波本+薄荷+糖+碎冰，肯塔基德比赛马会的官方饮品。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mint-julep-6695cdc4aa398.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mint-julep-6695cdc4aa398.webp', 89, 128, '[{"key":"SWEETNESS","label":"甜度","score":6.0},{"key":"SOURNESS","label":"酸度","score":1.0},{"key":"BITTERNESS","label":"苦度","score":1.0},{"key":"ALCOHOL","label":"酒精感","score":7.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":6.0}]', '["古典家族","波本基底","薄荷","捣压","碎冰","经典"]', '["经典","夏季"]', '{"baseSpirit":"波本基底","cocktailType":"古典家族","flavor":"薄荷、草本","abv":"较高＞20%～30%","extra":"无明显非酒精成分","scene":["经典","夏季"]}', '[{"nameZh":"波本威士忌","nameEn":"Bourbon Whiskey","amount":60,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"新鲜薄荷","nameEn":"Fresh Mint sprigs","amount":4,"unit":"piece","role":"捣压释放香气"},{"nameZh":"糖粉","nameEn":"Powdered Sugar","amount":4,"unit":"g","role":"1 茶匙"},{"nameZh":"过滤水","nameEn":"Water","amount":10,"unit":"ml","role":"2 茶匙，助溶糖粉"},{"nameZh":"碎冰","nameEn":"Cracked ice","amount":200,"unit":"ml","role":"加满杯"},{"nameZh":"薄荷枝","nameEn":"Mint sprig","amount":1,"unit":"piece","role":"装饰用"}]', '["朱利普杯中放入薄荷叶、糖粉与水。","轻压薄荷叶释放香气。","加满碎冰，倒入波本威士忌。","搅拌至杯壁结霜。","以薄荷枝装饰，配吸管饮用。"]', '["Mint Julep", "肯塔基朱利普", "薄荷冰酒"]', 'A', '2026-08-04', 1, '{"id": "cocktail-mint-julep", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "薄荷茱莉普", "nameEn": "Mint Julep", "intro": "以波本威士忌、新鲜薄荷与糖浆加碎冰调制的经典长饮，薄荷清凉衬托波本的焦糖与橡木香，冰爽饱满，是美国南部的代表鸡尾酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-mint-julep-6695cdc4aa398.webp", "tags": ["古典家族", "波本基底", "薄荷", "捣压", "碎冰", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 89, "attributes": {"baseSpirit": "波本基底", "cocktailType": "古典家族", "flavor": "薄荷、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jungle-bird-classic', 'cocktail', 'COCKTAIL', '丛林鸟', 'Jungle Bird', 'conglinniao', 'cln', '以黑朗姆、菠萝汁、青柠汁与金巴利调制的提基鸡尾酒，热带果甜与草药苦味交织，是朗姆与金巴利的经典碰撞。', '配方遵循 IBA 官方配比：黑朗姆 45 ml、金巴利 22.5 ml、菠萝汁 45 ml、青柠汁 15 ml 与德梅拉拉糖浆 15 ml，摇和滤入加冰老式杯，以菠萝角装饰。苦甜平衡，ABV 为编辑估算值。 背景：1978年吉隆坡希尔顿酒店艾维阿里酒吧调酒师杰弗里·翁（Jeffrey Ong）创制，黑朗姆+金巴利+菠萝汁+青柠，1980年代传入欧美。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-jungle-bird-6695d3ab45a87.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-jungle-bird-6695d3ab45a87.webp', 93, 179, '[{"key":"SWEETNESS","label":"甜度","score":5.0},{"key":"SOURNESS","label":"酸度","score":4.0},{"key":"BITTERNESS","label":"苦度","score":6.0},{"key":"ALCOHOL","label":"酒精感","score":6.0},{"key":"BODY","label":"酒体","score":5.0},{"key":"REFRESHING","label":"清爽度","score":5.0}]', '["提基","朗姆基底","苦甜","菠萝","摇和","经典"]', '["经典","热带"]', '{"baseSpirit":"朗姆基底","cocktailType":"提基","flavor":"苦感主导、菠萝","abv":"中度＞10%～20%","extra":["新鲜菠萝汁","新鲜青柠汁"],"scene":["经典","热带"]}', '[{"nameZh":"黑朗姆酒","nameEn":"Blackstrap Rum","amount":45,"unit":"ml","role":"IBA 官方配比"},{"nameZh":"金巴利","nameEn":"Campari","amount":22.5,"unit":"ml","role":"草药苦味"},{"nameZh":"新鲜菠萝汁","nameEn":"Pineapple Juice","amount":45,"unit":"ml","role":"热带果甜"},{"nameZh":"新鲜青柠汁","nameEn":"Freshly Squeezed Lime Juice","amount":15,"unit":"ml","role":"酸度平衡"},{"nameZh":"德梅拉拉糖浆","nameEn":"Demerara Sugar Syrup","amount":15,"unit":"ml","role":"焦糖甜香"},{"nameZh":"菠萝角","nameEn":"Pineapple wedge","amount":1,"unit":"piece","role":"装饰用"}]', '["摇酒壶加冰，倒入黑朗姆、金巴利、菠萝汁、青柠汁与德梅拉拉糖浆。","摇和约 12 秒至充分降温。","滤入装满冰块的老式杯。","以菠萝角装饰。"]', '["Jungle Bird", "经典丛林鸟"]', 'A', '2026-08-04', 1, '{"id": "cocktail-jungle-bird-classic", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "丛林鸟", "nameEn": "Jungle Bird", "intro": "以黑朗姆、菠萝汁、青柠汁与金巴利调制的提基鸡尾酒，热带果甜与草药苦味交织，是朗姆与金巴利的经典碰撞。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-jungle-bird-6695d3ab45a87.webp", "tags": ["提基", "朗姆基底", "苦甜", "菠萝", "摇和", "经典"], "scene": ["经典", "热带"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "苦感主导、菠萝", "abv": "中度＞10%～20%", "extra": ["新鲜菠萝汁", "新鲜青柠汁"], "scene": ["经典", "热带"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-alexander', 'cocktail', 'COCKTAIL', '白兰地亚历山大', 'Alexander', 'bailandiyalishanda', 'bldylsd', '以干邑白兰地、褐色可可利口酒与鲜奶油摇和而成的餐后甜饮，可可与奶香交融，杯面撒新鲜肉豆蔻粉。', '按 IBA 官方配比：干邑白兰地、褐色可可利口酒与鲜奶油各 30 毫升摇和，滤入冰镇鸡尾酒杯后撒新鲜研磨肉豆蔻粉。可可利口酒与鲜奶油赋予其标志性的奶香。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-alexander-669491364f7f2.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-alexander-669491364f7f2.webp', 92, 180, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["白兰地基底", "餐后甜饮", "摇和", "奶香", "可可", "餐后", "节日"]', '["餐后", "节日"]', '{"baseSpirit": "白兰地基底", "cocktailType": "餐后甜饮", "flavor": "奶香、可可", "abv": "较高＞20%～30%", "extra": ["鲜奶油"], "scene": ["餐后", "节日"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 30, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "褐色可可利口酒", "nameEn": "Crème de Cacao (Brown)", "amount": 30, "unit": "ml", "role": "褐色可可利口酒"}, {"nameZh": "鲜奶油", "nameEn": "Fresh cream", "amount": 30, "unit": "ml", "role": "鲜奶油"}, {"nameZh": "肉豆蔻粉", "nameEn": "Ground nutmeg", "amount": 1, "unit": "dash", "role": "装饰用"}]', '["摇酒壶加冰。", "倒入干邑白兰地、可可利口酒与鲜奶油。", "摇和约 10 秒至充分冷却。", "滤入冰镇鸡尾酒杯。", "撒上新鲜研磨的肉豆蔻粉。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-alexander", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白兰地亚历山大", "nameEn": "Alexander", "intro": "以干邑白兰地、褐色可可利口酒与鲜奶油摇和而成的餐后甜饮，可可与奶香交融，杯面撒新鲜肉豆蔻粉。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-alexander-669491364f7f2.webp", "tags": ["白兰地基底", "餐后甜饮", "摇和", "奶香", "可可", "餐后", "节日"], "scene": ["餐后", "节日"], "recommendationScore": 92, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "餐后甜饮", "flavor": "奶香、可可", "abv": "较高＞20%～30%", "extra": ["鲜奶油"], "scene": ["餐后", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-angel-face', 'cocktail', 'COCKTAIL', '天使之颜', 'Angel Face', 'tianshizhiyan', 'tszy', '金酒、杏子白兰地与卡尔瓦多斯三款烈酒组成的极简鸡尾酒，杏果香与苹果白兰地气息交织，酒体强劲。', '1930 年收录于伦敦萨伏依酒店的《萨伏依鸡尾酒手册》。IBA 配比：金酒、杏子白兰地、卡尔瓦多斯各 30 毫升摇和，滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-angel-face-669490fe6df67.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-angel-face-669490fe6df67.webp', 90, 181, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["烈酒主导", "金酒基底", "摇和", "果香", "杏子", "经典", "日常"]', '["经典", "日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "果香、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "日常"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 30, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "杏子白兰地", "nameEn": "Apricot brandy", "amount": 30, "unit": "ml", "role": "杏子白兰地利口酒"}, {"nameZh": "卡尔瓦多斯", "nameEn": "Calvados", "amount": 30, "unit": "ml", "role": "40% ABV 苹果白兰地"}]', '["摇酒壶加冰。", "倒入金酒、杏子白兰地与卡尔瓦多斯。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-angel-face", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "天使之颜", "nameEn": "Angel Face", "intro": "金酒、杏子白兰地与卡尔瓦多斯三款烈酒组成的极简鸡尾酒，杏果香与苹果白兰地气息交织，酒体强劲。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-angel-face-669490fe6df67.webp", "tags": ["烈酒主导", "金酒基底", "摇和", "果香", "杏子", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 90, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "果香、草本", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-aviation', 'cocktail', 'COCKTAIL', '飞行', 'Aviation', 'feixing', 'fx', '金酒、马拉斯奇诺、柠檬汁与紫罗兰利口酒摇和而成的淡紫色鸡尾酒，紫罗兰花香与樱桃核香并存，是经典金酒酸酒。', '1916 年前后由纽约调酒师雨果·恩斯林创制，正值航空热潮而得名。IBA 配比：金酒 45 毫升、马拉斯奇诺 15 毫升、新鲜柠檬汁 15 毫升、紫罗兰利口酒 1 吧匙，摇和滤入冰镇鸡尾酒杯，可选樱桃装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-aviation-66949102296a4.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-aviation-66949102296a4.webp', 94, 182, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "花香", "柑橘", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "花香、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "紫罗兰利口酒"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 45, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 15, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "紫罗兰利口酒", "nameEn": "Crème de Violette", "amount": 5, "unit": "ml", "role": "1 吧匙紫罗兰利口酒"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰（可选）"}]', '["摇酒壶加冰。", "倒入金酒、马拉斯奇诺利口酒、柠檬汁与紫罗兰利口酒。", "摇和后滤入冰镇鸡尾酒杯。", "可选以马拉斯奇诺樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-aviation", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "飞行", "nameEn": "Aviation", "intro": "金酒、马拉斯奇诺、柠檬汁与紫罗兰利口酒摇和而成的淡紫色鸡尾酒，紫罗兰花香与樱桃核香并存，是经典金酒酸酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-aviation-66949102296a4.webp", "tags": ["酸型鸡尾酒", "金酒基底", "花香", "柑橘", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 94, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "花香、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "紫罗兰利口酒"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-between-the-sheets', 'cocktail', 'COCKTAIL', '床笫之间', 'Between the Sheets', 'chuangzizhijian', 'czzj', '白朗姆、干邑与橙味利口酒加柠檬汁摇和而成的边车变体，三种烈酒与柑橘酸爽达成平衡。', '1930 年代巴黎哈里酒吧的哈里·麦克埃尔霍恩在边车基础上加入朗姆酒改良而成。IBA 配比：白朗姆、干邑、橙味利口酒各 30 毫升，加新鲜柠檬汁 20 毫升摇和滤杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-between-the-sheets-669491023d7af.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-between-the-sheets-669491023d7af.webp', 91, 183, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "朗姆基底", "柑橘", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 30, "unit": "ml", "role": "40% ABV 白朗姆酒"}, {"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 30, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "橙味利口酒", "nameEn": "Triple sec", "amount": 30, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}]', '["摇酒壶加冰。", "倒入白朗姆、干邑、橙味利口酒与柠檬汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-between-the-sheets", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "床笫之间", "nameEn": "Between the Sheets", "intro": "白朗姆、干邑与橙味利口酒加柠檬汁摇和而成的边车变体，三种烈酒与柑橘酸爽达成平衡。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-between-the-sheets-669491023d7af.webp", "tags": ["酸型鸡尾酒", "朗姆基底", "柑橘", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-boulevardier', 'cocktail', 'COCKTAIL', '浪子', 'Boulevardier', 'langzi', 'lz', '波本或黑麦威士忌、金巴利与甜红味美思搅拌而成的威士忌版内格罗尼，苦甜交织、酒体饱满。', '1927 年由巴黎的美国侨民杂志人埃尔斯金·格温创制。IBA 配比：波本或黑麦威士忌 45 毫升、金巴利 30 毫升、甜红味美思 30 毫升，搅拌滤入冰镇鸡尾酒杯，以橙皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-boulevardier-6694910552acd.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-boulevardier-6694910552acd.webp', 93, 184, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "苦感主导", "搅拌", "草本", "经典", "开胃"]', '["经典", "开胃"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}', '[{"nameZh": "波本或黑麦威士忌", "nameEn": "Bourbon or rye whiskey", "amount": 45, "unit": "ml", "role": "40% ABV 威士忌"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 30, "unit": "ml", "role": "金巴利苦味利口酒"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "橙皮", "nameEn": "Orange zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["搅拌杯加冰。", "倒入波本或黑麦威士忌、金巴利与甜红味美思。", "搅拌至充分冷却。", "滤入冰镇鸡尾酒杯。", "以橙皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-boulevardier", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "浪子", "nameEn": "Boulevardier", "intro": "波本或黑麦威士忌、金巴利与甜红味美思搅拌而成的威士忌版内格罗尼，苦甜交织、酒体饱满。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-boulevardier-6694910552acd.webp", "tags": ["威士忌基底", "苦感主导", "搅拌", "草本", "经典", "开胃"], "scene": ["经典", "开胃"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "苦感主导、草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-brandy-crusta', 'cocktail', 'COCKTAIL', '白兰地科斯塔', 'Brandy Crusta', 'bailandikesita', 'bldkst', '白兰地、马拉斯奇诺与库拉索加柠檬汁摇和的新奥尔良古典，糖边杯口并旋入整条柠檬皮，是最早的糖边配方之一。', '1850 年代新奥尔良调酒师约瑟夫·桑蒂尼创制，1862 年收录于杰里·托马斯的《调酒师指南》。IBA 配比：白兰地 52.5 毫升、马拉斯奇诺 7.5 毫升、库拉索 1 吧匙、柠檬汁 15 毫升、单糖浆 1 吧匙、芳香苦精 2 滴。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-brandy-crusta-6694910571bcb.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-brandy-crusta-6694910571bcb.webp', 92, 185, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["白兰地基底", "酸型鸡尾酒", "柑橘", "糖边", "经典"]', '["经典"]', '{"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "细砂糖"], "scene": ["经典"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 52.5, "unit": "ml", "role": "40% ABV 白兰地"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 7.5, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "库拉索利口酒", "nameEn": "Curacao", "amount": 5, "unit": "ml", "role": "1 吧匙库拉索利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "单糖浆", "nameEn": "Simple syrup", "amount": 5, "unit": "ml", "role": "1 吧匙 1:1 单糖浆"}, {"nameZh": "芳香苦精", "nameEn": "Aromatic bitters", "amount": 2, "unit": "dash", "role": "芳香苦精"}, {"nameZh": "细砂糖", "nameEn": "Pulverized white sugar", "amount": 1, "unit": "dash", "role": "糖边用"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "螺旋状卷入杯内装饰"}]', '["以橙片润湿杯口并蘸细砂糖作糖边。", "将橙皮旋成螺旋状贴入杯内壁。", "搅拌杯加冰，倒入白兰地、马拉斯奇诺、库拉索、柠檬汁、糖浆与苦精。", "搅拌至充分冷却。", "滤入备好的酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-brandy-crusta", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白兰地科斯塔", "nameEn": "Brandy Crusta", "intro": "白兰地、马拉斯奇诺与库拉索加柠檬汁摇和的新奥尔良古典，糖边杯口并旋入整条柠檬皮，是最早的糖边配方之一。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-brandy-crusta-6694910571bcb.webp", "tags": ["白兰地基底", "酸型鸡尾酒", "柑橘", "糖边", "经典"], "scene": ["经典"], "recommendationScore": 92, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "细砂糖"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-casino', 'cocktail', 'COCKTAIL', '赌场', 'Casino', 'duchang', 'dc', '老汤姆金酒、马拉斯奇诺与柠檬汁加橙味苦精摇和的金酒酸酒，甜酸清爽，以柠檬皮与樱桃装饰。', '1916 年收录于雨果·恩斯林的《混合饮品配方》。IBA 配比：老汤姆金酒 40 毫升、马拉斯奇诺 10 毫升、新鲜柠檬汁 10 毫升、橙味苦精 2 滴，摇和滤入加冰古典杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-casino-6694910882cd6.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-casino-6694910882cd6.webp', 89, 186, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "柑橘", "摇和", "经典", "日常"]', '["经典", "日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典", "日常"]}', '[{"nameZh": "老汤姆金酒", "nameEn": "Old Tom gin", "amount": 40, "unit": "ml", "role": "老汤姆金酒"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 10, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 10, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰用"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["摇酒壶加冰。", "倒入老汤姆金酒、马拉斯奇诺利口酒、柠檬汁与橙味苦精。", "摇和充分。", "滤入加冰的古典杯。", "以柠檬皮与马拉斯奇诺樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-casino", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "赌场", "nameEn": "Casino", "intro": "老汤姆金酒、马拉斯奇诺与柠檬汁加橙味苦精摇和的金酒酸酒，甜酸清爽，以柠檬皮与樱桃装饰。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-casino-6694910882cd6.webp", "tags": ["酸型鸡尾酒", "金酒基底", "柑橘", "摇和", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 89, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-clover-club', 'cocktail', 'COCKTAIL', '三叶草俱乐部', 'Clover Club', 'sanyecaojulebu', 'sycjlb', '金酒、覆盆子糖浆、柠檬汁与蛋清摇和出绵密泡沫的粉色调经典鸡尾酒，果香酸甜、口感顺滑。', '20 世纪初诞生于费城贝尔维尤-斯特拉特福德酒店，为当地文人聚会调制。IBA 配比：金酒 45 毫升、覆盆子糖浆 15 毫升、新鲜柠檬汁 15 毫升、蛋清数滴，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-clover-club-66949108a3e54.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-clover-club-66949108a3e54.webp', 91, 187, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "果香", "蛋清泡沫", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 45, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "覆盆子糖浆", "nameEn": "Raspberry syrup", "amount": 15, "unit": "ml", "role": "覆盆子糖浆"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 5, "unit": "ml", "role": "数滴蛋清"}, {"nameZh": "新鲜覆盆子", "nameEn": "Fresh raspberries", "amount": 3, "unit": "piece", "role": "装饰用"}]', '["摇酒壶加冰。", "倒入金酒、覆盆子糖浆、柠檬汁与蛋清。", "用力摇和约 12 秒至起绵密泡沫。", "滤入冰镇鸡尾酒杯。", "以新鲜覆盆子装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-clover-club", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "三叶草俱乐部", "nameEn": "Clover Club", "intro": "金酒、覆盆子糖浆、柠檬汁与蛋清摇和出绵密泡沫的粉色调经典鸡尾酒，果香酸甜、口感顺滑。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-clover-club-66949108a3e54.webp", "tags": ["酸型鸡尾酒", "金酒基底", "果香", "蛋清泡沫", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、酸甜", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "蛋清"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gin-fizz', 'cocktail', 'COCKTAIL', '金菲兹', 'Gin Fizz', 'jinfeizi', 'jfz', '金酒、柠檬汁与糖浆摇和后以苏打水补足的金酒气泡长饮，酸爽轻盈，是菲兹家族的鼻祖。', '1888 年前后新奥尔良已有记载。IBA 配比：金酒 45 毫升、新鲜柠檬汁 30 毫升、单糖浆 10 毫升摇和，滤入细长杯后补入苏打水，不加冰饮用。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-gin-fizz-6694910fc2eab.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-gin-fizz-6694910fc2eab.webp', 93, 188, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["菲兹", "金酒基底", "柑橘", "气泡", "清爽", "夏季", "新手友好"]', '["夏季", "新手友好"]', '{"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、气泡", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季", "新手友好"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 45, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "单糖浆", "nameEn": "Simple syrup", "amount": 10, "unit": "ml", "role": "单糖浆"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "最后补足气泡"}, {"nameZh": "柠檬片", "nameEn": "Lemon slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["摇酒壶加冰。", "倒入金酒、柠檬汁与单糖浆。", "充分摇和。", "滤入细高杯。", "补入苏打水至杯口，以柠檬片装饰，不加冰饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-gin-fizz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金菲兹", "nameEn": "Gin Fizz", "intro": "金酒、柠檬汁与糖浆摇和后以苏打水补足的金酒气泡长饮，酸爽轻盈，是菲兹家族的鼻祖。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-gin-fizz-6694910fc2eab.webp", "tags": ["菲兹", "金酒基底", "柑橘", "气泡", "清爽", "夏季", "新手友好"], "scene": ["夏季", "新手友好"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、气泡", "abv": "中度＞10%～20%", "extra": ["新鲜柠檬汁", "苏打水"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-hanky-panky', 'cocktail', 'COCKTAIL', '汉基帕基', 'Hanky Panky', 'hanjipaji', 'hjpj', '伦敦干金酒、甜红味美思与少量菲奈特苦酒搅拌而成的草本苦甜鸡尾酒，1920 年代伦敦萨伏依酒店创制。', '由女调酒师艾达·科尔曼为演员查尔斯·霍特里调制，霍特里赞其“货真价实的把戏”（hanky-panky）而得名。IBA 配比：伦敦干金酒 45 毫升、甜红味美思 45 毫升、菲奈特 7.5 毫升，搅拌滤杯，橙皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-hanky-panky-66949112edbf5.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-hanky-panky-66949112edbf5.webp', 91, 189, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "金酒基底", "草本", "苦感主导", "搅拌", "经典", "开胃"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "草本、苦感主导", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 45, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "菲奈特苦酒", "nameEn": "Fernet-Branca", "amount": 7.5, "unit": "ml", "role": "菲奈特苦酒"}, {"nameZh": "橙皮", "nameEn": "Orange zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["搅拌杯加冰。", "倒入伦敦干金酒、甜红味美思与菲奈特。", "搅拌至充分冷却。", "滤入冰镇鸡尾酒杯。", "以橙皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-hanky-panky", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "汉基帕基", "nameEn": "Hanky Panky", "intro": "伦敦干金酒、甜红味美思与少量菲奈特苦酒搅拌而成的草本苦甜鸡尾酒，1920 年代伦敦萨伏依酒店创制。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-hanky-panky-66949112edbf5.webp", "tags": ["烈酒主导", "金酒基底", "草本", "苦感主导", "搅拌", "经典", "开胃"], "scene": ["经典", "开胃"], "recommendationScore": 91, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "草本、苦感主导", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-last-word', 'cocktail', 'COCKTAIL', '最后一语', 'Last Word', 'zuihouyiyu', 'zhyy', '金酒、绿查特、马拉斯奇诺与青柠汁等量摇和的四件套经典，草本与樱桃核香、酸度均衡。', '1916 年前后诞生于底特律运动俱乐部酒吧，禁酒令后一度失传，2004 年被西雅图调酒师默里·斯滕森复兴。IBA 配比：金酒、绿查特利口酒、马拉斯奇诺、新鲜青柠汁各 22.5 毫升摇和滤杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-last-word-6694911607ddf.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-last-word-6694911607ddf.webp', 95, 190, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "草本", "等量配比", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本、柑橘", "abv": "高度＞30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 22.5, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "绿查特利口酒", "nameEn": "Green Chartreuse", "amount": 22.5, "unit": "ml", "role": "绿查特利口酒"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 22.5, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 22.5, "unit": "ml", "role": "新鲜青柠汁"}]', '["摇酒壶加冰。", "倒入金酒、绿查特利口酒、马拉斯奇诺与青柠汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-last-word", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "最后一语", "nameEn": "Last Word", "intro": "金酒、绿查特、马拉斯奇诺与青柠汁等量摇和的四件套经典，草本与樱桃核香、酸度均衡。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-last-word-6694911607ddf.webp", "tags": ["酸型鸡尾酒", "金酒基底", "草本", "等量配比", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 95, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本、柑橘", "abv": "高度＞30%", "extra": ["新鲜青柠汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-martinez', 'cocktail', 'COCKTAIL', '马丁内斯', 'Martinez', 'madingneisi', 'mdns', '伦敦干金酒、甜红味美思与马拉斯奇诺、橙味苦精搅拌而成的经典鸡尾酒，被视为马天尼的前身。', '据传起源可追溯至 19 世纪加州马丁内斯镇。IBA 配比：伦敦干金酒 45 毫升、甜红味美思 45 毫升、马拉斯奇诺 1 吧匙、橙味苦精 2 滴，搅拌滤入冰镇鸡尾酒杯，柠檬皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-martinez-6694911927849.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-martinez-6694911927849.webp', 92, 191, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["烈酒主导", "金酒基底", "草本", "搅拌", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本、甜苦平衡", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London dry gin", "amount": 45, "unit": "ml", "role": "伦敦干金酒"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 45, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 5, "unit": "ml", "role": "1 吧匙马拉斯奇诺利口酒"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["搅拌杯加冰。", "倒入伦敦干金酒、甜红味美思、马拉斯奇诺与橙味苦精。", "搅拌至充分冷却。", "滤入冰镇鸡尾酒杯。", "以柠檬皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-martinez", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "马丁内斯", "nameEn": "Martinez", "intro": "伦敦干金酒、甜红味美思与马拉斯奇诺、橙味苦精搅拌而成的经典鸡尾酒，被视为马天尼的前身。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-martinez-6694911927849.webp", "tags": ["烈酒主导", "金酒基底", "草本", "搅拌", "经典"], "scene": ["经典"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本、甜苦平衡", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mary-pickford', 'cocktail', 'COCKTAIL', '玛丽·匹克福德', 'Mary Pickford', 'mali·pikefude', 'ml·pkfd', '白朗姆、新鲜菠萝汁与马拉斯奇诺、石榴糖浆摇和的果香鸡尾酒，以好莱坞默片时代女星玛丽·匹克福德命名。', '1920 年代哈瓦那创制。IBA 配比：白朗姆 45 毫升、新鲜菠萝汁 45 毫升、马拉斯奇诺 7.5 毫升、石榴糖浆 5 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-mary-pickford-6694911933ea7.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-mary-pickford-6694911933ea7.webp', 90, 192, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "果香", "菠萝", "摇和", "经典", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、菠萝", "abv": "中度＞10%～20%", "extra": ["新鲜菠萝汁", "石榴糖浆"], "scene": ["经典", "夏季"]}', '[{"nameZh": "白朗姆酒", "nameEn": "White rum", "amount": 45, "unit": "ml", "role": "40% ABV 白朗姆酒"}, {"nameZh": "新鲜菠萝汁", "nameEn": "Fresh pineapple juice", "amount": 45, "unit": "ml", "role": "新鲜菠萝汁"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 7.5, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine syrup", "amount": 5, "unit": "ml", "role": "石榴糖浆"}]', '["摇酒壶加冰。", "倒入白朗姆、菠萝汁、马拉斯奇诺与石榴糖浆。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-mary-pickford", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "玛丽·匹克福德", "nameEn": "Mary Pickford", "intro": "白朗姆、新鲜菠萝汁与马拉斯奇诺、石榴糖浆摇和的果香鸡尾酒，以好莱坞默片时代女星玛丽·匹克福德命名。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-mary-pickford-6694911933ea7.webp", "tags": ["朗姆基底", "果香", "菠萝", "摇和", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、菠萝", "abv": "中度＞10%～20%", "extra": ["新鲜菠萝汁", "石榴糖浆"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-monkey-gland', 'cocktail', 'COCKTAIL', '猴腺', 'Monkey Gland', 'houxian', 'hx', '干金酒与新鲜橙汁摇和，加入少量苦艾酒与石榴糖浆的果香鸡尾酒，橙香清甜中带一丝茴香气息。', '1920 年代巴黎哈里酒吧创制，以宣扬“猴腺移植返老还童术”的塞尔日·沃罗诺夫命名。IBA 配比：干金酒 45 毫升、新鲜橙汁 45 毫升、苦艾酒 1 汤匙、石榴糖浆 1 汤匙，摇和滤杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-monkey-gland-6694911cbf5a2.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-monkey-gland-6694911cbf5a2.webp', 89, 193, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["金酒基底", "果香", "柑橘", "摇和", "经典", "日常"]', '["经典", "日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁", "石榴糖浆"], "scene": ["经典", "日常"]}', '[{"nameZh": "干金酒", "nameEn": "Dry gin", "amount": 45, "unit": "ml", "role": "干金酒"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 45, "unit": "ml", "role": "新鲜橙汁"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 15, "unit": "ml", "role": "1 汤匙苦艾酒"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine syrup", "amount": 15, "unit": "ml", "role": "1 汤匙石榴糖浆"}]', '["摇酒壶加冰。", "倒入干金酒、橙汁、苦艾酒与石榴糖浆。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-monkey-gland", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "猴腺", "nameEn": "Monkey Gland", "intro": "干金酒与新鲜橙汁摇和，加入少量苦艾酒与石榴糖浆的果香鸡尾酒，橙香清甜中带一丝茴香气息。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-monkey-gland-6694911cbf5a2.webp", "tags": ["金酒基底", "果香", "柑橘", "摇和", "经典", "日常"], "scene": ["经典", "日常"], "recommendationScore": 89, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁", "石榴糖浆"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-paradise', 'cocktail', 'COCKTAIL', '天堂', 'Paradise', 'tiantang', 'tt', '金酒、杏子白兰地与新鲜橙汁摇和的三料鸡尾酒，杏香与橙香柔和，被视为天使之颜的姊妹款。', '1930 年收录于《萨伏依鸡尾酒手册》。IBA 配比：金酒 30 毫升、杏子白兰地 20 毫升、新鲜橙汁 15 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-paradise-6694911fdbd4b.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-paradise-6694911fdbd4b.webp', 90, 194, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "果香", "杏子", "摇和", "经典", "下午茶"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "果香、杏子", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 30, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "杏子白兰地", "nameEn": "Apricot brandy", "amount": 20, "unit": "ml", "role": "杏子白兰地利口酒"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh orange juice", "amount": 15, "unit": "ml", "role": "新鲜橙汁"}]', '["摇酒壶加冰。", "倒入金酒、杏子白兰地与橙汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-paradise", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "天堂", "nameEn": "Paradise", "intro": "金酒、杏子白兰地与新鲜橙汁摇和的三料鸡尾酒，杏香与橙香柔和，被视为天使之颜的姊妹款。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-paradise-6694911fdbd4b.webp", "tags": ["金酒基底", "果香", "杏子", "摇和", "经典", "下午茶"], "scene": ["经典", "下午茶"], "recommendationScore": 90, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "果香、杏子", "abv": "较高＞20%～30%", "extra": ["新鲜橙汁"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-planters-punch', 'cocktail', 'COCKTAIL', '种植者潘趣', 'Planter\'s Punch', 'zhongzhizhepanqu', 'zzzpq', '牙买加朗姆、青柠汁与甘蔗汁直调的加勒比潘趣，甘蔗清甜与朗姆的强劲酒体并存。', '源自 17 世纪加勒比种植园潘趣传统，流传着“一酸二甜三强四弱”的调配口诀。IBA 配比：牙买加朗姆 45 毫升、青柠汁 15 毫升、甘蔗汁 30 毫升，直调于小杯，可按口味以水、冰或果汁稀释。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-planters-punch-66949122d41fb.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-planters-punch-66949122d41fb.webp', 91, 195, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "果香", "柑橘", "直调", "经典", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "潘趣", "flavor": "果香、甘蔗", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "甘蔗汁"], "scene": ["经典", "夏季"]}', '[{"nameZh": "牙买加朗姆酒", "nameEn": "Jamaican rum", "amount": 45, "unit": "ml", "role": "牙买加朗姆酒"}, {"nameZh": "青柠汁", "nameEn": "Lime juice", "amount": 15, "unit": "ml", "role": "青柠汁"}, {"nameZh": "甘蔗汁", "nameEn": "Sugar cane juice", "amount": 30, "unit": "ml", "role": "甘蔗汁"}, {"nameZh": "橙皮", "nameEn": "Orange zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["小古典杯或陶土杯加冰。", "倒入牙买加朗姆、青柠汁与甘蔗汁。", "轻搅拌至混合。", "以橙皮装饰，可按口味加水或冰稀释。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-planters-punch", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "种植者潘趣", "nameEn": "Planter\'s Punch", "intro": "牙买加朗姆、青柠汁与甘蔗汁直调的加勒比潘趣，甘蔗清甜与朗姆的强劲酒体并存。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-planters-punch-66949122d41fb.webp", "tags": ["朗姆基底", "果香", "柑橘", "直调", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "潘趣", "flavor": "果香、甘蔗", "abv": "中度＞10%～20%", "extra": ["新鲜青柠汁", "甘蔗汁"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-porto-flip', 'cocktail', 'COCKTAIL', '波特酒弗利普', 'Porto Flip', 'botejiufulipu', 'btjflp', '茶色波特酒与少量白兰地加蛋黄摇和的暖色餐后蛋诺类鸡尾酒，酒体绵密，以肉豆蔻粉装饰。', '19 世纪流行的“翻转”（flip，酒+蛋+糖）家族成员，1862 年杰里·托马斯著作已有记载。IBA 配比：白兰地 15 毫升、茶色波特酒 45 毫升、蛋黄 10 毫升，摇和滤入冰镇鸡尾酒杯后撒肉豆蔻粉。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-porto-flip-669491230cea4.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-porto-flip-669491230cea4.webp', 89, 196, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["白兰地基底", "餐后甜饮", "摇和", "蛋香", "餐后", "节日"]', '["餐后", "节日"]', '{"baseSpirit": "白兰地基底", "cocktailType": "餐后甜饮", "flavor": "果香、蛋香", "abv": "较高＞20%～30%", "extra": ["蛋黄"], "scene": ["餐后", "节日"]}', '[{"nameZh": "白兰地", "nameEn": "Brandy", "amount": 15, "unit": "ml", "role": "40% ABV 白兰地"}, {"nameZh": "茶色波特酒", "nameEn": "Red tawny port wine", "amount": 45, "unit": "ml", "role": "茶色波特酒"}, {"nameZh": "蛋黄", "nameEn": "Egg yolk", "amount": 10, "unit": "ml", "role": "蛋黄"}, {"nameZh": "肉豆蔻粉", "nameEn": "Ground nutmeg", "amount": 1, "unit": "dash", "role": "装饰用"}]', '["摇酒壶加冰。", "倒入白兰地、波特酒与蛋黄。", "充分摇和至绵密。", "滤入冰镇鸡尾酒杯。", "撒上肉豆蔻粉。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-porto-flip", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波特酒弗利普", "nameEn": "Porto Flip", "intro": "茶色波特酒与少量白兰地加蛋黄摇和的暖色餐后蛋诺类鸡尾酒，酒体绵密，以肉豆蔻粉装饰。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-porto-flip-669491230cea4.webp", "tags": ["白兰地基底", "餐后甜饮", "摇和", "蛋香", "餐后", "节日"], "scene": ["餐后", "节日"], "recommendationScore": 89, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "餐后甜饮", "flavor": "果香、蛋香", "abv": "较高＞20%～30%", "extra": ["蛋黄"], "scene": ["餐后", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-ramos-fizz', 'cocktail', 'COCKTAIL', '拉莫斯金菲兹', 'Ramos Fizz', 'lamosijinfeizi', 'lmsjfz', '金酒、青柠汁、柠檬汁与糖浆、奶油、蛋清长时间摇和出绵密泡沫，再以苏打水补足的新奥尔良经典菲兹。', '1888 年亨利·拉莫斯创制，原版需 30 名摇酒师轮班长摇约 12 分钟。IBA 配比：金酒 45 毫升、青柠汁 15 毫升、柠檬汁 15 毫升、糖浆 30 毫升、奶油 60 毫升、蛋清 30 毫升、橙花水 3 滴、香草精 2 滴，双重滤杯后补苏打水。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-ramos-fizz-669491260ca6c.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-ramos-fizz-669491260ca6c.webp', 92, 197, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["菲兹", "金酒基底", "蛋清泡沫", "奶香", "气泡", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、奶香、花香", "abv": "低度≤10%", "extra": ["新鲜青柠汁", "鲜奶油", "蛋清", "苏打水"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 45, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh lime juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "单糖浆", "nameEn": "Sugar syrup", "amount": 30, "unit": "ml", "role": "单糖浆"}, {"nameZh": "鲜奶油", "nameEn": "Cream", "amount": 60, "unit": "ml", "role": "鲜奶油"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 30, "unit": "ml", "role": "蛋清"}, {"nameZh": "橙花水", "nameEn": "Orange flower water", "amount": 3, "unit": "dash", "role": "橙花水"}, {"nameZh": "香草精", "nameEn": "Vanilla extract", "amount": 2, "unit": "dash", "role": "香草精"}, {"nameZh": "苏打水", "nameEn": "Soda water", "amount": 60, "unit": "ml", "role": "最后补足气泡"}]', '["摇酒壶加冰，倒入除苏打水外的全部原料。", "用力摇和约两分钟。", "双重滤入高球杯。", "将酒液倒回摇酒壶，不加冰再大力摇约一分钟。", "滤回杯中，补入苏打水至杯口。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-ramos-fizz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "拉莫斯金菲兹", "nameEn": "Ramos Fizz", "intro": "金酒、青柠汁、柠檬汁与糖浆、奶油、蛋清长时间摇和出绵密泡沫，再以苏打水补足的新奥尔良经典菲兹。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-ramos-fizz-669491260ca6c.webp", "tags": ["菲兹", "金酒基底", "蛋清泡沫", "奶香", "气泡", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "菲兹", "flavor": "柑橘、奶香、花香", "abv": "低度≤10%", "extra": ["新鲜青柠汁", "鲜奶油", "蛋清", "苏打水"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-remember-the-maine', 'cocktail', 'COCKTAIL', '记住缅因号', 'Remember the Maine', 'jizhumianyinhao', 'jzmyh', '黑麦威士忌、甜味美思与樱桃利口酒搅拌、杯壁以苦艾酒冲洗的曼哈顿变体，甜苦平衡、层次分明。', '以 1898 年美西战争导火索“缅因号战舰爆炸”事件命名。IBA 配比：黑麦威士忌 60 毫升、甜味美思 22.5 毫升、樱桃利口酒 15 毫升，搅拌滤入以苦艾酒冲洗过的杯内，柠檬皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-remember-the-main-6694912622959.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-remember-the-main-6694912622959.webp', 91, 198, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "搅拌", "甜苦平衡", "樱桃", "经典", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "甜苦平衡、樱桃", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 60, "unit": "ml", "role": "40% ABV 黑麦威士忌"}, {"nameZh": "甜味美思", "nameEn": "Sweet vermouth", "amount": 22.5, "unit": "ml", "role": "甜味美思"}, {"nameZh": "樱桃利口酒", "nameEn": "Cherry brandy", "amount": 15, "unit": "ml", "role": "樱桃利口酒"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 7.5, "unit": "ml", "role": "冲洗杯壁用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将苦艾酒倒入杯沿杯并旋转挂壁，倒掉余液。", "搅拌杯加冰，倒入黑麦威士忌、甜味美思与樱桃利口酒。", "搅拌至冷却。", "滤入以苦艾酒冲洗过的杯内。", "以柠檬皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-remember-the-maine", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "记住缅因号", "nameEn": "Remember the Maine", "intro": "黑麦威士忌、甜味美思与樱桃利口酒搅拌、杯壁以苦艾酒冲洗的曼哈顿变体，甜苦平衡、层次分明。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-remember-the-main-6694912622959.webp", "tags": ["威士忌基底", "搅拌", "甜苦平衡", "樱桃", "经典", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "甜苦平衡、樱桃", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rusty-nail', 'cocktail', 'COCKTAIL', '锈钉', 'Rusty Nail', 'xiuding', 'xd', '苏格兰威士忌与杜林标蜂蜜利口酒直调的琥珀色经典，蜜香与烟熏气息融合，酒体饱满。', '1960 年代在纽约 21 俱乐部等场所流行，琥珀色如生锈钉子而得名。IBA 配比：苏格兰威士忌 45 毫升、杜林标 25 毫升，古典杯加冰直调并轻搅拌，柠檬皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-rusty-nail-66949129acfd1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-rusty-nail-66949129acfd1.webp', 92, 199, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 6.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "烈酒主导", "直调", "蜂蜜", "经典", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "烈酒主导", "flavor": "蜂蜜、烟熏", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "苏格兰威士忌", "nameEn": "Scotch whisky", "amount": 45, "unit": "ml", "role": "40% ABV 苏格兰威士忌"}, {"nameZh": "杜林标利口酒", "nameEn": "Drambuie", "amount": 25, "unit": "ml", "role": "杜林标蜂蜜利口酒"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["古典杯加满冰。", "倒入苏格兰威士忌与杜林标。", "轻搅拌使其混合。", "以柠檬皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-rusty-nail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "锈钉", "nameEn": "Rusty Nail", "intro": "苏格兰威士忌与杜林标蜂蜜利口酒直调的琥珀色经典，蜜香与烟熏气息融合，酒体饱满。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-rusty-nail-66949129acfd1.webp", "tags": ["威士忌基底", "烈酒主导", "直调", "蜂蜜", "经典", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 92, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "烈酒主导", "flavor": "蜂蜜、烟熏", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sidecar', 'cocktail', 'COCKTAIL', '边车', 'Sidecar', 'bianche', 'bc', '干邑、橙味利口酒与柠檬汁摇和而成的经典酸型鸡尾酒，柑橘酸爽与干邑果香平衡。', '一战后在巴黎流行，最著名的说法是丽兹酒店为一位常骑挎斗摩托车（sidecar）的美国军官调制。IBA 配比：干邑 50 毫升、橙味利口酒 20 毫升、新鲜柠檬汁 20 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-sidecar-6694912cb8aa9.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-sidecar-6694912cb8aa9.webp', 93, 200, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "白兰地基底", "柑橘", "摇和", "经典"]', '["经典"]', '{"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 50, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "橙味利口酒", "nameEn": "Triple sec", "amount": 20, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}]', '["摇酒壶加冰。", "倒入干邑、橙味利口酒与柠檬汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-sidecar", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "边车", "nameEn": "Sidecar", "intro": "干邑、橙味利口酒与柠檬汁摇和而成的经典酸型鸡尾酒，柑橘酸爽与干邑果香平衡。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-sidecar-6694912cb8aa9.webp", "tags": ["酸型鸡尾酒", "白兰地基底", "柑橘", "摇和", "经典"], "scene": ["经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-stinger', 'cocktail', 'COCKTAIL', '史丁格', 'Stinger', 'shidingge', 'sdg', '干邑与白色薄荷利口酒搅拌而成的餐后鸡尾酒，清凉薄荷与干邑果香形成明快对比。', '1890 年代在纽约流行，是 20 世纪初上流社会流行的餐后酒，因后劲十足又被称为“绅士的鸡尾酒”。IBA 配比：干邑 50 毫升、白色薄荷利口酒 20 毫升，搅拌滤入冰镇马天尼杯，可选薄荷叶装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-stinger-6694912ce0b8d.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-stinger-6694912ce0b8d.webp', 90, 201, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["白兰地基底", "烈酒主导", "搅拌", "薄荷", "餐后", "经典"]', '["餐后", "经典"]', '{"baseSpirit": "白兰地基底", "cocktailType": "烈酒主导", "flavor": "薄荷、清凉", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["餐后", "经典"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 50, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "白色薄荷利口酒", "nameEn": "White crème de menthe", "amount": 20, "unit": "ml", "role": "白色薄荷利口酒"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaf", "amount": 1, "unit": "piece", "role": "装饰（可选）"}]', '["搅拌杯加冰。", "倒入干邑与白色薄荷利口酒。", "搅拌至充分冷却。", "滤入冰镇马天尼杯。", "可选以薄荷叶装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-stinger", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "史丁格", "nameEn": "Stinger", "intro": "干邑与白色薄荷利口酒搅拌而成的餐后鸡尾酒，清凉薄荷与干邑果香形成明快对比。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-stinger-6694912ce0b8d.webp", "tags": ["白兰地基底", "烈酒主导", "搅拌", "薄荷", "餐后", "经典"], "scene": ["餐后", "经典"], "recommendationScore": 90, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "烈酒主导", "flavor": "薄荷、清凉", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tuxedo', 'cocktail', 'COCKTAIL', '燕尾服', 'Tuxedo', 'yanweifu', 'ywf', '老汤姆金酒、干味美思加少量马拉斯奇诺、苦艾酒与橙味苦精搅拌的马天尼变体，以纽约燕尾服俱乐部命名。', '以纽约曼哈顿著名的“燕尾服俱乐部”命名。IBA 配比：老汤姆金酒 30 毫升、干味美思 30 毫升、马拉斯奇诺半吧匙、苦艾酒四分之一吧匙、橙味苦精 3 滴，搅拌滤入冰镇马天尼杯，樱桃与柠檬皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-tuxedo-6694912fd3b8f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-tuxedo-6694912fd3b8f.webp', 90, 202, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["烈酒主导", "金酒基底", "马天尼", "搅拌", "草本", "经典"]', '["经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}', '[{"nameZh": "老汤姆金酒", "nameEn": "Old Tom gin", "amount": 30, "unit": "ml", "role": "老汤姆金酒"}, {"nameZh": "干味美思", "nameEn": "Dry vermouth", "amount": 30, "unit": "ml", "role": "干味美思"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino", "amount": 2.5, "unit": "ml", "role": "半吧匙马拉斯奇诺利口酒"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 1, "unit": "ml", "role": "四分之一吧匙苦艾酒"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 3, "unit": "dash", "role": "橙味苦精"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["搅拌杯加冰。", "倒入老汤姆金酒、干味美思、马拉斯奇诺、苦艾酒与橙味苦精。", "搅拌至充分冷却。", "滤入冰镇马天尼杯。", "以马拉斯奇诺樱桃与柠檬皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-tuxedo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "燕尾服", "nameEn": "Tuxedo", "intro": "老汤姆金酒、干味美思加少量马拉斯奇诺、苦艾酒与橙味苦精搅拌的马天尼变体，以纽约燕尾服俱乐部命名。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-tuxedo-6694912fd3b8f.webp", "tags": ["烈酒主导", "金酒基底", "马天尼", "搅拌", "草本", "经典"], "scene": ["经典"], "recommendationScore": 90, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本", "abv": "较高＞20%～30%", "extra": "无明显非酒精成分", "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vieux-carre', 'cocktail', 'COCKTAIL', '老广场', 'Vieux Carré', 'laoguangchang', 'lgc', '黑麦威士忌、干邑、甜味美思与少量本笃会利口酒加佩肖苦精搅拌的新奥尔良经典，层次丰富、甜苦交织。', '1938 年新奥尔良蒙特莱昂酒店调酒师沃尔特·伯杰龙为致敬法国区（Vieux Carré）创制。IBA 配比：黑麦威士忌、干邑、甜味美思各 30 毫升，本笃会 1 吧匙、佩肖苦精 2 滴，搅拌滤杯，橙皮与樱桃装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-vieux-carre-6694913015248.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-vieux-carre-6694913015248.webp', 93, 203, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 6.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 7.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["威士忌基底", "搅拌", "草本", "苦感主导", "经典", "餐后"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "草本、苦甜交织", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 30, "unit": "ml", "role": "40% ABV 黑麦威士忌"}, {"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 30, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "甜红味美思", "nameEn": "Sweet red vermouth", "amount": 30, "unit": "ml", "role": "甜红味美思"}, {"nameZh": "本笃会利口酒", "nameEn": "Bénédictine", "amount": 5, "unit": "ml", "role": "1 吧匙本笃会利口酒"}, {"nameZh": "佩肖苦精", "nameEn": "Peychaud\'s bitters", "amount": 2, "unit": "dash", "role": "佩肖苦精"}, {"nameZh": "橙皮", "nameEn": "Orange zest", "amount": 1, "unit": "piece", "role": "装饰用"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["搅拌杯加冰。", "倒入黑麦威士忌、干邑、甜味美思、本笃会利口酒与佩肖苦精。", "搅拌至充分冷却。", "滤入冰镇鸡尾酒杯。", "以橙皮与马拉斯奇诺樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-vieux-carre", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "老广场", "nameEn": "Vieux Carré", "intro": "黑麦威士忌、干邑、甜味美思与少量本笃会利口酒加佩肖苦精搅拌的新奥尔良经典，层次丰富、甜苦交织。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-vieux-carre-6694913015248.webp", "tags": ["威士忌基底", "搅拌", "草本", "苦感主导", "经典", "餐后"], "scene": ["经典", "餐后"], "recommendationScore": 93, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "古典家族", "flavor": "草本、苦甜交织", "abv": "高度＞30%", "extra": "无明显非酒精成分", "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-white-lady', 'cocktail', 'COCKTAIL', '白色佳人', 'White Lady', 'baisejiaren', 'bsjr', '金酒、橙味利口酒与柠檬汁摇和的经典酸型鸡尾酒，明亮柑橘酸爽，被视为金酒版边车。', '1919 年哈里·麦克埃尔霍恩以薄荷版创制，1929 年伦敦萨伏依酒店哈里·克拉多克改为金酒加君度加柠檬的经典版本。IBA 配比：金酒 40 毫升、橙味利口酒 30 毫升、新鲜柠檬汁 20 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-white-lady-6694913318105.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-white-lady-6694913318105.webp', 93, 204, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "柑橘", "摇和", "经典", "下午茶"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 40, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "橙味利口酒", "nameEn": "Triple sec", "amount": 30, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "新鲜柠檬汁"}]', '["摇酒壶加冰。", "倒入金酒、橙味利口酒与柠檬汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-white-lady", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "白色佳人", "nameEn": "White Lady", "intro": "金酒、橙味利口酒与柠檬汁摇和的经典酸型鸡尾酒，明亮柑橘酸爽，被视为金酒版边车。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-the-unforgettables-white-lady-6694913318105.webp", "tags": ["酸型鸡尾酒", "金酒基底", "柑橘", "摇和", "经典", "下午茶"], "scene": ["经典", "下午茶"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cardinale', 'cocktail', 'COCKTAIL', '红衣主教', 'Cardinale', 'hongyizhujiao', 'hyzj', '金酒、干味美思与金巴利搅拌而成的意式风格鸡尾酒，以红衣主教的红色教袍命名，苦橙与草本气息交织。', 'IBA 配比：金酒 40 毫升、干味美思 20 毫升、金巴利 10 毫升，加冰搅拌后滤入冰镇鸡尾酒杯，以柠檬皮拧香装饰。苦甜平衡，被视作内格罗尼的干爽变体。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cardinale-6695cdaa5f0d8.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cardinale-6695cdaa5f0d8.webp', 90, 205, '[{"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "SWEETNESS", "label": "甜度", "score": 3.0}]', '["金酒基底", "意大利风格", "搅拌", "草本", "苦甜", "开胃", "经典"]', '["开胃", "经典"]', '{"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "草本、苦橙", "abv": "较高＞20%～30%", "extra": ["干味美思", "金巴利"], "scene": ["开胃", "经典"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 40, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "干味美思", "nameEn": "Dry Vermouth", "amount": 20, "unit": "ml", "role": "干味美思"}, {"nameZh": "金巴利", "nameEn": "Bitter Campari", "amount": 10, "unit": "ml", "role": "金巴利苦味利口酒"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰"}]', '["鸡尾酒杯加冰预冷。", "搅拌杯加冰块，倒入金酒、干味美思与金巴利。", "充分搅拌约 20 秒至冷却。", "滤入冰镇鸡尾酒杯。", "柠檬皮拧香装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-cardinale", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "红衣主教", "nameEn": "Cardinale", "intro": "金酒、干味美思与金巴利搅拌而成的意式风格鸡尾酒，以红衣主教的红色教袍命名，苦橙与草本气息交织。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cardinale-6695cdaa5f0d8.webp", "tags": ["金酒基底", "意大利风格", "搅拌", "草本", "苦甜", "开胃", "经典"], "scene": ["开胃", "经典"], "recommendationScore": 90, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "古典家族", "flavor": "草本、苦橙", "abv": "较高＞20%～30%", "extra": ["干味美思", "金巴利"], "scene": ["开胃", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-corpse-reviver-2', 'cocktail', 'COCKTAIL', '死而复生2号', 'Corpse Reviver #2', 'sierfusheng2hao', 'sefs2h', '金酒、君度、丽莱白与柠檬汁摇和并以苦艾酒点缀的经典“还魂”鸡尾酒，酸甜清爽带草本气息。', '1930 年收录于《萨伏依鸡尾酒手册》，是解宿醉的“还魂”系列配方之一。IBA 配比：金酒、君度、丽莱白、新鲜柠檬汁各 30 毫升，加 1 滴苦艾酒摇和，滤入冰镇鸡尾酒杯，橙皮拧香装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-corpse-reviver-2-6695cdad6da15.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-corpse-reviver-2-6695cdad6da15.webp', 93, 206, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 8.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "金酒基底", "柑橘", "草本", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、草本", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "丽莱白", "苦艾酒"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 30, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "君度", "nameEn": "Cointreau", "amount": 30, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "丽莱白", "nameEn": "Lillet Blanc", "amount": 30, "unit": "ml", "role": "法国加香葡萄酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "苦艾酒", "nameEn": "Absinthe", "amount": 1, "unit": "dash", "role": "苦艾酒"}, {"nameZh": "橙皮", "nameEn": "Orange zest", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰。", "倒入金酒、君度、丽莱白与柠檬汁，滴入苦艾酒。", "充分摇和。", "滤入冰镇鸡尾酒杯。", "橙皮拧香装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-corpse-reviver-2", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "死而复生2号", "nameEn": "Corpse Reviver #2", "intro": "金酒、君度、丽莱白与柠檬汁摇和并以苦艾酒点缀的经典“还魂”鸡尾酒，酸甜清爽带草本气息。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-corpse-reviver-2-6695cdad6da15.webp", "tags": ["酸型鸡尾酒", "金酒基底", "柑橘", "草本", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 93, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "柑橘、草本", "abv": "较高＞20%～30%", "extra": ["新鲜柠檬汁", "丽莱白", "苦艾酒"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-cosmopolitan', 'cocktail', 'COCKTAIL', '大都会', 'Cosmopolitan', 'daduhui', 'ddh', '伏特加、君度、蔓越莓汁与青柠汁摇和的粉红色经典鸡尾酒，酸甜清爽、果香突出。', '1980 年代在纽约定型，1990 年代末因《欲望都市》全球走红。IBA 配比：伏特加 40 毫升、君度 15 毫升、蔓越莓汁 30 毫升、新鲜青柠汁 15 毫升，摇和滤入大号鸡尾酒杯，柠檬卷皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cosmopolitan-6695cdae389dc.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cosmopolitan-6695cdae389dc.webp', 95, 207, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "伏特加基底", "果香", "柑橘", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、柑橘", "abv": "中度＞10%～20%", "extra": ["蔓越莓汁", "君度"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "柠檬风味伏特加", "nameEn": "Vodka Citron", "amount": 40, "unit": "ml", "role": "柠檬风味伏特加"}, {"nameZh": "君度", "nameEn": "Cointreau", "amount": 15, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "蔓越莓汁", "nameEn": "Cranberry Juice", "amount": 30, "unit": "ml", "role": "蔓越莓汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "柠檬卷皮", "nameEn": "Lemon twist", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰。", "倒入伏特加、君度、蔓越莓汁与青柠汁。", "充分摇和。", "滤入大号冰镇鸡尾酒杯。", "柠檬卷皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-cosmopolitan", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "大都会", "nameEn": "Cosmopolitan", "intro": "伏特加、君度、蔓越莓汁与青柠汁摇和的粉红色经典鸡尾酒，酸甜清爽、果香突出。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-cosmopolitan-6695cdae389dc.webp", "tags": ["酸型鸡尾酒", "伏特加基底", "果香", "柑橘", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 95, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、柑橘", "abv": "中度＞10%～20%", "extra": ["蔓越莓汁", "君度"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-french-connection', 'cocktail', 'COCKTAIL', '法国情怀', 'French Connection', 'faguoqinghuai', 'fgqh', '干邑白兰地与杏仁利口酒一比一直调的双料鸡尾酒，杏仁甜香包裹干邑的果香，柔和顺口。', '以 1971 年电影《法国贩毒网》命名。IBA 配比：干邑白兰地、阿玛雷托杏仁利口酒各 35 毫升，倒入加冰古典杯轻搅即成，无装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-french-connection-6695cdb3cc15f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-french-connection-6695cdb3cc15f.webp', 88, 208, '[{"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["烈酒主导", "白兰地基底", "直调", "杏仁", "甜感", "餐后"]', '["餐后"]', '{"baseSpirit": "白兰地基底", "cocktailType": "烈酒主导", "flavor": "杏仁、果香", "abv": "较高＞20%～30%", "extra": ["杏仁利口酒"], "scene": ["餐后"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 35, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "阿玛雷托杏仁利口酒", "nameEn": "Amaretto", "amount": 35, "unit": "ml", "role": "杏仁利口酒"}]', '["古典杯加冰块。", "倒入干邑白兰地。", "倒入杏仁利口酒。", "轻搅调和即成。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-french-connection", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "法国情怀", "nameEn": "French Connection", "intro": "干邑白兰地与杏仁利口酒一比一直调的双料鸡尾酒，杏仁甜香包裹干邑的果香，柔和顺口。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-french-connection-6695cdb3cc15f.webp", "tags": ["烈酒主导", "白兰地基底", "直调", "杏仁", "甜感", "餐后"], "scene": ["餐后"], "recommendationScore": 88, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "烈酒主导", "flavor": "杏仁、果香", "abv": "较高＞20%～30%", "extra": ["杏仁利口酒"], "scene": ["餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-garibaldi', 'cocktail', 'COCKTAIL', '加里波第', 'Garibaldi', 'jialibodi', 'jlbd', '金巴利与鲜榨橙汁直调的高球鸡尾酒，苦甜相映、橙香浓郁，是意大利国民开胃酒。', '以意大利统一英雄加里波第命名，其追随者“红衫军”对应金巴利的红色。IBA 配比：金巴利 45 毫升、鲜榨橙汁 120 毫升，加冰直调于高球杯，橙角装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-garibaldi-6695cdb4cbf81.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-garibaldi-6695cdb4cbf81.webp', 90, 209, '[{"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜度", "score": 4.0}]', '["高球", "意大利风格", "直调", "柑橘", "气泡", "开胃"]', '["开胃", "早午餐"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "橙香、苦甜", "abv": "低度≤10%", "extra": ["鲜榨橙汁"], "scene": ["开胃", "早午餐"]}', '[{"nameZh": "金巴利", "nameEn": "Bitter Campari", "amount": 45, "unit": "ml", "role": "金巴利苦味利口酒"}, {"nameZh": "鲜榨橙汁", "nameEn": "Freshly Squeezed Orange Juice", "amount": 120, "unit": "ml", "role": "鲜榨橙汁"}, {"nameZh": "橙角", "nameEn": "Orange wedge", "amount": 1, "unit": "piece", "role": "装饰"}]', '["高球杯加冰块。", "倒入金巴利。", "加满鲜榨橙汁。", "轻搅调和。", "橙角装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-garibaldi", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "加里波第", "nameEn": "Garibaldi", "intro": "金巴利与鲜榨橙汁直调的高球鸡尾酒，苦甜相映、橙香浓郁，是意大利国民开胃酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-garibaldi-6695cdb4cbf81.webp", "tags": ["高球", "意大利风格", "直调", "柑橘", "气泡", "开胃"], "scene": ["开胃", "早午餐"], "recommendationScore": 90, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "橙香、苦甜", "abv": "低度≤10%", "extra": ["鲜榨橙汁"], "scene": ["开胃", "早午餐"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-grasshopper', 'cocktail', 'COCKTAIL', '绿蚱蜢', 'Grasshopper', 'lvzhameng', 'lzm', '绿薄荷利口酒、白可可利口酒与鲜奶油摇和的薄荷绿餐后甜饮，清凉薄荷与奶香交融。', '1919 年新奥尔良调酒师菲利亚·吉谢为行业比赛创制并获奖。IBA 配比：绿薄荷利口酒、白可可利口酒与鲜奶油各 20 毫升，快速摇和滤入冰镇鸡尾酒杯，可选薄荷叶装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-grasshopper-6695cdb737498.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-grasshopper-6695cdb737498.webp', 91, 210, '[{"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "SWEETNESS", "label": "甜度", "score": 9.0}]', '["餐后甜饮", "摇和", "薄荷", "奶香", "可可", "餐后"]', '["餐后", "节日"]', '{"baseSpirit": "未标注基酒", "cocktailType": "餐后甜饮", "flavor": "薄荷、奶香", "abv": "中度＞10%～20%", "extra": ["鲜奶油"], "scene": ["餐后", "节日"]}', '[{"nameZh": "白可可利口酒", "nameEn": "Crème de Cacao (White)", "amount": 20, "unit": "ml", "role": "白可可利口酒"}, {"nameZh": "绿薄荷利口酒", "nameEn": "Crème de Menthe (Green)", "amount": 20, "unit": "ml", "role": "绿薄荷利口酒"}, {"nameZh": "鲜奶油", "nameEn": "Fresh Cream", "amount": 20, "unit": "ml", "role": "鲜奶油"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaf", "amount": 1, "unit": "piece", "role": "装饰（可选）"}]', '["摇酒壶加冰。", "倒入白可可利口酒、绿薄荷利口酒与鲜奶油。", "快速摇和数秒。", "滤入冰镇鸡尾酒杯。", "可选薄荷叶装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-grasshopper", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "绿蚱蜢", "nameEn": "Grasshopper", "intro": "绿薄荷利口酒、白可可利口酒与鲜奶油摇和的薄荷绿餐后甜饮，清凉薄荷与奶香交融。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-grasshopper-6695cdb737498.webp", "tags": ["餐后甜饮", "摇和", "薄荷", "奶香", "可可", "餐后"], "scene": ["餐后", "节日"], "recommendationScore": 91, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "餐后甜饮", "flavor": "薄荷、奶香", "abv": "中度＞10%～20%", "extra": ["鲜奶油"], "scene": ["餐后", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-hemingway-special', 'cocktail', 'COCKTAIL', '海明威特调', 'Hemingway Special', 'haimingweitediao', 'hmwtd', '朗姆、西柚汁、马拉斯奇诺与青柠汁摇和的大吉利变体，西柚微苦与果酸交织，清爽利落。', '1930 年代哈瓦那佛罗里迪塔酒吧为海明威调制，双倍朗姆、不加糖，原名“大吉利冰沙”。IBA 配比：朗姆 60 毫升、西柚汁 40 毫升、马拉斯奇诺 15 毫升、新鲜青柠汁 15 毫升，摇和滤入大号鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-hemingway-special-6695cdb814e5a.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-hemingway-special-6695cdb814e5a.webp', 93, 211, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 4.0}]', '["酸型鸡尾酒", "朗姆基底", "果香", "西柚", "摇和", "经典"]', '["经典", "夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、西柚", "abv": "中度＞10%～20%", "extra": ["西柚汁", "马拉斯奇诺利口酒"], "scene": ["经典", "夏季"]}', '[{"nameZh": "朗姆", "nameEn": "Rum", "amount": 60, "unit": "ml", "role": "40% ABV 朗姆"}, {"nameZh": "西柚汁", "nameEn": "Grapefruit Juice", "amount": 40, "unit": "ml", "role": "西柚汁"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino Luxardo", "amount": 15, "unit": "ml", "role": "马拉斯奇诺利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}]', '["摇酒壶加冰。", "倒入朗姆、西柚汁、马拉斯奇诺与青柠汁。", "充分摇和。", "滤入大号冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-hemingway-special", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "海明威特调", "nameEn": "Hemingway Special", "intro": "朗姆、西柚汁、马拉斯奇诺与青柠汁摇和的大吉利变体，西柚微苦与果酸交织，清爽利落。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-hemingway-special-6695cdb814e5a.webp", "tags": ["酸型鸡尾酒", "朗姆基底", "果香", "西柚", "摇和", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、西柚", "abv": "中度＞10%～20%", "extra": ["西柚汁", "马拉斯奇诺利口酒"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-horses-neck', 'cocktail', 'COCKTAIL', '马颈', 'Horse\'s Neck', 'majing', 'mj', '干邑、姜汁汽水与苦精构成的高球饮品，盘绕杯中的长螺旋柠檬皮形似“马颈”，是其标志。', '1890 年代美国流行的高球。IBA 配比：干邑 40 毫升、姜汁汽水 120 毫升，加冰直调于高球杯，可加 1 dash 安高天娜苦精，以螺旋柠檬皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-horses-neck-6695cdba5fadc.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-horses-neck-6695cdba5fadc.webp', 88, 212, '[{"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["高球", "白兰地基底", "直调", "姜汁", "气泡", "经典"]', '["日常", "开胃"]', '{"baseSpirit": "白兰地基底", "cocktailType": "高球", "flavor": "姜汁、柑橘", "abv": "低度≤10%", "extra": ["姜汁汽水"], "scene": ["日常", "开胃"]}', '[{"nameZh": "干邑白兰地", "nameEn": "Cognac", "amount": 40, "unit": "ml", "role": "40% ABV 干邑白兰地"}, {"nameZh": "姜汁汽水", "nameEn": "Ginger Ale", "amount": 120, "unit": "ml", "role": "姜汁汽水"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 1, "unit": "dash", "role": "可选"}, {"nameZh": "螺旋柠檬皮", "nameEn": "Lemon rind spiral", "amount": 1, "unit": "piece", "role": "装饰"}]', '["高球杯加冰块。", "倒入干邑白兰地与姜汁汽水。", "可选滴入安高天娜苦精。", "轻搅调和。", "螺旋柠檬皮挂杯装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-horses-neck", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "马颈", "nameEn": "Horse\'s Neck", "intro": "干邑、姜汁汽水与苦精构成的高球饮品，盘绕杯中的长螺旋柠檬皮形似“马颈”，是其标志。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-horses-neck-6695cdba5fadc.webp", "tags": ["高球", "白兰地基底", "直调", "姜汁", "气泡", "经典"], "scene": ["日常", "开胃"], "recommendationScore": 88, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "高球", "flavor": "姜汁、柑橘", "abv": "低度≤10%", "extra": ["姜汁汽水"], "scene": ["日常", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-kir', 'cocktail', 'COCKTAIL', '基尔', 'Kir', 'jier', 'je', '干白葡萄酒与黑醋栗利口酒直调的开胃酒，黑醋栗的莓果甜香融入干白，简单清新。', '以二战法国第戎市长、葡萄酒业推动者菲利克斯·基尔命名。IBA 配比：干白葡萄酒 90 毫升、黑醋栗利口酒 10 毫升，杯中直调，换用香槟即为皇家基尔。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-kir-6695cdbdbb2e1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-kir-6695cdbdbb2e1.webp', 92, 213, '[{"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["直调", "果香", "黑醋栗", "开胃", "经典", "气泡"]', '["开胃", "下午茶"]', '{"baseSpirit": "未标注基酒", "cocktailType": "开胃鸡尾酒", "flavor": "果香、黑醋栗", "abv": "中度＞10%～20%", "extra": ["黑醋栗利口酒"], "scene": ["开胃", "下午茶"]}', '[{"nameZh": "干白葡萄酒", "nameEn": "Dry White Wine", "amount": 90, "unit": "ml", "role": "干白葡萄酒"}, {"nameZh": "黑醋栗利口酒", "nameEn": "Crème de Cassis", "amount": 10, "unit": "ml", "role": "黑醋栗利口酒"}]', '["酒杯中倒入黑醋栗利口酒。", "加满冰镇干白葡萄酒。", "轻搅即成。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-kir", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "基尔", "nameEn": "Kir", "intro": "干白葡萄酒与黑醋栗利口酒直调的开胃酒，黑醋栗的莓果甜香融入干白，简单清新。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-kir-6695cdbdbb2e1.webp", "tags": ["直调", "果香", "黑醋栗", "开胃", "经典", "气泡"], "scene": ["开胃", "下午茶"], "recommendationScore": 92, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "开胃鸡尾酒", "flavor": "果香、黑醋栗", "abv": "中度＞10%～20%", "extra": ["黑醋栗利口酒"], "scene": ["开胃", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lemon-drop-martini', 'cocktail', 'COCKTAIL', '柠檬滴马天尼', 'Lemon Drop Martini', 'ningmengdimatianni', 'nmdmtn', '伏特加、橙味利口酒与鲜榨柠檬汁摇和的柠檬味酸酒，酸甜明亮、清爽利落。', '1970 年代旧金山亨利酒吧创制，柠檬糖边杯口是其标志性装饰。IBA 配比：伏特加 30 毫升、橙味利口酒 20 毫升、鲜榨柠檬汁 15 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-lemon-drop-martini-6695cdbe3eed7.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-lemon-drop-martini-6695cdbe3eed7.webp', 92, 214, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "伏特加基底", "柑橘", "摇和", "经典", "下午茶"]', '["经典", "下午茶"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "柠檬、柑橘", "abv": "较高＞20%～30%", "extra": ["橙味利口酒", "鲜榨柠檬汁"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 30, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "橙味利口酒", "nameEn": "Triple Sec", "amount": 20, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "鲜榨柠檬汁", "nameEn": "Fresh Squeezed Lemon Juice", "amount": 15, "unit": "ml", "role": "鲜榨柠檬汁"}]', '["摇酒壶加冰。", "倒入伏特加、橙味利口酒与鲜榨柠檬汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-lemon-drop-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "柠檬滴马天尼", "nameEn": "Lemon Drop Martini", "intro": "伏特加、橙味利口酒与鲜榨柠檬汁摇和的柠檬味酸酒，酸甜明亮、清爽利落。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-lemon-drop-martini-6695cdbe3eed7.webp", "tags": ["酸型鸡尾酒", "伏特加基底", "柑橘", "摇和", "经典", "下午茶"], "scene": ["经典", "下午茶"], "recommendationScore": 92, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "柠檬、柑橘", "abv": "较高＞20%～30%", "extra": ["橙味利口酒", "鲜榨柠檬汁"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-long-island-iced-tea', 'cocktail', 'COCKTAIL', '长岛冰茶', 'Long Island Iced Tea', 'zhangdaobingcha', 'zdbc', '伏特加、金酒、朗姆、龙舌兰与君度五种烈酒加可乐直调，色泽似冰茶却酒劲十足。', '1970 年代纽约长岛创制，因颜色酷似冰茶而闻名。IBA 配比：五种烈酒各 15 毫升、柠檬汁 25 毫升、糖浆 30 毫升，加冰高球杯直调，以可乐加满，柠檬片装饰（可选）。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-long-island-iced-tea-6695cdc10c463.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-long-island-iced-tea-6695cdc10c463.webp', 94, 215, '[{"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["高球", "多基酒", "直调", "柠檬", "气泡", "经典"]', '["日常", "夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "柑橘、可乐", "abv": "中度＞10%～20%", "extra": ["可乐", "糖浆"], "scene": ["日常", "夏季"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 15, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "龙舌兰", "nameEn": "Tequila", "amount": 15, "unit": "ml", "role": "40% ABV 龙舌兰"}, {"nameZh": "白朗姆", "nameEn": "White Rum", "amount": 15, "unit": "ml", "role": "40% ABV 白朗姆"}, {"nameZh": "金酒", "nameEn": "Gin", "amount": 15, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "君度", "nameEn": "Cointreau", "amount": 15, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "柠檬汁", "nameEn": "Lemon Juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 30, "unit": "ml", "role": "糖浆"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 90, "unit": "ml", "role": "加满"}, {"nameZh": "柠檬片", "nameEn": "Lemon slice", "amount": 1, "unit": "piece", "role": "装饰（可选）"}]', '["高球杯加冰块。", "依次倒入五种烈酒与君度。", "加入柠檬汁与糖浆。", "轻搅调和。", "可乐加满。", "柠檬片装饰（可选）。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-long-island-iced-tea", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "长岛冰茶", "nameEn": "Long Island Iced Tea", "intro": "伏特加、金酒、朗姆、龙舌兰与君度五种烈酒加可乐直调，色泽似冰茶却酒劲十足。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-long-island-iced-tea-6695cdc10c463.webp", "tags": ["高球", "多基酒", "直调", "柠檬", "气泡", "经典"], "scene": ["日常", "夏季"], "recommendationScore": 94, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "柑橘、可乐", "abv": "中度＞10%～20%", "extra": ["可乐", "糖浆"], "scene": ["日常", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rabo-de-galo', 'cocktail', 'COCKTAIL', '公鸡尾', 'Rabo de Galo', 'gongjiwei', 'gjw', '卡莎萨、甜味美思与西纳苦酒组成的巴西经典鸡尾酒，橙色酒体恰如公鸡尾羽，苦甜深邃。', 'IBA 配比：卡莎萨 60 毫升、甜味美思 20 毫升、西纳苦酒 15 毫升，可选 2 滴安高天娜苦精，加冰岩石杯轻搅，橙皮拧香装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-rabo-de-galo-6695cdcdb2df1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-rabo-de-galo-6695cdcdb2df1.webp', 89, 216, '[{"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["烈酒主导", "搅拌", "草本", "苦甜", "巴西", "餐后"]', '["餐后", "经典"]', '{"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "草本、焦糖", "abv": "较高＞20%～30%", "extra": ["甜味美思", "西纳苦酒"], "scene": ["餐后", "经典"]}', '[{"nameZh": "卡莎萨", "nameEn": "Cachaca", "amount": 60, "unit": "ml", "role": "40% ABV 甘蔗烈酒"}, {"nameZh": "甜味美思", "nameEn": "Sweet Vermouth Cinzano Rosso", "amount": 20, "unit": "ml", "role": "甜味美思"}, {"nameZh": "西纳苦酒", "nameEn": "Cynar", "amount": 15, "unit": "ml", "role": "洋蓟草本苦酒"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 1, "unit": "dash", "role": "可选"}, {"nameZh": "橙皮", "nameEn": "Orange twist", "amount": 1, "unit": "piece", "role": "装饰"}]', '["岩石杯加冰。", "倒入卡莎萨、甜味美思与西纳苦酒。", "可选滴入安高天娜苦精。", "轻搅调和。", "橙皮拧香装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-rabo-de-galo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "公鸡尾", "nameEn": "Rabo de Galo", "intro": "卡莎萨、甜味美思与西纳苦酒组成的巴西经典鸡尾酒，橙色酒体恰如公鸡尾羽，苦甜深邃。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-rabo-de-galo-6695cdcdb2df1.webp", "tags": ["烈酒主导", "搅拌", "草本", "苦甜", "巴西", "餐后"], "scene": ["餐后", "经典"], "recommendationScore": 89, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "草本、焦糖", "abv": "较高＞20%～30%", "extra": ["甜味美思", "西纳苦酒"], "scene": ["餐后", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vesper', 'cocktail', 'COCKTAIL', '维斯帕', 'Vesper', 'weisipa', 'wsp', '金酒与伏特加双烈酒加丽莱白摇和的“邦德鸡尾酒”，酒体强劲、草本气息明显，收尾干爽。', '1953 年出自伊恩·弗莱明小说《皇家赌场》，以女郎维斯帕·林德命名，后正式收录进 IBA 名单。IBA 配比：金酒 45 毫升、伏特加 15 毫升、丽莱白 7.5 毫升，摇和滤入冰镇鸡尾酒杯，柠檬皮拧香装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-vesper-6695cdd43284b.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-vesper-6695cdd43284b.webp', 96, 217, '[{"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "SWEETNESS", "label": "甜度", "score": 3.0}]', '["烈酒主导", "金酒基底", "摇和", "草本", "经典"]', '["经典", "日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本、植物香", "abv": "高度＞30%", "extra": ["伏特加", "丽莱白"], "scene": ["经典", "日常"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 45, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "伏特加", "nameEn": "Vodka", "amount": 15, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "丽莱白", "nameEn": "Lillet Blanc", "amount": 7.5, "unit": "ml", "role": "法国加香葡萄酒"}, {"nameZh": "柠檬皮", "nameEn": "Lemon zest", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰。", "倒入金酒、伏特加与丽莱白。", "充分摇和。", "滤入冰镇鸡尾酒杯。", "柠檬皮拧香装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-vesper", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "维斯帕", "nameEn": "Vesper", "intro": "金酒与伏特加双烈酒加丽莱白摇和的“邦德鸡尾酒”，酒体强劲、草本气息明显，收尾干爽。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-contemporary-classics-vesper-6695cdd43284b.webp", "tags": ["烈酒主导", "金酒基底", "摇和", "草本", "经典"], "scene": ["经典", "日常"], "recommendationScore": 96, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "马天尼", "flavor": "草本、植物香", "abv": "高度＞30%", "extra": ["伏特加", "丽莱白"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bees-knees', 'cocktail', 'COCKTAIL', '蜂之膝', 'Bee\'s Knees', 'fengzhixi', 'fzx', '金酒、蜂蜜糖浆与柑橘汁摇和的甜酸鸡尾酒，蜂蜜的圆润包裹金酒的草本香，酸甜平衡。', '1920 年代禁酒令时期流行，用蜂蜜掩盖劣质金酒的风味，俚语意为“极好之物”。IBA 配比：金酒 52.5 毫升、蜂蜜糖浆 2 茶匙、新鲜柠檬汁与橙汁各 22.5 毫升，摇和滤入冰镇鸡尾酒杯，可选柑橘皮装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-bees-knees-6695d397e26c1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-bees-knees-6695d397e26c1.webp', 92, 218, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "蜂蜜", "柑橘", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["蜂蜜糖浆", "新鲜橙汁"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Dry Gin", "amount": 52.5, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "蜂蜜糖浆", "nameEn": "Honey Syrup", "amount": 10, "unit": "ml", "role": "2 茶匙"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh Orange Juice", "amount": 22.5, "unit": "ml", "role": "新鲜橙汁"}]', '["摇酒壶中搅拌蜂蜜糖浆与两种果汁至融化。", "加入金酒。", "加冰充分摇和。", "滤入冰镇鸡尾酒杯。", "可选柠檬或橙皮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-bees-knees", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蜂之膝", "nameEn": "Bee\'s Knees", "intro": "金酒、蜂蜜糖浆与柑橘汁摇和的甜酸鸡尾酒，蜂蜜的圆润包裹金酒的草本香，酸甜平衡。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-bees-knees-6695d397e26c1.webp", "tags": ["酸型鸡尾酒", "金酒基底", "蜂蜜", "柑橘", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["蜂蜜糖浆", "新鲜橙汁"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bramble', 'cocktail', 'COCKTAIL', '树莓', 'Bramble', 'shumei', 'sm', '金酒、柠檬汁与黑莓利口酒组成的现代经典，黑莓利口酒淋面带来标志性的渐变色泽与浆果香气。', '1984 年伦敦调酒师迪克·布拉德塞尔创制，以英国乡间采摘黑莓的传统命名。IBA 配比：金酒 50 毫升、柠檬汁 25 毫升、糖浆 12.5 毫升摇和，滤入装满碎冰的古典杯，再沿杯壁环形淋上 15 毫升黑莓利口酒，可选柠檬片与黑莓装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-bramble-6695d398036e1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-bramble-6695d398036e1.webp', 92, 219, '[{"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["酸型鸡尾酒", "金酒基底", "果香", "浆果", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、浆果", "abv": "中度＞10%～20%", "extra": ["黑莓利口酒", "糖浆"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 50, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "糖浆", "nameEn": "Sugar Syrup", "amount": 12.5, "unit": "ml", "role": "糖浆"}, {"nameZh": "黑莓利口酒", "nameEn": "Crème de Mûre", "amount": 15, "unit": "ml", "role": "淋面用"}, {"nameZh": "黑莓", "nameEn": "Blackberries", "amount": 3, "unit": "piece", "role": "装饰（可选）"}]', '["摇酒壶加冰。", "倒入金酒、柠檬汁与糖浆，充分摇和。", "滤入装满碎冰的古典杯。", "将黑莓利口酒沿杯壁环形淋于表面。", "可选柠檬片与黑莓装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-bramble", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "树莓", "nameEn": "Bramble", "intro": "金酒、柠檬汁与黑莓利口酒组成的现代经典，黑莓利口酒淋面带来标志性的渐变色泽与浆果香气。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-bramble-6695d398036e1.webp", "tags": ["酸型鸡尾酒", "金酒基底", "果香", "浆果", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "果香、浆果", "abv": "中度＞10%～20%", "extra": ["黑莓利口酒", "糖浆"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-canchanchara', 'cocktail', 'COCKTAIL', '坎昌恰拉', 'Canchanchara', 'kanchangqiala', 'kcql', '古巴甘蔗烈酒、青柠汁与蜂蜜调制的古巴传统饮品，蜂蜜甜润、青柠清新，甘蔗气息浓郁。', '19 世纪古巴独立战争时期为士兵调制，如今是特立尼达的城市节庆饮品。IBA 配比：古巴甘蔗烈酒 60 毫升、青柠汁 15 毫升、原蜜 15 毫升、水 50 毫升，杯底涂抹蜜汁后加碎冰与烈酒，由下至上用力搅拌，青柠角装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-canchanchara-6695d39b24d7e.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-canchanchara-6695d39b24d7e.webp', 90, 220, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["朗姆基底", "蜂蜜", "柑橘", "古巴", "夏季", "经典"]', '["夏季", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "烈酒主导", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["蜂蜜", "水"], "scene": ["夏季", "经典"]}', '[{"nameZh": "古巴甘蔗烈酒", "nameEn": "Cuban Aguardiente", "amount": 60, "unit": "ml", "role": "40% ABV 甘蔗烈酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "原蜜", "nameEn": "Raw Honey", "amount": 15, "unit": "ml", "role": "原蜜"}, {"nameZh": "水", "nameEn": "Water", "amount": 50, "unit": "ml", "role": "水"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 1, "unit": "piece", "role": "装饰"}]', '["杯中混合蜂蜜、水与青柠汁并涂抹杯壁杯底。", "加入碎冰。", "倒入古巴甘蔗烈酒。", "由下至上用力搅拌调和。", "青柠角装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-canchanchara", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "坎昌恰拉", "nameEn": "Canchanchara", "intro": "古巴甘蔗烈酒、青柠汁与蜂蜜调制的古巴传统饮品，蜂蜜甜润、青柠清新，甘蔗气息浓郁。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-canchanchara-6695d39b24d7e.webp", "tags": ["朗姆基底", "蜂蜜", "柑橘", "古巴", "夏季", "经典"], "scene": ["夏季", "经典"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "烈酒主导", "flavor": "蜂蜜、柑橘", "abv": "中度＞10%～20%", "extra": ["蜂蜜", "水"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-chartreuse-swizzle', 'cocktail', 'COCKTAIL', '查特酒斯威兹', 'Chartreuse Swizzle', 'chatejiusiweizi', 'ctjswz', '绿查特酒、菠萝汁、青柠汁与法勒南组成的加勒比斯威兹，草本与热带果香并存，清凉馥郁。', '以法国草本利口酒绿查特酒为核心，采用加勒比“斯威兹”搅打碎冰手法。IBA 配比：绿查特酒 45 毫升、菠萝汁 30 毫升、青柠汁 22.5 毫升、法勒南 15 毫升，碎冰中大力搅拌，薄荷叶与肉豆蔻粉装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-chartreuse-swizzle-6695d39b326e0.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-chartreuse-swizzle-6695d39b326e0.webp', 92, 221, '[{"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["烈酒主导", "查特酒", "草本", "菠萝", "搅拌", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "草本、菠萝", "abv": "较高＞20%～30%", "extra": ["菠萝汁", "法勒南糖浆"], "scene": ["经典", "夏季"]}', '[{"nameZh": "绿查特酒", "nameEn": "Green Chartreuse", "amount": 45, "unit": "ml", "role": "55% ABV 草本利口酒"}, {"nameZh": "新鲜菠萝汁", "nameEn": "Fresh Pineapple Juice", "amount": 30, "unit": "ml", "role": "新鲜菠萝汁"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22.5, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "法勒南糖浆", "nameEn": "Falernum", "amount": 15, "unit": "ml", "role": "法勒南糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint leaves", "amount": 1, "unit": "piece", "role": "装饰"}, {"nameZh": "肉豆蔻粉", "nameEn": "Ground nutmeg", "amount": 1, "unit": "dash", "role": "装饰"}]', '["高杯加入碎冰。", "倒入绿查特酒、菠萝汁、青柠汁与法勒南。", "用斯威兹棒或吧匙大力搅拌。", "补满碎冰。", "薄荷叶与肉豆蔻粉装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-chartreuse-swizzle", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "查特酒斯威兹", "nameEn": "Chartreuse Swizzle", "intro": "绿查特酒、菠萝汁、青柠汁与法勒南组成的加勒比斯威兹，草本与热带果香并存，清凉馥郁。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-chartreuse-swizzle-6695d39b326e0.webp", "tags": ["烈酒主导", "查特酒", "草本", "菠萝", "搅拌", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 92, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "烈酒主导", "flavor": "草本、菠萝", "abv": "较高＞20%～30%", "extra": ["菠萝汁", "法勒南糖浆"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-dark-n-stormy', 'cocktail', 'COCKTAIL', '黑暗风暴', 'Dark \'n\' Stormy', 'heianfengbao', 'hafb', '哥斯兰黑朗姆浮层与姜汁啤酒组成的高球，姜香辛辣、黑朗姆焦糖气息浓郁，名字形容海面乌云压境。', '一战前诞生于百慕大，是哥斯兰公司的注册商标饮品。IBA 配比：高球杯加冰后先倒姜汁啤酒 100 毫升，再将哥斯兰黑朗姆 60 毫升缓缓浮于上层，青柠角装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-dark-n-stormy-6695d39e2bd94.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-dark-n-stormy-6695d39e2bd94.webp', 93, 222, '[{"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "SWEETNESS", "label": "甜度", "score": 4.0}]', '["高球", "朗姆基底", "直调", "姜汁", "气泡", "夏季"]', '["夏季", "日常"]', '{"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "姜汁、焦糖", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒"], "scene": ["夏季", "日常"]}', '[{"nameZh": "哥斯兰黑朗姆", "nameEn": "Goslings Rum", "amount": 60, "unit": "ml", "role": "40% ABV 黑朗姆"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger Beer", "amount": 100, "unit": "ml", "role": "姜汁啤酒"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 1, "unit": "piece", "role": "装饰"}]', '["高球杯加冰块。", "倒入姜汁啤酒。", "将黑朗姆缓缓浮于上层。", "轻搅或保持分层。", "青柠角装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-dark-n-stormy", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "黑暗风暴", "nameEn": "Dark \'n\' Stormy", "intro": "哥斯兰黑朗姆浮层与姜汁啤酒组成的高球，姜香辛辣、黑朗姆焦糖气息浓郁，名字形容海面乌云压境。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-dark-n-stormy-6695d39e2bd94.webp", "tags": ["高球", "朗姆基底", "直调", "姜汁", "气泡", "夏季"], "scene": ["夏季", "日常"], "recommendationScore": 93, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "高球", "flavor": "姜汁、焦糖", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒"], "scene": ["夏季", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-dons-special-daiquiri', 'cocktail', 'COCKTAIL', '唐氏特调大吉利', 'Don\'s Special Daiquiri', 'tangshitediaodajili', 'tstddjl', '牙买加与古巴朗姆加百香果糖浆、蜂蜜糖浆调制而成的大吉利变体，热带果香浓郁、甜酸交织。', '1930 年代 Don the Beachcomber 酒吧老板唐恩·比奇创制，是提基文化奠基配方之一。IBA 配比：牙买加金朗姆 30 毫升、古巴朗姆 15 毫升、百香果糖浆 15 毫升、青柠汁 15 毫升、蜂蜜糖浆 15 毫升，与碎冰搅拌倒入带脚杯，半颗百香果装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-dons-special-daiquiri-6695d39e89fd7.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-dons-special-daiquiri-6695d39e89fd7.webp', 90, 223, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["酸型鸡尾酒", "朗姆基底", "果香", "百香果", "提基", "夏季"]', '["夏季", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "百香果、蜂蜜", "abv": "中度＞10%～20%", "extra": ["百香果糖浆", "蜂蜜糖浆"], "scene": ["夏季", "经典"]}', '[{"nameZh": "牙买加金朗姆", "nameEn": "Gold Jamaican Rum", "amount": 30, "unit": "ml", "role": "40% ABV 金朗姆"}, {"nameZh": "古巴朗姆", "nameEn": "Cuban Rum", "amount": 15, "unit": "ml", "role": "40% ABV 朗姆"}, {"nameZh": "百香果糖浆", "nameEn": "Passion Fruit Syrup", "amount": 15, "unit": "ml", "role": "百香果糖浆"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "蜂蜜糖浆", "nameEn": "Honey Syrup", "amount": 15, "unit": "ml", "role": "蜂蜜糖浆"}, {"nameZh": "百香果", "nameEn": "Passion fruit", "amount": 1, "unit": "piece", "role": "半颗装饰"}]', '["搅拌机中加入各配料与碎冰。", "低速搅拌数秒。", "倒入带脚杯。", "补满碎冰。", "半颗百香果装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-dons-special-daiquiri", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "唐氏特调大吉利", "nameEn": "Don\'s Special Daiquiri", "intro": "牙买加与古巴朗姆加百香果糖浆、蜂蜜糖浆调制而成的大吉利变体，热带果香浓郁、甜酸交织。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-dons-special-daiquiri-6695d39e89fd7.webp", "tags": ["酸型鸡尾酒", "朗姆基底", "果香", "百香果", "提基", "夏季"], "scene": ["夏季", "经典"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "百香果、蜂蜜", "abv": "中度＞10%～20%", "extra": ["百香果糖浆", "蜂蜜糖浆"], "scene": ["夏季", "经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-fernandito', 'cocktail', 'COCKTAIL', '费尔南迪托', 'Fernandito', 'feiernandituo', 'fendt', '费内特苦酒兑可乐的阿根廷国民饮品，草本苦香与可乐甜感碰撞，清凉苦甜。', '源自阿根廷国饮“费内特加可乐”，2015 年入选 IBA 名单。IBA 配比：费内特苦酒 50 毫升加冰后以可乐加满，轻搅即可，无装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-fernandito-6695d3a1a3586.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-fernandito-6695d3a1a3586.webp', 88, 224, '[{"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["高球", "苦酒", "直调", "草本", "可乐", "开胃"]', '["开胃", "日常"]', '{"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "草本、可乐", "abv": "低度≤10%", "extra": ["可乐"], "scene": ["开胃", "日常"]}', '[{"nameZh": "费内特苦酒", "nameEn": "Fernet Branca", "amount": 50, "unit": "ml", "role": "39% ABV 草本苦酒"}, {"nameZh": "可乐", "nameEn": "Cola", "amount": 150, "unit": "ml", "role": "加满"}]', '["双老式杯加冰块。", "倒入费内特苦酒。", "可乐加满。", "轻搅调和即成。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-fernandito", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "费尔南迪托", "nameEn": "Fernandito", "intro": "费内特苦酒兑可乐的阿根廷国民饮品，草本苦香与可乐甜感碰撞，清凉苦甜。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-fernandito-6695d3a1a3586.webp", "tags": ["高球", "苦酒", "直调", "草本", "可乐", "开胃"], "scene": ["开胃", "日常"], "recommendationScore": 88, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "高球", "flavor": "草本、可乐", "abv": "低度≤10%", "extra": ["可乐"], "scene": ["开胃", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gin-basil-smash', 'cocktail', 'COCKTAIL', '金酒罗勒碎', 'Gin Basil Smash', 'jinjiuluolesui', 'jjlls', '金酒、新鲜罗勒、柠檬汁与糖浆摇和的现代“捣碎”鸡尾酒，罗勒清香包裹柠檬酸爽，草本气息鲜明。', '2008 年德国汉堡调酒师约尔格·迈耶创制。IBA 配比：金酒 60 毫升、鲜榨柠檬汁 22.5 毫升、糖浆 22.5 毫升、罗勒叶 10 片，加冰大力摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-gin-basil-smash-6695d3a4c0967.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-gin-basil-smash-6695d3a4c0967.webp', 92, 225, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 7.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "金酒基底", "草本", "罗勒", "摇和", "夏季"]', '["夏季", "日常"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "罗勒、柠檬", "abv": "中度＞10%～20%", "extra": ["罗勒叶", "糖浆"], "scene": ["夏季", "日常"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 60, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "鲜榨柠檬汁", "nameEn": "Freshly Squeezed Lemon Juice", "amount": 22.5, "unit": "ml", "role": "鲜榨柠檬汁"}, {"nameZh": "糖浆", "nameEn": "Sugar Syrup", "amount": 22.5, "unit": "ml", "role": "糖浆"}, {"nameZh": "罗勒叶", "nameEn": "Italian Basil leaves", "amount": 10, "unit": "piece", "role": "新鲜罗勒叶"}]', '["摇酒壶加冰。", "倒入金酒、柠檬汁、糖浆与罗勒叶。", "大力摇和使罗勒释放香气。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-gin-basil-smash", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "金酒罗勒碎", "nameEn": "Gin Basil Smash", "intro": "金酒、新鲜罗勒、柠檬汁与糖浆摇和的现代“捣碎”鸡尾酒，罗勒清香包裹柠檬酸爽，草本气息鲜明。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-gin-basil-smash-6695d3a4c0967.webp", "tags": ["酸型鸡尾酒", "金酒基底", "草本", "罗勒", "摇和", "夏季"], "scene": ["夏季", "日常"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "罗勒、柠檬", "abv": "中度＞10%～20%", "extra": ["罗勒叶", "糖浆"], "scene": ["夏季", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-grand-margarita', 'cocktail', 'COCKTAIL', '大玛格丽特', 'Grand Margarita', 'damagelite', 'dmglt', '100% 龙舌兰、柑曼怡与青柠汁摇和而成的玛格丽特“尊贵版”，以柑曼怡的橙香与干邑底蕴提升口感，酸甜明亮。', '2020 年入选 IBA 名单，是玛格丽特家族的高阶变体。IBA 配比：100% 龙舌兰 45 毫升、柑曼怡 30 毫升、新鲜青柠汁 15 毫升，杯口抹海盐边，加冰摇和约 10 秒后滤入岩石杯，青柠片装饰。', '/assets/images/placeholder.jpg', '/assets/images/placeholder.jpg', 92, 226, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "龙舌兰基底", "柑橘", "橙香", "摇和", "经典"]', '["经典", "夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "橙香、青柠", "abv": "较高＞20%～30%", "extra": ["柑曼怡", "盐边"], "scene": ["经典", "夏季"]}', '[{"nameZh": "100% 龙舌兰", "nameEn": "Tequila 100% Agave", "amount": 45, "unit": "ml", "role": "40% ABV 龙舌兰"}, {"nameZh": "柑曼怡", "nameEn": "Grand Marnier", "amount": 30, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "海盐", "nameEn": "Sea Salt", "amount": 1, "unit": "piece", "role": "杯口盐边装饰"}, {"nameZh": "青柠片", "nameEn": "Lime Slice", "amount": 1, "unit": "piece", "role": "装饰"}]', '["岩石杯杯口以海盐抹出盐边并加冰预冷。", "摇酒壶加冰，倒入 100% 龙舌兰、柑曼怡与青柠汁。", "用力摇和约 10 秒。", "滤入加盐边的岩石杯。", "青柠片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-grand-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "大玛格丽特", "nameEn": "Grand Margarita", "intro": "100% 龙舌兰、柑曼怡与青柠汁摇和而成的玛格丽特“尊贵版”，以柑曼怡的橙香与干邑底蕴提升口感，酸甜明亮。", "imageUrl": "/assets/images/placeholder.jpg", "tags": ["酸型鸡尾酒", "龙舌兰基底", "柑橘", "橙香", "摇和", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 92, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "橙香、青柠", "abv": "较高＞20%～30%", "extra": ["柑曼怡", "盐边"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-iba-tiki', 'cocktail', 'COCKTAIL', 'IBA提基', 'IBA Tiki', 'IBAtiji', 'Itj', '深味与烟熏双朗姆搭配杏仁、榛子利口酒及百香果、菠萝、青柠汁的提基风格饮品，热带果香浓郁、层次丰富。', '2021 年入选 IBA 名单，向提基文化致敬。IBA 配比：深味朗姆与烟熏朗姆各 30 毫升、杏仁利口酒 15 毫升、榛子利口酒 5 毫升、玛拉斯奇诺数滴、百香果果泥 30 毫升、菠萝汁 90 毫升、青柠汁 30 毫升，捣压姜片后加冰用力摇和，滤入装满碎冰的提基杯，柑橘与脱水菠萝片装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-iba-tiki-6695d3a7e33fd.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-iba-tiki-6695d3a7e33fd.webp', 91, 227, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["提基", "朗姆基底", "热带水果", "百香果", "菠萝", "摇和", "夏季"]', '["夏季", "派对"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "百香果、菠萝", "abv": "中度＞10%～20%", "extra": ["百香果果泥", "杏仁利口酒"], "scene": ["夏季", "派对"]}', '[{"nameZh": "深味朗姆", "nameEn": "Ron Profundo Havana Club", "amount": 30, "unit": "ml", "role": "40% ABV 深味朗姆"}, {"nameZh": "烟熏朗姆", "nameEn": "Ron Smoky Havana Club", "amount": 30, "unit": "ml", "role": "烟熏朗姆"}, {"nameZh": "杏仁利口酒", "nameEn": "Licor Amaretto", "amount": 15, "unit": "ml", "role": "杏仁利口酒"}, {"nameZh": "榛子利口酒", "nameEn": "Licor Frangelico", "amount": 5, "unit": "ml", "role": "榛子利口酒"}, {"nameZh": "玛拉斯奇诺", "nameEn": "Maraschino Luxardo", "amount": 1, "unit": "dash", "role": "IBA 原文 5 滴"}, {"nameZh": "百香果果泥", "nameEn": "Passion Fruit Puree", "amount": 30, "unit": "ml", "role": "百香果果泥"}, {"nameZh": "菠萝汁", "nameEn": "Fresh Pineapple Juice", "amount": 90, "unit": "ml", "role": "新鲜菠萝汁"}, {"nameZh": "青柠汁", "nameEn": "Fresh Lime Juice", "amount": 30, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "姜片", "nameEn": "Gengibre Slice", "amount": 1, "unit": "piece", "role": "捣压用"}]', '["摇酒壶中捣压薄姜片。", "倒入双朗姆、两种利口酒与百香果果泥、菠萝汁、青柠汁。", "加冰用力摇和。", "滤入装满碎冰的冰镇提基杯。", "柑橘与脱水菠萝片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-iba-tiki", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "IBA提基", "nameEn": "IBA Tiki", "intro": "深味与烟熏双朗姆搭配杏仁、榛子利口酒及百香果、菠萝、青柠汁的提基风格饮品，热带果香浓郁、层次丰富。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-iba-tiki-6695d3a7e33fd.webp", "tags": ["提基", "朗姆基底", "热带水果", "百香果", "菠萝", "摇和", "夏季"], "scene": ["夏季", "派对"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "百香果、菠萝", "abv": "中度＞10%～20%", "extra": ["百香果果泥", "杏仁利口酒"], "scene": ["夏季", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-illegal', 'cocktail', 'COCKTAIL', '非法', 'Illegal', 'feifa', 'ff', '梅斯卡尔、牙买加高浓度白朗姆与法勒南、青柠汁摇和的现代经典，烟熏与草本交织、酸甜利落。', '1990 年代末意大利调酒师萨穆埃莱·安布罗西在卡斯特尔布兰多酒店创制，客人品尝后感叹“这真的该被禁止”而得名；后改用梅斯卡尔并加入玛拉斯奇诺与蛋清，2020 年入选 IBA 名单。IBA 配比：埃斯帕丁梅斯卡尔 30 毫升、牙买加高浓度白朗姆 15 毫升、法勒南 15 毫升、玛拉斯奇诺 1 吧匙、新鲜青柠汁 22.5 毫升、糖浆 15 毫升，可选蛋清，摇和滤入冰镇鸡尾酒杯，或加冰倒入传统陶土杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-illegal-6695d3a7de51f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-illegal-6695d3a7de51f.webp', 92, 228, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "梅斯卡尔", "烟熏", "草本", "摇和", "经典"]', '["经典", "日常"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "烟熏、草本", "abv": "中度＞10%～20%", "extra": ["法勒南", "玛拉斯奇诺"], "scene": ["经典", "日常"]}', '[{"nameZh": "埃斯帕丁梅斯卡尔", "nameEn": "Espadin Mezcal", "amount": 30, "unit": "ml", "role": "烟熏龙舌兰烈酒"}, {"nameZh": "牙买加高浓度白朗姆", "nameEn": "Jamaica Overproof White Rum", "amount": 15, "unit": "ml", "role": "高浓度白朗姆"}, {"nameZh": "法勒南", "nameEn": "Falernum", "amount": 15, "unit": "ml", "role": "香料糖浆"}, {"nameZh": "玛拉斯奇诺", "nameEn": "Maraschino Luxardo", "amount": 5, "unit": "ml", "role": "1 吧匙"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22.5, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 15, "unit": "ml", "role": "糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg White", "amount": 1, "unit": "piece", "role": "可选"}]', '["摇酒壶加冰，倒入除蛋清外全部配料。", "可选加入蛋清。", "用力摇和。", "滤入冰镇鸡尾酒杯，或加冰倒入传统陶土杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-illegal", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "非法", "nameEn": "Illegal", "intro": "梅斯卡尔、牙买加高浓度白朗姆与法勒南、青柠汁摇和的现代经典，烟熏与草本交织、酸甜利落。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-illegal-6695d3a7de51f.webp", "tags": ["酸型鸡尾酒", "梅斯卡尔", "烟熏", "草本", "摇和", "经典"], "scene": ["经典", "日常"], "recommendationScore": 92, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "烟熏、草本", "abv": "中度＞10%～20%", "extra": ["法勒南", "玛拉斯奇诺"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-missionarys-downfall', 'cocktail', 'COCKTAIL', '传教士的堕落', 'Missionary\'s Downfall', 'chuanjiaoshideduoluo', 'cjsddl', '白朗姆、蜜桃白兰地与菠萝、薄荷、蜂蜜搅打而成的冰沙风格经典，蜜桃果香与薄荷清凉交融，“传教士喝了也会堕落”的俏皮命名。', '1930 年代 Don the Beachcomber 酒吧唐恩·比奇创制。IBA 配比：白朗姆 30 毫升、蜜桃白兰地 15 毫升、新鲜青柠汁 15 毫升、蜂蜜调汁 30 毫升、薄荷叶 10 片、菠萝块 3-4 块，加半杯碎冰搅打，倒入大号带脚杯，薄荷枝与菠萝片装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-missionarys-downfall-6695d3ab4d4c5.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-missionarys-downfall-6695d3ab4d4c5.webp', 90, 229, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["提基", "朗姆基底", "蜜桃", "菠萝", "薄荷", "搅拌", "夏季"]', '["夏季", "派对"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "蜜桃、菠萝", "abv": "中度＞10%～20%", "extra": ["蜜桃白兰地", "蜂蜜调汁"], "scene": ["夏季", "派对"]}', '[{"nameZh": "白朗姆", "nameEn": "White Rum", "amount": 30, "unit": "ml", "role": "40% ABV 白朗姆"}, {"nameZh": "蜜桃白兰地", "nameEn": "Peach Brandy", "amount": 15, "unit": "ml", "role": "蜜桃利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "蜂蜜调汁", "nameEn": "Honey Mix", "amount": 30, "unit": "ml", "role": "蜂蜜调汁"}, {"nameZh": "薄荷叶", "nameEn": "Mint Leaves", "amount": 10, "unit": "piece", "role": "10 片"}, {"nameZh": "菠萝块", "nameEn": "Pineapple Chunks", "amount": 3, "unit": "piece", "role": "3-4 块"}, {"nameZh": "薄荷枝", "nameEn": "Mint Sprig", "amount": 1, "unit": "piece", "role": "装饰"}, {"nameZh": "菠萝片", "nameEn": "Pineapple Slice", "amount": 1, "unit": "piece", "role": "装饰"}]', '["搅拌机中加入全部配料与半杯碎冰。", "搅打至冰沙状。", "倒入大号带脚杯。", "薄荷枝与菠萝片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-missionarys-downfall", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "传教士的堕落", "nameEn": "Missionary\'s Downfall", "intro": "白朗姆、蜜桃白兰地与菠萝、薄荷、蜂蜜搅打而成的冰沙风格经典，蜜桃果香与薄荷清凉交融，“传教士喝了也会堕落”的俏皮命名。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-missionarys-downfall-6695d3ab4d4c5.webp", "tags": ["提基", "朗姆基底", "蜜桃", "菠萝", "薄荷", "搅拌", "夏季"], "scene": ["夏季", "派对"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "蜜桃、菠萝", "abv": "中度＞10%～20%", "extra": ["蜜桃白兰地", "蜂蜜调汁"], "scene": ["夏季", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-naked-and-famous', 'cocktail', 'COCKTAIL', '赤裸与名人', 'Naked and Famous', 'chiluoyumingren', 'clymr', '梅斯卡尔、黄查特酒、阿佩罗与青柠汁等量摇和的现代经典，烟熏、草本与苦橙三味交织，层次分明。', '2011 年纽约 Attaboy 酒吧调酒师华金·西莫创制，以 1997 年电影《赤裸与名人》命名。IBA 配比：梅斯卡尔、黄查特酒、阿佩罗与新鲜青柠汁各 22.5 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-naked-and-famous-6695d3ae8e1dc.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-naked-and-famous-6695d3ae8e1dc.webp', 93, 230, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 4.0}]', '["酸型鸡尾酒", "梅斯卡尔", "草本", "烟熏", "摇和", "经典"]', '["经典", "下午茶"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "烟熏、草本", "abv": "中度＞10%～20%", "extra": ["黄查特酒", "阿佩罗"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "梅斯卡尔", "nameEn": "Mezcal", "amount": 22.5, "unit": "ml", "role": "烟熏龙舌兰烈酒"}, {"nameZh": "黄查特酒", "nameEn": "Yellow Chartreuse", "amount": 22.5, "unit": "ml", "role": "40% ABV 草本利口酒"}, {"nameZh": "阿佩罗", "nameEn": "Aperol", "amount": 22.5, "unit": "ml", "role": "意大利开胃酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22.5, "unit": "ml", "role": "新鲜青柠汁"}]', '["摇酒壶加冰。", "倒入梅斯卡尔、黄查特酒、阿佩罗与青柠汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-naked-and-famous", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "赤裸与名人", "nameEn": "Naked and Famous", "intro": "梅斯卡尔、黄查特酒、阿佩罗与青柠汁等量摇和的现代经典，烟熏、草本与苦橙三味交织，层次分明。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-naked-and-famous-6695d3ae8e1dc.webp", "tags": ["酸型鸡尾酒", "梅斯卡尔", "草本", "烟熏", "摇和", "经典"], "scene": ["经典", "下午茶"], "recommendationScore": 93, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "烟熏、草本", "abv": "中度＞10%～20%", "extra": ["黄查特酒", "阿佩罗"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-new-york-sour', 'cocktail', 'COCKTAIL', '纽约酸酒', 'New York Sour', 'niuyuesuanjiu', 'nysj', '黑麦威士忌或波本、柠檬汁与糖浆摇和，再以红葡萄酒漂浮收尾的威士忌酸变体，红酒浮层带来莓果香与丝滑层次。', '19 世纪末纽约流行的威士忌酸酒变体，因红酒漂浮层风靡纽约而得名（也有芝加哥起源说）。IBA 配比：黑麦威士忌或波本 60 毫升、糖浆 22.5 毫升、新鲜柠檬汁 30 毫升，可选蛋清，摇和滤入装满冰块的老式杯，将西拉或马尔贝克红葡萄酒 15 毫升漂浮于上层，柠檬或橙皮与樱桃装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-new-york-sour-6695d3ae88cd2.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-new-york-sour-6695d3ae88cd2.webp', 94, 231, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "威士忌基底", "红酒", "柑橘", "摇和", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "柠檬、莓果", "abv": "中度＞10%～20%", "extra": ["红葡萄酒", "蛋清"], "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌或波本", "nameEn": "Rye Whiskey or Bourbon", "amount": 60, "unit": "ml", "role": "40% ABV 威士忌"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 22.5, "unit": "ml", "role": "糖浆"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蛋清", "nameEn": "Egg White", "amount": 1, "unit": "piece", "role": "可选"}, {"nameZh": "红葡萄酒", "nameEn": "Red Wine (Shiraz or Malbec)", "amount": 15, "unit": "ml", "role": "漂浮层"}, {"nameZh": "柠檬皮", "nameEn": "Lemon Zest", "amount": 1, "unit": "piece", "role": "装饰"}, {"nameZh": "樱桃", "nameEn": "Cherry", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰，倒入威士忌、糖浆、柠檬汁与可选蛋清。", "用力摇和。", "滤入装满冰块的老式杯。", "将红葡萄酒沿吧匙缓缓漂浮于上层。", "柠檬或橙皮与樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-new-york-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "纽约酸酒", "nameEn": "New York Sour", "intro": "黑麦威士忌或波本、柠檬汁与糖浆摇和，再以红葡萄酒漂浮收尾的威士忌酸变体，红酒浮层带来莓果香与丝滑层次。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-new-york-sour-6695d3ae88cd2.webp", "tags": ["酸型鸡尾酒", "威士忌基底", "红酒", "柑橘", "摇和", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 94, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "柠檬、莓果", "abv": "中度＞10%～20%", "extra": ["红葡萄酒", "蛋清"], "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-old-cuban', 'cocktail', 'COCKTAIL', '老古巴', 'Old Cuban', 'laoguba', 'lgb', '陈年朗姆、青柠汁与薄荷摇和，再以干型香槟加顶的现代经典，薄荷清凉与香槟气泡叠加，优雅馥郁。', '2002 年纽约 Pegu Club 酒吧调酒师奥德丽·桑德斯创制，向古巴黄金年代致敬。IBA 配比：陈年朗姆 45 毫升、新鲜青柠汁 22.5 毫升、糖浆 30 毫升、安高天娜苦精 2 滴，加薄荷叶摇和，滤入冰镇优雅鸡尾酒杯，以干型香槟或普罗塞克 60 毫升加顶，薄荷枝装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-old-cuban-6695d3b18c692.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-old-cuban-6695d3b18c692.webp', 94, 232, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "朗姆基底", "薄荷", "香槟", "气泡", "摇和", "经典"]', '["经典", "派对"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["干型香槟", "薄荷"], "scene": ["经典", "派对"]}', '[{"nameZh": "薄荷叶", "nameEn": "Mint Leaves", "amount": 1, "unit": "piece", "role": "新鲜薄荷叶"}, {"nameZh": "陈年朗姆", "nameEn": "Aged Rum", "amount": 45, "unit": "ml", "role": "40% ABV 陈年朗姆"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22.5, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 30, "unit": "ml", "role": "糖浆"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "安高天娜苦精"}, {"nameZh": "干型香槟或普罗塞克", "nameEn": "Brut Champagne or Prosecco", "amount": 60, "unit": "ml", "role": "加顶"}, {"nameZh": "薄荷枝", "nameEn": "Mint Sprig", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰，除香槟外全部配料倒入。", "充分摇和。", "滤入冰镇优雅鸡尾酒杯。", "以干型香槟或普罗塞克加顶。", "薄荷枝装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-old-cuban", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "老古巴", "nameEn": "Old Cuban", "intro": "陈年朗姆、青柠汁与薄荷摇和，再以干型香槟加顶的现代经典，薄荷清凉与香槟气泡叠加，优雅馥郁。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-old-cuban-6695d3b18c692.webp", "tags": ["酸型鸡尾酒", "朗姆基底", "薄荷", "香槟", "气泡", "摇和", "经典"], "scene": ["经典", "派对"], "recommendationScore": 94, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柑橘", "abv": "中度＞10%～20%", "extra": ["干型香槟", "薄荷"], "scene": ["经典", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-paper-plane', 'cocktail', 'COCKTAIL', '纸飞机', 'Paper Plane', 'zhifeiji', 'zfj', '波本、阿玛罗·诺尼诺、阿佩罗与柠檬汁等量摇和的现代经典，苦甜柑橘与波本焦糖香平衡，明快利落。', '2008 年纽约调酒师山姆·罗斯创制，以 M.I.A. 歌曲《Paper Planes》命名。IBA 配比：波本威士忌、阿玛罗·诺尼诺、阿佩罗与新鲜柠檬汁各 30 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-paper-plane-6695d3b4745eb.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-paper-plane-6695d3b4745eb.webp', 95, 233, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "威士忌基底", "苦甜", "柑橘", "摇和", "经典"]', '["经典", "日常"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "苦甜、柑橘", "abv": "中度＞10%～20%", "extra": ["阿玛罗·诺尼诺", "阿佩罗"], "scene": ["经典", "日常"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon Whiskey", "amount": 30, "unit": "ml", "role": "40% ABV 波本"}, {"nameZh": "阿玛罗·诺尼诺", "nameEn": "Amaro Nonino", "amount": 30, "unit": "ml", "role": "意大利草本苦酒"}, {"nameZh": "阿佩罗", "nameEn": "Aperol", "amount": 30, "unit": "ml", "role": "意大利开胃酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}]', '["摇酒壶加冰。", "倒入波本、阿玛罗·诺尼诺、阿佩罗与柠檬汁。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-paper-plane", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "纸飞机", "nameEn": "Paper Plane", "intro": "波本、阿玛罗·诺尼诺、阿佩罗与柠檬汁等量摇和的现代经典，苦甜柑橘与波本焦糖香平衡，明快利落。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-paper-plane-6695d3b4745eb.webp", "tags": ["酸型鸡尾酒", "威士忌基底", "苦甜", "柑橘", "摇和", "经典"], "scene": ["经典", "日常"], "recommendationScore": 95, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "苦甜、柑橘", "abv": "中度＞10%～20%", "extra": ["阿玛罗·诺尼诺", "阿佩罗"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-penicillin', 'cocktail', 'COCKTAIL', '盘尼西林', 'Penicillin', 'pannixilin', 'pnxl', '调和苏格兰威士忌、蜂蜜糖浆、柠檬汁与新鲜姜捣压摇和，再以艾雷岛单一麦芽威士忌漂浮，烟熏与姜蜜交织的现代经典。', '2005 年纽约 Milk & Honey 酒吧调酒师山姆·罗斯创制，以“治愈感冒的良药”命名。IBA 配比：调和苏格兰威士忌 60 毫升、新鲜柠檬汁 22.5 毫升、蜂蜜糖浆 22.5 毫升，与鲜姜切片捣压摇和，滤入装满冰块的老式杯，以拉加维林 16 年威士忌 7.5 毫升漂浮，糖姜片装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-penicillin-6695d3b47b79f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-penicillin-6695d3b47b79f.webp', 95, 234, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "威士忌基底", "姜", "蜂蜜", "烟熏", "摇和", "经典"]', '["经典", "冬季"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "姜、蜂蜜", "abv": "中度＞10%～20%", "extra": ["蜂蜜糖浆", "艾雷岛威士忌"], "scene": ["经典", "冬季"]}', '[{"nameZh": "调和苏格兰威士忌", "nameEn": "Blended Scotch Whisky", "amount": 60, "unit": "ml", "role": "40% ABV 调和威士忌"}, {"nameZh": "拉加维林16年", "nameEn": "Lagavulin 16y", "amount": 7.5, "unit": "ml", "role": "漂浮层"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜糖浆", "nameEn": "Honey Syrup", "amount": 22.5, "unit": "ml", "role": "蜂蜜糖浆"}, {"nameZh": "新鲜姜", "nameEn": "Fresh Ginger", "amount": 2, "unit": "piece", "role": "切片捣压用"}, {"nameZh": "糖姜片", "nameEn": "Candied Ginger", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶中捣压鲜姜片。", "倒入调和威士忌、柠檬汁与蜂蜜糖浆。", "加冰充分摇和。", "滤入装满冰块的老式杯。", "将艾雷岛单一麦芽威士忌漂浮于上层。", "糖姜片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-penicillin", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "盘尼西林", "nameEn": "Penicillin", "intro": "调和苏格兰威士忌、蜂蜜糖浆、柠檬汁与新鲜姜捣压摇和，再以艾雷岛单一麦芽威士忌漂浮，烟熏与姜蜜交织的现代经典。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-penicillin-6695d3b47b79f.webp", "tags": ["酸型鸡尾酒", "威士忌基底", "姜", "蜂蜜", "烟熏", "摇和", "经典"], "scene": ["经典", "冬季"], "recommendationScore": 95, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "姜、蜂蜜", "abv": "中度＞10%～20%", "extra": ["蜂蜜糖浆", "艾雷岛威士忌"], "scene": ["经典", "冬季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-pisco-punch', 'cocktail', 'COCKTAIL', '皮斯科潘趣', 'Pisco Punch', 'pisikepanqu', 'pskpq', '皮斯科、菠萝汁与干白葡萄酒、丁香组合的旧金山经典潘趣，菠萝甜香包裹皮斯科，果香馥郁、余韵悠长。', '19 世纪末旧金山银行交易所酒吧调酒师邓肯·尼科尔创制，配方曾秘传一度失传。IBA 配比：皮斯科 60 毫升、菠萝汁 22.5 毫升、糖浆 15 毫升、新鲜柠檬汁 15 毫升、干白葡萄酒 30 毫升、丁香 3 粒，丁香与糖浆轻捣后摇和，双重滤入大号高脚杯，葡萄酒浮于上层轻搅。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-pisco-punch-6695d3b74b9f5.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-pisco-punch-6695d3b74b9f5.webp', 92, 235, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["潘趣", "皮斯科基底", "菠萝", "丁香", "摇和", "经典"]', '["经典", "派对"]', '{"baseSpirit": "皮斯科基底", "cocktailType": "潘趣", "flavor": "菠萝、丁香", "abv": "中度＞10%～20%", "extra": ["干白葡萄酒", "丁香"], "scene": ["经典", "派对"]}', '[{"nameZh": "皮斯科", "nameEn": "Pisco", "amount": 60, "unit": "ml", "role": "40% ABV 皮斯科"}, {"nameZh": "新鲜菠萝汁", "nameEn": "Fresh Pineapple Juice", "amount": 22.5, "unit": "ml", "role": "新鲜菠萝汁"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 15, "unit": "ml", "role": "糖浆"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 15, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "干白葡萄酒", "nameEn": "Dry White Wine", "amount": 30, "unit": "ml", "role": "漂浮层"}, {"nameZh": "丁香", "nameEn": "Cloves", "amount": 3, "unit": "piece", "role": "捣压用"}]', '["大号高脚杯预冷。", "摇酒壶中丁香与糖浆轻捣。", "倒入皮斯科、菠萝汁与柠檬汁。", "加冰用力摇和后双重滤入大号高脚杯。", "干白葡萄酒浮于上层并轻搅即成。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-pisco-punch", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皮斯科潘趣", "nameEn": "Pisco Punch", "intro": "皮斯科、菠萝汁与干白葡萄酒、丁香组合的旧金山经典潘趣，菠萝甜香包裹皮斯科，果香馥郁、余韵悠长。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-pisco-punch-6695d3b74b9f5.webp", "tags": ["潘趣", "皮斯科基底", "菠萝", "丁香", "摇和", "经典"], "scene": ["经典", "派对"], "recommendationScore": 92, "attributes": {"baseSpirit": "皮斯科基底", "cocktailType": "潘趣", "flavor": "菠萝、丁香", "abv": "中度＞10%～20%", "extra": ["干白葡萄酒", "丁香"], "scene": ["经典", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-porn-star-martini', 'cocktail', 'COCKTAIL', '情色明星马天尼', 'Porn Star Martini', 'qingsemingxingmatianni', 'qsmxmtn', '香草伏特加、百香果利口酒与百香果果泥摇和的双层马天尼，百香果酸甜浓郁，佐以香槟杯同饮。', '2000 年代初伦敦酒吧界兴起，因大胆命名风靡全球。IBA 配比：香草伏特加 50 毫升、百香果利口酒 20 毫升、百香果果泥 50 毫升、香草糖 2 吧匙，摇和双重滤入大号冰镇鸡尾酒杯，附 50 毫升香槟一杯佐饮，半颗百香果与糖装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-porn-star-martini-6695d3b771b97.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-porn-star-martini-6695d3b771b97.webp', 90, 236, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["酸型鸡尾酒", "伏特加基底", "百香果", "热带水果", "摇和", "派对"]', '["派对", "夏季"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "百香果、香草", "abv": "中度＞10%～20%", "extra": ["百香果果泥", "香草伏特加"], "scene": ["派对", "夏季"]}', '[{"nameZh": "香草伏特加", "nameEn": "Vanilla Vodka", "amount": 50, "unit": "ml", "role": "40% ABV 香草伏特加"}, {"nameZh": "百香果利口酒", "nameEn": "Passion Fruit Liqueur", "amount": 20, "unit": "ml", "role": "百香果利口酒"}, {"nameZh": "百香果果泥", "nameEn": "Passion Fruit Puree", "amount": 50, "unit": "ml", "role": "百香果果泥"}, {"nameZh": "香草糖", "nameEn": "Vanilla Sugar", "amount": 5, "unit": "ml", "role": "2 吧匙"}, {"nameZh": "香槟", "nameEn": "Champagne", "amount": 50, "unit": "ml", "role": "佐饮"}, {"nameZh": "百香果", "nameEn": "Passion Fruit", "amount": 1, "unit": "piece", "role": "半颗装饰"}]', '["摇酒壶加冰。", "倒入香草伏特加、百香果利口酒、百香果果泥与香草糖。", "充分摇和。", "双重滤入大号冰镇鸡尾酒杯。", "附香槟一杯佐饮。", "半颗百香果与糖装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-porn-star-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "情色明星马天尼", "nameEn": "Porn Star Martini", "intro": "香草伏特加、百香果利口酒与百香果果泥摇和的双层马天尼，百香果酸甜浓郁，佐以香槟杯同饮。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-porn-star-martini-6695d3b771b97.webp", "tags": ["酸型鸡尾酒", "伏特加基底", "百香果", "热带水果", "摇和", "派对"], "scene": ["派对", "夏季"], "recommendationScore": 90, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "百香果、香草", "abv": "中度＞10%～20%", "extra": ["百香果果泥", "香草伏特加"], "scene": ["派对", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-russian-spring-punch', 'cocktail', 'COCKTAIL', '俄罗斯之春潘趣', 'Russian Spring Punch', 'eluosizhichunpanqu', 'elszcpq', '伏特加、柠檬汁、黑醋栗利口酒与糖浆摇和，再以起泡酒加顶的春日潘趣，黑醋栗莓果香与气泡轻盈。', '1980 年代伦敦调酒师迪克·布拉德塞尔为推广伏特加创制。IBA 配比：伏特加 25 毫升、新鲜柠檬汁 25 毫升、黑醋栗利口酒 15 毫升、糖浆 10 毫升，摇和滤入装满冰块的高球杯，以起泡酒加满，黑莓与柠檬片装饰（可选）。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-russian-spring-punch-6695d3ba314f1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-russian-spring-punch-6695d3ba314f1.webp', 91, 237, '[{"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["潘趣", "伏特加基底", "黑醋栗", "气泡", "莓果", "摇和", "开胃"]', '["开胃", "派对"]', '{"baseSpirit": "伏特加基底", "cocktailType": "潘趣", "flavor": "黑醋栗、柑橘", "abv": "中度＞10%～20%", "extra": ["黑醋栗利口酒", "起泡酒"], "scene": ["开胃", "派对"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 25, "unit": "ml", "role": "40% ABV 伏特加"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 25, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "黑醋栗利口酒", "nameEn": "Creme de Cassis", "amount": 15, "unit": "ml", "role": "黑醋栗利口酒"}, {"nameZh": "糖浆", "nameEn": "Sugar Syrup", "amount": 10, "unit": "ml", "role": "糖浆"}, {"nameZh": "起泡酒", "nameEn": "Sparkling Wine", "amount": 0, "unit": "ml", "role": "加满"}, {"nameZh": "黑莓", "nameEn": "Blackberries", "amount": 3, "unit": "piece", "role": "装饰"}, {"nameZh": "柠檬片", "nameEn": "Lemon Slice", "amount": 1, "unit": "piece", "role": "装饰（可选）"}]', '["摇酒壶加冰，倒入伏特加、柠檬汁、黑醋栗利口酒与糖浆。", "充分摇和。", "滤入装满冰块的高球杯。", "以起泡酒加满。", "黑莓与柠檬片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-russian-spring-punch", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "俄罗斯之春潘趣", "nameEn": "Russian Spring Punch", "intro": "伏特加、柠檬汁、黑醋栗利口酒与糖浆摇和，再以起泡酒加顶的春日潘趣，黑醋栗莓果香与气泡轻盈。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-russian-spring-punch-6695d3ba314f1.webp", "tags": ["潘趣", "伏特加基底", "黑醋栗", "气泡", "莓果", "摇和", "开胃"], "scene": ["开胃", "派对"], "recommendationScore": 91, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "潘趣", "flavor": "黑醋栗、柑橘", "abv": "中度＞10%～20%", "extra": ["黑醋栗利口酒", "起泡酒"], "scene": ["开胃", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-sherry-cobbler', 'cocktail', 'COCKTAIL', '雪利寇伯乐', 'Sherry Cobbler', 'xuelikoubole', 'xlkbl', '阿蒙提拉多与帕洛科尔塔多双雪利酒加糖、橙片与柠檬片摇和，倒入碎冰杯的 19 世纪经典，坚果香与果香交融。', '19 世纪美国最早的“碎冰+吸管”饮品之一，1862 年收录于杰里·托马斯著作。IBA 配比：阿蒙提拉多雪利酒 45 毫升、帕洛科尔塔多 45 毫升、超细糖 1 茶匙，与橙片、柠檬片摇和，滤入装满碎冰的朱利普杯，新鲜莓果与橙柠角装饰，配吸管。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-sherry-cobbler-6695d3ba8bdb7.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-sherry-cobbler-6695d3ba8bdb7.webp', 89, 238, '[{"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["长饮", "雪利酒", "碎冰", "果香", "经典", "直调"]', '["经典", "下午茶"]', '{"baseSpirit": "未标注基酒", "cocktailType": "长饮", "flavor": "坚果、果香", "abv": "中度＞10%～20%", "extra": ["双雪利酒"], "scene": ["经典", "下午茶"]}', '[{"nameZh": "阿蒙提拉多雪利酒", "nameEn": "Amontillado Sherry", "amount": 45, "unit": "ml", "role": "陈年干型雪利酒"}, {"nameZh": "帕洛科尔塔多", "nameEn": "Palo Cortado", "amount": 45, "unit": "ml", "role": "陈年雪利酒"}, {"nameZh": "超细糖", "nameEn": "Superfine Sugar", "amount": 5, "unit": "g", "role": "1 茶匙"}, {"nameZh": "橙轮", "nameEn": "Orange Wheel", "amount": 1, "unit": "piece", "role": "摇和与装饰"}, {"nameZh": "柠檬轮", "nameEn": "Lemon Wheel", "amount": 1, "unit": "piece", "role": "摇和与装饰"}, {"nameZh": "新鲜莓果", "nameEn": "Fresh Berries", "amount": 3, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰，倒入两种雪利酒与糖。", "加入橙片与柠檬片。", "快速摇和。", "滤入装满碎冰的朱利普杯。", "新鲜莓果与橙柠角装饰，配吸管。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-sherry-cobbler", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "雪利寇伯乐", "nameEn": "Sherry Cobbler", "intro": "阿蒙提拉多与帕洛科尔塔多双雪利酒加糖、橙片与柠檬片摇和，倒入碎冰杯的 19 世纪经典，坚果香与果香交融。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-sherry-cobbler-6695d3ba8bdb7.webp", "tags": ["长饮", "雪利酒", "碎冰", "果香", "经典", "直调"], "scene": ["经典", "下午茶"], "recommendationScore": 89, "attributes": {"baseSpirit": "未标注基酒", "cocktailType": "长饮", "flavor": "坚果、果香", "abv": "中度＞10%～20%", "extra": ["双雪利酒"], "scene": ["经典", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-south-side', 'cocktail', 'COCKTAIL', '南边', 'South Side', 'nanbian', 'nb', '伦敦干金酒、柠檬汁与糖浆加薄荷摇和的金酒酸变体，薄荷清新覆盖金酒草本香，明亮爽口。', '禁酒令时期芝加哥南区帮派时代流行的“南区”饮品，是薄荷版金酒酸酒。IBA 配比：伦敦干金酒 60 毫升、新鲜柠檬汁 30 毫升、糖浆 15 毫升、薄荷叶 5-6 片，可选蛋清，摇和双重滤入冰镇鸡尾酒杯，薄荷枝装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-south-side-6695d3bdcc9fe.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-south-side-6695d3bdcc9fe.webp', 92, 239, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "金酒基底", "薄荷", "柑橘", "摇和", "经典"]', '["经典", "夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柠檬", "abv": "中度＞10%～20%", "extra": ["薄荷叶", "蛋清"], "scene": ["经典", "夏季"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London Dry Gin", "amount": 60, "unit": "ml", "role": "40% ABV 金酒"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 15, "unit": "ml", "role": "糖浆"}, {"nameZh": "薄荷叶", "nameEn": "Mint Leaves", "amount": 5, "unit": "piece", "role": "5-6 片"}, {"nameZh": "蛋清", "nameEn": "Egg White", "amount": 1, "unit": "piece", "role": "可选"}, {"nameZh": "薄荷枝", "nameEn": "Mint Sprig", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰，倒入金酒、柠檬汁、糖浆与薄荷叶。", "可选加入蛋清后用力摇和。", "双重滤入冰镇鸡尾酒杯。", "薄荷枝装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-south-side", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "南边", "nameEn": "South Side", "intro": "伦敦干金酒、柠檬汁与糖浆加薄荷摇和的金酒酸变体，薄荷清新覆盖金酒草本香，明亮爽口。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-south-side-6695d3bdcc9fe.webp", "tags": ["酸型鸡尾酒", "金酒基底", "薄荷", "柑橘", "摇和", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "薄荷、柠檬", "abv": "中度＞10%～20%", "extra": ["薄荷叶", "蛋清"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-spicy-fifty', 'cocktail', 'COCKTAIL', '辛辣五十', 'Spicy Fifty', 'xinlawushi', 'xlws', '香草伏特加、接骨木花糖浆与蜂蜜糖浆摇和，红辣椒的微辣贯穿香草与青柠的甜酸，一款带辣度的现代鸡尾酒。', '2005 年伦敦萨伏依酒店调酒师彼得·多雷利为萨伏依五十周年创制。IBA 配比：香草伏特加 50 毫升、接骨木花糖浆 15 毫升、新鲜青柠汁 15 毫升、蜂蜜糖浆 10 毫升、红辣椒薄片 2 片，摇和双重滤入冰镇鸡尾酒杯，红辣椒装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-spicy-fifty-6695d3bdd14b1.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-spicy-fifty-6695d3bdd14b1.webp', 90, 240, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "伏特加基底", "辛辣", "接骨木花", "摇和", "时尚"]', '["派对", "日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "香草、微辣", "abv": "中度＞10%～20%", "extra": ["接骨木花糖浆", "红辣椒"], "scene": ["派对", "日常"]}', '[{"nameZh": "香草伏特加", "nameEn": "Vodka Vanilla", "amount": 50, "unit": "ml", "role": "40% ABV 香草伏特加"}, {"nameZh": "接骨木花糖浆", "nameEn": "Elderflower Cordial", "amount": 15, "unit": "ml", "role": "接骨木花糖浆"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "蜂蜜糖浆", "nameEn": "Monin Honey Syrup", "amount": 10, "unit": "ml", "role": "蜂蜜糖浆"}, {"nameZh": "红辣椒薄片", "nameEn": "Red Chili Pepper", "amount": 2, "unit": "piece", "role": "2 片"}, {"nameZh": "红辣椒", "nameEn": "Red Chili Pepper", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰。", "倒入香草伏特加、接骨木花糖浆、青柠汁与蜂蜜糖浆。", "加入红辣椒薄片。", "充分摇和。", "双重滤入冰镇鸡尾酒杯。", "红辣椒装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-spicy-fifty", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "辛辣五十", "nameEn": "Spicy Fifty", "intro": "香草伏特加、接骨木花糖浆与蜂蜜糖浆摇和，红辣椒的微辣贯穿香草与青柠的甜酸，一款带辣度的现代鸡尾酒。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-spicy-fifty-6695d3bdd14b1.webp", "tags": ["酸型鸡尾酒", "伏特加基底", "辛辣", "接骨木花", "摇和", "时尚"], "scene": ["派对", "日常"], "recommendationScore": 90, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "香草、微辣", "abv": "中度＞10%～20%", "extra": ["接骨木花糖浆", "红辣椒"], "scene": ["派对", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-spritz', 'cocktail', 'COCKTAIL', '阿佩罗橙光', 'Spritz', 'apeiluochengguang', 'aplcg', '普罗塞克与阿佩罗加苏打水直调的意大利经典开胃酒，苦橙与气泡交织，橙香明快，是夏日晚酌的代表。', '源自意大利威尼托地区传统“斯普里茨”，如今以阿佩罗版本最流行。IBA 配比：普罗塞克 90 毫升、阿佩罗 60 毫升、苏打水少许，加冰葡萄酒杯直调轻搅，橙片装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-spritz-6695d3c0f113f.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-spritz-6695d3c0f113f.webp', 93, 241, '[{"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "SWEETNESS", "label": "甜度", "score": 4.0}]', '["开胃鸡尾酒", "起泡酒基底", "气泡", "苦甜", "橙香", "直调", "夏季"]', '["开胃", "夏季"]', '{"baseSpirit": "起泡酒基底", "cocktailType": "开胃鸡尾酒", "flavor": "苦橙、气泡", "abv": "中度＞10%～20%", "extra": ["普罗塞克", "阿佩罗"], "scene": ["开胃", "夏季"]}', '[{"nameZh": "普罗塞克", "nameEn": "Prosecco", "amount": 90, "unit": "ml", "role": "起泡葡萄酒"}, {"nameZh": "阿佩罗", "nameEn": "Aperol", "amount": 60, "unit": "ml", "role": "意大利开胃酒"}, {"nameZh": "苏打水", "nameEn": "Soda Water", "amount": 0, "unit": "ml", "role": "少许"}, {"nameZh": "橙片", "nameEn": "Orange Slice", "amount": 1, "unit": "piece", "role": "装饰"}]', '["葡萄酒杯加冰块。", "倒入阿佩罗。", "加入普罗塞克。", "加少许苏打水。", "轻搅调和。", "橙片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿佩罗橙光", "nameEn": "Spritz", "intro": "普罗塞克与阿佩罗加苏打水直调的意大利经典开胃酒，苦橙与气泡交织，橙香明快，是夏日晚酌的代表。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-spritz-6695d3c0f113f.webp", "tags": ["开胃鸡尾酒", "起泡酒基底", "气泡", "苦甜", "橙香", "直调", "夏季"], "scene": ["开胃", "夏季"], "recommendationScore": 93, "attributes": {"baseSpirit": "起泡酒基底", "cocktailType": "开胃鸡尾酒", "flavor": "苦橙、气泡", "abv": "中度＞10%～20%", "extra": ["普罗塞克", "阿佩罗"], "scene": ["开胃", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-three-dots-and-a-dash', 'cocktail', 'COCKTAIL', '三点一划', 'Three Dots and a Dash', 'sandianyihua', 'sdyh', '马提尼克甘蔗朗姆与陈年朗姆搭配法勒南、多香果利口酒及橙汁、蜂蜜糖浆搅打的提基经典，热带果香与香料层次丰富。', '1940 年代 Don the Beachcomber 酒吧唐恩·比奇创制，名字取自摩斯电码“V”（胜利）信号（三点一划）。IBA 配比：马提尼克甘蔗朗姆 45 毫升、陈年朗姆 15 毫升、法勒南 7.5 毫升、多香果利口酒 7.5 毫升、新鲜青柠汁 15 毫升、新鲜橙汁 15 毫升、蜂蜜糖浆 15 毫升、安高天娜苦精 2 滴，与碎冰快速搅打，倒入带脚杯，三颗樱桃与方块菠萝装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-three-dots-and-a-dash-6695d3c3e2d24.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-three-dots-and-a-dash-6695d3c3e2d24.webp', 92, 242, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "SWEETNESS", "label": "甜度", "score": 7.0}]', '["提基", "朗姆基底", "热带水果", "香料", "搅拌", "夏季"]', '["夏季", "派对"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "菠萝、香料", "abv": "较高＞20%～30%", "extra": ["法勒南", "多香果利口酒"], "scene": ["夏季", "派对"]}', '[{"nameZh": "马提尼克甘蔗朗姆", "nameEn": "Rhum Martinique Agricole", "amount": 45, "unit": "ml", "role": "50% ABV 甘蔗朗姆"}, {"nameZh": "陈年朗姆", "nameEn": "Blended Aged Rum", "amount": 15, "unit": "ml", "role": "40% ABV 陈年朗姆"}, {"nameZh": "法勒南", "nameEn": "Falernum", "amount": 7.5, "unit": "ml", "role": "香料糖浆"}, {"nameZh": "多香果利口酒", "nameEn": "Allspice Pimento Dram", "amount": 7.5, "unit": "ml", "role": "多香果利口酒"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 15, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh Orange Juice", "amount": 15, "unit": "ml", "role": "新鲜橙汁"}, {"nameZh": "蜂蜜糖浆", "nameEn": "Honey Syrup", "amount": 15, "unit": "ml", "role": "蜂蜜糖浆"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "安高天娜苦精"}, {"nameZh": "樱桃", "nameEn": "Cherry", "amount": 3, "unit": "piece", "role": "装饰"}, {"nameZh": "菠萝块", "nameEn": "Pineapple Chunk", "amount": 1, "unit": "piece", "role": "方块装饰"}]', '["搅拌机中加入全部配料与碎冰。", "快速搅打数秒。", "倒入带脚杯。", "补满碎冰。", "三颗樱桃与方块菠萝装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-three-dots-and-a-dash", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "三点一划", "nameEn": "Three Dots and a Dash", "intro": "马提尼克甘蔗朗姆与陈年朗姆搭配法勒南、多香果利口酒及橙汁、蜂蜜糖浆搅打的提基经典，热带果香与香料层次丰富。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-three-dots-and-a-dash-6695d3c3e2d24.webp", "tags": ["提基", "朗姆基底", "热带水果", "香料", "搅拌", "夏季"], "scene": ["夏季", "派对"], "recommendationScore": 92, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "菠萝、香料", "abv": "较高＞20%～30%", "extra": ["法勒南", "多香果利口酒"], "scene": ["夏季", "派对"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tipperary', 'cocktail', 'COCKTAIL', '蒂珀雷里', 'Tipperary', 'dipoleili', 'dpll', '爱尔兰威士忌、甜味美思与绿查特酒搅拌的曼哈顿变体，草本利口酒带来独特植物香，深邃醇厚。', '一战时期伦敦流行，以爱尔兰蒂珀雷里郡及一战歌曲《It’s a Long Way to Tipperary》命名。IBA 配比：爱尔兰威士忌 50 毫升、甜红味美思 25 毫升、绿查特酒 15 毫升、安高天娜苦精 2 滴，加冰搅拌滤入冰镇马天尼杯，橙片装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-tipperary-6695d3c453fd3.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-tipperary-6695d3c453fd3.webp', 91, 243, '[{"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["曼哈顿", "威士忌基底", "搅拌", "草本", "苦甜", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "草本、甜味美思", "abv": "较高＞20%～30%", "extra": ["甜味美思", "绿查特酒"], "scene": ["经典", "餐后"]}', '[{"nameZh": "爱尔兰威士忌", "nameEn": "Irish Whiskey", "amount": 50, "unit": "ml", "role": "40% ABV 爱尔兰威士忌"}, {"nameZh": "甜红味美思", "nameEn": "Sweet Red Vermouth", "amount": 25, "unit": "ml", "role": "甜味美思"}, {"nameZh": "绿查特酒", "nameEn": "Green Chartreuse", "amount": 15, "unit": "ml", "role": "55% ABV 草本利口酒"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "安高天娜苦精"}, {"nameZh": "橙片", "nameEn": "Orange Slice", "amount": 1, "unit": "piece", "role": "装饰"}]', '["搅拌杯加冰。", "倒入爱尔兰威士忌、甜味美思与绿查特酒，滴入苦精。", "充分搅拌至冷却。", "滤入冰镇马天尼杯。", "橙片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-tipperary", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蒂珀雷里", "nameEn": "Tipperary", "intro": "爱尔兰威士忌、甜味美思与绿查特酒搅拌的曼哈顿变体，草本利口酒带来独特植物香，深邃醇厚。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-tipperary-6695d3c453fd3.webp", "tags": ["曼哈顿", "威士忌基底", "搅拌", "草本", "苦甜", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 91, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "曼哈顿", "flavor": "草本、甜味美思", "abv": "较高＞20%～30%", "extra": ["甜味美思", "绿查特酒"], "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tommys-margarita', 'cocktail', 'COCKTAIL', '汤米玛格丽特', 'Tommy\'s Margarita', 'tangmimagelite', 'tmmglt', '100% 龙舌兰、青柠汁与龙舌兰蜜糖浆三料摇和的极简玛格丽特，龙舌兰植物香与龙舌兰蜜的圆润甜感浑然一体。', '1990 年代旧金山 Tommy’s 墨西哥餐厅酒吧老板胡里奥·贝尔梅霍创制并推广。IBA 配比：100% 龙舌兰 60 毫升、新鲜青柠汁 30 毫升、龙舌兰蜜糖浆 30 毫升，摇和滤入装满冰块的老式杯，青柠片装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-tommys-margarita-6695d3c7171ef.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-tommys-margarita-6695d3c7171ef.webp', 94, 244, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "龙舌兰基底", "柑橘", "摇和", "经典", "极简"]', '["经典", "夏季"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "龙舌兰、青柠", "abv": "中度＞10%～20%", "extra": ["龙舌兰蜜糖浆"], "scene": ["经典", "夏季"]}', '[{"nameZh": "100% 龙舌兰", "nameEn": "Tequila 100% Agave", "amount": 60, "unit": "ml", "role": "40% ABV 龙舌兰"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 30, "unit": "ml", "role": "新鲜青柠汁"}, {"nameZh": "龙舌兰蜜糖浆", "nameEn": "Agave Nectar", "amount": 30, "unit": "ml", "role": "龙舌兰蜜糖浆"}, {"nameZh": "青柠片", "nameEn": "Lime Slice", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰。", "倒入 100% 龙舌兰、青柠汁与龙舌兰蜜糖浆。", "充分摇和。", "滤入装满冰块的老式杯。", "青柠片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-tommys-margarita", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "汤米玛格丽特", "nameEn": "Tommy\'s Margarita", "intro": "100% 龙舌兰、青柠汁与龙舌兰蜜糖浆三料摇和的极简玛格丽特，龙舌兰植物香与龙舌兰蜜的圆润甜感浑然一体。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-tommys-margarita-6695d3c7171ef.webp", "tags": ["酸型鸡尾酒", "龙舌兰基底", "柑橘", "摇和", "经典", "极简"], "scene": ["经典", "夏季"], "recommendationScore": 94, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸型鸡尾酒", "flavor": "龙舌兰、青柠", "abv": "中度＞10%～20%", "extra": ["龙舌兰蜜糖浆"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-trinidad-sour', 'cocktail', 'COCKTAIL', '特立尼达酸酒', 'Trinidad Sour', 'telinidasuanjiu', 'tlndsj', '以安高天娜苦精为主料、配奥卡特糖浆与黑麦威士忌的“反向用量”酸酒，苦精带来草本香料与酸甜交织的复杂风味。', '2008 年纽约调酒师朱塞佩·冈萨雷斯创制，是苦精“反向用量”的创意典范。IBA 配比：安高天娜苦精 45 毫升、奥卡特糖浆 30 毫升、新鲜柠檬汁 22.5 毫升、黑麦威士忌 15 毫升，摇和滤入冰镇鸡尾酒杯。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-trinidad-sour-6695d3c794a43.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-trinidad-sour-6695d3c794a43.webp', 90, 245, '[{"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 5.0}]', '["酸型鸡尾酒", "苦精", "黑麦", "草本", "香料", "摇和"]', '["经典", "日常"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本、香料", "abv": "中度＞10%～20%", "extra": ["安高天娜苦精", "奥卡特糖浆"], "scene": ["经典", "日常"]}', '[{"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 45, "unit": "ml", "role": "44.7% ABV 苦精"}, {"nameZh": "奥卡特糖浆", "nameEn": "Orgeat Syrup", "amount": 30, "unit": "ml", "role": "杏仁糖浆"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "黑麦威士忌", "nameEn": "Rye Whiskey", "amount": 15, "unit": "ml", "role": "40% ABV 黑麦威士忌"}]', '["摇酒壶加冰。", "倒入安高天娜苦精、奥卡特糖浆、柠檬汁与黑麦威士忌。", "充分摇和。", "滤入冰镇鸡尾酒杯。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-trinidad-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "特立尼达酸酒", "nameEn": "Trinidad Sour", "intro": "以安高天娜苦精为主料、配奥卡特糖浆与黑麦威士忌的“反向用量”酸酒，苦精带来草本香料与酸甜交织的复杂风味。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-trinidad-sour-6695d3c794a43.webp", "tags": ["酸型鸡尾酒", "苦精", "黑麦", "草本", "香料", "摇和"], "scene": ["经典", "日常"], "recommendationScore": 90, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸型鸡尾酒", "flavor": "草本、香料", "abv": "中度＞10%～20%", "extra": ["安高天娜苦精", "奥卡特糖浆"], "scene": ["经典", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-ve-n-to', 'cocktail', 'COCKTAIL', '韦恩托', 'Ve.n.to', 'weientuo', 'wet', '白格拉帕、柠檬汁、蜂蜜调汁与洋甘菊糖浆摇和的现代经典，洋甘菊花香包裹格拉帕的果香，清爽甘甜。', '2021 年入选 IBA 名单。IBA 配比：白格拉帕 45 毫升、新鲜柠檬汁 22.5 毫升、蜂蜜调汁 15 毫升、洋甘菊糖浆 15 毫升，可选蛋清，摇和滤入装满冰块的小号平底杯，柠檬皮与白葡萄装饰。', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-vento-6695d3ca45bc2.webp', 'https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-vento-6695d3ca45bc2.webp', 89, 246, '[{"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 0.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "SWEETNESS", "label": "甜度", "score": 6.0}]', '["酸型鸡尾酒", "白兰地基底", "洋甘菊", "花香", "摇和", "时尚"]', '["日常", "下午茶"]', '{"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "花香、柠檬", "abv": "中度＞10%～20%", "extra": ["洋甘菊糖浆", "蜂蜜调汁"], "scene": ["日常", "下午茶"]}', '[{"nameZh": "白格拉帕", "nameEn": "White Smooth Grappa", "amount": 45, "unit": "ml", "role": "40% ABV 葡萄渣白兰地"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "新鲜柠檬汁"}, {"nameZh": "蜂蜜调汁", "nameEn": "Honey Mix", "amount": 15, "unit": "ml", "role": "可用洋甘菊浸液调制"}, {"nameZh": "洋甘菊糖浆", "nameEn": "Chamomile Cordial", "amount": 15, "unit": "ml", "role": "洋甘菊糖浆"}, {"nameZh": "蛋清", "nameEn": "Egg White", "amount": 1, "unit": "piece", "role": "可选"}, {"nameZh": "柠檬皮", "nameEn": "Lemon Zest", "amount": 1, "unit": "piece", "role": "装饰"}, {"nameZh": "白葡萄", "nameEn": "White Grapes", "amount": 2, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰。", "倒入格拉帕、柠檬汁、蜂蜜调汁与洋甘菊糖浆。", "可选加入蛋清。", "用力摇和。", "滤入装满冰块的小号平底杯。", "柠檬皮与白葡萄装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-ve-n-to", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "韦恩托", "nameEn": "Ve.n.to", "intro": "白格拉帕、柠檬汁、蜂蜜调汁与洋甘菊糖浆摇和的现代经典，洋甘菊花香包裹格拉帕的果香，清爽甘甜。", "imageUrl": "https://iba-world.com/wp-content/uploads/2024/07/iba-cocktail-new-era-vento-6695d3ca45bc2.webp", "tags": ["酸型鸡尾酒", "白兰地基底", "洋甘菊", "花香", "摇和", "时尚"], "scene": ["日常", "下午茶"], "recommendationScore": 89, "attributes": {"baseSpirit": "白兰地基底", "cocktailType": "酸型鸡尾酒", "flavor": "花香、柠檬", "abv": "中度＞10%～20%", "extra": ["洋甘菊糖浆", "蜂蜜调汁"], "scene": ["日常", "下午茶"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gimlet', 'cocktail', 'COCKTAIL', '吉姆雷特', 'Gimlet', 'jimuleite', 'jmlt', '以金酒与青柠利口酒调制而成的经典酸型鸡尾酒，青柠的酸爽与金酒的草本感干净利落，被视为海军风鸡尾酒的代表。', '现代通行配比为金酒 60 毫升对青柠利口酒（lime cordial）15 毫升（4:1），摇和滤入冰镇鸡尾酒杯；《Savoy 鸡尾酒书》（1930）则记载 1:1 的偏甜旧式配比。甜度可按青柠利口酒用量调节。 背景：1928 年首见文字记载，一说得名自手钻（gimlet）的“锐利”意象，另一说与皇家海军军医 Thomas Gimlette 爵士以青柠汁防坏血病的故事相关；雷蒙德·钱德勒《漫长的告别》中“真正的吉姆雷特是一半金酒一半玫瑰牌青柠汁”成为经典台词。', 'https://images.unsplash.com/photo-1601491641387-035a4ae3c7cb?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1601491641387-035a4ae3c7cb?w=1200&q=80&auto=format&fit=crop', 88, 247, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["酸型鸡尾酒", "金酒基底", "青柠", "摇和", "经典"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、草本、青柠", "abv": "较高＞20%～30%", "extra": ["青柠利口酒"], "scene": ["经典", "开胃"]}', '[{"nameZh": "金酒", "nameEn": "London Dry Gin", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "青柠利口酒", "nameEn": "Lime Cordial", "amount": 15, "unit": "ml", "role": "甜酸平衡（现代 4:1）"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "摇和用"}, {"nameZh": "青柠片", "nameEn": "Lime slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将鸡尾酒杯提前冰镇。", "摇酒壶加冰，倒入金酒与青柠利口酒。", "充分摇和约 12 秒至冰镇。", "滤入冰镇鸡尾酒杯。", "以青柠片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-gimlet", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "吉姆雷特", "nameEn": "Gimlet", "intro": "以金酒与青柠利口酒调制而成的经典酸型鸡尾酒，青柠的酸爽与金酒的草本感干净利落，被视为海军风鸡尾酒的代表。", "imageUrl": "https://images.unsplash.com/photo-1601491641387-035a4ae3c7cb?w=1200&q=80&auto=format&fit=crop", "tags": ["酸型鸡尾酒", "金酒基底", "青柠", "摇和", "经典"], "scene": ["经典", "开胃"], "recommendationScore": 88, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、草本、青柠", "abv": "较高＞20%～30%", "extra": ["青柠利口酒"], "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-aperol-spritz', 'cocktail', 'COCKTAIL', '阿佩罗橙光', 'Aperol Spritz', 'apeiluochengguang', 'aplcg', '以普罗赛柯、阿佩罗利口酒与苏打水直调而成的意大利气泡长饮，苦甜橙香、气泡充足，是全球最受欢迎的夏季开胃酒之一。', '本条目按意大利标准配比：普罗赛柯 90 毫升、阿佩罗 60 毫升、苏打水少量，葡萄酒杯加冰直调并以橙片装饰。阿佩罗苦中带甜、酒精度仅 11%，是低度开胃酒的典型。 背景：Spritz 源自 19 世纪威尼斯驻军兑水喝当地葡萄酒的习惯，1920 年出现威尼托本土苦酒版本；如今阿佩罗版风靡全球，是意大利“开胃时刻”文化的代表。', 'https://images.unsplash.com/photo-1570598912132-0ba1dc952b7d?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1570598912132-0ba1dc952b7d?w=1200&q=80&auto=format&fit=crop', 96, 248, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 1.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["长饮", "气泡酒基底", "苦甜", "直调", "夏季", "新手友好"]', '["夏季", "开胃", "新手友好"]', '{"baseSpirit": "气泡酒基底", "cocktailType": "汽酒长饮", "flavor": "苦甜、橙香、气泡", "abv": "低度≤10%", "extra": ["普罗赛柯", "苏打水"], "scene": ["夏季", "开胃", "新手友好"]}', '[{"nameZh": "普罗赛柯", "nameEn": "Prosecco", "amount": 90, "unit": "ml", "role": "气泡基酒"}, {"nameZh": "阿佩罗利口酒", "nameEn": "Aperol", "amount": 60, "unit": "ml", "role": "苦甜风味核心"}, {"nameZh": "苏打水", "nameEn": "Soda Water", "amount": 20, "unit": "ml", "role": "补充气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "直调用"}, {"nameZh": "橙片", "nameEn": "Orange slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["葡萄酒杯加满冰块。", "倒入普罗赛柯与阿佩罗利口酒。", "补入少量苏打水。", "轻轻搅拌混合。", "以橙片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-aperol-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿佩罗橙光", "nameEn": "Aperol Spritz", "intro": "以普罗赛柯、阿佩罗利口酒与苏打水直调而成的意大利气泡长饮，苦甜橙香、气泡充足，是全球最受欢迎的夏季开胃酒之一。", "imageUrl": "https://images.unsplash.com/photo-1570598912132-0ba1dc952b7d?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "气泡酒基底", "苦甜", "直调", "夏季", "新手友好"], "scene": ["夏季", "开胃", "新手友好"], "recommendationScore": 96, "attributes": {"baseSpirit": "气泡酒基底", "cocktailType": "汽酒长饮", "flavor": "苦甜、橙香、气泡", "abv": "低度≤10%", "extra": ["普罗赛柯", "苏打水"], "scene": ["夏季", "开胃", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-vodka-martini', 'cocktail', 'COCKTAIL', '伏特加马天尼', 'Vodka Martini', 'futejiamatianni', 'ftjmtn', '以伏特加与少量干味美思调制而成的极干型鸡尾酒，酒体清冽、风味纯粹，是马天尼家族最著名的变体之一。', '配方按马天尼家族通行比例标准化：伏特加 60 毫升兑干味美思 10 毫升，搅拌（亦可摇和）后滤入冰镇鸡尾酒杯，以橄榄或柠檬皮装饰。基酒换成中性的伏特加后，草本感较金酒版更弱、风味更干净。 背景：007 詹姆斯·邦德著名的“伏特加马天尼，摇匀不要搅拌”让这款酒家喻户晓，也因此引发关于摇匀稀释与口感之争的长期讨论。', 'https://images.unsplash.com/photo-1671713682257-359a1baf806e?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1671713682257-359a1baf806e?w=1200&q=80&auto=format&fit=crop', 92, 249, '[{"key": "SWEETNESS", "label": "甜度", "score": 1.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 9.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["烈酒主导", "伏特加基底", "偏干", "搅拌", "经典"]', '["经典"]', '{"baseSpirit": "伏特加基底", "cocktailType": "烈酒主导", "flavor": "偏干、草本、清冽", "abv": "高度＞30%", "extra": ["无明显非酒精成分"], "scene": ["经典"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "干味美思", "nameEn": "Dry Vermouth", "amount": 10, "unit": "ml", "role": "少量调味"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "搅拌用"}, {"nameZh": "青橄榄或柠檬皮", "nameEn": "Olive or lemon twist", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["将马天尼杯提前冰镇。", "搅拌杯加冰，倒入伏特加与干味美思。", "搅拌约 20 秒至充分降温。", "滤入冰镇马天尼杯。", "以青橄榄或挤入柠檬皮油提香装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-vodka-martini", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "伏特加马天尼", "nameEn": "Vodka Martini", "intro": "以伏特加与少量干味美思调制而成的极干型鸡尾酒，酒体清冽、风味纯粹，是马天尼家族最著名的变体之一。", "imageUrl": "https://images.unsplash.com/photo-1671713682257-359a1baf806e?w=1200&q=80&auto=format&fit=crop", "tags": ["烈酒主导", "伏特加基底", "偏干", "搅拌", "经典"], "scene": ["经典"], "recommendationScore": 92, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "烈酒主导", "flavor": "偏干、草本、清冽", "abv": "高度＞30%", "extra": ["无明显非酒精成分"], "scene": ["经典"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-fitzgerald', 'cocktail', 'COCKTAIL', '菲茨杰拉德', 'Fitzgerald', 'feicijielade', 'fcjld', '以金酒、柠檬汁、糖浆与苦精摇和而成的现代经典酸酒，酸甜中带一丝苦精的复杂度，风格与黛绮丽同构。', '业界公认标准（纽约 Death & Co 通行配比）：金酒 60 毫升、新鲜柠檬汁 22.5 毫升、单糖浆 22.5 毫升、安格斯图拉苦精 2 滴，摇和滤入冰镇鸡尾酒杯。苦精的加入使其区别于普通金酒酸酒，层次更丰富。 背景：2007 年由纽约 Death & Co 酒吧创制的现代经典，命名致敬美国作家 F·斯科特·菲茨杰拉德，属于新酸酒运动的代表作品。', 'https://images.unsplash.com/photo-1657313666513-70770d329ef4?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1657313666513-70770d329ef4?w=1200&q=80&auto=format&fit=crop', 84, 250, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["酸型鸡尾酒", "金酒基底", "苦精", "摇和", "现代经典"]', '["经典", "开胃"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、微苦、柑橘", "abv": "较高＞20%～30%", "extra": ["安格斯图拉苦精"], "scene": ["经典", "开胃"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "酸度核心"}, {"nameZh": "单糖浆", "nameEn": "Simple Syrup", "amount": 22.5, "unit": "ml", "role": "平衡酸度"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "增加复杂度"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "摇和用"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["摇酒壶加冰，倒入金酒、柠檬汁、单糖浆与苦精。", "充分摇和约 12 秒至冰镇。", "滤入冰镇鸡尾酒杯。", "挤入柠檬皮油提香并装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-fitzgerald", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "菲茨杰拉德", "nameEn": "Fitzgerald", "intro": "以金酒、柠檬汁、糖浆与苦精摇和而成的现代经典酸酒，酸甜中带一丝苦精的复杂度，风格与黛绮丽同构。", "imageUrl": "https://images.unsplash.com/photo-1657313666513-70770d329ef4?w=1200&q=80&auto=format&fit=crop", "tags": ["酸型鸡尾酒", "金酒基底", "苦精", "摇和", "现代经典"], "scene": ["经典", "开胃"], "recommendationScore": 84, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸甜、微苦、柑橘", "abv": "较高＞20%～30%", "extra": ["安格斯图拉苦精"], "scene": ["经典", "开胃"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-amaretto-sour', 'cocktail', 'COCKTAIL', '杏仁酸', 'Amaretto Sour', 'xingrensuan', 'xrs', '以阿玛雷托杏仁利口酒与柠檬汁摇和而成的甜酸鸡尾酒，杏仁香气浓郁，加蛋清摇出的泡沫更显绵密。', '现代通行配比（源自 Jeffrey Morgenthaler 改良版本）为阿玛雷托利口酒 60 毫升、新鲜柠檬汁 30 毫升与蛋清 1 个，先干摇再加冰摇和，滤入加冰的古典杯。早期配方为利口酒兑酸味剂（sour mix），口感较单薄；改良版以真实柠檬汁与蛋清泡沫提升质感。 背景：1974 年由阿玛雷托进口商以两分利口酒对一分柠檬汁的简单组合推向市场，1980 年代风行；2012 年波特兰调酒师莫根塔勒的改良版使其重获专业认可。', 'https://images.unsplash.com/photo-1677425039174-5bfa15efb2d9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1677425039174-5bfa15efb2d9?w=1200&q=80&auto=format&fit=crop', 87, 251, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["酸型鸡尾酒", "利口酒基底", "杏仁风味", "蛋清泡沫", "摇和"]', '["经典", "餐后"]', '{"baseSpirit": "利口酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "杏仁、酸甜", "abv": "中度＞10%～20%", "extra": ["蛋清（可选）"], "scene": ["经典", "餐后"]}', '[{"nameZh": "阿玛雷托利口酒", "nameEn": "Amaretto Liqueur", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "酸度核心"}, {"nameZh": "蛋清", "nameEn": "Egg white", "amount": 1, "unit": "piece", "role": "泡沫（可选）"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "摇和用"}, {"nameZh": "鸡尾酒樱桃", "nameEn": "Cocktail cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["摇酒壶中倒入阿玛雷托、柠檬汁与蛋清。", "不加冰干摇约 15 秒使蛋清起泡。", "加冰再摇和约 10 秒至充分冰镇。", "滤入加冰的古典杯。", "以鸡尾酒樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-amaretto-sour", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "杏仁酸", "nameEn": "Amaretto Sour", "intro": "以阿玛雷托杏仁利口酒与柠檬汁摇和而成的甜酸鸡尾酒，杏仁香气浓郁，加蛋清摇出的泡沫更显绵密。", "imageUrl": "https://images.unsplash.com/photo-1677425039174-5bfa15efb2d9?w=1200&q=80&auto=format&fit=crop", "tags": ["酸型鸡尾酒", "利口酒基底", "杏仁风味", "蛋清泡沫", "摇和"], "scene": ["经典", "餐后"], "recommendationScore": 87, "attributes": {"baseSpirit": "利口酒基底", "cocktailType": "酸型鸡尾酒", "flavor": "杏仁、酸甜", "abv": "中度＞10%～20%", "extra": ["蛋清（可选）"], "scene": ["经典", "餐后"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-punch', 'cocktail', 'COCKTAIL', '朗姆潘趣', 'Rum Punch', 'langmupanqu', 'lmpq', '以朗姆、青柠、糖与水按加勒比经典口诀调制的潘趣酒，酸甜平衡、香料点睛，是巴巴多斯国民级热带饮品。', '本条目采用巴巴多斯（Bajan）国民配方口诀“一酸二甜三强四弱”：青柠汁 1 份、甜味剂 2 份、朗姆 3 份、水 4 份，另加安格斯图拉苦精数滴与肉豆蔻提味。换算单份为朗姆 90 毫升、青柠汁 30 毫升、单糖浆 60 毫升、水 120 毫升。 背景：潘趣一词 1632 年首现英文文献，17 世纪由东印度公司从印度次大陆带入英国；1655 年牙买加朗姆出现后，以朗姆为基的现代潘趣正式成型，朗姆潘趣自此成为加勒比与英国宴饮的常客。', 'https://images.unsplash.com/photo-1632987788901-0c090e5f4eaf?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1632987788901-0c090e5f4eaf?w=1200&q=80&auto=format&fit=crop', 86, 252, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["潘趣", "朗姆基底", "香料", "直调", "派对"]', '["夏季", "节日"]', '{"baseSpirit": "朗姆基底", "cocktailType": "潘趣", "flavor": "酸甜、香料、果香", "abv": "中度＞10%～20%", "extra": ["安格斯图拉苦精", "肉豆蔻"], "scene": ["夏季", "节日"]}', '[{"nameZh": "朗姆酒（建议巴巴多斯）", "nameEn": "Rum (ideally Barbados)", "amount": 90, "unit": "ml", "role": "基酒核心"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 30, "unit": "ml", "role": "酸度核心"}, {"nameZh": "单糖浆", "nameEn": "Simple Syrup", "amount": 60, "unit": "ml", "role": "甜味核心"}, {"nameZh": "过滤水", "nameEn": "Water", "amount": 120, "unit": "ml", "role": "稀释弱化"}, {"nameZh": "安格斯图拉苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "提味"}, {"nameZh": "肉豆蔻", "nameEn": "Nutmeg", "amount": 1, "unit": "piece", "role": "表面撒粉"}]', '["高杯或潘趣杯加冰块。", "倒入朗姆酒、青柠汁与单糖浆。", "补入过滤水并轻轻搅拌。", "滴入安格斯图拉苦精。", "表面撒少许肉豆蔻即可饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-rum-punch", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆潘趣", "nameEn": "Rum Punch", "intro": "以朗姆、青柠、糖与水按加勒比经典口诀调制的潘趣酒，酸甜平衡、香料点睛，是巴巴多斯国民级热带饮品。", "imageUrl": "https://images.unsplash.com/photo-1632987788901-0c090e5f4eaf?w=1200&q=80&auto=format&fit=crop", "tags": ["潘趣", "朗姆基底", "香料", "直调", "派对"], "scene": ["夏季", "节日"], "recommendationScore": 86, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "潘趣", "flavor": "酸甜、香料、果香", "abv": "中度＞10%～20%", "extra": ["安格斯图拉苦精", "肉豆蔻"], "scene": ["夏季", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mexican-mule', 'cocktail', 'COCKTAIL', '墨西哥骡子', 'Mexican Mule', 'moxigeluozi', 'mxglz', '以龙舌兰、姜汁啤酒与青柠汁调制的骡子变体，姜味辛香与龙舌兰的植物气息搭配，气泡充足、清爽解腻。', '作为莫斯科骡子的变体，墨西哥骡子将伏特加换成龙舌兰：龙舌兰 45 毫升、新鲜青柠汁 10 毫升、姜汁啤酒补足约 120 毫升，加冰直调，传统以铜杯盛装。龙舌兰特有的植物香气让姜味更加立体。 背景：莫斯科骡子 1941 年于洛杉矶创制后风靡全球，衍生出墨西哥骡子（龙舌兰）、梅斯卡尔骡子等众多变体，是“雄鹿”（Buck）家族的当代代表作。', 'https://images.unsplash.com/photo-1643139173179-4bdca3c38a65?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1643139173179-4bdca3c38a65?w=1200&q=80&auto=format&fit=crop', 83, 253, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["长饮", "龙舌兰基底", "姜味", "直调", "铜杯"]', '["夏季", "新手友好"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘、辛香", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["夏季", "新手友好"]}', '[{"nameZh": "龙舌兰（银标）", "nameEn": "Silver Tequila", "amount": 45, "unit": "ml", "role": "基酒核心"}, {"nameZh": "姜汁啤酒", "nameEn": "Ginger Beer", "amount": 120, "unit": "ml", "role": "姜味与气泡"}, {"nameZh": "新鲜青柠汁", "nameEn": "Fresh Lime Juice", "amount": 10, "unit": "ml", "role": "酸香平衡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "青柠片", "nameEn": "Lime slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["铜杯或高球杯加满冰块。", "倒入龙舌兰与新鲜青柠汁。", "补入冷藏姜汁啤酒。", "轻轻搅拌混合。", "以青柠片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-mexican-mule", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "墨西哥骡子", "nameEn": "Mexican Mule", "intro": "以龙舌兰、姜汁啤酒与青柠汁调制的骡子变体，姜味辛香与龙舌兰的植物气息搭配，气泡充足、清爽解腻。", "imageUrl": "https://images.unsplash.com/photo-1643139173179-4bdca3c38a65?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "龙舌兰基底", "姜味", "直调", "铜杯"], "scene": ["夏季", "新手友好"], "recommendationScore": 83, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "雄鹿", "flavor": "姜味、柑橘、辛香", "abv": "中度＞10%～20%", "extra": ["姜汁啤酒", "新鲜青柠汁"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-hurricane', 'cocktail', 'COCKTAIL', '飓风', 'Hurricane', 'jufeng', 'jf', '以黑朗姆与白朗姆双基底、百香果糖浆与柠檬汁调制的甜酸长饮，果香浓烈，装在高脚飓风杯中极具辨识度。', '经典配比为黑朗姆 1 份、白朗姆 1 份、过烈朗姆半份，配百香果糖浆（或传统 fassionola）与柠檬汁；本条目采用黑朗姆 60 毫升、白朗姆 60 毫升、百香果糖浆 45 毫升、柠檬汁 30 毫升，摇和后加冰倒入飓风杯。 背景：1940 年代新奥尔良 Pat O\'Brien 酒吧为清掉经销商强制搭配的低人气朗姆而创制，弯口飓风杯成为其标志；如今被视为新奥尔良的象征饮品之一。', 'https://images.unsplash.com/photo-1618799805265-4f27cb61ede9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1618799805265-4f27cb61ede9?w=1200&q=80&auto=format&fit=crop', 90, 254, '[{"key": "SWEETNESS", "label": "甜度", "score": 8.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["长饮", "朗姆基底", "百香果", "摇和", "新奥尔良"]', '["夏季", "节日"]', '{"baseSpirit": "朗姆基底", "cocktailType": "热带长饮", "flavor": "百香果、甜酸", "abv": "较高＞20%～30%", "extra": ["百香果糖浆"], "scene": ["夏季", "节日"]}', '[{"nameZh": "黑朗姆", "nameEn": "Dark Rum", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "白朗姆", "nameEn": "White Rum", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "百香果糖浆", "nameEn": "Passion Fruit Syrup", "amount": 45, "unit": "ml", "role": "果味与甜度"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "酸度平衡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 150, "unit": "g", "role": "摇和与杯用"}, {"nameZh": "橙片与樱桃", "nameEn": "Orange slice & cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["摇酒壶加冰，倒入黑朗姆、白朗姆、百香果糖浆与柠檬汁。", "充分摇和约 12 秒。", "滤入加冰的飓风杯。", "以橙片与樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-hurricane", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "飓风", "nameEn": "Hurricane", "intro": "以黑朗姆与白朗姆双基底、百香果糖浆与柠檬汁调制的甜酸长饮，果香浓烈，装在高脚飓风杯中极具辨识度。", "imageUrl": "https://images.unsplash.com/photo-1618799805265-4f27cb61ede9?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "朗姆基底", "百香果", "摇和", "新奥尔良"], "scene": ["夏季", "节日"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "热带长饮", "flavor": "百香果、甜酸", "abv": "较高＞20%～30%", "extra": ["百香果糖浆"], "scene": ["夏季", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-kir-royale', 'cocktail', 'COCKTAIL', '皇家基尔', 'Kir Royale', 'huangjiajier', 'hjje', '以黑加仑利口酒与香槟直调而成的法国经典气泡开胃酒，莓果甜香与细腻气泡结合，是基尔（Kir）的高阶变体。', '标准配比为香槟（或起泡酒）90 毫升、黑加仑利口酒（crème de cassis）10 毫升：先将利口酒注入杯底，再以香槟补满，香槟笛形杯盛装。传统基尔使用干白葡萄酒，皇家基尔则以香槟代替，气泡感更华丽。 背景：基尔得名自二战时期勃艮第第戎抵抗运动英雄、时任市长 Canon Félix Kir 神父；皇家基尔是其最著名的变体，也是法式开胃酒的标志之一。', 'https://images.unsplash.com/photo-1653515906764-96bfd5c01141?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1653515906764-96bfd5c01141?w=1200&q=80&auto=format&fit=crop', 85, 255, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["汽酒", "气泡酒基底", "黑加仑", "直调", "开胃"]', '["开胃", "节日"]', '{"baseSpirit": "气泡酒基底", "cocktailType": "汽酒", "flavor": "莓果、清甜、气泡", "abv": "中度＞10%～20%", "extra": ["黑加仑利口酒"], "scene": ["开胃", "节日"]}', '[{"nameZh": "香槟或起泡酒", "nameEn": "Champagne / Sparkling wine", "amount": 90, "unit": "ml", "role": "气泡基酒"}, {"nameZh": "黑加仑利口酒", "nameEn": "Crème de Cassis", "amount": 10, "unit": "ml", "role": "莓果风味核心"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 60, "unit": "g", "role": "冰镇杯用（可省）"}, {"nameZh": "红醋栗", "nameEn": "Redcurrant", "amount": 1, "unit": "piece", "role": "装饰用（可选）"}]', '["香槟笛形杯提前冰镇。", "将黑加仑利口酒注入杯底。", "沿杯壁缓缓倒入冰镇香槟补满。", "轻拌或直接静置让两者自然融合。", "可按喜好点缀红醋栗。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-kir-royale", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皇家基尔", "nameEn": "Kir Royale", "intro": "以黑加仑利口酒与香槟直调而成的法国经典气泡开胃酒，莓果甜香与细腻气泡结合，是基尔（Kir）的高阶变体。", "imageUrl": "https://images.unsplash.com/photo-1653515906764-96bfd5c01141?w=1200&q=80&auto=format&fit=crop", "tags": ["汽酒", "气泡酒基底", "黑加仑", "直调", "开胃"], "scene": ["开胃", "节日"], "recommendationScore": 85, "attributes": {"baseSpirit": "气泡酒基底", "cocktailType": "汽酒", "flavor": "莓果、清甜、气泡", "abv": "中度＞10%～20%", "extra": ["黑加仑利口酒"], "scene": ["开胃", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-hugo-spritz', 'cocktail', 'COCKTAIL', '雨果气泡酒', 'Hugo Spritz', 'yuguoqipaojiu', 'ygqpj', '以普罗赛柯、接骨木花糖浆、苏打水与薄荷调制的气泡长饮，花香清甜、低度爽口，是近年风靡欧洲的夏季开胃酒。', '通行配比为普罗赛柯 100 毫升、接骨木花糖浆 30 毫升、苏打水 20 毫升，葡萄酒杯加冰直调，以薄荷枝与青柠片装饰。接骨木花带来清雅的花香甜感，酒精度极低，几乎无负担。 背景：2005 年由南蒂罗尔纳图尔恩 San Zeno 酒吧的罗兰·格鲁伯创制，短短十余年间从阿尔卑斯山麓传遍德语区与全球，被视为新一代经典 Spritz。', 'https://images.unsplash.com/photo-1656183011599-0405c3e44f06?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1656183011599-0405c3e44f06?w=1200&q=80&auto=format&fit=crop', 88, 256, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 1.0}, {"key": "REFRESHING", "label": "清爽度", "score": 9.0}]', '["长饮", "气泡酒基底", "接骨木花", "薄荷", "直调", "夏季"]', '["夏季", "开胃", "新手友好"]', '{"baseSpirit": "气泡酒基底", "cocktailType": "汽酒长饮", "flavor": "花香、清甜、薄荷", "abv": "低度≤10%", "extra": ["接骨木花糖浆", "苏打水"], "scene": ["夏季", "开胃", "新手友好"]}', '[{"nameZh": "普罗赛柯", "nameEn": "Prosecco", "amount": 100, "unit": "ml", "role": "气泡基酒"}, {"nameZh": "接骨木花糖浆", "nameEn": "Elderflower Syrup", "amount": 30, "unit": "ml", "role": "花香甜味核心"}, {"nameZh": "苏打水", "nameEn": "Sparkling Water", "amount": 20, "unit": "ml", "role": "补充气泡"}, {"nameZh": "薄荷枝", "nameEn": "Mint sprig", "amount": 1, "unit": "piece", "role": "香气与装饰"}, {"nameZh": "青柠片", "nameEn": "Lime slice", "amount": 1, "unit": "piece", "role": "装饰用"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 100, "unit": "g", "role": "直调用"}]', '["葡萄酒杯加满冰块。", "倒入接骨木花糖浆。", "补入普罗赛柯与苏打水。", "轻轻搅拌混合。", "以薄荷枝与青柠片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-hugo-spritz", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "雨果气泡酒", "nameEn": "Hugo Spritz", "intro": "以普罗赛柯、接骨木花糖浆、苏打水与薄荷调制的气泡长饮，花香清甜、低度爽口，是近年风靡欧洲的夏季开胃酒。", "imageUrl": "https://images.unsplash.com/photo-1656183011599-0405c3e44f06?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "气泡酒基底", "接骨木花", "薄荷", "直调", "夏季"], "scene": ["夏季", "开胃", "新手友好"], "recommendationScore": 88, "attributes": {"baseSpirit": "气泡酒基底", "cocktailType": "汽酒长饮", "flavor": "花香、清甜、薄荷", "abv": "低度≤10%", "extra": ["接骨木花糖浆", "苏打水"], "scene": ["夏季", "开胃", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-blue-lagoon', 'cocktail', 'COCKTAIL', '蓝色珊瑚礁', 'Blue Lagoon', 'lanseshanhujiao', 'lsshj', '以伏特加、蓝橙利口酒与柠檬汽水调制的高颜值蓝色长饮，清澈的蓝色外观极具辨识度，口感甜爽易饮。', '标准配比为伏特加 50 毫升、蓝橙利口酒 20 毫升、柠檬汽水 100 毫升：先摇和酒液再滤入加冰高球杯，以柠檬汽水补满，橙片或柠檬片装饰。蓝橙利口酒赋予其标志性的蔚蓝色。 背景：巴黎 Harry\'s New York Bar 声称发明了这款鸡尾酒；在丹麦它被称为“北极熊”（Isbjørn），并衍生出加入树莓汁或红石榴糖浆的“水果叮当”（Fruit Tingle）变体。', 'https://images.unsplash.com/photo-1630071121741-d52aa221e9e0?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1630071121741-d52aa221e9e0?w=1200&q=80&auto=format&fit=crop', 82, 257, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["长饮", "伏特加基底", "蓝橙利口酒", "直调", "高颜值"]', '["夏季", "新手友好"]', '{"baseSpirit": "伏特加基底", "cocktailType": "长饮", "flavor": "甜橙、清甜、柠檬", "abv": "中度＞10%～20%", "extra": ["蓝橙利口酒", "柠檬汽水"], "scene": ["夏季", "新手友好"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 50, "unit": "ml", "role": "基酒核心"}, {"nameZh": "蓝橙利口酒", "nameEn": "Blue Curaçao", "amount": 20, "unit": "ml", "role": "色泽与橙香"}, {"nameZh": "柠檬汽水", "nameEn": "Lemonade", "amount": 100, "unit": "ml", "role": "甜度与气泡"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "橙片或柠檬片", "nameEn": "Orange or lemon slice", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["高球杯加满冰块。", "摇酒壶加冰，倒入伏特加与蓝橙利口酒摇匀。", "滤入杯中，以柠檬汽水补满。", "轻轻搅拌。", "以橙片或柠檬片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-blue-lagoon", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蓝色珊瑚礁", "nameEn": "Blue Lagoon", "intro": "以伏特加、蓝橙利口酒与柠檬汽水调制的高颜值蓝色长饮，清澈的蓝色外观极具辨识度，口感甜爽易饮。", "imageUrl": "https://images.unsplash.com/photo-1630071121741-d52aa221e9e0?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "伏特加基底", "蓝橙利口酒", "直调", "高颜值"], "scene": ["夏季", "新手友好"], "recommendationScore": 82, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "长饮", "flavor": "甜橙、清甜、柠檬", "abv": "中度＞10%～20%", "extra": ["蓝橙利口酒", "柠檬汽水"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-harvey-wallbanger', 'cocktail', 'COCKTAIL', '哈维撞墙', 'Harvey Wallbanger', 'haweizhuangqiang', 'hwzq', '以伏特加、橙汁与加利安奴香草利口酒调制的高杯长饮，橙汁打底、香草利口酒浮层，是 1970 年代美国酒吧的人气单品。', '标准配比为伏特加 45 毫升、加利安奴利口酒 15 毫升、鲜橙汁 90 毫升：杯中加冰搅拌伏特加与橙汁，再让加利安奴缓缓浮于表面，橙片与樱桃装饰。浮层的香草金色酒液是它的辨识标志。 背景：1969 年由加利安奴进口商 McKesson 公司为推广利口酒而策划创制，配套的冲浪卡通形象广告让它在 1970 年代的美国成为国民级鸡尾酒。', 'https://images.unsplash.com/photo-1600271886742-f049cd451bba?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1600271886742-f049cd451bba?w=1200&q=80&auto=format&fit=crop', 80, 258, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["长饮", "伏特加基底", "橙汁", "直调", "高杯"]', '["早午餐", "日常"]', '{"baseSpirit": "伏特加基底", "cocktailType": "长饮", "flavor": "香草、橙香", "abv": "中度＞10%～20%", "extra": ["鲜橙汁"], "scene": ["早午餐", "日常"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "基酒核心"}, {"nameZh": "鲜橙汁", "nameEn": "Fresh Orange Juice", "amount": 90, "unit": "ml", "role": "果味主体"}, {"nameZh": "加利安奴利口酒", "nameEn": "Galliano Liqueur", "amount": 15, "unit": "ml", "role": "浮层香草风味"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 120, "unit": "g", "role": "直调用"}, {"nameZh": "橙片与樱桃", "nameEn": "Orange slice & cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["高球杯加满冰块。", "倒入伏特加与鲜橙汁并搅拌。", "沿吧勺缓缓倒入加利安奴使其浮于表面。", "以橙片与樱桃装饰即可饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-harvey-wallbanger", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "哈维撞墙", "nameEn": "Harvey Wallbanger", "intro": "以伏特加、橙汁与加利安奴香草利口酒调制的高杯长饮，橙汁打底、香草利口酒浮层，是 1970 年代美国酒吧的人气单品。", "imageUrl": "https://images.unsplash.com/photo-1600271886742-f049cd451bba?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "伏特加基底", "橙汁", "直调", "高杯"], "scene": ["早午餐", "日常"], "recommendationScore": 80, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "长饮", "flavor": "香草、橙香", "abv": "中度＞10%～20%", "extra": ["鲜橙汁"], "scene": ["早午餐", "日常"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-scorpion', 'cocktail', 'COCKTAIL', '蝎子', 'Scorpion', 'xiezi', 'xz', '以白朗姆、白兰地、橙汁、柠檬汁与杏仁糖浆调制的蒂基鸡尾酒，热带果香与杏仁甜感交融，多人分享的蝎子碗是其标志形态。', '单杯版（Trader Vic 通行配比）为白朗姆 45 毫升、白兰地 45 毫升、橙汁 30 毫升、柠檬汁 30 毫升、杏仁糖浆 15 毫升，摇和后滤入加冰杯中；多人版则以大碗盛装、插长吸管共享。 背景：蝎子最初是单杯鸡尾酒，经蒂基文化教父 Trader Vic 推广后以大型“蝎子碗”形态成为蒂基酒吧的招牌；成分组合（淡朗姆、白兰地、杏仁糖浆、橙与柠檬汁）在 Trader Vic 1972 年调酒指南中有记载。', 'https://images.unsplash.com/photo-1655973577713-5acd43022732?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1655973577713-5acd43022732?w=1200&q=80&auto=format&fit=crop', 85, 259, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["蒂基", "朗姆基底", "白兰地", "杏仁糖浆", "摇和", "热带"]', '["夏季", "节日"]', '{"baseSpirit": "朗姆基底", "cocktailType": "蒂基鸡尾酒", "flavor": "热带果香、杏仁", "abv": "较高＞20%～30%", "extra": ["橙汁", "柠檬汁", "杏仁糖浆"], "scene": ["夏季", "节日"]}', '[{"nameZh": "白朗姆", "nameEn": "Light Rum", "amount": 45, "unit": "ml", "role": "基酒核心"}, {"nameZh": "白兰地", "nameEn": "Brandy", "amount": 45, "unit": "ml", "role": "基酒核心"}, {"nameZh": "新鲜橙汁", "nameEn": "Fresh Orange Juice", "amount": 30, "unit": "ml", "role": "果味"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "酸度平衡"}, {"nameZh": "杏仁糖浆", "nameEn": "Orgeat Syrup", "amount": 15, "unit": "ml", "role": "杏仁甜香"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 150, "unit": "g", "role": "摇和与杯用"}]', '["摇酒壶加冰，倒入白朗姆、白兰地、橙汁、柠檬汁与杏仁糖浆。", "充分摇和约 15 秒。", "滤入加冰的高杯。", "按蒂基风格以水果与可食用花朵装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-scorpion", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蝎子", "nameEn": "Scorpion", "intro": "以白朗姆、白兰地、橙汁、柠檬汁与杏仁糖浆调制的蒂基鸡尾酒，热带果香与杏仁甜感交融，多人分享的蝎子碗是其标志形态。", "imageUrl": "https://images.unsplash.com/photo-1655973577713-5acd43022732?w=1200&q=80&auto=format&fit=crop", "tags": ["蒂基", "朗姆基底", "白兰地", "杏仁糖浆", "摇和", "热带"], "scene": ["夏季", "节日"], "recommendationScore": 85, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "蒂基鸡尾酒", "flavor": "热带果香、杏仁", "abv": "较高＞20%～30%", "extra": ["橙汁", "柠檬汁", "杏仁糖浆"], "scene": ["夏季", "节日"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-tom-collins', 'cocktail', 'COCKTAIL', '汤姆·柯林斯', 'Tom Collins', 'tangmu·kelinsi', 'tm·kls', '以老汤姆金酒、柠檬汁、糖浆与苏打水直调而成的气泡长饮，酸甜清爽，是柯林斯家族与高球类鸡尾酒的经典代表。', '标准配比为老汤姆金酒 60 毫升、柠檬汁 25 毫升、单糖浆 15 毫升、苏打水 50 毫升：高身柯林斯杯加冰直调，以柠檬片与樱桃装饰。老汤姆金酒比伦敦干金酒更甜，正契合柯林斯的甜酸框架。 背景：1882 年哈里·约翰逊《新改良调酒师手册》同时记载了汤姆·柯林斯（老汤姆金酒）与约翰·柯林斯（荷兰金酒），是最早出版的 Collins 与 Fizz 类配方；另有 1874 年纽约“汤姆·柯林斯骗局”的都市传说背景。', 'https://images.unsplash.com/photo-1630071073903-423f86c14389?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1630071073903-423f86c14389?w=1200&q=80&auto=format&fit=crop', 90, 260, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 2.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["长饮", "金酒基底", "气泡", "直调", "经典"]', '["经典", "夏季"]', '{"baseSpirit": "金酒基底", "cocktailType": "柯林斯", "flavor": "柠檬、清爽、气泡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["经典", "夏季"]}', '[{"nameZh": "老汤姆金酒", "nameEn": "Old Tom Gin", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 25, "unit": "ml", "role": "酸度核心"}, {"nameZh": "单糖浆", "nameEn": "Simple Syrup", "amount": 15, "unit": "ml", "role": "平衡酸度"}, {"nameZh": "苏打水", "nameEn": "Club Soda", "amount": 50, "unit": "ml", "role": "气泡与稀释"}, {"nameZh": "冰块", "nameEn": "Ice cubes", "amount": 150, "unit": "g", "role": "直调用"}, {"nameZh": "柠檬片与樱桃", "nameEn": "Lemon slice & cherry", "amount": 1, "unit": "piece", "role": "装饰用"}]', '["柯林斯杯加满冰块。", "倒入老汤姆金酒、柠檬汁与单糖浆。", "补入苏打水并轻轻搅拌。", "以柠檬片与樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-tom-collins", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "汤姆·柯林斯", "nameEn": "Tom Collins", "intro": "以老汤姆金酒、柠檬汁、糖浆与苏打水直调而成的气泡长饮，酸甜清爽，是柯林斯家族与高球类鸡尾酒的经典代表。", "imageUrl": "https://images.unsplash.com/photo-1630071073903-423f86c14389?w=1200&q=80&auto=format&fit=crop", "tags": ["长饮", "金酒基底", "气泡", "直调", "经典"], "scene": ["经典", "夏季"], "recommendationScore": 90, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "柯林斯", "flavor": "柠檬、清爽、气泡", "abv": "中度＞10%～20%", "extra": ["苏打水"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-peach-bourbon-smash', 'cocktail', 'COCKTAIL', '蜜桃波本碎冰', 'Peach Bourbon Smash', 'mitaobobensuibing', 'mtbbsb', '以波本威士忌、新鲜蜜桃、柠檬汁与薄荷调制的水果碎冰鸡尾酒，蜜桃甜香与薄荷清凉平衡了波本的强劲。', '业界通行配比（现代经典酒吧标准）为波本威士忌 60 毫升、新鲜柠檬汁 22.5 毫升、单糖浆 22.5 毫升、蜜桃片 2 片捣压后加碎冰摇和，以薄荷枝装饰。蜜桃的果甜与波本的橡木甜香相得益彰，碎冰带来畅快的夏日口感。 背景：“碎冰”家族历史悠久——1862 年杰瑞·托马斯《调酒师指南》即有 smash 类配方，意为暑热天随手取水果压碎调制的清凉饮品；蜜桃波本碎冰是其在当代水果版本中的代表。', 'https://images.unsplash.com/photo-1592858321831-dabeabc2dd65?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1592858321831-dabeabc2dd65?w=1200&q=80&auto=format&fit=crop', 84, 261, '[{"key": "SWEETNESS", "label": "甜度", "score": 7.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["碎冰", "波本基底", "蜜桃", "捣压", "夏季"]', '["夏季", "新手友好"]', '{"baseSpirit": "威士忌基底", "cocktailType": "碎冰家族", "flavor": "蜜桃、薄荷、橡木", "abv": "较高＞20%～30%", "extra": ["新鲜蜜桃", "薄荷"], "scene": ["夏季", "新手友好"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon Whiskey", "amount": 60, "unit": "ml", "role": "基酒核心"}, {"nameZh": "新鲜柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "酸度核心"}, {"nameZh": "单糖浆", "nameEn": "Simple Syrup", "amount": 22.5, "unit": "ml", "role": "平衡酸度"}, {"nameZh": "蜜桃片", "nameEn": "Peach slices", "amount": 2, "unit": "piece", "role": "捣压出汁"}, {"nameZh": "薄荷枝", "nameEn": "Mint sprig", "amount": 1, "unit": "piece", "role": "香气与装饰"}, {"nameZh": "碎冰", "nameEn": "Crushed ice", "amount": 150, "unit": "g", "role": "摇和与杯用"}]', '["摇酒壶中放入蜜桃片、薄荷叶、柠檬汁与单糖浆。", "用捣棒轻压释放蜜桃汁液与薄荷香气。", "加入波本与碎冰，充分摇和。", "倒入装满碎冰的高杯。", "以蜜桃片与薄荷枝装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-peach-bourbon-smash", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蜜桃波本碎冰", "nameEn": "Peach Bourbon Smash", "intro": "以波本威士忌、新鲜蜜桃、柠檬汁与薄荷调制的水果碎冰鸡尾酒，蜜桃甜香与薄荷清凉平衡了波本的强劲。", "imageUrl": "https://images.unsplash.com/photo-1592858321831-dabeabc2dd65?w=1200&q=80&auto=format&fit=crop", "tags": ["碎冰", "波本基底", "蜜桃", "捣压", "夏季"], "scene": ["夏季", "新手友好"], "recommendationScore": 84, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "碎冰家族", "flavor": "蜜桃、薄荷、橡木", "abv": "较高＞20%～30%", "extra": ["新鲜蜜桃", "薄荷"], "scene": ["夏季", "新手友好"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bamboo', 'cocktail', 'COCKTAIL', '竹子', 'Bamboo', 'zhuzi', 'zz', '以干雪莉酒与干味美思等量调和、加苦精提香的古典低度鸡尾酒，口感干爽微苦，是诞生于日本横滨的经典餐前酒。', '本条目采用业界通行的 IBA 配比：干雪莉酒（菲诺）30 ml 兑干味美思 30 ml，加橙味苦精与安高天娜苦精各 1 滴，搅拌后滤入冰镇杯，以柠檬皮装饰。 背景：1890 年代末由 Louis Eppinger 在日本横滨大酒店创制，被誉为主流酒吧最早的餐前酒（aperitif）之一，随后流行于纽约与伦敦。', 'https://images.unsplash.com/photo-1587223962930-cb7f31384c19?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1587223962930-cb7f31384c19?w=1200&q=80&auto=format&fit=crop', 88, 247, '[{"key": "SWEETNESS", "label": "甜度", "score": 2.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["低度", "雪莉酒基底", "搅拌", "干爽", "草本", "餐前酒", "经典"]', '["餐前开胃", "经典"]', '{"baseSpirit": "雪莉酒基底", "cocktailType": "古典家族", "flavor": "干爽、坚果与草本", "abv": "中度＞10%～20%", "extra": "以雪莉酒与味美思为主的低酒精组合", "scene": ["餐前开胃", "经典"]}', '[{"nameZh": "干雪莉酒（菲诺）", "nameEn": "Fino dry sherry", "amount": 30, "unit": "ml", "role": "基底"}, {"nameZh": "干味美思", "nameEn": "Dry vermouth", "amount": 30, "unit": "ml", "role": "辅料"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 1, "unit": "dash", "role": "提香"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "提香"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇鸡尾酒杯或尼克罗尼杯。", "搅拌杯加冰，倒入干雪莉酒与干味美思。", "加入橙味苦精与安高天娜苦精。", "搅拌约 20-30 秒至充分降温。", "滤入冰镇杯，以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-bamboo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "竹子", "nameEn": "Bamboo", "intro": "以干雪莉酒与干味美思等量调和、加苦精提香的古典低度鸡尾酒，口感干爽微苦，是诞生于日本横滨的经典餐前酒。", "imageUrl": "https://images.unsplash.com/photo-1587223962930-cb7f31384c19?w=1200&q=80&auto=format&fit=crop", "tags": ["低度", "雪莉酒基底", "搅拌", "干爽", "草本", "餐前酒", "经典"], "scene": ["餐前开胃", "经典"], "recommendationScore": 88, "attributes": {"baseSpirit": "雪莉酒基底", "cocktailType": "古典家族", "flavor": "干爽、坚果与草本", "abv": "中度＞10%～20%", "extra": "以雪莉酒与味美思为主的低酒精组合", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-kamikaze', 'cocktail', 'COCKTAIL', '神风特攻', 'Kamikaze', 'shenfengtegong', 'sftg', '伏特加、橙皮利口酒与青柠汁等量调配的酸型鸡尾酒，口感清冽酸爽，是 20 世纪 70 年代酒吧流行的小杯烈饮。', '本条目按维基百科标准配比：伏特加 30 ml、橙皮利口酒（君度）30 ml、鲜青柠汁 30 ml，加冰摇匀后滤入鸡尾酒杯，以青柠角装饰。 背景：名字取自二战日本"神风"特攻队，具体出处不详；上世纪 70 年代在美国酒吧广泛流行，成为伏特加酸类与酒吧常备经典。', 'https://images.unsplash.com/photo-1514361659284-59851c90d011?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1514361659284-59851c90d011?w=1200&q=80&auto=format&fit=crop', 84, 248, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 6.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 2.5}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["伏特加基底", "酸型鸡尾酒", "柑橘", "摇匀", "清爽", "经典"]', '["酒吧", "聚会"]', '{"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸爽、柑橘调", "abv": "中度＞10%～20%", "extra": "等量三分组合，口感直接", "scene": ["酒吧", "聚会"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 30, "unit": "ml", "role": "基底"}, {"nameZh": "橙皮利口酒（君度）", "nameEn": "Triple sec (Cointreau)", "amount": 30, "unit": "ml", "role": "橙味利口酒"}, {"nameZh": "鲜青柠汁", "nameEn": "Lime juice", "amount": 30, "unit": "ml", "role": "酸味汁"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇鸡尾酒杯。", "摇酒壶加冰，倒入伏特加、橙皮利口酒与青柠汁。", "用力摇匀约 12-15 秒。", "滤入冰镇鸡尾酒杯。", "以青柠角装饰后立即饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-kamikaze", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "神风特攻", "nameEn": "Kamikaze", "intro": "伏特加、橙皮利口酒与青柠汁等量调配的酸型鸡尾酒，口感清冽酸爽，是 20 世纪 70 年代酒吧流行的小杯烈饮。", "imageUrl": "https://images.unsplash.com/photo-1514361659284-59851c90d011?w=1200&q=80&auto=format&fit=crop", "tags": ["伏特加基底", "酸型鸡尾酒", "柑橘", "摇匀", "清爽", "经典"], "scene": ["酒吧", "聚会"], "recommendationScore": 84, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "酸型鸡尾酒", "flavor": "酸爽、柑橘调", "abv": "中度＞10%～20%", "extra": "等量三分组合，口感直接", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-alaska', 'cocktail', 'COCKTAIL', '阿拉斯加', 'Alaska', 'alasijia', 'alsj', '以金酒为主、黄查特酒为辅的烈性搅拌鸡尾酒，金黄色酒体带有查特酒标志性的药草与蜂蜜气息。', '本条目采用业界通行的 2:1 配比：金酒 50 ml 配黄查特酒 25 ml，加 2 滴橙味苦精，搅拌后滤杯，以柠檬皮挤油装饰。 背景：最早见于 1913 年 Straub\'s Manual of Mixed Drinks，被视为干马天尼的变体——以黄查特酒替代干味美思；名字由来众说纷纭，一说与阿拉斯加淘金热有关，一说影射寒冷。', 'https://images.unsplash.com/photo-1721673078782-82fe896261e1?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1721673078782-82fe896261e1?w=1200&q=80&auto=format&fit=crop', 86, 249, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 8.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 3.0}]', '["金酒基底", "烈酒主导", "药草", "搅拌", "金色", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "药草、蜂蜜、偏干", "abv": "高度＞30%", "extra": "仅金酒与黄查特酒两种主料", "scene": ["经典", "餐后"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 50, "unit": "ml", "role": "基底"}, {"nameZh": "黄查特酒", "nameEn": "Yellow Chartreuse", "amount": 25, "unit": "ml", "role": "药草利口酒"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 2, "unit": "dash", "role": "提香"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇尼克罗尼杯或鸡尾酒杯。", "搅拌杯加冰，倒入金酒与黄查特酒。", "加入橙味苦精。", "搅拌约 30 秒至充分降温。", "滤入冰镇杯，以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-alaska", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿拉斯加", "nameEn": "Alaska", "intro": "以金酒为主、黄查特酒为辅的烈性搅拌鸡尾酒，金黄色酒体带有查特酒标志性的药草与蜂蜜气息。", "imageUrl": "https://images.unsplash.com/photo-1721673078782-82fe896261e1?w=1200&q=80&auto=format&fit=crop", "tags": ["金酒基底", "烈酒主导", "药草", "搅拌", "金色", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 86, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "药草、蜂蜜、偏干", "abv": "高度＞30%", "extra": "仅金酒与黄查特酒两种主料", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bijou', 'cocktail', 'COCKTAIL', '宝石', 'Bijou', 'baoshi', 'bs', '金酒、绿查特酒与甜味美思等量调和的烈性鸡尾酒，因三种酒色如钻石、红宝石与祖母绿而得名"宝石"。', '本条目按维基百科标准配比：金酒、绿查特酒、甜味美思各 1 份，加 1 滴橙味苦精，搅拌后滤入鸡尾酒杯，以柠檬皮装饰。 背景：1890 年代由"职业调酒师之父"Harry Johnson 创制并收录于其 1900 年著作；1980 年代经 Dale DeGroff 将金酒比例提至 3:1:1 后重新流行，其版本成为现代主流。', 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=1200&q=80&auto=format&fit=crop', 85, 250, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.5}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.5}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.5}]', '["金酒基底", "烈酒主导", "药草", "搅拌", "甜润", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "药草、甜润、饱满", "abv": "较高＞20%～30%", "extra": "现代标准为金酒 3 份配其他各 1 份", "scene": ["经典", "餐后"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 30, "unit": "ml", "role": "基底"}, {"nameZh": "绿查特酒", "nameEn": "Green Chartreuse", "amount": 30, "unit": "ml", "role": "药草利口酒"}, {"nameZh": "甜味美思", "nameEn": "Sweet vermouth", "amount": 30, "unit": "ml", "role": "辅料"}, {"nameZh": "橙味苦精", "nameEn": "Orange bitters", "amount": 1, "unit": "dash", "role": "提香"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇鸡尾酒杯。", "搅拌杯加冰，倒入金酒、绿查特酒与甜味美思。", "加入橙味苦精。", "搅拌约 20-30 秒至充分降温。", "滤入冰镇杯，以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-bijou", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "宝石", "nameEn": "Bijou", "intro": "金酒、绿查特酒与甜味美思等量调和的烈性鸡尾酒，因三种酒色如钻石、红宝石与祖母绿而得名”宝石”。", "imageUrl": "https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=1200&q=80&auto=format&fit=crop", "tags": ["金酒基底", "烈酒主导", "药草", "搅拌", "甜润", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 85, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "烈酒主导", "flavor": "药草、甜润、饱满", "abv": "较高＞20%～30%", "extra": "现代标准为金酒 3 份配其他各 1 份", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-caesar', 'cocktail', 'COCKTAIL', '血腥凯撒', 'Caesar', 'xuexingkaisa', 'xxks', '加拿大国民鸡尾酒，以伏特加与番茄蛤蜊汁为基，加入辣酱与伍斯特酱，杯沿蘸芹菜盐，以芹菜杆与青柠角装饰。', '本条目按维基百科标准配比：番茄蛤蜊汁 180 ml 配伏特加 30-45 ml，加 2 滴辣酱、4 滴伍斯特酱与盐、现磨胡椒调味，杯沿蘸芹菜盐，以芹菜杆与青柠角装饰，加冰饮用。 背景：1969 年由卡尔加里酒店餐厅经理 Walter Chell 创制，灵感来自意大利蛤蜊意面，后成为加拿大最受欢迎的调酒，与血腥玛丽的关键区别在于加入蛤蜊汁。', 'https://images.unsplash.com/photo-1601627901831-2d9626bea5b8?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1601627901831-2d9626bea5b8?w=1200&q=80&auto=format&fit=crop', 90, 251, '[{"key": "SWEETNESS", "label": "甜度", "score": 2.0}, {"key": "SOURNESS", "label": "酸度", "score": 2.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 3.0}, {"key": "BODY", "label": "酒体", "score": 4.5}, {"key": "REFRESHING", "label": "清爽度", "score": 5.0}]', '["伏特加基底", "咸鲜", "番茄调", "微辣", "加冰", "低度", "加拿大经典"]', '["早午餐", "周末", "餐前"]', '{"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、微辣、番茄调", "abv": "低度≤10%", "extra": "含蛤蜊汁是区分血腥玛丽的关键", "scene": ["早午餐", "周末", "餐前"]}', '[{"nameZh": "伏特加", "nameEn": "Vodka", "amount": 45, "unit": "ml", "role": "基底"}, {"nameZh": "番茄蛤蜊汁", "nameEn": "Clamato juice", "amount": 180, "unit": "ml", "role": "主料果汁"}, {"nameZh": "伍斯特酱", "nameEn": "Worcestershire sauce", "amount": 4, "unit": "dash", "role": "调味"}, {"nameZh": "辣酱", "nameEn": "Hot sauce", "amount": 2, "unit": "dash", "role": "调味"}, {"nameZh": "芹菜盐", "nameEn": "Celery salt", "amount": 1, "unit": "piece", "role": "杯沿蘸盐"}, {"nameZh": "芹菜杆", "nameEn": "Celery stalk", "amount": 1, "unit": "piece", "role": "装饰"}, {"nameZh": "青柠角", "nameEn": "Lime wedge", "amount": 1, "unit": "piece", "role": "装饰"}]', '["高球杯杯沿以青柠擦拭后蘸芹菜盐。", "杯中加满冰块，倒入伏特加。", "加入伍斯特酱、辣酱与盐、现磨胡椒。", "倒入番茄蛤蜊汁并轻搅混合。", "以芹菜杆与青柠角装饰后饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-caesar", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "血腥凯撒", "nameEn": "Caesar", "intro": "加拿大国民鸡尾酒，以伏特加与番茄蛤蜊汁为基，加入辣酱与伍斯特酱，杯沿蘸芹菜盐，以芹菜杆与青柠角装饰。", "imageUrl": "https://images.unsplash.com/photo-1601627901831-2d9626bea5b8?w=1200&q=80&auto=format&fit=crop", "tags": ["伏特加基底", "咸鲜", "番茄调", "微辣", "加冰", "低度", "加拿大经典"], "scene": ["早午餐", "周末", "餐前"], "recommendationScore": 90, "attributes": {"baseSpirit": "伏特加基底", "cocktailType": "血腥玛丽类", "flavor": "咸鲜、微辣、番茄调", "abv": "低度≤10%", "extra": "含蛤蜊汁是区分血腥玛丽的关键", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-gold-rush', 'cocktail', 'COCKTAIL', '淘金热', 'Gold Rush', 'taojinre', 'tjr', '波本威士忌、蜂蜜糖浆与鲜柠檬汁组成的现代经典酸酒，蜂蜜的圆润甜感中和了波本的烈度。', '本条目按业界通行配比：波本威士忌 60 ml、蜂蜜糖浆（蜂蜜与水 2:1）22.5 ml、鲜柠檬汁 22.5 ml，加冰摇匀后滤入冰镇杯。 背景：2000 年代初期由 T.J. Siegel 在纽约 Milk & Honey 酒吧创制，被 Difford\'s 指南概括为"以蜂蜜替代糖浆的威士忌酸"，是蜂蜜酸鸡尾酒的代表作。', 'https://images.unsplash.com/photo-1609951651556-5334e2706168?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1609951651556-5334e2706168?w=1200&q=80&auto=format&fit=crop', 93, 252, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.5}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 3.5}, {"key": "REFRESHING", "label": "清爽度", "score": 5.5}]', '["波本基底", "酸型鸡尾酒", "蜂蜜", "摇匀", "现代经典"]', '["酒吧", "聚会", "经典"]', '{"baseSpirit": "波本基底", "cocktailType": "酸型鸡尾酒", "flavor": "蜂蜜、柠檬、醇厚", "abv": "中度＞10%～20%", "extra": "蜂蜜糖浆替代糖浆是其特色", "scene": ["酒吧", "聚会", "经典"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "基底"}, {"nameZh": "蜂蜜糖浆（2:1）", "nameEn": "Honey syrup (2:1)", "amount": 22.5, "unit": "ml", "role": "甜味剂"}, {"nameZh": "鲜柠檬汁", "nameEn": "Lemon juice", "amount": 22.5, "unit": "ml", "role": "酸味汁"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇鸡尾酒杯或岩石杯。", "摇酒壶加冰，倒入波本、蜂蜜糖浆与柠檬汁。", "用力摇匀约 12-15 秒。", "滤入冰镇杯（可加冰饮用）。", "以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-gold-rush", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "淘金热", "nameEn": "Gold Rush", "intro": "波本威士忌、蜂蜜糖浆与鲜柠檬汁组成的现代经典酸酒，蜂蜜的圆润甜感中和了波本的烈度。", "imageUrl": "https://images.unsplash.com/photo-1609951651556-5334e2706168?w=1200&q=80&auto=format&fit=crop", "tags": ["波本基底", "酸型鸡尾酒", "蜂蜜", "摇匀", "现代经典"], "scene": ["酒吧", "聚会", "经典"], "recommendationScore": 93, "attributes": {"baseSpirit": "波本基底", "cocktailType": "酸型鸡尾酒", "flavor": "蜂蜜、柠檬、醇厚", "abv": "中度＞10%～20%", "extra": "蜂蜜糖浆替代糖浆是其特色", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-saturn', 'cocktail', 'COCKTAIL', '土星', 'Saturn', 'tuxing', 'tx', '金酒与百香果糖浆、杏仁糖浆、法勒纳姆调和的提基风鸡尾酒，果香与草本交织，以柠檬皮环套樱桃象征土星环。', '本条目按 IBA 锦标赛原配方配比：金酒 45 ml、柠檬汁 15 ml、百香果糖浆 15 ml、法勒纳姆 7.5 ml、杏仁糖浆 7.5 ml，与碎冰搅打后倒入高脚杯，以柠檬皮环与樱桃装饰。 背景：1967 年由菲律宾裔调酒师 J."Popo" Galsini 创制并赢得当年 IBA 世界调酒锦标赛，是少见的金酒基底提基鸡尾酒。', 'https://images.unsplash.com/photo-1610970883364-30e1ab2dc48b?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1610970883364-30e1ab2dc48b?w=1200&q=80&auto=format&fit=crop', 92, 253, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["金酒基底", "提基", "果味", "百香果", "碎冰", "经典"]', '["夏日", "聚会", "热带风情"]', '{"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "百香果、杏仁、草本", "abv": "中度＞10%～20%", "extra": "罕见采用金酒的提基配方", "scene": ["夏日", "聚会", "热带风情"]}', '[{"nameZh": "金酒", "nameEn": "Gin", "amount": 45, "unit": "ml", "role": "基底"}, {"nameZh": "鲜柠檬汁", "nameEn": "Lemon juice", "amount": 15, "unit": "ml", "role": "酸味汁"}, {"nameZh": "百香果糖浆", "nameEn": "Passion fruit syrup", "amount": 15, "unit": "ml", "role": "果味糖浆"}, {"nameZh": "法勒纳姆", "nameEn": "Falernum", "amount": 7.5, "unit": "ml", "role": "香料酒"}, {"nameZh": "杏仁糖浆", "nameEn": "Orgeat", "amount": 7.5, "unit": "ml", "role": "坚果糖浆"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰，配柠檬皮环"}]', '["将柠檬皮刨成长条做成环状。", "搅拌机或摇酒壶中加入金酒、柠檬汁、百香果糖浆、法勒纳姆与杏仁糖浆。", "加碎冰搅打至顺滑（或加冰摇匀）。", "倒入高脚杯或提基杯。", "以柠檬皮环套樱桃装饰，形如土星环。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-saturn", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "土星", "nameEn": "Saturn", "intro": "金酒与百香果糖浆、杏仁糖浆、法勒纳姆调和的提基风鸡尾酒，果香与草本交织，以柠檬皮环套樱桃象征土星环。", "imageUrl": "https://images.unsplash.com/photo-1610970883364-30e1ab2dc48b?w=1200&q=80&auto=format&fit=crop", "tags": ["金酒基底", "提基", "果味", "百香果", "碎冰", "经典"], "scene": ["夏日", "聚会", "热带风情"], "recommendationScore": 92, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "百香果、杏仁、草本", "abv": "中度＞10%～20%", "extra": "罕见采用金酒的提基配方", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-air-mail', 'cocktail', 'COCKTAIL', '航空信', 'Air Mail', 'hangkongxin', 'hkx', '朗姆酒、青柠汁与蜂蜜糖浆摇匀后以香槟补满的气泡鸡尾酒，酸甜中带着起泡酒的清脆与蜂蜜的圆润。', '本条目按业界通行配比：朗姆酒 3 cl、青柠汁 1.5 cl、蜂蜜糖浆（蜂蜜与水 2:1）1.5 cl 加冰摇匀，滤入冰镇香槟杯后以 3 cl 干香槟补满，可选以青柠角或邮票装饰。 背景：1920-30 年代禁酒令时期诞生于古巴，名称取自当时连接美国与古巴的航空邮递；1941 年收录于《Here\'s How》调酒书，被视为法国 75 与蜂蜜蜂的结合体。', 'https://images.unsplash.com/photo-1677729311005-65d74274e9e9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1677729311005-65d74274e9e9?w=1200&q=80&auto=format&fit=crop', 88, 254, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.5}, {"key": "SOURNESS", "label": "酸度", "score": 4.5}, {"key": "BITTERNESS", "label": "苦度", "score": 1.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.5}, {"key": "BODY", "label": "酒体", "score": 3.0}, {"key": "REFRESHING", "label": "清爽度", "score": 7.0}]', '["朗姆基底", "气泡", "蜂蜜", "酸甜", "摇匀", "经典"]', '["聚会", "庆祝", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "菲兹", "flavor": "酸甜、气泡、蜂蜜", "abv": "中度＞10%～20%", "extra": "香槟补顶的气泡鸡尾酒", "scene": ["聚会", "庆祝", "经典"]}', '[{"nameZh": "朗姆酒", "nameEn": "Rum", "amount": 30, "unit": "ml", "role": "基底"}, {"nameZh": "鲜青柠汁", "nameEn": "Lime juice", "amount": 15, "unit": "ml", "role": "酸味汁"}, {"nameZh": "蜂蜜糖浆（2:1）", "nameEn": "Honey syrup (2:1)", "amount": 15, "unit": "ml", "role": "甜味剂"}, {"nameZh": "干香槟", "nameEn": "Dry champagne", "amount": 30, "unit": "ml", "role": "气泡酒补顶"}, {"nameZh": "青柠角", "nameEn": "Lime slice", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇香槟杯或郁金香杯。", "摇酒壶加冰，倒入朗姆酒、青柠汁与蜂蜜糖浆。", "摇匀后滤入冰镇杯。", "以干香槟或起泡酒补满。", "以青柠角点缀（巴卡迪官方以邮票造型装饰）。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-air-mail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "航空信", "nameEn": "Air Mail", "intro": "朗姆酒、青柠汁与蜂蜜糖浆摇匀后以香槟补满的气泡鸡尾酒，酸甜中带着起泡酒的清脆与蜂蜜的圆润。", "imageUrl": "https://images.unsplash.com/photo-1677729311005-65d74274e9e9?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "气泡", "蜂蜜", "酸甜", "摇匀", "经典"], "scene": ["聚会", "庆祝", "经典"], "recommendationScore": 88, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "菲兹", "flavor": "酸甜、气泡、蜂蜜", "abv": "中度＞10%～20%", "extra": "香槟补顶的气泡鸡尾酒", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bobby-burns', 'cocktail', 'COCKTAIL', '鲍比·伯恩斯', 'Bobby Burns', 'baobi·boensi', 'bb·bes', '苏格兰威士忌与红味美思等量调和、加少量本笃会利口酒的烈性鸡尾酒，药草与果香平衡，得名于苏格兰诗人罗伯特·彭斯。', '本条目按维基百科标准配比：苏格兰威士忌 45 ml、红味美思 45 ml、本笃会利口酒 3 滴，加冰搅拌后滤入鸡尾酒杯，柠檬皮挤油提香。 背景：原配方见于 1900 年《Fancy Drinks》，名为"Baby Burns"；1908 年起以罗伯特·彭斯之名流传，后逐渐称"Bobby Burns"；1948 年版曾以杜林标替代本笃会。', 'https://images.unsplash.com/photo-1569529465841-dfecdab7503b?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1569529465841-dfecdab7503b?w=1200&q=80&auto=format&fit=crop', 82, 255, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.5}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["威士忌基底", "烈酒主导", "药草", "搅拌", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "威士忌基底", "cocktailType": "烈酒主导", "flavor": "药草、果香、饱满", "abv": "较高＞20%～30%", "extra": "苏格兰威士忌与红味美思等量调和", "scene": ["经典", "餐后"]}', '[{"nameZh": "苏格兰威士忌", "nameEn": "Scotch whisky", "amount": 45, "unit": "ml", "role": "基底"}, {"nameZh": "红味美思", "nameEn": "Red vermouth", "amount": 45, "unit": "ml", "role": "辅料"}, {"nameZh": "本笃会利口酒", "nameEn": "Bénédictine", "amount": 3, "unit": "dash", "role": "药草利口酒"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇鸡尾酒杯。", "搅拌杯加冰，倒入苏格兰威士忌与红味美思。", "加入本笃会利口酒。", "搅拌约 20-30 秒至充分降温。", "滤入冰镇杯，以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-bobby-burns", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "鲍比·伯恩斯", "nameEn": "Bobby Burns", "intro": "苏格兰威士忌与红味美思等量调和、加少量本笃会利口酒的烈性鸡尾酒，药草与果香平衡，得名于苏格兰诗人罗伯特·彭斯。", "imageUrl": "https://images.unsplash.com/photo-1569529465841-dfecdab7503b?w=1200&q=80&auto=format&fit=crop", "tags": ["威士忌基底", "烈酒主导", "药草", "搅拌", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 82, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "烈酒主导", "flavor": "药草、果香、饱满", "abv": "较高＞20%～30%", "extra": "苏格兰威士忌与红味美思等量调和", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-brooklyn', 'cocktail', 'COCKTAIL', '布鲁克林', 'Brooklyn', 'bulukelin', 'blkl', '黑麦威士忌、干味美思、马拉斯奇诺利口酒与苦精调和的曼哈顿变体，微苦中带樱桃果香与皮康的橙皮苦甜。', '本条目按维基百科标准配比：黑麦威士忌 60 ml、干味美思 30 ml、马拉斯奇诺利口酒 7.5 ml、皮康苦精 7.5 ml（或安高天娜苦精数滴），加冰搅拌后滤入鸡尾酒杯，以马拉斯奇诺樱桃装饰。 背景：1910 年由演员兼剧作家 Maurice Hegeman 在布鲁克林大桥旁创制，是纽约五个行政区命名鸡尾酒之一，禁酒令后一度湮没，1990 年代复兴。', 'https://images.unsplash.com/photo-1546540749-3229ce1f48da?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1546540749-3229ce1f48da?w=1200&q=80&auto=format&fit=crop', 84, 256, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.5}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 4.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.5}, {"key": "REFRESHING", "label": "清爽度", "score": 2.5}]', '["黑麦基底", "烈酒主导", "微苦", "搅拌", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "黑麦基底", "cocktailType": "烈酒主导", "flavor": "微苦、樱桃果香、偏干", "abv": "较高＞20%～30%", "extra": "皮康苦精缺货时可用安高天娜替代", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 60, "unit": "ml", "role": "基底"}, {"nameZh": "干味美思", "nameEn": "Dry vermouth", "amount": 30, "unit": "ml", "role": "辅料"}, {"nameZh": "马拉斯奇诺利口酒", "nameEn": "Maraschino liqueur", "amount": 7.5, "unit": "ml", "role": "果味利口酒"}, {"nameZh": "皮康苦精", "nameEn": "Picon (Amer Picon)", "amount": 7.5, "unit": "ml", "role": "苦味利口酒"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino cherry", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇鸡尾酒杯。", "搅拌杯加冰，倒入黑麦威士忌与干味美思。", "加入马拉斯奇诺利口酒与皮康苦精（或安高天娜苦精数滴）。", "搅拌约 20-30 秒至充分降温。", "滤入冰镇杯，以马拉斯奇诺樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-brooklyn", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "布鲁克林", "nameEn": "Brooklyn", "intro": "黑麦威士忌、干味美思、马拉斯奇诺利口酒与苦精调和的曼哈顿变体，微苦中带樱桃果香与皮康的橙皮苦甜。", "imageUrl": "https://images.unsplash.com/photo-1546540749-3229ce1f48da?w=1200&q=80&auto=format&fit=crop", "tags": ["黑麦基底", "烈酒主导", "微苦", "搅拌", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 84, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "烈酒主导", "flavor": "微苦、樱桃果香、偏干", "abv": "较高＞20%～30%", "extra": "皮康苦精缺货时可用安高天娜替代", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-monte-carlo', 'cocktail', 'COCKTAIL', '蒙特卡洛', 'Monte Carlo', 'mengtekaluo', 'mtkl', '黑麦威士忌与本笃会利口酒、苦精调和的曼哈顿变体，蜂蜜般的药草甜感被高浓度黑麦的辛香平衡。', '本条目按业界通行配比：黑麦威士忌 60 ml、本笃会利口酒 15 ml、安高天娜苦精 1-2 滴，加冰搅拌后滤入加冰的岩石杯，以柠檬皮装饰。 背景：最早见于 1948 年 David A. Embury 的《The Fine Art of Mixing Drinks》，以本笃会替代甜味美思，被视为"改良曼哈顿"；Embury 原配方使用更高比例的本笃会，现代版本通常减至 15 ml 以求平衡。', 'https://images.unsplash.com/photo-1679441846341-0d22ac3d10da?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1679441846341-0d22ac3d10da?w=1200&q=80&auto=format&fit=crop', 85, 257, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 3.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.5}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 2.0}]', '["黑麦基底", "古典家族", "蜂蜜药草", "搅拌", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "蜂蜜、药草、辛香", "abv": "高度＞30%", "extra": "本笃会替代甜味美思的改良曼哈顿", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 60, "unit": "ml", "role": "基底"}, {"nameZh": "本笃会利口酒", "nameEn": "Bénédictine", "amount": 15, "unit": "ml", "role": "药草利口酒"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "提香"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["岩石杯中加入大冰块备用。", "搅拌杯加冰，倒入黑麦威士忌与本笃会利口酒。", "加入安高天娜苦精。", "搅拌约 30 秒至充分降温。", "滤入加冰岩石杯，以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-monte-carlo", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "蒙特卡洛", "nameEn": "Monte Carlo", "intro": "黑麦威士忌与本笃会利口酒、苦精调和的曼哈顿变体，蜂蜜般的药草甜感被高浓度黑麦的辛香平衡。", "imageUrl": "https://images.unsplash.com/photo-1679441846341-0d22ac3d10da?w=1200&q=80&auto=format&fit=crop", "tags": ["黑麦基底", "古典家族", "蜂蜜药草", "搅拌", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 85, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "蜂蜜、药草、辛香", "abv": "高度＞30%", "extra": "本笃会替代甜味美思的改良曼哈顿", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jungle-cat', 'cocktail', 'COCKTAIL', '丛林猫', 'Jungle Cat', 'conglinmao', 'clm', '以陈年金酒替代黑朗姆的丛林鸟变体，金巴利的苦甜与菠萝、青柠、枫糖浆的果香交织，热带风情浓郁。', '本条目按 Barr Hill 蒸馏厂官方配比：陈年金酒 45 ml、金巴利 22.5 ml、鲜菠萝汁 45 ml、鲜青柠汁 15 ml、深色枫糖浆 15 ml，加冰摇匀后滤入加碎冰的岩石杯，以菠萝角装饰。 背景：由佛蒙特州 Barr Hill 蒸馏厂首席调酒师 Sam Nelis 创制，以自家橡木桶陈酿的 Tom Cat 金酒命名，是金酒版"丛林鸟"（Jungle Bird）。', 'https://images.unsplash.com/photo-1563223771-375783ee91ad?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1563223771-375783ee91ad?w=1200&q=80&auto=format&fit=crop', 80, 258, '[{"key": "SWEETNESS", "label": "甜度", "score": 5.5}, {"key": "SOURNESS", "label": "酸度", "score": 4.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 4.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 6.0}]', '["金酒基底", "提基", "热带", "苦甜", "菠萝", "摇匀"]', '["夏日", "聚会", "热带风情"]', '{"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "苦甜、菠萝、热带果香", "abv": "中度＞10%～20%", "extra": "丛林鸟的金酒变体", "scene": ["夏日", "聚会", "热带风情"]}', '[{"nameZh": "陈年金酒", "nameEn": "Aged gin", "amount": 45, "unit": "ml", "role": "基底"}, {"nameZh": "金巴利", "nameEn": "Campari", "amount": 22.5, "unit": "ml", "role": "苦味利口酒"}, {"nameZh": "鲜菠萝汁", "nameEn": "Pineapple juice", "amount": 45, "unit": "ml", "role": "果汁"}, {"nameZh": "鲜青柠汁", "nameEn": "Lime juice", "amount": 15, "unit": "ml", "role": "酸味汁"}, {"nameZh": "枫糖浆", "nameEn": "Maple syrup", "amount": 15, "unit": "ml", "role": "甜味剂"}, {"nameZh": "菠萝角", "nameEn": "Pineapple wedge", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶加冰，倒入陈年金酒、金巴利、菠萝汁、青柠汁与枫糖浆。", "用力摇匀约 12-15 秒。", "岩石杯或提基杯加碎冰。", "滤入杯中。", "以菠萝角与樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-jungle-cat", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "丛林猫", "nameEn": "Jungle Cat", "intro": "以陈年金酒替代黑朗姆的丛林鸟变体，金巴利的苦甜与菠萝、青柠、枫糖浆的果香交织，热带风情浓郁。", "imageUrl": "https://images.unsplash.com/photo-1563223771-375783ee91ad?w=1200&q=80&auto=format&fit=crop", "tags": ["金酒基底", "提基", "热带", "苦甜", "菠萝", "摇匀"], "scene": ["夏日", "聚会", "热带风情"], "recommendationScore": 80, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "提基", "flavor": "苦甜、菠萝、热带果香", "abv": "中度＞10%～20%", "extra": "丛林鸟的金酒变体", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-toronto', 'cocktail', 'COCKTAIL', '多伦多', 'Toronto', 'duolunduo', 'dld', '黑麦威士忌与费内特·布兰卡苦酒调和的古典变体，苦甜醇厚、药草气息浓郁，是费内特苦酒最著名的载体。', '本条目按维基百科标准配比：黑麦威士忌 60 ml、费内特·布兰卡 7.5 ml、糖 1/4 茶匙（或糖浆）、安高天娜苦精 1 滴，加冰搅拌后滤入鸡尾酒杯，以橙皮装饰。 背景：最早以"Fernet Cocktail"之名见于 1922 年 Robert Vermeire 的《Cocktails: How to Mix Them》，书中称该酒"深受多伦多加拿大人喜爱"；1930 年起以多伦多鸡尾酒之名流传，是加入费内特的古典鸡尾酒变体。', 'https://images.unsplash.com/photo-1538287816585-a55721195734?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1538287816585-a55721195734?w=1200&q=80&auto=format&fit=crop', 87, 259, '[{"key": "SWEETNESS", "label": "甜度", "score": 3.0}, {"key": "SOURNESS", "label": "酸度", "score": 1.0}, {"key": "BITTERNESS", "label": "苦度", "score": 5.5}, {"key": "ALCOHOL", "label": "酒精感", "score": 7.0}, {"key": "BODY", "label": "酒体", "score": 4.5}, {"key": "REFRESHING", "label": "清爽度", "score": 2.5}]', '["黑麦基底", "古典家族", "苦甜", "药草", "搅拌", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦甜、药草、醇厚", "abv": "高度＞30%", "extra": "费内特·布兰卡赋予标志性苦味", "scene": ["经典", "餐后"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye whiskey", "amount": 60, "unit": "ml", "role": "基底"}, {"nameZh": "费内特·布兰卡", "nameEn": "Fernet-Branca", "amount": 7.5, "unit": "ml", "role": "苦味利口酒"}, {"nameZh": "细砂糖", "nameEn": "Sugar", "amount": 1, "unit": "g", "role": "甜味剂"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "提香"}, {"nameZh": "橙皮", "nameEn": "Orange peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇鸡尾酒杯。", "搅拌杯加冰，倒入黑麦威士忌与费内特·布兰卡。", "加入糖与安高天娜苦精。", "搅拌约 20-30 秒至充分降温。", "滤入冰镇杯，以橙皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-toronto", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "多伦多", "nameEn": "Toronto", "intro": "黑麦威士忌与费内特·布兰卡苦酒调和的古典变体，苦甜醇厚、药草气息浓郁，是费内特苦酒最著名的载体。", "imageUrl": "https://images.unsplash.com/photo-1538287816585-a55721195734?w=1200&q=80&auto=format&fit=crop", "tags": ["黑麦基底", "古典家族", "苦甜", "药草", "搅拌", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 87, "attributes": {"baseSpirit": "黑麦基底", "cocktailType": "古典家族", "flavor": "苦甜、药草、醇厚", "abv": "高度＞30%", "extra": "费内特·布兰卡赋予标志性苦味", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-lions-tail', 'cocktail', 'COCKTAIL', '狮尾', 'Lions Tail', 'shiwei', 'sw', '波本威士忌、多香果利口酒与青柠汁调和的禁酒令时期酸酒，辛香料与热带果酸交织，得名于"twisting the lion\'s tail"俗语。', '本条目按业界通行配比：波本威士忌 60 ml、多香果利口酒 15 ml、鲜青柠汁 15 ml、简单糖浆 5 ml、安高天娜苦精 1-2 滴，加冰摇匀后滤入鸡尾酒杯。 背景：最早见于 1937 年伦敦《Café Royal Cocktail Book》，食谱署名 L.A. Clarke；名字取自挑衅英国人的美国俗语"twisting the lion\'s tail"，2000 年代末经 Ted Haigh 著作再版后复兴。', 'https://images.unsplash.com/photo-1578554109124-40bc961c97a9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1578554109124-40bc961c97a9?w=1200&q=80&auto=format&fit=crop', 86, 260, '[{"key": "SWEETNESS", "label": "甜度", "score": 4.0}, {"key": "SOURNESS", "label": "酸度", "score": 3.5}, {"key": "BITTERNESS", "label": "苦度", "score": 4.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 6.0}, {"key": "BODY", "label": "酒体", "score": 4.0}, {"key": "REFRESHING", "label": "清爽度", "score": 4.0}]', '["波本基底", "酸型鸡尾酒", "辛香料", "摇匀", "禁酒令时期", "经典"]', '["经典", "餐后"]', '{"baseSpirit": "波本基底", "cocktailType": "酸型鸡尾酒", "flavor": "辛香、果酸、微苦", "abv": "较高＞20%～30%", "extra": "牙买加多香果利口酒是风味核心", "scene": ["经典", "餐后"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon whiskey", "amount": 60, "unit": "ml", "role": "基底"}, {"nameZh": "多香果利口酒", "nameEn": "Allspice dram (pimento dram)", "amount": 15, "unit": "ml", "role": "辛香利口酒"}, {"nameZh": "鲜青柠汁", "nameEn": "Lime juice", "amount": 15, "unit": "ml", "role": "酸味汁"}, {"nameZh": "简单糖浆", "nameEn": "Simple syrup", "amount": 5, "unit": "ml", "role": "甜味剂"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura bitters", "amount": 2, "unit": "dash", "role": "提香"}, {"nameZh": "柠檬皮", "nameEn": "Lemon peel", "amount": 1, "unit": "piece", "role": "装饰，挤油提香"}]', '["冰镇鸡尾酒杯。", "摇酒壶加冰，倒入波本、多香果利口酒与青柠汁。", "加入简单糖浆与安高天娜苦精。", "用力摇匀约 12-15 秒。", "滤入冰镇杯，以柠檬皮挤油装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-lions-tail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "狮尾", "nameEn": "Lions Tail", "intro": "波本威士忌、多香果利口酒与青柠汁调和的禁酒令时期酸酒，辛香料与热带果酸交织，得名于”twisting the lion\'s tail”俗语。", "imageUrl": "https://images.unsplash.com/photo-1578554109124-40bc961c97a9?w=1200&q=80&auto=format&fit=crop", "tags": ["波本基底", "酸型鸡尾酒", "辛香料", "摇匀", "禁酒令时期", "经典"], "scene": ["经典", "餐后"], "recommendationScore": 86, "attributes": {"baseSpirit": "波本基底", "cocktailType": "酸型鸡尾酒", "flavor": "辛香、果酸、微苦", "abv": "较高＞20%～30%", "extra": "牙买加多香果利口酒是风味核心", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-navy-grog', 'cocktail', 'COCKTAIL', '海军格罗格', 'Navy Grog', 'haijungeluoge', 'hjglg', '三种朗姆酒叠加青柠汁、葡萄柚汁与蜂蜜的三重朗姆鸡尾酒，Tiki 文化的经典代表，曾在 Don the Beachcomber 餐厅风靡数十年。', '本条目采用 Don the Beachcomber 原版配比：金德梅拉拉朗姆、牙买加深色朗姆、古巴白朗姆各 30 ml，配 22 ml 青柠汁、22 ml 白葡萄柚汁、22 ml 苏打水与 30 ml 蜂蜜液（1:1 蜂蜜与水），摇匀滤入碎冰杯。背景：Donn Beach 于 1940 年代创制，是 Tiki 风潮中最具代表性的朗姆饮之一，菜单曾限每人两至三杯。', 'https://images.unsplash.com/photo-1587145990254-e0f1b1733b95?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1587145990254-e0f1b1733b95?w=1200&q=80&auto=format&fit=crop', 90, 247, '[{"key": "SWEETNESS", "label": "甜度", "score": 6}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 2}, {"key": "ALCOHOL", "label": "酒精感", "score": 7}, {"key": "BODY", "label": "酒体", "score": 5}, {"key": "REFRESHING", "label": "清爽度", "score": 7}]', '["朗姆基底", "三重朗姆", "Tiki 风格", "果味", "热带", "长饮", "经典"]', '["聚会", "热带风情", "经典"]', '{"baseSpirit": "朗姆基底", "cocktailType": "长饮/果味鸡尾酒", "flavor": "果香、蜂蜜、热带", "abv": "中度15-25%", "extra": "蜂蜜液与苏打水", "scene": ["聚会", "热带风情", "经典"]}', '[{"nameZh": "金德梅拉拉朗姆", "nameEn": "Gold Demerara Rum", "amount": 30, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "牙买加深色朗姆", "nameEn": "Dark Jamaican Rum", "amount": 30, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "古巴白朗姆", "nameEn": "White Rum", "amount": 30, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22, "unit": "ml", "role": "酸味来源"}, {"nameZh": "白葡萄柚汁", "nameEn": "White Grapefruit Juice", "amount": 22, "unit": "ml", "role": "果味来源"}, {"nameZh": "苏打水", "nameEn": "Club Soda", "amount": 22, "unit": "ml", "role": "气泡口感"}, {"nameZh": "蜂蜜液（1:1 蜂蜜与水）", "nameEn": "Honey Mix (1:1)", "amount": 30, "unit": "ml", "role": "甜味来源"}]', '["摇酒壶加冰，倒入三种朗姆酒、青柠汁、葡萄柚汁、苏打水与蜂蜜液。", "充分摇匀约 15 秒至完全冷却。", "滤入装满碎冰的宽底老式杯中。", "以薄荷枝或青柠角装饰，插入吸管饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-navy-grog", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "海军格罗格", "nameEn": "Navy Grog", "intro": "三种朗姆酒叠加青柠汁、葡萄柚汁与蜂蜜的三重朗姆鸡尾酒，Tiki 文化的经典代表，曾在 Don the Beachcomber 餐厅风靡数十年。", "imageUrl": "https://images.unsplash.com/photo-1587145990254-e0f1b1733b95?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "三重朗姆", "Tiki 风格", "果味", "热带", "长饮", "经典"], "scene": ["聚会", "热带风情", "经典"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "长饮/果味鸡尾酒", "flavor": "果香、蜂蜜、热带", "abv": "中度15-25%", "extra": "蜂蜜液与苏打水", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-ward-8', 'cocktail', 'COCKTAIL', '第八区', 'Ward 8', 'dibaqu', 'dbq', '以黑麦威士忌为基底、融合柠檬汁、橙汁与石榴糖浆的波士顿经典酸酒，诞生于 1898 年的 Locke-Ober 餐厅。', '本条目采用 Locke-Ober 餐厅复业时的经典配比：60 ml 黑麦威士忌、15 ml 柠檬汁、15 ml 橙汁、5 ml 石榴糖浆，摇匀滤入冰镇鸡尾酒杯，以马拉斯奇诺樱桃装饰。背景：1898 年为庆祝波士顿第八选区（Ward 8）政治人物 Martin Lomasney 当选而创制，是波士顿政坛与餐厅历史交织的经典代表。', 'https://images.unsplash.com/photo-1609951651556-5334e2706168?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1609951651556-5334e2706168?w=1200&q=80&auto=format&fit=crop', 89, 248, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 3}, {"key": "ALCOHOL", "label": "酒精感", "score": 6}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 5}]', '["威士忌基底", "黑麦威士忌", "酸酒", "果味", "经典", "摇匀"]', '["经典", "怀旧", "商务"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸酒风格", "flavor": "果香、酸甜平衡", "abv": "中度15-25%", "extra": "石榴糖浆增色", "scene": ["经典", "怀旧", "商务"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye Whiskey", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 15, "unit": "ml", "role": "酸味来源"}, {"nameZh": "橙汁", "nameEn": "Fresh Orange Juice", "amount": 15, "unit": "ml", "role": "果味来源"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 5, "unit": "ml", "role": "甜味与色泽"}, {"nameZh": "马拉斯奇诺樱桃", "nameEn": "Maraschino Cherry", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇鸡尾酒杯备用。", "摇酒壶加冰，倒入黑麦威士忌、柠檬汁、橙汁与石榴糖浆。", "用力摇匀约 15 秒至充分冷却。", "滤入冰镇鸡尾酒杯。", "以马拉斯奇诺樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-ward-8", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "第八区", "nameEn": "Ward 8", "intro": "以黑麦威士忌为基底、融合柠檬汁、橙汁与石榴糖浆的波士顿经典酸酒，诞生于 1898 年的 Locke-Ober 餐厅。", "imageUrl": "https://images.unsplash.com/photo-1609951651556-5334e2706168?w=1200&q=80&auto=format&fit=crop", "tags": ["威士忌基底", "黑麦威士忌", "酸酒", "果味", "经典", "摇匀"], "scene": ["经典", "怀旧", "商务"], "recommendationScore": 89, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸酒风格", "flavor": "果香、酸甜平衡", "abv": "中度15-25%", "extra": "石榴糖浆增色", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-jack-rose', 'cocktail', 'COCKTAIL', '杰克玫瑰', 'Jack Rose', 'jiekemeigui', 'jkmg', '苹果白兰地、石榴糖浆与柠檬汁构成的粉色经典鸡尾酒，1920-30 年代盛行，亦是海明威笔下的标志性饮品。', '本条目采用传统比例：苹果白兰地与柠檬汁按 4:1、石榴糖浆按半份配比（即 60 ml 苹果白兰地、15 ml 柠檬汁、7.5 ml 石榴糖浆），摇匀滤入冰镇鸡尾酒杯并以柠檬皮装饰。背景：1920-30 年代广受欢迎，海明威《太阳照常升起》中 Jake Barnes 在巴黎喝的就是它，亦被 David Embury 列为六大基本鸡尾酒之一。', 'https://images.unsplash.com/photo-1563223771-5fe4038fbfc9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1563223771-5fe4038fbfc9?w=1200&q=80&auto=format&fit=crop', 88, 249, '[{"key": "SWEETNESS", "label": "甜度", "score": 6}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 2}, {"key": "ALCOHOL", "label": "酒精感", "score": 7}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 5}]', '["苹果白兰地基底", "粉色", "果味", "经典", "摇匀"]', '["经典", "文艺", "独酌"]', '{"baseSpirit": "苹果白兰地基底", "cocktailType": "烈酒果味", "flavor": "苹果、石榴、微酸", "abv": "中度15-25%", "extra": "石榴糖浆呈粉色", "scene": ["经典", "文艺", "独酌"]}', '[{"nameZh": "苹果白兰地", "nameEn": "Applejack", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 15, "unit": "ml", "role": "酸味来源"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 7.5, "unit": "ml", "role": "甜味与色泽"}, {"nameZh": "柠檬皮", "nameEn": "Lemon Peel", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇鸡尾酒杯备用。", "摇酒壶加冰，倒入苹果白兰地、柠檬汁与石榴糖浆。", "摇匀约 15 秒至充分冷却。", "滤入冰镇鸡尾酒杯。", "挤柠檬皮油提香后投入装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-jack-rose", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "杰克玫瑰", "nameEn": "Jack Rose", "intro": "苹果白兰地、石榴糖浆与柠檬汁构成的粉色经典鸡尾酒，1920-30 年代盛行，亦是海明威笔下的标志性饮品。", "imageUrl": "https://images.unsplash.com/photo-1563223771-5fe4038fbfc9?w=1200&q=80&auto=format&fit=crop", "tags": ["苹果白兰地基底", "粉色", "果味", "经典", "摇匀"], "scene": ["经典", "文艺", "独酌"], "recommendationScore": 88, "attributes": {"baseSpirit": "苹果白兰地基底", "cocktailType": "烈酒果味", "flavor": "苹果、石榴、微酸", "abv": "中度15-25%", "extra": "石榴糖浆呈粉色", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-fog-cutter', 'cocktail', 'COCKTAIL', '迷雾切割', 'Fog Cutter', 'miwuqiege', 'mwqg', '朗姆、白兰地与金酒三烈酒叠加柠檬橙汁与杏仁糖浆的强力 Tiki 长饮，顶部漂浮雪莉酒，被誉为「Tiki 界的长岛冰茶」。', '本条目采用 Trader Vic 1947 年《Bartender\'s Guide》配比：60 ml 淡朗姆、30 ml 白兰地、15 ml 金酒、60 ml 柠檬汁、30 ml 橙汁、15 ml 杏仁糖浆，摇匀后加冰注入杯中，再浮一层 15 ml 奶油雪莉。背景：Victor Bergeron 的经典 Tiki 作品，酒精度高，历史菜单上注明一人限两杯。', 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=1200&q=80&auto=format&fit=crop', 91, 250, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 2}, {"key": "ALCOHOL", "label": "酒精感", "score": 8}, {"key": "BODY", "label": "酒体", "score": 5}, {"key": "REFRESHING", "label": "清爽度", "score": 6}]', '["朗姆基底", "多烈酒", "Tiki 风格", "雪莉漂浮", "长饮", "果味", "经典"]', '["聚会", "热带风情", "夏日"]', '{"baseSpirit": "朗姆基底", "cocktailType": "长饮/多烈酒", "flavor": "热带果香、坚果雪莉", "abv": "高度＞30%", "extra": "奶油雪莉漂浮", "scene": ["聚会", "热带风情", "夏日"]}', '[{"nameZh": "淡朗姆", "nameEn": "Light Rum", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "白兰地", "nameEn": "Brandy", "amount": 30, "unit": "ml", "role": "第二烈酒"}, {"nameZh": "金酒", "nameEn": "Gin", "amount": 15, "unit": "ml", "role": "第三烈酒"}, {"nameZh": "柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 60, "unit": "ml", "role": "酸味来源"}, {"nameZh": "橙汁", "nameEn": "Fresh Orange Juice", "amount": 30, "unit": "ml", "role": "果味来源"}, {"nameZh": "杏仁糖浆", "nameEn": "Orgeat Syrup", "amount": 15, "unit": "ml", "role": "甜味来源"}, {"nameZh": "奶油雪莉", "nameEn": "Cream Sherry", "amount": 15, "unit": "ml", "role": "漂浮层"}]', '["摇酒壶加冰，倒入淡朗姆、白兰地、金酒、柠檬汁、橙汁与杏仁糖浆。", "摇匀约 15 秒至充分冷却。", "滤入加碎冰的 Fog Cutter 马克杯或高脚杯。", "沿表面缓缓倒入奶油雪莉使其漂浮。", "以薄荷枝或橙角装饰，插入吸管饮用。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-fog-cutter", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "迷雾切割", "nameEn": "Fog Cutter", "intro": "朗姆、白兰地与金酒三烈酒叠加柠檬橙汁与杏仁糖浆的强力 Tiki 长饮，顶部漂浮雪莉酒，被誉为「Tiki 界的长岛冰茶」。", "imageUrl": "https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "多烈酒", "Tiki 风格", "雪莉漂浮", "长饮", "果味", "经典"], "scene": ["聚会", "热带风情", "夏日"], "recommendationScore": 91, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "长饮/多烈酒", "flavor": "热带果香、坚果雪莉", "abv": "高度＞30%", "extra": "奶油雪莉漂浮", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-el-presidente', 'cocktail', 'COCKTAIL', '总统先生', 'El Presidente', 'zongtongxiansheng', 'ztxs', '白朗姆与白味美思等量对半、佐以橙皮利口酒与石榴糖浆的古巴经典鸡尾酒，1920-40 年代哈瓦那上流社会的标志饮品。', '本条目采用维基百科 infobox 传统比例：白朗姆与白味美思各 45 ml、5 ml 橙皮利口酒（curaçao）、2.5 ml 石榴糖浆，搅拌后滤入冰镇鸡尾酒杯并以橙皮装饰。背景：1920-40 年代美国禁酒令期间在哈瓦那成名，成为古巴上层阶级最爱的鸡尾酒，或以古巴总统（Menocal 或 Machado）之名命名。', 'https://images.unsplash.com/photo-1624487394217-6d192d003564?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1624487394217-6d192d003564?w=1200&q=80&auto=format&fit=crop', 90, 251, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 2}, {"key": "BITTERNESS", "label": "苦度", "score": 3}, {"key": "ALCOHOL", "label": "酒精感", "score": 7}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 4}]', '["朗姆基底", "古巴风情", "搅拌", "果味", "药草", "经典"]', '["经典", "优雅", "晚餐"]', '{"baseSpirit": "朗姆基底", "cocktailType": "烈酒主导", "flavor": "甜润、草药、柑橘", "abv": "中度15-25%", "extra": "白味美思对半", "scene": ["经典", "优雅", "晚餐"]}', '[{"nameZh": "白朗姆", "nameEn": "White Rum", "amount": 45, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "白味美思", "nameEn": "Blanc Vermouth", "amount": 45, "unit": "ml", "role": "草药风味"}, {"nameZh": "橙皮利口酒", "nameEn": "Curaçao", "amount": 5, "unit": "ml", "role": "柑橘风味"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 2.5, "unit": "ml", "role": "甜味与色泽"}, {"nameZh": "橙皮", "nameEn": "Orange Peel", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇鸡尾酒杯备用。", "搅拌杯加冰，倒入白朗姆、白味美思、橙皮利口酒与石榴糖浆。", "搅拌约 20 秒至充分冷却。", "滤入冰镇鸡尾酒杯。", "挤橙皮油提香后投入装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-el-presidente", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "总统先生", "nameEn": "El Presidente", "intro": "白朗姆与白味美思等量对半、佐以橙皮利口酒与石榴糖浆的古巴经典鸡尾酒，1920-40 年代哈瓦那上流社会的标志饮品。", "imageUrl": "https://images.unsplash.com/photo-1624487394217-6d192d003564?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "古巴风情", "搅拌", "果味", "药草", "经典"], "scene": ["经典", "优雅", "晚餐"], "recommendationScore": 90, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "烈酒主导", "flavor": "甜润、草药、柑橘", "abv": "中度15-25%", "extra": "白味美思对半", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-army-navy', 'cocktail', 'COCKTAIL', '陆海军', 'Army & Navy', 'luhaijun', 'lhj', '金酒、柠檬汁、杏仁糖浆与安高天娜苦精构成的干爽酸酒，经 David Embury 著作收录成为经典金酒代表。', '本条目采用现代标准配比（金酒:柠檬汁:杏仁糖浆 = 8:3:2）：60 ml 伦敦干金酒、22.5 ml 柠檬汁、15 ml 杏仁糖浆、2 dash 安高天娜苦精，摇匀滤入冰镇杯并以柠檬皮装饰。背景：经典金酒酸酒，最早出现于 David Embury 1948 年《The Fine Art of Mixing Drinks》，Embury 偏爱干爽的金酒主导版本。', 'https://images.unsplash.com/photo-1524704055514-dc539e83c899?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1524704055514-dc539e83c899?w=1200&q=80&auto=format&fit=crop', 87, 252, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 3}, {"key": "ALCOHOL", "label": "酒精感", "score": 7}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 5}]', '["金酒基底", "酸酒", "杏仁糖浆", "摇匀", "经典", "草本"]', '["经典", "独酌", "商务"]', '{"baseSpirit": "金酒基底", "cocktailType": "酸酒风格", "flavor": "草本、杏仁、酸甜", "abv": "中度15-25%", "extra": "杏仁糖浆增香", "scene": ["经典", "独酌", "商务"]}', '[{"nameZh": "伦敦干金酒", "nameEn": "London Dry Gin", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "酸味来源"}, {"nameZh": "杏仁糖浆", "nameEn": "Orgeat Syrup", "amount": 15, "unit": "ml", "role": "甜味来源"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "香料苦味"}]', '["冰镇鸡尾酒杯或 coupe 杯备用。", "摇酒壶加冰，倒入金酒、柠檬汁、杏仁糖浆与苦精。", "用力摇匀约 15 秒至充分冷却。", "滤入冰镇杯。", "以柠檬皮挤油提香后装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-army-navy", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "陆海军", "nameEn": "Army & Navy", "intro": "金酒、柠檬汁、杏仁糖浆与安高天娜苦精构成的干爽酸酒，经 David Embury 著作收录成为经典金酒代表。", "imageUrl": "https://images.unsplash.com/photo-1524704055514-dc539e83c899?w=1200&q=80&auto=format&fit=crop", "tags": ["金酒基底", "酸酒", "杏仁糖浆", "摇匀", "经典", "草本"], "scene": ["经典", "独酌", "商务"], "recommendationScore": 87, "attributes": {"baseSpirit": "金酒基底", "cocktailType": "酸酒风格", "flavor": "草本、杏仁、酸甜", "abv": "中度15-25%", "extra": "杏仁糖浆增香", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-royal-bermuda-yacht-club', 'cocktail', 'COCKTAIL', '皇家百慕大游艇俱乐部', 'Royal Bermuda Yacht Club', 'huangjiabaimudayoutingjulebu', 'hjbmdytjlb', '陈年巴巴多斯朗姆、青柠汁、君度与法勒南构成的达奇利变体，1940 年代起以百慕大皇家游艇俱乐部命名。', '本条目采用业界主流配比：60 ml 陈年巴巴多斯朗姆、22.5 ml 青柠汁、7.5 ml 君度橙酒、15 ml 法勒南香料糖浆，摇匀滤入冰镇 coupe 杯并以青柠轮装饰。背景：1940 年代末的经典达奇利变体，以百慕大皇家游艇俱乐部命名（该款 1941 年起有记载），用君度与法勒南替代普通糖浆。', 'https://images.unsplash.com/photo-1630541010111-1bd604c9aba2?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1630541010111-1bd604c9aba2?w=1200&q=80&auto=format&fit=crop', 88, 253, '[{"key": "SWEETNESS", "label": "甜度", "score": 6}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 2}, {"key": "ALCOHOL", "label": "酒精感", "score": 6}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 6}]', '["朗姆基底", "达奇利变体", "青柠", "香料", "摇匀", "经典"]', '["经典", "夏日", "海边"]', '{"baseSpirit": "朗姆基底", "cocktailType": "酸酒风格", "flavor": "朗姆、香料、柑橘", "abv": "中度15-25%", "extra": "法勒南香料糖浆", "scene": ["经典", "夏日", "海边"]}', '[{"nameZh": "陈年巴巴多斯朗姆", "nameEn": "Aged Barbados Rum", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22.5, "unit": "ml", "role": "酸味来源"}, {"nameZh": "君度橙酒", "nameEn": "Cointreau", "amount": 7.5, "unit": "ml", "role": "柑橘甜味"}, {"nameZh": "法勒南糖浆", "nameEn": "Falernum", "amount": 15, "unit": "ml", "role": "香料风味"}]', '["冰镇 coupe 杯备用。", "摇酒壶加冰，倒入陈年朗姆、青柠汁、君度与法勒南。", "摇匀约 15 秒至充分冷却。", "滤入冰镇 coupe 杯。", "以青柠轮装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-royal-bermuda-yacht-club", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "皇家百慕大游艇俱乐部", "nameEn": "Royal Bermuda Yacht Club", "intro": "陈年巴巴多斯朗姆、青柠汁、君度与法勒南构成的达奇利变体，1940 年代起以百慕大皇家游艇俱乐部命名。", "imageUrl": "https://images.unsplash.com/photo-1630541010111-1bd604c9aba2?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "达奇利变体", "青柠", "香料", "摇匀", "经典"], "scene": ["经典", "夏日", "海边"], "recommendationScore": 88, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "酸酒风格", "flavor": "朗姆、香料、柑橘", "abv": "中度15-25%", "extra": "法勒南香料糖浆", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-scofflaw', 'cocktail', 'COCKTAIL', '逍遥法外', 'Scofflaw', 'xiaoyaofawai', 'xyfw', '黑麦威士忌、干味美思、柠檬汁与石榴糖浆构成的禁酒令时期巴黎经典，名字意为「藐视法律者」。', '本条目采用业界主流配比：60 ml 黑麦威士忌、30 ml 干味美思、22.5 ml 柠檬汁、15 ml 石榴糖浆、2 dash 橙味苦精，摇匀滤入冰镇杯并以橙皮装饰。背景：1924 年创制于巴黎 Harry\'s New York Bar，以禁酒令时期的「scofflaw」（藐视法律者）一词命名，是禁酒令文化最有名的纪念性鸡尾酒之一。', 'https://images.unsplash.com/photo-1679441846341-0d22ac3d10da?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1679441846341-0d22ac3d10da?w=1200&q=80&auto=format&fit=crop', 89, 254, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 3}, {"key": "ALCOHOL", "label": "酒精感", "score": 7}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 4}]', '["威士忌基底", "黑麦威士忌", "酸酒", "禁酒令时期", "经典"]', '["经典", "怀旧", "晚餐"]', '{"baseSpirit": "威士忌基底", "cocktailType": "酸酒风格", "flavor": "辛香、石榴、微苦", "abv": "中度15-25%", "extra": "干味美思与苦精", "scene": ["经典", "怀旧", "晚餐"]}', '[{"nameZh": "黑麦威士忌", "nameEn": "Rye Whiskey", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "干味美思", "nameEn": "Dry Vermouth", "amount": 30, "unit": "ml", "role": "草药风味"}, {"nameZh": "柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 22.5, "unit": "ml", "role": "酸味来源"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 15, "unit": "ml", "role": "甜味与色泽"}, {"nameZh": "橙味苦精", "nameEn": "Orange Bitters", "amount": 2, "unit": "dash", "role": "柑橘苦味"}]', '["冰镇鸡尾酒杯备用。", "摇酒壶加冰，倒入黑麦威士忌、干味美思、柠檬汁、石榴糖浆与橙味苦精。", "用力摇匀约 15 秒。", "滤入冰镇鸡尾酒杯。", "以橙皮挤油提香后装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-scofflaw", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "逍遥法外", "nameEn": "Scofflaw", "intro": "黑麦威士忌、干味美思、柠檬汁与石榴糖浆构成的禁酒令时期巴黎经典，名字意为「藐视法律者」。", "imageUrl": "https://images.unsplash.com/photo-1679441846341-0d22ac3d10da?w=1200&q=80&auto=format&fit=crop", "tags": ["威士忌基底", "黑麦威士忌", "酸酒", "禁酒令时期", "经典"], "scene": ["经典", "怀旧", "晚餐"], "recommendationScore": 89, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "酸酒风格", "flavor": "辛香、石榴、微苦", "abv": "中度15-25%", "extra": "干味美思与苦精", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-mexican-firing-squad', 'cocktail', 'COCKTAIL', '墨西哥行刑队', 'Mexican Firing Squad', 'moxigexingxingdui', 'mxgxxd', '银龙舌兰、石榴糖浆与青柠汁加安高天娜苦精的酸甜龙舌兰经典，可加苏打水制成清爽长饮。', '本条目采用现代标准配比：60 ml 银龙舌兰、22.5 ml 青柠汁、22.5 ml 石榴糖浆、2 dash 安高天娜苦精，摇匀后滤入加冰杯，可按需加 60 ml 苏打水提升清爽度。背景：1939 年 Charles H. Baker 在《The Gentleman\'s Companion》中记录，源自墨西哥城 La Cucaracha 酒吧，是龙舌兰酸甜酒的代表作。', 'https://images.unsplash.com/photo-1608635360956-5ebde7952ed6?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1608635360956-5ebde7952ed6?w=1200&q=80&auto=format&fit=crop', 88, 255, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 2}, {"key": "ALCOHOL", "label": "酒精感", "score": 6}, {"key": "BODY", "label": "酒体", "score": 3}, {"key": "REFRESHING", "label": "清爽度", "score": 7}]', '["龙舌兰基底", "酸酒", "石榴", "清爽", "摇匀", "经典"]', '["夏日", "聚会", "开胃"]', '{"baseSpirit": "龙舌兰基底", "cocktailType": "酸酒风格", "flavor": "石榴、青柠、植物气息", "abv": "中度15-25%", "extra": "可加苏打水", "scene": ["夏日", "聚会", "开胃"]}', '[{"nameZh": "银龙舌兰", "nameEn": "Blanco Tequila", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "青柠汁", "nameEn": "Fresh Lime Juice", "amount": 22.5, "unit": "ml", "role": "酸味来源"}, {"nameZh": "石榴糖浆", "nameEn": "Grenadine", "amount": 22.5, "unit": "ml", "role": "甜味与色泽"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "香料苦味"}, {"nameZh": "苏打水", "nameEn": "Soda Water", "amount": 60, "unit": "ml", "role": "气泡口感（可选）"}]', '["摇酒壶加冰，倒入银龙舌兰、青柠汁、石榴糖浆与苦精。", "摇匀约 15 秒至充分冷却。", "滤入装满冰块的高球杯。", "加苏打水至顶部并轻搅融合。", "以青柠角装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-mexican-firing-squad", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "墨西哥行刑队", "nameEn": "Mexican Firing Squad", "intro": "银龙舌兰、石榴糖浆与青柠汁加安高天娜苦精的酸甜龙舌兰经典，可加苏打水制成清爽长饮。", "imageUrl": "https://images.unsplash.com/photo-1608635360956-5ebde7952ed6?w=1200&q=80&auto=format&fit=crop", "tags": ["龙舌兰基底", "酸酒", "石榴", "清爽", "摇匀", "经典"], "scene": ["夏日", "聚会", "开胃"], "recommendationScore": 88, "attributes": {"baseSpirit": "龙舌兰基底", "cocktailType": "酸酒风格", "flavor": "石榴、青柠、植物气息", "abv": "中度15-25%", "extra": "可加苏打水", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-japanese-cocktail', 'cocktail', 'COCKTAIL', '日式鸡尾酒', 'Japanese Cocktail', 'rishijiweijiu', 'rsjwj', '干邑与杏仁糖浆配安高天娜苦精的十九世纪经典，由「教授」Jerry Thomas 收录于 1862 年著作，虽名「日式」却不含任何日本成分。', '本条目采用经典配比：60 ml 干邑、15 ml 杏仁糖浆、2 dash 安高天娜苦精，搅拌后滤入冰镇鸡尾酒杯，以柠檬皮装饰。背景：Jerry Thomas 1862 年《How to Mix Drinks》收录，据传以 1860 年访问纽约的日本使团命名，是干邑与杏仁糖浆的经典组合。', 'https://images.unsplash.com/photo-1775379995552-221458bf0be4?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1775379995552-221458bf0be4?w=1200&q=80&auto=format&fit=crop', 86, 256, '[{"key": "SWEETNESS", "label": "甜度", "score": 7}, {"key": "SOURNESS", "label": "酸度", "score": 1}, {"key": "BITTERNESS", "label": "苦度", "score": 3}, {"key": "ALCOHOL", "label": "酒精感", "score": 8}, {"key": "BODY", "label": "酒体", "score": 5}, {"key": "REFRESHING", "label": "清爽度", "score": 3}]', '["干邑基底", "搅拌", "杏仁糖浆", "经典", "十九世纪"]', '["经典", "餐后", "独酌"]', '{"baseSpirit": "干邑基底", "cocktailType": "烈酒主导", "flavor": "坚果、蜜感、微苦", "abv": "高度＞30%", "extra": "无果汁成分", "scene": ["经典", "餐后", "独酌"]}', '[{"nameZh": "干邑", "nameEn": "Cognac", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "杏仁糖浆", "nameEn": "Orgeat Syrup", "amount": 15, "unit": "ml", "role": "甜味来源"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura Bitters", "amount": 2, "unit": "dash", "role": "香料苦味"}, {"nameZh": "柠檬皮", "nameEn": "Lemon Peel", "amount": 1, "unit": "piece", "role": "装饰"}]', '["冰镇鸡尾酒杯备用。", "搅拌杯加冰，倒入干邑、杏仁糖浆与苦精。", "搅拌约 30 秒至充分降温。", "滤入冰镇鸡尾酒杯。", "以柠檬皮挤油提香后装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-japanese-cocktail", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "日式鸡尾酒", "nameEn": "Japanese Cocktail", "intro": "干邑与杏仁糖浆配安高天娜苦精的十九世纪经典，由「教授」Jerry Thomas 收录于 1862 年著作，虽名「日式」却不含任何日本成分。", "imageUrl": "https://images.unsplash.com/photo-1775379995552-221458bf0be4?w=1200&q=80&auto=format&fit=crop", "tags": ["干邑基底", "搅拌", "杏仁糖浆", "经典", "十九世纪"], "scene": ["经典", "餐后", "独酌"], "recommendationScore": 86, "attributes": {"baseSpirit": "干邑基底", "cocktailType": "烈酒主导", "flavor": "坚果、蜜感、微苦", "abv": "高度＞30%", "extra": "无果汁成分", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-bourbon-smash', 'cocktail', 'COCKTAIL', '波本碎冰', 'Bourbon Smash', 'bobensuibing', 'bbsb', '波本威士忌捣碎新鲜薄荷与柠檬、配糖浆摇匀的碎冰饮品，介于薄荷朱利普与威士忌酸酒之间的夏日经典。', '本条目采用业界标准配比：60 ml 波本威士忌、30 ml 柠檬汁、22.5 ml 糖浆，与 8-10 片新鲜薄荷一同捣碎后摇匀，滤入加碎冰杯并以薄荷枝装饰。背景：属于经典 Smash 家族（与薄荷朱利普同源），以捣碎（muddle）新鲜薄荷的方式萃取香气，是美式清凉鸡尾酒的代表。', 'https://images.unsplash.com/photo-1591634447477-5197ab46ce13?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1591634447477-5197ab46ce13?w=1200&q=80&auto=format&fit=crop', 90, 257, '[{"key": "SWEETNESS", "label": "甜度", "score": 5}, {"key": "SOURNESS", "label": "酸度", "score": 4}, {"key": "BITTERNESS", "label": "苦度", "score": 2}, {"key": "ALCOHOL", "label": "酒精感", "score": 7}, {"key": "BODY", "label": "酒体", "score": 4}, {"key": "REFRESHING", "label": "清爽度", "score": 7}]', '["威士忌基底", "波本", "薄荷", "碎冰", "清爽", "捣碎", "夏日"]', '["夏日", "聚会", "户外"]', '{"baseSpirit": "威士忌基底", "cocktailType": "碎冰清爽型", "flavor": "薄荷、柠檬、焦糖", "abv": "中度15-25%", "extra": "新鲜薄荷捣碎", "scene": ["夏日", "聚会", "户外"]}', '[{"nameZh": "波本威士忌", "nameEn": "Bourbon Whiskey", "amount": 60, "unit": "ml", "role": "基础烈酒"}, {"nameZh": "柠檬汁", "nameEn": "Fresh Lemon Juice", "amount": 30, "unit": "ml", "role": "酸味来源"}, {"nameZh": "糖浆", "nameEn": "Simple Syrup", "amount": 22.5, "unit": "ml", "role": "甜味来源"}, {"nameZh": "新鲜薄荷叶", "nameEn": "Fresh Mint Leaves", "amount": 8, "unit": "piece", "role": "捣碎提香"}, {"nameZh": "薄荷枝", "nameEn": "Mint Sprig", "amount": 1, "unit": "piece", "role": "装饰"}]', '["摇酒壶中加入薄荷叶与糖浆，轻捣约 10 秒释放香气。", "加入波本威士忌、柠檬汁与冰块。", "用力摇匀约 15 秒至充分冷却。", "双重过滤滤入装满碎冰的老式杯。", "拍醒薄荷枝后装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-bourbon-smash", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "波本碎冰", "nameEn": "Bourbon Smash", "intro": "波本威士忌捣碎新鲜薄荷与柠檬、配糖浆摇匀的碎冰饮品，介于薄荷朱利普与威士忌酸酒之间的夏日经典。", "imageUrl": "https://images.unsplash.com/photo-1591634447477-5197ab46ce13?w=1200&q=80&auto=format&fit=crop", "tags": ["威士忌基底", "波本", "薄荷", "碎冰", "清爽", "捣碎", "夏日"], "scene": ["夏日", "聚会", "户外"], "recommendationScore": 90, "attributes": {"baseSpirit": "威士忌基底", "cocktailType": "碎冰清爽型", "flavor": "薄荷、柠檬、焦糖", "abv": "中度15-25%", "extra": "新鲜薄荷捣碎", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-alabama-slammer', 'cocktail', 'COCKTAIL', '阿拉巴马撞击', 'Alabama Slammer', 'alabamazhuangji', 'albmzj', '杏仁利口酒、南方舒适威士忌利口酒与黑刺李金酒叠加橙汁的橙黄果味长饮，1980 年代美国大学校园流行至今。', '本条目采用经典配比：15 ml 杏仁利口酒、15 ml 南方舒适、15 ml 黑刺李金酒，加冰注入柯林斯杯后以橙汁加满。背景：1980 年代美国大学派对文化中流行，曾出现在 T.G.I. Friday\'s 等连锁餐厅酒单，也被称为 southern slammer。', 'https://images.unsplash.com/photo-1677425039174-5bfa15efb2d9?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1677425039174-5bfa15efb2d9?w=1200&q=80&auto=format&fit=crop', 84, 258, '[{"key": "SWEETNESS", "label": "甜度", "score": 8}, {"key": "SOURNESS", "label": "酸度", "score": 2}, {"key": "BITTERNESS", "label": "苦度", "score": 1}, {"key": "ALCOHOL", "label": "酒精感", "score": 6}, {"key": "BODY", "label": "酒体", "score": 3}, {"key": "REFRESHING", "label": "清爽度", "score": 6}]', '["利口酒基底", "橙汁", "果味", "甜饮", "长饮", "派对"]', '["聚会", "派对", "夜生活"]', '{"baseSpirit": "利口酒基底", "cocktailType": "甜味果饮", "flavor": "杏仁、橙子、甜美", "abv": "中度15-25%", "extra": "橙汁加满", "scene": ["聚会", "派对", "夜生活"]}', '[{"nameZh": "杏仁利口酒", "nameEn": "Amaretto", "amount": 15, "unit": "ml", "role": "基础利口酒"}, {"nameZh": "南方舒适", "nameEn": "Southern Comfort", "amount": 15, "unit": "ml", "role": "威士忌利口酒"}, {"nameZh": "黑刺李金酒", "nameEn": "Sloe Gin", "amount": 15, "unit": "ml", "role": "果味利口酒"}, {"nameZh": "橙汁", "nameEn": "Orange Juice", "amount": 90, "unit": "ml", "role": "加满用果汁"}]', '["柯林斯杯加满冰块。", "依次倒入杏仁利口酒、南方舒适与黑刺李金酒。", "以橙汁加满至杯口。", "轻轻搅拌融合。", "以橙片装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-alabama-slammer", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "阿拉巴马撞击", "nameEn": "Alabama Slammer", "intro": "杏仁利口酒、南方舒适威士忌利口酒与黑刺李金酒叠加橙汁的橙黄果味长饮，1980 年代美国大学校园流行至今。", "imageUrl": "https://images.unsplash.com/photo-1677425039174-5bfa15efb2d9?w=1200&q=80&auto=format&fit=crop", "tags": ["利口酒基底", "橙汁", "果味", "甜饮", "长饮", "派对"], "scene": ["聚会", "派对", "夜生活"], "recommendationScore": 84, "attributes": {"baseSpirit": "利口酒基底", "cocktailType": "甜味果饮", "flavor": "杏仁、橙子、甜美", "abv": "中度15-25%", "extra": "橙汁加满", "scene": []}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-rum-swizzle', 'cocktail', 'COCKTAIL', '朗姆斯威兹', 'Rum Swizzle', 'langmusiweizi', 'lmswz', '百慕大「国饮」，双朗姆与菠萝橙汁、法勒南调和的 tropical 潘趣，碎冰搅拌至起沫。', '以黑朗姆与金朗姆双基底，配菠萝汁、橙汁、柠檬汁与杏仁香料法勒南，加碎冰大力搅拌至表面起沫。 背景：被称为百慕大国饮，Swizzle Inn 酒馆自 1932 年起供应；swizzle stick（搅拌棒）之名即源于这类饮品。', 'https://images.unsplash.com/photo-1500217052183-bc01eee1a74e?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1500217052183-bc01eee1a74e?w=1200&q=80&auto=format&fit=crop', 88, 290, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 2.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "潘趣", "热带水果", "气泡感", "经典", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "潘趣", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["菠萝汁", "橙汁", "法勒南糖浆"], "scene": ["经典", "夏季"]}', '[{"nameZh": "黑朗姆酒", "nameEn": "Black rum", "amount": 20, "unit": "ml", "role": "深邃朗姆骨架"}, {"nameZh": "金朗姆酒", "nameEn": "Gold rum", "amount": 20, "unit": "ml", "role": "圆润朗姆主体"}, {"nameZh": "鲜榨柠檬汁", "nameEn": "Fresh lemon juice", "amount": 20, "unit": "ml", "role": "酸度平衡"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 25, "unit": "ml", "role": "热带果香"}, {"nameZh": "橙汁", "nameEn": "Orange juice", "amount": 25, "unit": "ml", "role": "果甜基底"}, {"nameZh": "百慕大法勒南", "nameEn": "Bermuda falernum", "amount": 10, "unit": "ml", "role": "杏仁香料甜酒"}, {"nameZh": "安高天娜苦精", "nameEn": "Angostura bitters", "amount": 1, "unit": "dash", "role": "复杂度"}]', '["海波杯或 pitcher 加入碎冰。", "倒入黑朗姆、金朗姆、柠檬汁、菠萝汁、橙汁与法勒南。", "用力摇晃或搅拌至表面出现泡沫层。", "滤入加冰杯中，橙片与樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-rum-swizzle", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "朗姆斯威兹", "nameEn": "Rum Swizzle", "intro": "百慕大「国饮」，双朗姆与菠萝橙汁、法勒南调和的 tropical 潘趣，碎冰搅拌至起沫。", "imageUrl": "https://images.unsplash.com/photo-1500217052183-bc01eee1a74e?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "潘趣", "热带水果", "气泡感", "经典", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 88, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "潘趣", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["菠萝汁", "橙汁", "法勒南糖浆"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
INSERT INTO drink (id, mode, category, name_zh, name_en, name_pinyin, name_pinyin_initials, intro, description, image_url, poster_url, recommendation_score, sort_order, radar_json, tags_json, scene_json, attributes_json, ingredients_json, steps_json, aliases_json, source_level, updated_at, reviewed, card_json) VALUES ('cocktail-south-pacific', 'cocktail', 'COCKTAIL', '南太平洋', 'South Pacific', 'nantaipingyang', 'ntpy', '以黑朗姆为基底的提基风格热带饮品，菠萝与百香果交织，碎冰盛杯清爽馥郁。', '黑朗姆 45 毫升配菠萝汁 60 毫升、百香果糖浆 20 毫升与青柠汁 15 毫升摇和，滤入盛碎冰的飓风杯，酒精度约 14%。 背景：热带提基风格的代表之一，围绕朗姆、菠萝与百香果的轻松热带气质构建。', 'https://images.unsplash.com/photo-1655973577713-5acd43022732?w=1200&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1655973577713-5acd43022732?w=1200&q=80&auto=format&fit=crop', 82, 291, '[{"key": "SWEETNESS", "label": "甜度", "score": 6.0}, {"key": "SOURNESS", "label": "酸度", "score": 5.0}, {"key": "BITTERNESS", "label": "苦度", "score": 1.0}, {"key": "ALCOHOL", "label": "酒精感", "score": 5.0}, {"key": "BODY", "label": "酒体", "score": 5.0}, {"key": "REFRESHING", "label": "清爽度", "score": 8.0}]', '["朗姆基底", "提基", "热带水果", "百香果", "碎冰", "夏季"]', '["经典", "夏季"]', '{"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["菠萝汁", "百香果糖浆"], "scene": ["经典", "夏季"]}', '[{"nameZh": "黑朗姆酒", "nameEn": "Dark rum", "amount": 45, "unit": "ml", "role": "深邃朗姆骨架"}, {"nameZh": "菠萝汁", "nameEn": "Pineapple juice", "amount": 60, "unit": "ml", "role": "热带果香主体"}, {"nameZh": "百香果糖浆", "nameEn": "Passionfruit syrup", "amount": 20, "unit": "ml", "role": "百香果甜香"}, {"nameZh": "鲜榨青柠汁", "nameEn": "Lime juice", "amount": 15, "unit": "ml", "role": "酸度平衡"}]', '["全部原料加冰摇和。", "滤入盛碎冰的飓风杯。", "菠萝角与樱桃装饰。"]', '[]', 'B', '2026-08-17', 1, '{"id": "cocktail-south-pacific", "mode": "cocktail", "category": "COCKTAIL", "nameZh": "南太平洋", "nameEn": "South Pacific", "intro": "以黑朗姆为基底的提基风格热带饮品，菠萝与百香果交织，碎冰盛杯清爽馥郁。", "imageUrl": "https://images.unsplash.com/photo-1655973577713-5acd43022732?w=1200&q=80&auto=format&fit=crop", "tags": ["朗姆基底", "提基", "热带水果", "百香果", "碎冰", "夏季"], "scene": ["经典", "夏季"], "recommendationScore": 82, "attributes": {"baseSpirit": "朗姆基底", "cocktailType": "提基", "flavor": "果香、热带水果", "abv": "中度＞10%～20%", "extra": ["菠萝汁", "百香果糖浆"], "scene": ["经典", "夏季"]}}') ON DUPLICATE KEY UPDATE card_json=VALUES(card_json);
